        asm:label("category_clear_scrollbar")
        asm:mov(asm:m8("esi", 0x94), 0)
    
        asm:label("category_call_native")
        asm:push(asm:m32("ebp", 0x0C))
        asm:push(asm:m32("ebp", 0x08))
        asm:mov("ecx", "esi")
        asm:mov("eax", render_target)
        asm:call("eax")
        asm:mov(asm:m32("ebp", -0x0C), "eax")
        asm:test("edi", "edi")
