['home'] = function(...)
 
local modules = ...
local home = {controls = {}, shots = 0, hits = 0, kills = 0, deaths = 0, start_time = 0, last_refresh = -1, active = false}
local function clean(value)
    local text = tostring(value or ''):gsub('[%c]', ''):gsub('^%s+', ''):gsub('%s+$', '')
    if text == '' then return 'user' end
    local index, count, finish = 1, 0, 0
    while index <= #text and count < 24 do
        local byte = text:byte(index)
        local size = byte < 128 and 1 or byte < 224 and 2 or byte < 240 and 3 or 4
        if index + size - 1 > #text then break end
        finish, index, count = index + size - 1, index + size, count + 1
    end
    return finish > 0 and text:sub(1, finish) or 'user'
end
local function add(self, category, ref)
    self.controls[category] = self.controls[category] or {}
    table.insert(self.controls[category], ref)
    return ref
end
function home:username()
    local fallback = clean(rawget(_G, '_USERNAME'))
    if self.username_select and ui.get(self.username_select) == 'Steam' then
        local ok, name = pcall(function() return panorama.open().MyPersonaAPI.GetName() end)
        if ok and type(name) == 'string' and name ~= '' then return clean(name) end
    end
    return fallback
end
local menu_color_ref
pcall(function() menu_color_ref = ui.reference('MISC', 'Settings', 'Menu color') end)
local function menu_accent()
    local r, g, b = 140, 110, 115
    if menu_color_ref then
        pcall(function()
            local cr, cg, cb = ui.get(menu_color_ref)
            if cr ~= nil and cg ~= nil and cb ~= nil then r, g, b = cr, cg, cb end
        end)
    end
    return r, g, b
end
local function color(r, g, b)
    return string.format('\a%02X%02X%02XFF', math.floor(r + 0.5), math.floor(g + 0.5), math.floor(b + 0.5))
end
local function gradient(text, r, g, b, time)
    local chars, index = {}, 1
    while index <= #text do
        local byte = text:byte(index)
        local size = byte < 128 and 1 or byte < 224 and 2 or byte < 240 and 3 or 4
        if index + size - 1 > #text then break end
        chars[#chars + 1] = text:sub(index, index + size - 1)
        index = index + size
    end
    local result = {}
    for i, char in ipairs(chars) do
        local factor = 0.32 + 0.5 * (0.5 + 0.5 * math.cos((i - 1) * 0.32 - time * 1.1))
        result[#result + 1] = color(r + (255 - r) * factor, g + (255 - g) * factor, b + (255 - b) * factor) .. char
    end
    return table.concat(result) .. color(224, 228, 235)
end
local function line(r, g, b, glyph, text)
    return color(r, g, b) .. glyph .. color(224, 228, 235) .. '   ' .. text .. '\r'
end
function home:refresh()
    if not self.active then return end
    local now = globals.realtime() or 0
    local elapsed = math.max(0, math.floor(now - self.start_time))
    local session = string.format('%02d:%02d:%02d', math.floor(elapsed / 3600), math.floor(elapsed / 60) % 60, elapsed % 60)
    local pct = self.shots > 0 and math.floor(self.hits * 100 / self.shots) or 0
    local kd = self.kills / math.max(1, self.deaths)
    local r, g, b = menu_accent()
    local name = gradient(self:username(), r, g, b, now)
    local build = gradient(tostring(modules.core.build or 'Dev'), r, g, b, now)
    ui.set(self.info.user, line(r, g, b, '', 'Welcome back, ' .. name .. '!'))
    ui.set(self.info.build, line(r, g, b, '', "You're using the " .. build .. ' build.'))
    ui.set(self.info.version, line(r, g, b, '', 'Version: 31.07.2026'))
    ui.set(self.info.hitrate, line(r, g, b, '', string.format('Hit rate: %d / %d (%d%%)', self.hits, self.shots, pct)))
    ui.set(self.info.kills, line(r, g, b, '', string.format('Kills: %d   |   Deaths: %d', self.kills, self.deaths)))
    ui.set(self.info.kd, line(r, g, b, '', string.format('K/D: %.2f', kd)))
    ui.set(self.info.session, line(r, g, b, '', 'Session time: ' .. session))
end
function home:init()
    self.start_time = globals.realtime() or 0
    local tab = modules.tab
     
    self.info = {
        user = add(self, 'greeting', ui.new_label('LUA', 'A', 'Welcome back, user!')),
        build = add(self, 'greeting', ui.new_label('LUA', 'A', "You're using the Dev build.")),
        version = add(self, 'greeting', ui.new_label('LUA', 'A', 'Version: 31.07.2026')),
    }
    add(self, 'footer', ui.new_label('LUA', 'A', '\aA0A0A0FF~ nyameeow.pink\r'))
    add(self, 'footer', ui.new_label('LUA', 'A', '\aA0A0A0FFcrafted by lenora • 2026\r'))
    tab:adopt(2, 1)
    self.info.hitrate = add(self, 'stats', ui.new_label('LUA', 'B', 'Hit rate: 0 / 0 (0%)'))
    self.info.kills = add(self, 'stats', ui.new_label('LUA', 'B', 'Kills: 0   |   Deaths: 0'))
    self.info.kd = add(self, 'stats', ui.new_label('LUA', 'B', 'K/D: 0.00'))
    self.info.session = add(self, 'stats', ui.new_label('LUA', 'B', 'Session time: 00:00:00'))
    tab:adopt(3, 2)
    add(self, 'manipulations', ui.new_label('LUA', 'B', '\aB4B465FF   Features highlighted in this color\r'))
    add(self, 'manipulations', ui.new_label('LUA', 'B', '\aB4B465FFuse Skeet memory to apply their changes.\r'))
    add(self, 'manipulations', ui.new_label('LUA', 'B', '\aB4B465FFUse them at your own risk.\r'))
    self.username_select = add(self, 'manipulations', ui.new_combobox('LUA', 'B', '\a4B4B4BFF•\r Username', 'Loader', 'Steam'))
    ui.set_callback(self.username_select, function() self:refresh() end)
    tab:adopt(5, 2)
    self.social = add(self, 'network', ui.new_slider('LUA', 'B', '\a4B4B4BFF•\r Socials', 1, 3, 1, true, '', 1, {
        [1] = '\a8B96C9E8Discord\r', [2] = '\a79AFC7E8Telegram\r', [3] = '\aC97878E8Youtube (Lenora)\r'
    }))
    add(self, 'network', ui.new_button('LUA', 'B', '\v\238\132\171\r \a363636FF•\r Open Page', function()
        local links = {'https://discord.gg/CUHpYCamVj', 'https://t.me/gothsenselua', 'https://www.youtube.com/@%D0%BD%D0%B5%D0%B1%D0%BE%D1%81%D0%B2%D0%BE%D0%B4%D0%B5%D0%BD'}
        local link = links[tonumber(ui.get(self.social)) or 1]
        if link then
            local ok, err = pcall(function() panorama.open().SteamOverlayAPI.OpenExternalBrowserURL(link) end)
            if not ok then client.error_log('[nyameeow.pink recode] Open Page: ' .. tostring(err)) end
        end
    end))
    tab:adopt(9, 2)
    tab:activate()
    self.active = true
    modules.menu:update(true)
    self:refresh()
end
function home:set_visible(visible)
    for category, refs in pairs(self.controls) do
        if category ~= 'footer' then for _, ref in ipairs(refs) do ui.set_visible(ref, visible) end end
    end
end
function home:shutdown()
    self.active = false
    for _, refs in pairs(self.controls) do for _, ref in ipairs(refs) do pcall(ui.set_visible, ref, false) end end
end
home.events = {
    aim_fire = function() home.shots = home.shots + 1 end,
    aim_hit = function() home.hits = home.hits + 1 end,
    player_death = function(event)
        if not event then return end
        local me = entity.get_local_player()
        if not me then return end
        local victim = client.userid_to_entindex(event.userid or 0)
        local attacker = client.userid_to_entindex(event.attacker or 0)
        if victim == me then
            home.deaths = home.deaths + 1
        elseif attacker == me and victim and victim ~= 0 and entity.is_enemy(victim) then
            home.kills = home.kills + 1
        end
    end,
    paint_ui = function()
        if not ui.is_menu_open() then return end
        local now = globals.realtime() or 0
        if now - home.last_refresh >= 0.1 then home.last_refresh = now; home:refresh() end
    end,
}
return home


end,

 
['builder_menu'] = function(...)
 
local modules = ...
local symbols = modules.symbols
local builder = {refs = {}, value_refs = {}, value_specs = {}, defaults = {}, visibility = {}, states = {}, changing = false}
local conditions = {'Shared', 'Standing', 'Running', 'Slowing', 'Air', 'Air Crouching', 'Crouching', 'Sneaking', 'Freestanding', 'Manual', 'Legit AA'}
local teams = {'Terrorist', 'Counter-Terrorist'}
local team_options = {
    '\aE8B060FFTerrorist\r',
    '\a7AA2D4FFCounter-Terrorist\r',
}
local function team_name(value)
    local text = tostring(value or '')
    if text:find('Counter-Terrorist', 1, true) then return teams[2] end
    return teams[1]
end
local function team_option(value)
    return team_name(value) == teams[2] and team_options[2] or team_options[1]
end
local function copy_value(value)
    if type(value) ~= 'table' then return value end
    local result = {}
    for i, v in ipairs(value) do result[i] = v end
    return result
end
local function clone(source)
    local result = {}
    for k, value in pairs(source) do result[k] = copy_value(value) end
    return result
end
local function with_changing(owner, key, fn)
    local previous = owner[key]
    owner[key] = true
    local ok, err = pcall(fn)
    owner[key] = previous
    if not ok then error(err, 0) end
end
 
 
local function slider_labels(first, last, prefix, suffix)
    local labels = {}
    for value = first, last do labels[value] = prefix .. value .. suffix end
    return labels
end
local function contains(values, name)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == name then return true end end
    return false
end
 
function builder:register_value(key, ref, ctor, ...)
    local args = {...}
    local spec
    if ctor == ui.new_checkbox then spec = {kind='checkbox', default=false}
    elseif ctor == ui.new_slider then spec = {kind='slider', min=args[1], max=args[2], default=args[3] or args[1]}
    elseif ctor == ui.new_combobox then spec = {kind='combo', options=args, default=args[1]}
    elseif ctor == ui.new_multiselect then spec = {kind='multi', options=args, default={}}
    else error('Unsupported builder value type: ' .. key) end
    self.value_refs[key], self.value_specs[key], self.defaults[key] = ref, spec, copy_value(spec.default)
end
 
 
 
 
 
 
function builder:sync_defensive_lock()
    local r = self.refs
    if not r.defensive_enable then return end
    local state = ui.get(r.condition)
    if state == 'Legit AA' or state == 'Manual' then
        if self.defensive_legit_lock == nil then
            self.defensive_legit_lock = ui.get(r.defensive_enable) == true
            if ui.get(r.defensive_enable) ~= false then ui.set(r.defensive_enable, false) end
        end
        if type(ui.set_enabled) == 'function' then ui.set_enabled(r.defensive_enable, false) end
    elseif self.defensive_legit_lock ~= nil then
        self.defensive_legit_lock = nil
        if type(ui.set_enabled) == 'function' then ui.set_enabled(r.defensive_enable, true) end
    end
end
function builder:defensive_snapshot()
    local out = {}
    for key, ref in pairs(self.defensive_refs or {}) do out[key] = copy_value(ui.get(ref)) end
    if self.defensive_legit_lock ~= nil and out.defensive_enable == false then
        out.defensive_enable = self.defensive_legit_lock
    end
    return out
end
function builder:apply_defensive(values)
    with_changing(self, 'defensive_changing', function()
        for key, ref in pairs(self.defensive_refs) do
            local value = values[key]
            if value == nil then value = self.defensive_specs[key].default end
            if type(value) == 'table' then ui.set(ref, unpack(value)) else ui.set(ref, value) end
        end
    end)
end
function builder:snapshot()
    local values = {}
    for key, ref in pairs(self.value_refs) do values[key] = copy_value(ui.get(ref)) end
    return values
end
 
 
function builder:sync_body_mode()
    local r = self.refs
    if not r.desync_single then return end
    with_changing(self, 'changing', function()
        local mode = ui.get(r.desync)
        if mode == 'Randomize Jitter' then
            mode = 'Jitter'
            ui.set(r.desync, mode)
        end
        if not ui.get(r.second_yaw) and mode == 'L/R Desync' then
            mode = 'Off'
            ui.set(r.desync, mode)
        end
        if mode ~= 'L/R Desync' and ui.get(r.desync_single) ~= mode then
            ui.set(r.desync_single, mode)
        end
    end)
end
function builder:apply(values)
    with_changing(self, 'changing', function()
        for key, ref in pairs(self.value_refs) do
            local value = values[key]
            if key == 'desync' and value == 'Randomize Jitter' then value = 'Jitter' end
            if value == nil then value = copy_value(self.defaults[key]) end
            if value ~= nil then
                if type(value) == 'table' then ui.set(ref, unpack(value)) else ui.set(ref, value) end
            end
        end
        self:sync_body_mode()
    end)
end
function builder:team_name()
    return team_name(ui.get(self.refs.team))
end
function builder:set_team(value)
    ui.set(self.refs.team, team_option(value))
end
function builder:state_key()
    return self:team_name() .. ':' .. ui.get(self.refs.condition)
end
function builder:change_state()
    if self.changing then return end
    local next_condition = ui.get(self.refs.condition)
    if self.defensive_current and next_condition ~= self.defensive_current then
        self.defensive_states[self.defensive_current] = self:defensive_snapshot()
        self.defensive_current = next_condition
        self:apply_defensive(self.defensive_states[next_condition] or {})
    end
    self:sync_defensive_lock()
    self.states[self.current_key] = self:snapshot()
    self.current_key = self:state_key()
    self:apply(self.states[self.current_key] or self.defaults)
    self.states[self.current_key] = self:snapshot()
    self:refresh(self.page_active)
    local cfg = self.menu_config
    if cfg and type(cfg.schedule_builder_autosave) == 'function' then
        cfg:schedule_builder_autosave()
    end
end
function builder:init(tab, owned, on_settings_change)
    local r, left = self.refs, {}
    local dot, arrow = symbols.format('\f<afterglow_dot>'), symbols.format('\f<afterglow_arrow>')
    local function add(key, ctor, name, ...)
        local ref = ctor('LUA', 'A', name, ...)
        r[key] = ref
        self:register_value(key, ref, ctor, ...)
        left[#left + 1], owned[#owned + 1] = ref, ref
        return ref
    end
    local function decor(key, name)
        local ref = ui.new_label('LUA', 'A', name)
        r[key] = ref
        left[#left + 1], owned[#owned + 1] = ref, ref
        return ref
    end
     
     
    local settings = {}
    local function setting(key, ctor, name, ...)
        local ref = ctor('LUA', 'A', name, ...)
        r[key] = ref
        self:register_value(key, ref, ctor, ...)
        settings[#settings + 1], owned[#owned + 1] = ref, ref
        return ref
    end
    local function setting_action(key, ctor, name, ...)
        local ref = ctor('LUA', 'A', name, ...)
        r[key] = ref
        settings[#settings + 1], owned[#owned + 1] = ref, ref
        return ref
    end
    setting_action('pitch_label', ui.new_label, arrow .. ' Pitch')
    setting('pitch', ui.new_combobox, '\n afterglow_builder_pitch', 'Down', 'Up', 'Custom', 'Random')
    setting('pitch_value', ui.new_slider, dot .. ' Pitch Value', -89, 89, 0, true, '°')
    setting_action('settings_gap', ui.new_label, ' ')
    setting_action('yaw_base_label', ui.new_label, arrow .. ' Yaw Base')
    setting('yaw_base', ui.new_combobox, '\n afterglow_builder_yaw_base', 'At targets', 'Local view')
    setting_action('send_gap', ui.new_label, ' ')
    setting_action('send', ui.new_button, '   Send to Opposite Side', function()
        local opposite = team_name(ui.get(r.team)) == teams[1] and teams[2] or teams[1]
        self.states[opposite .. ':' .. ui.get(r.condition)] = clone(self:snapshot())
    end)
    setting_action('copy', ui.new_button, '   Copy', function() self.clipboard = self:snapshot() end)
    setting_action('paste', ui.new_button, '   Paste', function()
        if self.clipboard then self:apply(self.clipboard); self.states[self.current_key] = self:snapshot(); self:refresh(self.page_active) end
    end)
    tab:adopt_tail(6, 1, settings)
    self.settings_refs = settings
    add('override', ui.new_checkbox, dot .. ' Override')
     
