    add('yaw_random_single', ui.new_slider, '\n afterglow_builder_random_single', 0, 100, 0, true, '', 1, slider_labels(0, 100, 'Rand. Yaw ', '%'))
    add('yaw_random_left', ui.new_slider, '\n afterglow_builder_random_left', 0, 100, 0, true, '', 1, slider_labels(0, 100, 'Rand. L ', '%'))
    add('yaw_right', ui.new_slider, '\n afterglow_builder_yaw_right', -180, 180, 0, true, '', 1, slider_labels(-180, 180, 'R ', '°'))
    add('yaw_random_right', ui.new_slider, '\n afterglow_builder_random_right', 0, 100, 0, true, '', 1, slider_labels(0, 100, 'Rand. R ', '%'))
    decor('modifier_gap', ' ')
    decor('modifier_label', arrow .. ' Modifier')
    add('modifier', ui.new_combobox, '\n afterglow_builder_modifier', 'Off', 'Offset', 'Center', 'Random', 'Skitter', 'Ways')
    decor('modifier_options_gap', ' ')
    add('modifier_value', ui.new_slider, '\n afterglow_builder_modifier_value', -180, 180, 0, true, '', 1, slider_labels(-180, 180, 'Val. ', '°'))
     
     
    add('ways', ui.new_slider, '\n afterglow_builder_ways_count', 1, 12, 1, true, '', 1, slider_labels(1, 12, 'Ways ×', ''))
    local way_symbols = {'①', '②', '③', '④', '⑤', '⑥', '⑦', '⑧', '⑨', '⑩', '⑪', '⑫'}
    for i = 1, 12 do
        add('way_' .. i, ui.new_slider, '\n afterglow_builder_way_' .. i, -180, 180, 0, true, '', 1, slider_labels(-180, 180, way_symbols[i] .. ' ', '°'))
    end
    add('modifier_variability', ui.new_slider, '\n afterglow_builder_modifier_randomize', 0, 100, 0, true, '', 1, slider_labels(0, 100, 'Rand. ', '%'))
    decor('desync_gap', ' ')
    decor('desync_label', arrow .. ' Body Yaw')
    add('desync', ui.new_combobox, '\n afterglow_builder_body_yaw', 'Off', 'Opposite', 'Static', 'Jitter', 'L/R Desync')
     
    r.desync_single = ui.new_combobox('LUA', 'A', '\n afterglow_builder_body_yaw_single', 'Off', 'Opposite', 'Static', 'Jitter')
    left[#left + 1], owned[#owned + 1] = r.desync_single, r.desync_single
    add('desync_direction', ui.new_combobox, '\n afterglow_builder_static_sign', '+', '-')
    decor('desync_options_gap', ' ')
    add('desync_value', ui.new_slider, '\n afterglow_builder_body_jitter', -58, 58, 58, true, '°')
    add('desync_invert_chance', ui.new_slider, '\n afterglow_builder_body_invert_chance', 0, 100, 100, true, '', 1, slider_labels(0, 100, 'Invert Chance ', '%'))
    add('desync_left', ui.new_slider, '\n afterglow_builder_body_left', 0, 58, 58, true, '', 1, slider_labels(0, 58, 'L ', '°'))
    add('desync_right', ui.new_slider, '\n afterglow_builder_body_right', 0, 58, 58, true, '', 1, slider_labels(0, 58, 'R ', '°'))
    add('desync_random', ui.new_slider, '\n afterglow_builder_body_random', 0, 100, 0, true, '', 1, slider_labels(0, 100, 'Rand. ', '%'))
     
     
    decor('body_freestanding_gap', ' ')
    add('body_freestanding', ui.new_checkbox, dot .. ' Body Freestanding')
    decor('body_end_gap', ' ')
    tab:adopt_tail(2, 1, left)
    self.left_refs = left

    local right = {}
    local function state_control(key, ctor, name, ...)
        local ref = ctor('LUA', 'B', name, ...)
        r[key] = ref; right[#right + 1], owned[#owned + 1] = ref, ref
        return ref
    end
    state_control('condition_label', ui.new_label, '   State')
    state_control('condition', ui.new_combobox, '\n afterglow_builder_state', unpack(conditions))
    state_control('settings_button', ui.new_button, '', function()
        self.settings_open = not self.settings_open
        self:refresh(self.page_active)
        if on_settings_change then on_settings_change() end
    end)
    state_control('team_label', ui.new_label, '   Team')
    state_control('team', ui.new_combobox, '\n afterglow_builder_team', unpack(team_options))
    tab:adopt_tail(5, 2, right)
    self.right_refs = right
    self.current_key = self:state_key()
    self.states[self.current_key] = self:snapshot()
    for _, ref in pairs(self.value_refs) do self:bind_value(ref) end
    ui.set_callback(r.desync_single, function()
        if self.changing then return end
        with_changing(self, 'changing', function() ui.set(r.desync, ui.get(r.desync_single)) end)
        if self.current_key then self.states[self.current_key] = self:snapshot() end
        self:refresh(self.page_active, self.section)
    end)
    ui.set_callback(r.condition, function() self:change_state() end)
    ui.set_callback(r.team, function() self:change_state() end)
end
 
function builder:bind_value(ref)
    local r = self.refs
    ui.set_callback(ref, function()
        if self.changing then return end
        local other
        if ref == r.yaw_single then other = r.yaw_left
        elseif ref == r.yaw_left then other = r.yaw_single
        elseif ref == r.yaw_random_single then other = r.yaw_random_left
        elseif ref == r.yaw_random_left then other = r.yaw_random_single end
        if other and ui.get(other) ~= ui.get(ref) then
            with_changing(self, 'changing', function() ui.set(other, ui.get(ref)) end)
        end
        self:sync_body_mode()
        if self.current_key then self.states[self.current_key] = self:snapshot() end
        self:refresh(self.page_active, self.section)
        local cfg = self.menu_config
        if cfg and type(cfg.schedule_builder_autosave) == 'function' then
            cfg:schedule_builder_autosave()
        end
    end)
end

 
