    self:sync_defensive_lock()
end
function builder:refresh(active, section)
    self.page_active = active and true or false
    self.section = section or self.section
    local r = self.refs
    local function show(ref, yes)
        local value = active and yes and true or false
        if self.visibility[ref] ~= value then ui.set_visible(ref, value); self.visibility[ref] = value end
    end
    for _, ref in ipairs(self.right_refs) do show(ref, true) end
    show(r.condition_label, true); show(r.condition, true); show(r.settings_button, true)
    local state = ui.get(r.condition)
     
    local legit_state = state == 'Legit AA'
    local open = self.settings_open and not legit_state
    show(r.pitch_label, open); show(r.settings_gap, self.settings_open)
    show(r.yaw_base_label, open); show(r.send_gap, self.settings_open)
    show(r.send, self.settings_open)
    show(r.copy, self.settings_open); show(r.paste, self.settings_open)
    local enabled = state == 'Shared' or ui.get(r.override)
    show(r.override, state ~= 'Shared')
    show(r.yaw_base, open)
    show(r.pitch, open)
    show(r.pitch_value, open and ui.get(r.pitch) == 'Custom')
    self:sync_body_mode()
    local lr = ui.get(r.second_yaw) == true
    show(r.yaw_value, enabled)
    show(r.yaw_gap, enabled); show(r.second_yaw, enabled)
    show(r.yaw_single, enabled and not lr); show(r.yaw_left, enabled and lr)
    show(r.yaw_random_single, enabled and not lr); show(r.yaw_random_left, enabled and lr)
    show(r.yaw_right, enabled and lr); show(r.yaw_random_right, enabled and lr)
     
    if self.section_refs then
        local delay_available = enabled and lr and self.section == 'Manipulations'
        show(r.delay_enable, delay_available)
        local delay = delay_available and ui.get(r.delay_enable)
        show(r.delay_head_gap, delay); show(r.delay_mode_label, delay)
        show(r.delay_mode, delay); show(r.delay_count, delay)
        show(r.delay_features_gap, delay); show(r.delay_features_label, delay); show(r.delay_features, delay)
        for i = 1, 12 do show(r['delay_' .. i], delay and i <= ui.get(r.delay_count)) end
        local selected = ui.get(r.delay_features)
        local freeze = delay and contains(selected, 'Freeze Inverter')
        local disable = delay and contains(selected, 'Disabling')
        show(r.freeze_label, freeze)
        show(r.freeze_chance_label, freeze); show(r.freeze_chance, freeze)
        show(r.freeze_time_label, freeze); show(r.freeze_time, freeze)
        show(r.freeze_cooldown_label, freeze); show(r.freeze_cooldown, freeze)
        show(r.disable_label, disable)
        show(r.disable_chance_label, disable); show(r.disable_chance, disable)
        show(r.disable_time_label, disable); show(r.disable_time, disable)
        show(r.force_defensive, false)
        local defensive_page = self.section == 'Defensive'
        show(r.defensive_gap, defensive_page); show(r.defensive_force, defensive_page); show(r.defensive_enable, defensive_page)
        local triggers_visible = defensive_page and (ui.get(r.defensive_enable) or ui.get(r.defensive_force))
        show(r.defensive_filters_gap, triggers_visible)
        show(r.defensive_triggers_label, triggers_visible); show(r.defensive_triggers, triggers_visible)
        show(r.defensive_filter_row_gap, triggers_visible)
        show(r.defensive_activation_label, triggers_visible); show(r.defensive_activation, triggers_visible)
        local defensive_on = defensive_page and ui.get(r.defensive_enable)
        show(r.defensive_pitch_gap, defensive_on)
        show(r.defensive_pitch_label, defensive_on); show(r.defensive_pitch, defensive_on)
        local pitch_mode = ui.get(r.defensive_pitch)
        show(r.defensive_pitch_options_gap, defensive_on and pitch_mode ~= 'Keep')
        show(r.defensive_pitch_value, defensive_on and pitch_mode ~= 'Keep')
        show(r.defensive_pitch_second, defensive_on and pitch_mode ~= 'Keep' and pitch_mode ~= 'Custom')
        show(r.defensive_pitch_speed, defensive_on and pitch_mode == 'Sway')
        show(r.defensive_yaw_gap, defensive_on)
        show(r.defensive_yaw_label, defensive_on); show(r.defensive_yaw, defensive_on)
        local yaw_mode = ui.get(r.defensive_yaw)
        show(r.defensive_yaw_options_gap, defensive_on and yaw_mode ~= 'Keep')
        show(r.defensive_yaw_value, defensive_on and yaw_mode ~= 'Keep' and yaw_mode ~= 'Spin')
        show(r.defensive_second_gap, defensive_on and yaw_mode == 'Custom')
        show(r.defensive_yaw_add_second, defensive_on and yaw_mode == 'Custom')
        local two_yaw = defensive_on and yaw_mode == 'Custom' and ui.get(r.defensive_yaw_add_second)
        show(r.defensive_switch_label, two_yaw); show(r.defensive_yaw_switch, two_yaw)
        show(r.defensive_yaw_second, defensive_on and (yaw_mode == 'Sway' or yaw_mode == 'Static Random' or (yaw_mode == 'Custom' and ui.get(r.defensive_yaw_add_second))))
        show(r.defensive_yaw_speed, defensive_on and (yaw_mode == 'Spin' or yaw_mode == 'Sway'))
        local delay_visible = defensive_on and (pitch_mode == 'Switch' or pitch_mode == 'Random' or yaw_mode == 'Random'
            or yaw_mode == '3-Way' or yaw_mode == '5-Way' or (two_yaw and ui.get(r.defensive_yaw_switch) == 'Delay'))
        show(r.defensive_delay_gap, delay_visible); show(r.defensive_delay, delay_visible)
    end
    show(r.modifier_gap, enabled); show(r.modifier_label, enabled); show(r.modifier, enabled)
    local modifier = ui.get(r.modifier)
    local modified, ways = modifier ~= 'Off', modifier == 'Ways'
    show(r.modifier_options_gap, enabled and modified)
    show(r.modifier_value, enabled and modified and not ways)
    show(r.ways, enabled and ways)
    for i = 1, 12 do show(r['way_' .. i], enabled and ways and i <= ui.get(r.ways)) end
    show(r.modifier_variability, enabled and modified)
    show(r.desync_gap, enabled); show(r.desync_label, enabled)
    show(r.desync, enabled and lr); show(r.desync_single, enabled and not lr)
    local body_mode = ui.get(r.desync)
    local jitter = enabled and body_mode == 'Jitter'
    local lr_desync = enabled and body_mode == 'L/R Desync'
    show(r.desync_options_gap, jitter or lr_desync)
    show(r.desync_value, jitter)
    show(r.desync_invert_chance, jitter)
    show(r.desync_direction, enabled and body_mode == 'Static')
    show(r.desync_left, lr_desync); show(r.desync_right, lr_desync); show(r.desync_random, lr_desync)
    show(r.body_freestanding_gap, enabled)
    show(r.body_freestanding, enabled)
    show(r.body_end_gap, enabled)
end
return builder


end,

 
['misc_rage_menu'] = function(...)
 
local modules = ...
local symbols = modules.symbols
local menu = {refs = {}, visibility = {}, syncing_gap = false}

local function title(name, kind)
    return symbols.format(kind == 'combo' and '\f<afterglow_arrow>' or '\f<afterglow_dot>') .. ' ' .. name
end
local function warning(name)
    return symbols.format('\f<afterglow_dot>') .. ' \aB4B465FF' .. name .. '\r'
end
 
local plain = '\aE1E4E8FF'
local flourish = '\226\156\158 · \226\155\167 · \226\155\165 · \226\156\158'
function menu:refresh_ornaments(r, g, b, a)
    local accent = string.format('\a%02X%02X%02X%02X', math.floor(r), math.floor(g), math.floor(b), math.floor(a or 255))
    local function name(value) return plain .. value .. '  ' .. accent .. flourish .. '\r' end
    local fixes_text, tools_text = name('Fixes'), name('Features')
    local key = fixes_text .. tools_text
    if self.last_ornaments ~= key then
        self.last_ornaments = key
        ui.set(self.refs.fixes_label, fixes_text)
        ui.set(self.refs.tools_label, tools_text)
    end
end
local function has(ref, option)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == option then return true end end
    return false
end
function menu:init(tab, owned)
    local r = self.refs
    local function group(column) return {column = column, refs = {}} end
    local function add(g, key, constructor, ...)
        local ref = constructor('LUA', g.column, ...)
        r[key] = ref
        g.refs[#g.refs + 1] = ref
        owned[#owned + 1] = ref
        return ref
    end
    local c, combo, multi, slider, color = ui.new_checkbox, ui.new_combobox, ui.new_multiselect, ui.new_slider, ui.new_color_picker
