    add(left, 'teammate', c, title('Force Teammate Aimbot'))
    add(left, 'enemy_chat', c, title('Enemy Chat Viewer'))
    add(left, 'allow_duck_fd', c, title('Allow Duck on FD'))
    add(left, 'unlock_cvars', c, title('Unlock Hidden Cvars'))
    add(left, 'drop_nades', c, title('Drop Nades'))
    add(left, 'drop_nades_key', ui.new_hotkey, 'Drop Nades key', true)
