    add(anim, 'other_modes', multi, title('Other Modes', 'combo'), 'Body Lean', 'Earthshake', 'Leg movement', 'Pitch Zero on Land', 'Smooth Animfix')
    add(anim, 'leg_movement', combo, title('Leg movement', 'combo'), 'Off', 'Always slide', 'Never slide', 'Break balance')
    add(anim, 'body_lean', slider, title('Body Lean Strength'), 0, 100, 0, true, '%', 1, {[0]='Disabled',[10]='Very Low',[25]='Low',[40]='Medium',[60]='High',[80]='Strong',[100]='Maximum'})
    add(anim, 'standing_lean', c, title('Allow Standing Leaning'))
