        'violence_hblood', 'violence_ablood', 'violence_hgibs', 'violence_agibs', 'cl_ragdoll_physics_enable', 'ragdoll_sleepaftertime', 'cl_ragdoll_collide', 'r_eyemove', 'r_eyegloss', 'cl_csm_static_prop_shadows', 'cl_csm_world_shadows', 'cl_csm_viewmodel_shadows', 'r_decals', 'r_drawmodeldecals', 'r_maxmodeldecal', 'mp_decals', 'r_drawdetailprops', 'cl_detail_max_sway', 'r_3dsky', 'r_dynamic', 'muzzleflash_light', 'r_waterforceexpensive', 'r_waterdrawreflection', 'r_waterdrawrefraction', 'cl_show_splashes', 'rope_smooth', 'rope_wind_dist', 'rope_shake', 'cl_ejectbrass', 'func_break_max_pieces', 'r_drawtracers', 'r_drawtracers_firstperson', 'cl_disablefreezecam', 'cl_disablehtmlmotd', 'cl_autohelp', 'cl_showhelp')
    add(utilities, 'f12_events', multi, title('F12 Events', 'combo'), 'Kill', 'Miss')
    add(utilities, 'f12_event_edit', combo, title('Edit Event', 'combo'), 'Kill', 'Miss')
    add(utilities, 'f12_file_label', ui.new_label, title('Sound File'))
    add(utilities, 'f12_file', ui.new_listbox, '\n afterglow_f12_files', {'Off'})
    add(utilities, 'f12_loopback', c, title('Hear Own Sound'))
    add(utilities, 'client_nickname_text', ui.new_textbox, title('Nickname'))
    add(utilities, 'warmup', ui.new_button, '   Warmup Setup', function()
        if not self.runtime then return end
        local ok, err = pcall(self.runtime.warmup_setup, self.runtime)
        if not ok then self.runtime:report('Warmup Setup', err) end
    end)  
    tab:adopt_tail(5, 2, utilities.refs)
    tab:configure_listbox(r.f12_file, {fixed_rows = 3, hide_header = true})

     
     
    local fixes, tools = group('A'), group('B')
    local fix_defs = {
        {key = 'air_strafe', cat = 'Movement'},
        {key = 'quick_stop', cat = 'Movement'},
        {key = 'air_autostop', cat = 'Movement'},
        {key = 'spread_autostop', cat = 'Movement'},
        {key = 'dt_stability', cat = 'Double Tap'},
        {key = 'dt_return', cat = 'Double Tap'},
        {key = 'backtrack', cat = 'Records'},
        {key = 'adaptive', cat = 'Misc'},
        {key = 'shot_delay', cat = 'Misc'},
        {key = 'scan_accuracy', cat = 'Misc'},
        {key = 'animation_flags', cat = 'Misc'},
    }
    local tool_defs = {
        {key = 'force_shot', cat = 'Shooting'},
        {key = 'defensive_dt', cat = 'Double Tap'},
        {key = 'hs_fakelag', cat = 'Double Tap'},
        {key = 'quick_switch', cat = 'Misc'},
        {key = 'reset_fl', cat = 'Misc'},
    }
    self.fix_defs, self.tool_defs = fix_defs, tool_defs

    add(fixes, 'fixes_label', ui.new_label, 'Fixes')
    add(fixes, 'fixes_category', combo, '\n afterglow_rage_fix_category', 'Movement', 'Double Tap', 'Records', 'Misc')
    add(fixes, 'air_strafe', c, title('Neverlose Air Strafe'))
    add(fixes, 'strafe_smoothing', slider, title('Strafe Smoothing'), 0, 100, 50, true, '%')
    add(fixes, 'quick_stop', c, warning('Accurate Quick Stop [MAY AFFECT VAR]'))
    add(fixes, 'air_autostop', c, warning('Air Autostop'))
    add(fixes, 'spread_autostop', c, warning('Spread & Autostop Fix'))
    add(fixes, 'dt_stability', c, warning('Double Tap Stability Fix'))
    add(fixes, 'dt_return', c, warning('Double Tap Return Fix'))
    add(fixes, 'backtrack', c, warning('Backtrack Record Fix'))
    add(fixes, 'lag_records', c, warning('Lag Records'))
    add(fixes, 'extended_records', c, warning('Extended Lag Records'))
    add(fixes, 'record_gap', slider, warning('Record Gap'), 1, 10, 3, true, 't')
    add(fixes, 'extended_gap', slider, warning('Extended Record Gap'), 1, 20, 3, true, 't')
    ui.set_callback(r.extended_records, function()
        if self.syncing_gap then return end
        self.syncing_gap = true
