    add(tools, 'force_indicator', c, title('Force Shot Indicator'))
    add(tools, 'force_color', color, 'Force Shot Indicator Color', 235, 235, 235, 255)
    add(tools, 'defensive_dt', c, title('Defensive Double Tap on Peek'))
    add(tools, 'hs_fakelag', c, title('Hide Shots Fakelag Limit Fix'))
    add(tools, 'quick_switch', c, title('Custom Quick Switch'))
    add(tools, 'reset_fl', c, title('Reset Fake Lag on Shot'))
    add(tools, 'reset_delay', slider, title('Reset Delay (Ticks)'), 1, 32, 16, true, 't')
    tab:adopt_tail(3, 2, tools.refs)
end
function menu:refresh(page)
    local r = self.refs
    local misc, rage = page == 'Misc', page == 'Ragebot'
    local function show(key, condition)
        local visible = not not condition
        if self.visibility[key] ~= visible then ui.set_visible(r[key], visible); self.visibility[key] = visible end
    end
    local function many(keys, condition) for _, key in ipairs(keys) do show(key, condition) end end
    many({'event','event_triggers','event_group_gap','trash_group_gap','teammate','enemy_chat','trash','anim','utility_features','warmup','allow_duck_fd','unlock_cvars','drop_nades','drop_nades_key','fast_ladder','edge_quick_stop','edge_quick_stop_key'}, misc)
    show('avoid_flying', misc and ui.get(r.fast_ladder))
    show('drop_grenades', misc and ui.get(r.drop_nades))
    show('client_nickname_text', misc and has(r.utility_features, 'Client-side Nickname'))
    local f12 = misc and has(r.utility_features, 'F12 Sound')
    show('f12_events', f12); show('f12_loopback', f12)
    show('f12_event_edit', f12); show('f12_file_label', f12); show('f12_file', f12)
    local event = misc and ui.get(r.event)
    show('event_hit_color', event and (has(r.event_triggers, 'Aimbot') or has(r.event_triggers, 'Purchase')))
    show('event_miss_color', event and (has(r.event_triggers, 'Aimbot') or has(r.event_triggers, 'Connection problems')))
    many({'event_prefix','event_guide'}, event)
    local trash = misc and ui.get(r.trash)
    many({'trash_mode','spectating','send_time'}, trash)
    show('bait_events', trash and ui.get(r.trash_mode) == 'Bait')
    many({'author_events','message_interval'}, trash and ui.get(r.trash_mode) == 'Author')
    local anim = misc and ui.get(r.anim)
    show('anim_sections', anim)
    show('air_mode', anim and has(r.anim_sections, 'Air'))
    local legs = anim and has(r.anim_sections, 'Legs')
    show('legs_mode', legs)
    show('static_delta', legs and ui.get(r.legs_mode) == 'Static')
    many({'delta_from','delta_to','legs_delay'}, legs and ui.get(r.legs_mode) == 'Jitter')
    local other = anim and has(r.anim_sections, 'Other')
    many({'other_modes','walking_legs'}, other)
    show('leg_movement', other and has(r.other_modes, 'Leg movement'))
    many({'body_lean','standing_lean'}, other and has(r.other_modes, 'Body Lean'))
    show('earthshake', other and has(r.other_modes, 'Earthshake'))
    local opt = misc and has(r.utility_features, 'Performance Optimizer')
    many({'optimizer_profile','optimizer_flags'}, opt)
    show('optimizer_cvars', opt and ui.get(r.optimizer_profile) == 'Custom')
    many({'fixes_label', 'fixes_category', 'tools_label', 'tools_category'}, rage)
    local fix_cat = rage and ui.get(r.fixes_category) or nil
    local tool_cat = rage and ui.get(r.tools_category) or nil
    for _, def in ipairs(self.fix_defs) do show(def.key, rage and def.cat == fix_cat) end
    for _, def in ipairs(self.tool_defs) do show(def.key, rage and def.cat == tool_cat) end
    local function on(ref) return rage and ui.get(ref) == true end
    show('strafe_smoothing', fix_cat == 'Movement' and on(r.air_strafe))
    local backtrack = fix_cat == 'Records' and on(r.backtrack)
    show('lag_records', backtrack)
    local records = backtrack and on(r.lag_records)
    show('extended_records', records)
    show('record_gap', records and not on(r.extended_records))
    show('extended_gap', records and on(r.extended_records))
    show('prediction_stats', fix_cat == 'Misc' and on(r.adaptive))
    local force = tool_cat == 'Shooting' and on(r.force_shot)
    many({'force_key_label', 'force_shot_key', 'force_air', 'force_hitchance', 'force_indicator'}, force)
    show('force_color', force and on(r.force_indicator))
    show('reset_delay', tool_cat == 'Misc' and on(r.reset_fl))
end
return menu


end,

 
['visuals_menu'] = function(...)
 
local modules = ...
local symbols = modules.symbols
local visuals = {refs = {}, visibility = {}}
local function has_selection(ref, name)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == name then return true end end
    return false
end
function visuals:sync_scope_options(source, force)
    if self.syncing_scope_options then return end
    local r = self.refs
    local active = ui.get(r.scope_mode) == 'Rotated' and r.scope_options_rotated or r.scope_options_default
    if source ~= active and not force then return end
    local from_default = source == r.scope_options_default
    local target = from_default and r.scope_options_rotated or r.scope_options_default
    local reversed = has_selection(source, 'Reversed')
    if has_selection(target, 'Reversed') == reversed then return end
    local values = {}
    if reversed then values[#values + 1] = 'Reversed' end
     
    if from_default and has_selection(target, 'Animate') then values[#values + 1] = 'Animate' end
    self.syncing_scope_options = true
    local ok, err = pcall(ui.set, target, unpack(values))
    self.syncing_scope_options = false
    if not ok then error(err, 0) end
end
function visuals:load_scope_options()
     
     
    self.scope_storage_ready = false
end
function visuals:save_scope_options()
    return true
end
local function title(name, kind)
    return symbols.format(kind == 'combo' and '\f<afterglow_arrow>' or '\f<afterglow_dot>') .. ' ' .. name
end
function visuals:init(tab, owned)
    local refs = self.refs
    local function create(group, name, constructor, ...)
        local ref = constructor('LUA', group.column, ...)
        refs[name] = ref
        group.refs[#group.refs + 1] = ref
        owned[#owned + 1] = ref
        return ref
    end
    local left = {column = 'A', refs = {}}
    local right = {column = 'B', refs = {}}
    local notes = {column = 'B', refs = {}}
    local watermark = {column = 'B', refs = {}}
    local c, b, sl, cp, tx, ms = ui.new_checkbox, ui.new_combobox, ui.new_slider, ui.new_color_picker, ui.new_textbox, ui.new_multiselect
    create(left, 'manual', c, title('Manual Arrows'))
    create(left, 'manual_style', b, '\n afterglow_manual_style', 'Team Skeet', 'Custom', 'CS2', 'Modern')
    create(left, 'yaw_color', cp, 'Manual yaw color', 175, 255, 55, 255)
    create(left, 'body_color', cp, 'Manual body color', 56, 158, 252, 255)
    create(left, 'custom_color', cp, 'Manual custom color', 175, 255, 55, 255)
    create(left, 'arc_color', cp, 'Modern arc color', 138, 172, 218, 255)
    create(left, 'idle_color', cp, 'CS2 idle color', 255, 68, 78, 255)
    create(left, 'manual_font', b, title('Symbol Font', 'combo'), 'Default', 'Pixel', 'Bold', 'Large')
    create(left, 'left_symbol', tx, title('Left symbol'))
    create(left, 'right_symbol', tx, title('Right symbol'))
    create(left, 'forward_symbol', tx, title('Forward symbol'))
    create(left, 'manual_gap', ui.new_label, ' ')
    create(left, 'output', c, title('Custom Output'))
    create(left, 'output_style', b, '\n afterglow_output_style', 'Old', 'New')
