end
function visuals:refresh(active, world_selected)
    local r = self.refs
    local function show(name, flag)
        local value = active and flag and true or false
        if self.visibility[name] ~= value then ui.set_visible(r[name], value); self.visibility[name] = value end
    end
    local selected = {}
    if type(world_selected) == 'table' then
        for _, name in ipairs(world_selected) do selected[name] = true end
    end
    local manual, style = ui.get(r.manual), ui.get(r.manual_style)
    for _, name in ipairs({'manual', 'manual_gap', 'output', 'output_gap', 'scope', 'lifetime', 'max_items', 'y_offset', 'test'}) do show(name, true) end
    show('manual_style', manual)
    show('yaw_color', manual and style == 'Team Skeet'); show('body_color', manual and style == 'Team Skeet')
    show('custom_color', manual and (style == 'Custom' or style == 'CS2'))
    show('arc_color', manual and style == 'Modern'); show('idle_color', manual and style == 'CS2')
    for _, name in ipairs({'manual_font', 'left_symbol', 'right_symbol', 'forward_symbol'}) do show(name, manual and style == 'Custom') end
    show('output_style', ui.get(r.output))
    local scope = ui.get(r.scope)
    for _, name in ipairs({'scope_color', 'scope_mode', 'scope_length', 'scope_length_spacing', 'scope_gap', 'scope_gap_spacing', 'scope_speed'}) do show(name, scope) end
    local rotated = ui.get(r.scope_mode) == 'Rotated'
    show('scope_options_default', scope and not rotated)
    show('scope_options_rotated', scope and rotated)
    local zoom = selected['Zoom Animation'] == true
    local aspect = selected['Aspect Ratio'] == true
    local viewmodel = selected['Viewmodel Changer'] == true
    local second = selected['Force Second Zoom'] == true
    show('zoom', zoom); show('zoom_speed', zoom and ui.get(r.zoom))
    show('aspect', aspect); show('aspect_preset', aspect and ui.get(r.aspect))
    show('aspect_amount', aspect and ui.get(r.aspect) and ui.get(r.aspect_preset) == 'Custom')
    show('viewmodel', viewmodel)
    for _, name in ipairs({'viewmodel_features', 'viewmodel_x', 'viewmodel_y', 'viewmodel_z', 'viewmodel_fov'}) do
        show(name, viewmodel and ui.get(r.viewmodel))
    end
    show('second_scope', second); show('second_amount', second and ui.get(r.second_scope))
    show('grenade_warning_color', selected['Grenade Warning'] == true)
    local hitmarkers_selected = selected['Hitmarkers'] == true
    local hitmarkers = hitmarkers_selected and ui.get(r.hitmarkers_enabled) == true
    local hitmarker_2d = hitmarkers and has_selection(r.hitmarker_types, '2D')
    local hitmarker_3d = hitmarkers and has_selection(r.hitmarker_types, '3D')
    show('hitmarkers_enabled', hitmarkers_selected)
    show('hitmarker_types', hitmarkers)
    show('hitmarker_2d_color', hitmarker_2d)
    show('hitmarker_2d_duration', hitmarker_2d)
    show('hitmarker_3d_color', hitmarker_3d)
    show('hitmarker_3d_duration', hitmarker_3d)
    local mode = ui.get(r.wm_mode)
    for _, name in ipairs({'wm_text', 'wm_font', 'wm_settings', 'wm_mode_label', 'wm_mode', 'wm_effect', 'wm_prefix_color', 'wm_postfix_color'}) do show(name, true) end
    show('wm_icons', self.watermark_settings_open == true)
    show('wm_guide', self.watermark_settings_open == true)
    show('wm_gradient_direction', false); show('wm_rainbow_direction', false)
    show('wm_pulse', has_selection(r.wm_effect, 'Pulse'))
    for _, name in ipairs({'wm_main_color'}) do show(name, mode == 'Default') end
    local animated_effect = has_selection(r.wm_effect, 'Wave') or has_selection(r.wm_effect, 'Shine')
        or has_selection(r.wm_effect, 'Typewriter') or has_selection(r.wm_effect, 'Glitch')
        or has_selection(r.wm_effect, 'Scramble')
    show('wm_speed', mode == 'Gradient' or mode == 'Rainbow' or animated_effect)
    for _, name in ipairs({'wm_inner_color', 'wm_outer_color', 'wm_gradient_direction_button'}) do show(name, mode == 'Gradient') end
    for _, name in ipairs({'wm_rainbow_saturation', 'wm_rainbow_direction_button'}) do show(name, mode == 'Rainbow') end
     
    local colors_open = mode == 'Default' or mode == 'Gradient' or true
    show('wm_picker_anchor', colors_open)
end
return visuals


end,

 
['menu'] = function(...)
 
local modules = ...
 
local function required_module(name)
    local module = modules[name]
    if type(module) ~= 'table' then
        error('[nyameeow.pink] embedded module is unavailable: ' .. tostring(name), 0)
    end
    return module
end
local native, profile, stats, text = modules.lib_custom_tab, modules.profile, modules.statistics, modules.text
local symbols, enemy_misses = required_module('symbols'), required_module('enemy_misses')
local pui_bridge = required_module('pui_bridge')
local menu = {page = 'Home', refs = {}, owned = {}, layout_page = nil, next_refresh = 0}
local groups = {
    {page = 'Home', icon = ''},
    {page = 'Ragebot', icon = ''},  
    {page = 'Anti-Aim', icon = ''},  
    {page = 'Visuals', icon = ''},  
    {page = 'Misc', icon = ''},
}
 
local aa_sections = {
    {name = 'Manipulations', icon = ''},    
    {name = 'Defensive', icon = ''},  
    {name = 'Additional', icon = ''},  
}
local function make_aa_options(r, g, b, a)
    local options = {}
    for i, section in ipairs(aa_sections) do
        options[i] = text.icon(section.icon, r, g, b, a) .. '\a858585FF  ' .. section.name .. '\r'
    end
    return options
end
local aa_options = make_aa_options(text.menu_color())
local function selected_aa_index(value)
    for i, section in ipairs(aa_sections) do
         
        if type(value) == 'string' and value:find(section.name, 1, true) then return i end
    end
    return 1
end
 
 
local function additional_page_name(value)
    if type(value) ~= 'string' then return nil end
    if value:find('Hotkeys', 1, true) then return 'Hotkeys' end
    if value == 'Settings' or value:find('Features', 1, true) then return 'Features' end
    return nil
end
local function icon_strip(items, current, r, g, b, a, neutral)
     
     
    local parts, gray = {}, ''
    local function flush_gray()
        if gray ~= '' then
            parts[#parts + 1] = neutral and text.icon(gray, unpack(neutral)) or text.ui_icon(gray)
            gray = ''
        end
    end
    for index, item in ipairs(items) do
        if index > 1 then gray = gray .. '  ·  ' end
        if (item.page or item.name) == current then
            flush_gray()
            parts[#parts + 1] = text.icon(item.icon, r, g, b, a)
        else
            gray = gray .. item.icon
        end
    end
    flush_gray()
    return table.concat(parts)
end
local function navigation_rows(expanded)
    local rows, labels = {}, {}
    local function add_row(row, label)
        rows[#rows + 1], labels[#labels + 1] = row, label
    end
    for _, group in ipairs(groups) do
        local marker = group.children and (expanded == group.page and '   ' or '   ') or ''
        add_row({page = group.page}, group.icon .. '    ' .. group.page .. marker)
        if group.page == expanded and group.children then
            for _, child in ipairs(group.children) do
                add_row({page = group.page, subpage = child}, '        ' .. symbols.format('\f<afterglow_arrow>') .. '  ' .. child)
            end
        end
    end
    return rows, labels
end
local window_names = {'Velocity Indicator', 'Damage Indicator', 'Crosshair Indicator'}
local world_names = {'Zoom Animation', 'Aspect Ratio', 'Viewmodel Changer', 'Force Second Zoom', 'Hitmarkers', 'Grenade Warning'}
local socials = {
    'https://discord.gg/CUHpYCamVj', 'https://t.me/gothsenselua',
    'https://www.youtube.com/@%D0%BD%D0%B5%D0%B1%D0%BE%D1%81%D0%B2%D0%BE%D0%B4%D0%B5%D0%BD'
}
local function add(self, ref) self.owned[#self.owned + 1] = ref; return ref end
local function label(self, col, value) return add(self, ui.new_label('LUA', col, value)) end
local visibility = {}
local function visible(ref, value)
    if ref and visibility[ref] ~= value then
        ui.set_visible(ref, value)
        visibility[ref] = value
    end
end
function menu:init()
     
     
    self.pui_bridge = pui_bridge
    pui_bridge.install()
    local grid = native.pack_grid
    local dpi_ok, dpi_ref = pcall(ui.reference, 'MISC', 'Settings', 'DPI scale')
    if dpi_ok then self.dpi_ref = dpi_ref end
    self.tab = native.create({
        position = 'after_lua', replace_existing = false,
        icon_path = 'nyameeow.pink-embedded.png', icon_data = modules.icon.png,
        categories = {
            {name = 'Navigation', grid = grid(0, 0, 12, 6)},
            {name = 'Home', grid = grid(0, 6, 12, 18)},
            {name = 'Session statistics', grid = grid(12, 0, 12, 8)},
            {name = 'Changelog', grid = grid(12, 8, 12, 5)},
            {name = 'Details', grid = grid(12, 13, 12, 11)},
            {name = 'Builder Settings', grid = grid(0, 6, 12, 3)},
        }
    })
    local refs = self.refs
    local rows, items = navigation_rows(nil)
    self.nav_rows = rows
    refs.nav_ornament = label(self, 'B', '  ·    ·    ·    ·  ')
    refs.nav = add(self, ui.new_listbox('LUA', 'B', '\n afterglow_navigation', items))
    ui.set(refs.nav, 0)
    ui.set_callback(refs.nav, function()
        if self.updating_nav then return end
        local index = ui.get(refs.nav)
        local route = type(index) == 'number' and self.nav_rows[index + 1] or nil
        if not route then return end
        self.page, self.subpage = route.page, nil
        self:refresh_visibility(true)
        self:refresh_text()
    end)
    self.tab:adopt_tail(1, 2, {refs.nav_ornament, refs.nav})
    self.tab:configure_listbox(refs.nav, {fit_items = true, hide_header = true})

    refs.placeholder = label(self, 'A', 'Features will be added module by module.')
    refs.windows_label = label(self, 'A', '   Windows')
    refs.windows_select = add(self, ui.new_multiselect('LUA', 'A', '\n afterglow_windows_select', unpack(window_names)))
     
    refs.window_velocity_color = add(self, ui.new_color_picker('LUA', 'A', 'Velocity Color', 200, 200, 200, 255))
    refs.window_damage_color = add(self, ui.new_color_picker('LUA', 'A', 'Damage Color', 255, 255, 255, 255))
    refs.window_crosshair_color = add(self, ui.new_color_picker('LUA', 'A', 'Crosshair Color', 140, 110, 115, 255))
    ui.set_callback(refs.windows_select, function()
        if self.active and self.visuals then self:refresh_visibility(true) end
    end)
    refs.window_before_settings_gap = label(self, 'A', ' ')
    refs.window_settings_label = label(self, 'A', symbols.format('\f<afterglow_arrow>') .. ' Settings')
    refs.window_settings = add(self, ui.new_combobox('LUA', 'A', '\n afterglow_window_settings', 'Damage Indicator', 'Crosshair Indicator'))
    refs.window_settings_damage = add(self, ui.new_combobox('LUA', 'A', '\n afterglow_window_settings_damage', 'Damage Indicator'))
    refs.window_settings_crosshair = add(self, ui.new_combobox('LUA', 'A', '\n afterglow_window_settings_crosshair', 'Crosshair Indicator'))
    refs.window_settings_gap = label(self, 'A', ' ')
    refs.window_style_label = label(self, 'A', symbols.format('\f<afterglow_arrow>') .. ' Style')
    refs.window_crosshair_style = add(self, ui.new_combobox('LUA', 'A', '\n afterglow_crosshair_style', 'Default', 'Japanese'))
    refs.window_style_gap = label(self, 'A', ' ')
    refs.window_damage_font = add(self, ui.new_combobox('LUA', 'A', symbols.format('\f<afterglow_arrow>') .. ' Indicator Font', 'Default', 'Small', 'Bold'))
    refs.window_damage_font_gap = label(self, 'A', ' ')
    refs.window_damage_override_only = add(self, ui.new_checkbox('LUA', 'A', symbols.format('\f<afterglow_dot>') .. ' Only During Override'))
    for _, ref in ipairs({refs.window_settings, refs.window_crosshair_style}) do
        ui.set_callback(ref, function()
            if self.active and not self.updating_window_settings then self:refresh_visibility(true) end
        end)
    end
    refs.world_gap = label(self, 'A', ' ')
    refs.world_label = label(self, 'A', '   World')
    refs.world_select = add(self, ui.new_multiselect('LUA', 'A', '\n afterglow_world_select', unpack(world_names)))
    ui.set_callback(refs.world_select, function()
        if self.active and self.visuals then self:refresh_visibility(true) end
    end)
    refs.windows_gap = label(self, 'A', ' ')
    refs.config_list = add(self, ui.new_listbox('LUA', 'A', '\nConfig List', {'No configs'}))
    refs.config_name = add(self, ui.new_textbox('LUA', 'A', 'Config name'))
    refs.include_label = label(self, 'A', symbols.format('\f<afterglow_arrow_accent>') .. ' Include')
    refs.config_include = add(self, ui.new_multiselect('LUA', 'A', '\n afterglow_config_include',
        'Ragebot', 'Anti-Aim', 'Visuals', 'Misc'))
    ui.set(refs.config_include, 'Ragebot', 'Anti-Aim', 'Visuals', 'Misc')
    local function config_action(action)
        return function()
            if not self.config then return end
            local ok, err = pcall(self.config[action], self.config)
            if not ok then self.config:report(false, err) end
        end
    end
    refs.config_create = add(self, ui.new_button('LUA', 'A', '   Create', config_action('create')))
    refs.config_load = add(self, ui.new_button('LUA', 'A', '   Load', config_action('load_preset')))
