end
function menu:refresh_visibility(force)
    if not self.active or not self.tab then return end
    local refs, home = self.refs, self.page == 'Home'
    local subpage = self.subpage or ''
    local nav_height = 6
    local feature_page = self.page == 'Visuals'
    local misc_page, rage_page, aa_page = self.page == 'Misc', self.page == 'Ragebot', self.page == 'Anti-Aim'
    local settings_open = aa_page and self.builder.settings_open
    local layout_key = tostring(nav_height) .. ':' .. self.page .. ':' .. tostring(settings_open)
    if self.nav_layout_height ~= layout_key then
        local grid = native.pack_grid
        local top, bottom_y, bottom_h, middle_y, middle_h = 8, 8, 5, 13, 11
        if feature_page then top, bottom_y, bottom_h, middle_y, middle_h = 10, 18, 6, 10, 8 end
        if misc_page then top, bottom_y, bottom_h, middle_y, middle_h = 12, 20, 4, 12, 12 end
        if aa_page then top, bottom_y, bottom_h, middle_y, middle_h = 16, 20, 4, 16, 8 end
        local settings_height = settings_open and 4 or 0
        if rage_page then
             
            self.tab:set_category_layouts({
                grid(0, 0, 12, nav_height), grid(0, nav_height, 12, 24 - nav_height),
                grid(12, 0, 12, 24), grid(12, 12, 12, 5),
                grid(12, 17, 12, 7), grid(0, nav_height, 12, 4),
            })
        else
            self.tab:set_category_layouts({
                grid(0, 0, 12, nav_height), grid(0, nav_height + settings_height, 12, 24 - nav_height - settings_height),
                grid(12, 0, 12, top), grid(12, bottom_y, 12, bottom_h),
                grid(12, middle_y, 12, middle_h), grid(0, nav_height, 12, 4),
            })
        end
        self.nav_layout_height = layout_key
    end
     
     
    local r, g, b, a = text.menu_color()
    local function header(icon, name)
        return text.icon(icon, r, g, b, a) .. '\aCCCCCCFF   ' .. name .. '\r'
    end
    local page_icons = {Home = '', Ragebot = '', ['Anti-Aim'] = '', Visuals = '', Misc = ''}
    local title = rage_page and 'Ragebot' or (aa_page and 'Builder' or self.page)
    if subpage ~= '' then title = title .. ' / ' .. subpage end
    self.tab:set_category_name(1, header('', 'Navigation'))
    self.tab:set_category_name(2, header(page_icons[self.page] or '', title))
    self.tab:set_category_name(6, header('', 'Builder Settings'))
    self.layout_page = self.page .. ':' .. subpage
    for _, ref in ipairs({refs.welcome, refs.build, refs.version, refs.stats_gap, refs.hitrate, refs.kills, refs.kd, refs.enemy_misses, refs.session,
        refs.change1, refs.change2, refs.change3, refs.info1, refs.info2, refs.info3, refs.username, refs.social, refs.open}) do visible(ref, home) end
    visible(refs.placeholder, not home and not feature_page and not misc_page and not rage_page and not aa_page)
    visible(refs.aa_ornament, aa_page)
    visible(refs.aa_section, aa_page)
    local section = aa_sections[selected_aa_index(ui.get(refs.aa_section))].name
    local is_additional = aa_page and section == 'Additional'
    visible(refs.aa_additional_page, is_additional)
    local additional = is_additional and additional_page_name(ui.get(refs.aa_additional_page)) == 'Features'
    visible(refs.aa_features_label, additional)
    visible(refs.aa_features, additional)
    visible(refs.aa_features_gap, additional)
    local function contains(ref, value)
        local selected = ui.get(ref)
        if type(selected) ~= 'table' then return false end
        for _, name in ipairs(selected) do if name == value then return true end end
        return false
    end
    local hotkeys_page = is_additional and additional_page_name(ui.get(refs.aa_additional_page)) == 'Hotkeys'
    visible(refs.aa_hotkeys_label, hotkeys_page)
    visible(refs.aa_hotkeys, hotkeys_page)
    visible(refs.aa_hotkeys_gap, hotkeys_page)
    local freestand = hotkeys_page and contains(refs.aa_hotkeys, 'Freestand')
    local manual = hotkeys_page and contains(refs.aa_hotkeys, 'Manual')
    local inverter = hotkeys_page and contains(refs.aa_hotkeys, 'Inverter')
    local edge_yaw = hotkeys_page and contains(refs.aa_hotkeys, 'Edge Yaw')
    local settings_hk = hotkeys_page and contains(refs.aa_hotkeys, 'Settings')
    local manual_e = settings_hk and ui.get(refs.aa_manual_e) == true
    visible(refs.aa_manual_end_gap, manual and (inverter or edge_yaw))
    visible(refs.aa_inverter, inverter)
    visible(refs.aa_inverter_gap, inverter and edge_yaw)
    visible(refs.aa_edge_yaw, edge_yaw)
    visible(refs.aa_edge_yaw_mode, edge_yaw)
    visible(refs.aa_settings_gap, settings_hk and (manual or inverter or edge_yaw))
    visible(refs.aa_manual_e, settings_hk)
    visible(refs.aa_manual_round_reset, settings_hk)
    visible(refs.aa_legit_fix_bomb, settings_hk)
    for _, ref in ipairs({refs.aa_freestand, refs.aa_freestand_disablers}) do visible(ref, freestand) end
    visible(refs.aa_manual_gap, freestand and manual)
    for _, ref in ipairs({refs.aa_manual_forward, refs.aa_manual_left, refs.aa_manual_right}) do
        visible(ref, manual and not manual_e)
    end
    visible(refs.aa_prefer_manual, manual)
    local safe = additional and contains(refs.aa_features, 'Safe Head')
    local backstab = additional and contains(refs.aa_features, 'Avoid Backstab')
    local warmup = additional and contains(refs.aa_features, 'Warmup AA')
    local break_lc = additional and contains(refs.aa_features, 'Break LC')
    visible(refs.aa_break_lc, break_lc)
    visible(refs.aa_break_lc_triggers, break_lc and ui.get(refs.aa_break_lc))
    visible(refs.aa_safe_head, safe)
    visible(refs.aa_safe_conditions, safe and ui.get(refs.aa_safe_head))
    visible(refs.aa_safe_height, safe and ui.get(refs.aa_safe_head) and contains(refs.aa_safe_conditions, 'Above enemy'))
    visible(refs.aa_backstab, backstab)
    visible(refs.aa_backstab_distance, backstab and ui.get(refs.aa_backstab))
    visible(refs.aa_warmup, warmup)
    local warmup_enabled = warmup and ui.get(refs.aa_warmup)
    for _, ref in ipairs({refs.aa_warmup_triggers, refs.aa_warmup_pitch, refs.aa_warmup_yaw,
        refs.aa_warmup_range, refs.aa_warmup_speed}) do visible(ref, warmup_enabled) end
    local anti_bruteforce = aa_page and section == 'Manipulations'
    visible(refs.ab_gap, anti_bruteforce)
    visible(refs.ab_enable, anti_bruteforce)
    local ab_enabled = anti_bruteforce and ui.get(refs.ab_enable) == true
    for _, ref in ipairs({refs.ab_conditions_label, refs.ab_conditions, refs.ab_conditions_gap,
        refs.ab_triggers_label, refs.ab_triggers, refs.ab_triggers_gap,
        refs.ab_mode_label, refs.ab_mode, refs.ab_side_gap, refs.ab_side_label, refs.ab_side, refs.ab_mode_gap,
        refs.ab_randomize_label, refs.ab_randomize, refs.ab_randomize_gap,
        refs.ab_timeout_label, refs.ab_timeout,
        refs.ab_notify_gap, refs.ab_notify_label, refs.ab_notify}) do
        visible(ref, ab_enabled)
    end
    visible(refs.windows_label, feature_page)
    visible(refs.windows_select, feature_page)
    local velocity_window = feature_page and contains(refs.windows_select, 'Velocity Indicator')
    visible(refs.window_velocity_color, velocity_window)
    local damage_window = feature_page and contains(refs.windows_select, 'Damage Indicator')
    local crosshair_window = feature_page and contains(refs.windows_select, 'Crosshair Indicator')
    visible(refs.window_damage_color, damage_window)
    visible(refs.window_crosshair_color, crosshair_window)
     
     
    local both_windows = damage_window and crosshair_window
    local damage_only = damage_window and not crosshair_window
    local crosshair_only = crosshair_window and not damage_window
    if both_windows and self.window_settings_key ~= 'both' then
        local previous = self.window_settings_key
        if previous == 'damage' or previous == 'crosshair' then
            self.updating_window_settings = true
            ui.set(refs.window_settings, previous == 'damage' and 'Damage Indicator' or 'Crosshair Indicator')
            self.updating_window_settings = false
        end
    end
    self.window_settings_key = both_windows and 'both' or damage_only and 'damage' or crosshair_only and 'crosshair' or nil
    local current_window = damage_only and 'Damage Indicator' or crosshair_only and 'Crosshair Indicator'
        or both_windows and ui.get(refs.window_settings) or nil
    local crosshair_settings = crosshair_window and current_window == 'Crosshair Indicator'
    local damage_settings = damage_window and current_window == 'Damage Indicator'
    local has_settings = damage_window or crosshair_window
    visible(refs.window_before_settings_gap, has_settings)
    visible(refs.window_settings_label, has_settings)
    visible(refs.window_settings, both_windows)
    visible(refs.window_settings_damage, damage_only)
    visible(refs.window_settings_crosshair, crosshair_only)
    visible(refs.window_settings_gap, crosshair_settings or damage_settings)
    visible(refs.window_style_label, crosshair_settings)
    visible(refs.window_crosshair_style, crosshair_settings)
    visible(refs.window_style_gap, crosshair_settings)
    visible(refs.window_damage_font, damage_settings)
    visible(refs.window_damage_font_gap, damage_settings)
    visible(refs.window_damage_override_only, damage_settings)
    visible(refs.windows_gap, feature_page)
    visible(refs.world_gap, feature_page)
    visible(refs.world_label, feature_page)
    visible(refs.world_select, feature_page)
    self.visuals:refresh(feature_page, ui.get(refs.world_select))
    self.misc_rage:refresh(self.page)
    self.builder:refresh(aa_page, section)
    if feature_page then
        self.tab:set_category_name(3, header('', 'World'))
        self.tab:set_category_name(4, header('', 'Notifications'))
        self.tab:set_category_name(5, header('', 'Watermark'))
    elseif aa_page then
        self.tab:set_category_name(3, header('', 'Anti-Aim'))
        self.tab:set_category_name(5, header('', 'Side & Actions'))
    elseif misc_page then
        self.tab:set_category_name(3, header('', 'Animation Breaker'))
        self.tab:set_category_name(5, header('', 'Utilities'))
    elseif rage_page then
        self.tab:set_category_name(3, header('', 'Utilities'))  
        self.tab:set_category_name(4, header('', 'Changelog'))  
        self.tab:set_category_name(5, header('', 'Fake Lag'))
    else
        self.tab:set_category_name(3, header('', 'Session statistics'))
        self.tab:set_category_name(4, header('', 'Changelog'))
        self.tab:set_category_name(5, header('', 'Details'))
    end
    for _, ref in ipairs({refs.config_list, refs.config_name, refs.include_label, refs.config_create, refs.config_load, refs.config_save, refs.config_delete}) do
        visible(ref, home)
    end
    local show_import_export = home and ui.get(refs.config_mode) == 'Local'
    visible(refs.config_import, show_import_export)
    visible(refs.config_export, show_import_export)
    visible(refs.footer1, true)
    visible(refs.footer2, true)
    for _, ref in ipairs({refs.user_status, refs.online_users, refs.config_mode, refs.config_include}) do
        visible(ref, home)
    end
     
    self.tab:set_category_visible(1, true)
    self.tab:set_category_visible(2, true)
    self.tab:set_category_visible(3, home or feature_page or misc_page or aa_page or rage_page)
    self.tab:set_category_visible(4, home or feature_page)
    self.tab:set_category_visible(5, home or feature_page or misc_page or aa_page)
    self.tab:set_category_visible(6, settings_open)
end
function menu:refresh_text()
    if not self.active then return end
    local refs, now = self.refs, globals.realtime() or 0
    local r, g, b, a = text.menu_color()
     
    if self.tab and self.tab:is_ready() then
         
         
         
        local nav_icons = icon_strip(groups, self.page, r, g, b, a, {200, 200, 200, 255})
        if self.last_nav_icons ~= nav_icons then
            ui.set(refs.nav_ornament, nav_icons)
            self.last_nav_icons = nav_icons
        end
        local active_section = aa_sections[selected_aa_index(ui.get(refs.aa_section))].name
        local section_icons = icon_strip(aa_sections, active_section, r, g, b, a)
        if self.last_section_icons ~= section_icons then
            ui.set(refs.aa_ornament, section_icons)
            self.last_section_icons = section_icons
        end
    end
    local name = text.gradient(profile.name(ui.get(refs.username)), now, r, g, b)
    local build = text.gradient(profile.build, now, r, g, b)
    local value = stats.values(now)
    local function grad(value) return text.gradient(tostring(value), now, r, g, b) end
    ui.set(refs.footer1, text.icon(' · °  ° · ', r, g, b, a) .. '  ' .. grad('nyameeow.pink'))
    if self.misc_rage and self.misc_rage.refs.fixes_label then
        self.misc_rage:refresh_ornaments(r, g, b, a)
    end
    ui.set(refs.welcome, text.line('⛹', 'Welcome back, ' .. name .. '!', r, g, b, a))
    ui.set(refs.build, text.plain("You're using the " .. build .. ' build.'))
    ui.set(refs.version, text.plain('Version: ' .. grad(profile.version)))
    ui.set(refs.hitrate, text.plain(string.format('Hit rate: %d / %d ', stats.hits, stats.shots) .. grad('(' .. value.hitrate .. '%)')))
    ui.set(refs.kills, text.plain('Kills: ' .. grad(stats.kills) .. '   |   Deaths: ' .. grad(stats.deaths)))
    ui.set(refs.kd, text.plain('K/D: ' .. grad(string.format('%.2f', value.kd))))
    ui.set(refs.enemy_misses, text.plain('Enemy misses (est.): ' .. grad(enemy_misses.count)))
    ui.set(refs.session, text.plain('Session time: ' .. grad(value.session)))
    local dot = text.icon('•', r, g, b, a)
    ui.set(refs.change1, dot .. text.plain('   Added expandable navigation'))
    ui.set(refs.change2, dot .. text.plain('   Reorganized Home panels'))
    ui.set(refs.change3, dot .. text.plain('   Added session K/D and hit rate'))
     
    local status = text.colors.user_status_unavailable
    local users = text.colors.online_users_unavailable
    ui.set(refs.user_status, text.icon('•', unpack(status))
        .. text.plain('   User status: ') .. text.icon('unavailable', unpack(status)))
    ui.set(refs.online_users, text.icon('•', unpack(users))
        .. text.plain('   Online users: ') .. text.icon('unavailable', unpack(users)))
    local current = string.format('%d:%d:%d:%d', r, g, b, a)
    if self.tab:is_ready() and self.last_button_color ~= current then
        ui.set(refs.include_label, symbols.format('\f<afterglow_arrow_accent>') .. ' Include')
        self.tab:set_control_name(refs.windows_label, text.icon('', r, g, b, a) .. text.plain('   Windows'))
        self.tab:set_control_name(refs.world_label, text.icon('', r, g, b, a) .. text.plain('   World'))
        self.tab:set_control_name(refs.aa_features_label, text.icon('', r, g, b, a) .. text.plain('   Features'))
        self.tab:set_control_name(refs.aa_hotkeys_label, text.icon('', r, g, b, a) .. text.plain('   Hotkeys'))
        self.tab:set_control_name(self.builder.refs.condition_label, text.icon('', r, g, b, a) .. text.plain('   State'))
        self.tab:set_control_name(self.builder.refs.team_label, text.icon('', r, g, b, a) .. text.plain('   Team'))
        local buttons = {
            {refs.config_create, '', 'Create'}, {refs.config_load, '', 'Load'},
            {refs.config_save, '', 'Save'}, {refs.config_delete, '', 'Delete'},
            {refs.config_import, '', 'Import'}, {refs.config_export, '', 'Export'},
            {refs.open, '', 'Open Page'},
            {self.builder.refs.copy, '', 'Copy'},
            {self.builder.refs.paste, '', 'Paste'},
            {self.builder.refs.send, '', 'Send to Opposite Side'},
            {self.visuals.refs.wm_icons, '', 'Heroicons Library'},
            {self.visuals.refs.wm_guide, '', 'Print Instruction in Chat'},
            {self.misc_rage.refs.event_guide, '', 'Print Instruction in Chat'},
            {self.misc_rage.refs.warmup, '', 'Warmup Setup'},
            {self.visuals.refs.test, '', 'Send Notification'},
        }
        for _, button in ipairs(buttons) do
             
             
            self.tab:set_control_name(button[1], text.icon(button[2], r, g, b, a) .. text.plain('   ' .. button[3]))
        end
        self.last_button_color = current
    end
     
    if self.tab and self.tab:is_ready() and self.builder and self.builder.refs.override then
        local state = tostring(ui.get(self.builder.refs.condition) or '')
        local enable_name = text.icon('', r, g, b, a)
            .. text.plain('   Enable  ·  ' .. state)
        if self.last_override_name ~= enable_name then
            self.tab:set_control_name(self.builder.refs.override, enable_name)
            self.last_override_name = enable_name
        end
    end
end
function menu:paint()
    if not self.active or not ui.is_menu_open() then return end
     
     
    if not self.tab or not self.tab:is_ready() then return end
    self:refresh_visibility(false)
    local now = globals.realtime() or 0
    if now >= self.next_refresh then self.next_refresh = now + 0.1; self:refresh_text() end
     
    if self.tab:is_active() and type(self.tab.center_navigation_icons) == 'function' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        self.tab:center_navigation_icons(1, self.refs.nav_ornament, self.refs.nav, dpi / 100)
        if self.page == 'Anti-Aim' then
            self.tab:center_navigation_icons(3, self.refs.aa_ornament, self.refs.aa_section, dpi / 100, 80)
        end
    end
    if self.page == 'Anti-Aim' and self.tab:is_active() and type(self.tab.layout_builder_state_row) == 'function' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local b = self.builder.refs
        self.tab:layout_builder_state_row(5, b.condition, b.settings_button, b.team, dpi / 100)
        local scale = dpi / 100
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(2, {b.yaw_gap, b.modifier_gap, b.modifier_options_gap, b.desync_gap, b.desync_options_gap, b.body_end_gap}, scale)
        end
        if type(self.tab.layout_inline_combo) == 'function' then
            self.tab:layout_inline_combo(2, b.modifier_label, b.modifier, b.yaw_value, scale, 92, nil, true)
            local body_combo = ui.get(b.second_yaw) and b.desync or b.desync_single
            self.tab:layout_inline_combo(2, b.desync_label, body_combo, b.yaw_value, scale, 92, nil, true)
            if ui.get(b.desync) == 'Static' and type(self.tab.layout_inline_combo_pair) == 'function' then
                self.tab:layout_inline_combo_pair(2, b.desync_label, body_combo, b.desync_direction, b.yaw_value, scale, 92)
            end
        end
        if self.builder.settings_open and type(self.tab.layout_inline_combo) == 'function' then
            local scale = dpi / 100
            if type(self.tab.layout_spacing_labels) == 'function' then
                self.tab:layout_spacing_labels(6, {b.settings_gap, b.send_gap}, scale)
            end
            if type(self.tab.layout_button_pair) == 'function' then
                self.tab:layout_button_pair(6, b.send, b.copy, b.paste, scale)
            end
            self.tab:layout_inline_combo(6, b.pitch_label, b.pitch, b.pitch_value, scale, 105, nil, true)
            self.tab:layout_inline_combo(6, b.yaw_base_label, b.yaw_base, b.pitch_value, scale, 105, nil, true)
        end
    end
    if self.page == 'Anti-Aim' and self.tab:is_active() and type(self.tab.layout_inline_combo) == 'function'
        and aa_sections[selected_aa_index(ui.get(self.refs.aa_section))].name == 'Manipulations' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local r, scale = self.refs, dpi / 100
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(3, {r.ab_gap, r.ab_conditions_gap, r.ab_triggers_gap, r.ab_side_gap, r.ab_mode_gap, r.ab_randomize_gap, r.ab_notify_gap}, scale)
        end
         
         
        local width = 0
        if type(self.tab.get_category_rect) == 'function' then
            local ok, _, _, measured = pcall(self.tab.get_category_rect, self.tab, 3)
            if ok and type(measured) == 'number' then width = measured end
        end
        local combos_inline = width == 0 or width >= 240 * scale
        local slider_inline = width == 0 or width >= 270 * scale
        local mode = (combos_inline and 'inline' or 'stacked') .. ':' .. (slider_inline and 'inline' or 'stacked')
        if self.ab_layout_mode ~= mode then
            self.ab_layout_mode = mode
            if (not combos_inline or not slider_inline) and type(self.tab.reflow_category) == 'function' then
                pcall(self.tab.reflow_category, self.tab, 3)
            end
        end
        if combos_inline then
            self.tab:layout_inline_combo(3, r.ab_conditions_label, r.ab_conditions, r.aa_section, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, r.ab_triggers_label, r.ab_triggers, r.aa_section, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, r.ab_mode_label, r.ab_mode, r.aa_section, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, r.ab_side_label, r.ab_side, r.aa_section, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, r.ab_notify_label, r.ab_notify, r.aa_section, scale, 92, nil, true)
        end
        if slider_inline and type(self.tab.layout_inline_slider) == 'function' then
            self.tab:layout_inline_slider(3, r.ab_randomize_label, r.ab_randomize, r.aa_section, scale, 92)
            self.tab:layout_inline_slider(3, r.ab_timeout_label, r.ab_timeout, r.aa_section, scale, 92)
        end
    end
    if self.page == 'Anti-Aim' and self.tab:is_active()
        and aa_sections[selected_aa_index(ui.get(self.refs.aa_section))].name == 'Manipulations' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local b, scale = self.builder.refs, dpi / 100
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(3, {b.delay_head_gap, b.delay_features_gap}, scale)
        end
        if type(self.tab.layout_inline_combo) == 'function' then
            self.tab:layout_inline_combo(3, b.delay_mode_label, b.delay_mode, b.delay_count, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, b.delay_features_label, b.delay_features, b.delay_count, scale, 92, nil, true)
        end
        if type(self.tab.layout_inline_slider) == 'function' then
            self.tab:layout_inline_slider(3, b.freeze_chance_label, b.freeze_chance, b.delay_count, scale, 82)
            self.tab:layout_inline_slider(3, b.freeze_time_label, b.freeze_time, b.delay_count, scale, 82)
            self.tab:layout_inline_slider(3, b.freeze_cooldown_label, b.freeze_cooldown, b.delay_count, scale, 82)
            self.tab:layout_inline_slider(3, b.disable_chance_label, b.disable_chance, b.delay_count, scale, 82)
            self.tab:layout_inline_slider(3, b.disable_time_label, b.disable_time, b.delay_count, scale, 82)
        end
    end
    if self.page == 'Anti-Aim' and self.tab:is_active()
        and aa_sections[selected_aa_index(ui.get(self.refs.aa_section))].name == 'Defensive' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local b, scale = self.builder.refs, dpi / 100
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(3, {
                b.defensive_gap, b.defensive_filters_gap, b.defensive_filter_row_gap, b.defensive_pitch_gap,
                b.defensive_pitch_options_gap, b.defensive_yaw_gap, b.defensive_yaw_options_gap,
                b.defensive_second_gap, b.defensive_delay_gap,
            }, scale)
        end
        if type(self.tab.layout_inline_combo) == 'function' then
            self.tab:layout_inline_combo(3, b.defensive_triggers_label, b.defensive_triggers, b.defensive_yaw_value, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, b.defensive_activation_label, b.defensive_activation, b.defensive_yaw_value, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, b.defensive_pitch_label, b.defensive_pitch, b.defensive_pitch_value, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, b.defensive_yaw_label, b.defensive_yaw, b.defensive_yaw_value, scale, 92, nil, true)
            self.tab:layout_inline_combo(3, b.defensive_switch_label, b.defensive_yaw_switch, b.defensive_yaw_second, scale, 92, nil, true)
        end
    end
    if self.page == 'Anti-Aim' and self.tab:is_active() and type(self.tab.layout_inline_combo) == 'function'
        and aa_sections[selected_aa_index(ui.get(self.refs.aa_section))].name == 'Additional'
        and additional_page_name(ui.get(self.refs.aa_additional_page)) == 'Features' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local r = self.refs
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(3, {r.aa_features_gap}, dpi / 100)
        end
        local selected = ui.get(r.aa_features)
        local warmup_selected = false
        if type(selected) == 'table' then
            for _, item in ipairs(selected) do if item == 'Warmup AA' then warmup_selected = true; break end end
        end
        if warmup_selected and ui.get(r.aa_warmup) then
            self.tab:layout_inline_combo(3, r.aa_warmup, r.aa_warmup_triggers, r.aa_section, dpi / 100, 125)
        end
        if type(selected) == 'table' and ui.get(r.aa_break_lc) then
            for _, item in ipairs(selected) do
                if item == 'Break LC' then
                    self.tab:layout_inline_combo(3, r.aa_break_lc, r.aa_break_lc_triggers, r.aa_section, dpi / 100, 100, nil, true)
                    break
                end
            end
        end
        self.tab:layout_inline_combo(3, r.aa_features_label, r.aa_features, r.aa_section, dpi / 100, 85)
    end
    if self.page == 'Anti-Aim' and self.tab:is_active() and type(self.tab.layout_inline_combo) == 'function'
        and aa_sections[selected_aa_index(ui.get(self.refs.aa_section))].name == 'Additional'
        and additional_page_name(ui.get(self.refs.aa_additional_page)) == 'Hotkeys' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local r, scale = self.refs, dpi / 100
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(3, {r.aa_hotkeys_gap, r.aa_manual_gap, r.aa_manual_end_gap, r.aa_inverter_gap, r.aa_settings_gap}, scale)
        end
        self.tab:layout_inline_combo(3, r.aa_hotkeys_label, r.aa_hotkeys, r.aa_section, scale, 85)
    end
    if self.page == 'Visuals' and self.tab:is_active() and type(self.tab.layout_inline_combo) == 'function' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local scale = dpi / 100
        local v = self.visuals.refs
        if type(self.tab.layout_watermark_compact) == 'function' then
            local stacked = self.tab:layout_watermark_compact(5, v, scale, self.visuals.watermark_stacked == true)
            if stacked ~= nil and stacked ~= self.visuals.watermark_stacked then
                self.visuals.watermark_stacked = stacked
                self.visuals:refresh(true, ui.get(self.refs.world_select))
            end
        end
        if type(self.tab.layout_watermark_speed_row) == 'function' then
            self.tab:layout_watermark_speed_row(5, v.wm_speed, v.wm_gradient_direction_button, v.wm_icons, scale)
            self.tab:layout_watermark_speed_row(5, v.wm_speed, v.wm_rainbow_direction_button, v.wm_icons, scale)
        end
        if not self.watermark_compact_labels then
             
            self.tab:set_control_name(v.wm_speed, symbols.format('\f<afterglow_dot>') .. ' Speed')
            self.tab:set_control_name(v.wm_rainbow_saturation, symbols.format('\f<afterglow_dot>') .. ' Saturation')
            self.watermark_compact_labels = true
        end
        self.watermark_direction_names = self.watermark_direction_names or {}
        for _, pair in ipairs({{v.wm_gradient_direction, v.wm_gradient_direction_button}, {v.wm_rainbow_direction, v.wm_rainbow_direction_button}}) do
            local direction = ui.get(pair[1]) == 'Left' and 'Left' or 'Right'
            if self.watermark_direction_names[pair[2]] ~= direction then
                self.tab:set_control_name(pair[2], direction == 'Left' and '' or '')
                self.watermark_direction_names[pair[2]] = direction
            end
        end
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(2, {self.refs.window_before_settings_gap, self.refs.window_settings_gap, self.refs.window_style_gap,
                self.refs.window_damage_font_gap, self.refs.world_gap, self.refs.windows_gap,
                v.manual_gap, v.output_gap, v.scope_length_spacing, v.scope_gap_spacing}, scale)
        end
        local pickers = {}
        if ui.get(v.manual) then
            local style = ui.get(v.manual_style)
            pickers = style == 'Team Skeet' and {v.yaw_color, v.body_color}
                or style == 'CS2' and {v.custom_color, v.idle_color}
                or style == 'Custom' and {v.custom_color}
                or style == 'Modern' and {v.arc_color} or {}
        end
        local world_pickers, selected_world = {}, ui.get(self.refs.world_select) or {}
        for _, name in ipairs(selected_world) do if name == 'Grenade Warning' then world_pickers[#world_pickers + 1] = v.grenade_warning_color end end
        if type(self.tab.layout_inline_pickers) == 'function' and #world_pickers > 0 then
            self.tab:layout_inline_pickers(2, self.refs.world_label, v.scope_color, world_pickers, scale, true)
        end
        local windows_pickers = {}
        local selected_windows = ui.get(self.refs.windows_select) or {}
        for _, name in ipairs(selected_windows) do
            if name == 'Velocity Indicator' then windows_pickers[#windows_pickers + 1] = self.refs.window_velocity_color end
        end
        for _, name in ipairs(selected_windows) do
            if name == 'Damage Indicator' then
                windows_pickers[#windows_pickers + 1] = self.refs.window_damage_color
            end
        end
        for _, name in ipairs(selected_windows) do
            if name == 'Crosshair Indicator' then windows_pickers[#windows_pickers + 1] = self.refs.window_crosshair_color end
        end
        if type(self.tab.layout_inline_pickers) == 'function' and #windows_pickers > 0 then
            self.tab:layout_inline_pickers(2, self.refs.windows_label, v.scope_color, windows_pickers, scale, true)
        end
        self.tab:layout_inline_combo(2, self.refs.windows_label, self.refs.windows_select, v.scope_length, scale, 85, windows_pickers, true)
        self.tab:layout_inline_combo(2, self.refs.window_settings_label, self.refs.window_settings, v.scope_length, scale, 85, nil, true)
        self.tab:layout_inline_combo(2, self.refs.window_settings_label, self.refs.window_settings_damage, v.scope_length, scale, 85, nil, true)
        self.tab:layout_inline_combo(2, self.refs.window_settings_label, self.refs.window_settings_crosshair, v.scope_length, scale, 85, nil, true)
        self.tab:layout_inline_combo(2, self.refs.window_style_label, self.refs.window_crosshair_style, v.scope_length, scale, 85, nil, true)
