            self.tab:layout_inline_pickers(2, self.refs.world_label, v.scope_color, world_pickers, scale, true)
        end
        self.tab:layout_inline_combo(2, self.refs.world_label, self.refs.world_select, v.scope_length, scale, 85, world_pickers, true)
        if type(self.tab.layout_inline_pickers) == 'function' and #pickers > 0 then
            self.tab:layout_inline_pickers(2, v.manual, v.scope_color, pickers, scale, true)
        end
        self.tab:layout_inline_combo(2, v.manual, v.manual_style, v.scope_length, scale, 125, pickers, true)
        self.tab:layout_inline_combo(2, v.output, v.output_style, v.scope_length, scale, 125)
        self.tab:layout_inline_combo(2, v.scope, v.scope_mode, v.scope_length, scale, 150, {v.scope_color})
        self.tab:layout_inline_combo(3, v.aspect, v.aspect_preset, v.zoom_speed, scale, 105)
        self.tab:layout_inline_combo(3, v.hitmarkers_enabled, v.hitmarker_types, v.hitmarker_2d_duration, scale, 105)
        if type(self.tab.layout_inline_pickers) == 'function' then
            self.tab:layout_inline_pickers(3, v.hitmarker_2d_duration, v.hitmarker_2d_color, {v.hitmarker_2d_color}, scale, true)
            self.tab:layout_inline_pickers(3, v.hitmarker_3d_duration, v.hitmarker_3d_color, {v.hitmarker_3d_color}, scale, true)
        end
        if type(self.tab.layout_inline_pickers) == 'function' and #pickers > 0 then
            self.tab:layout_inline_pickers(2, v.manual, v.scope_color, pickers, scale, true)
            self.tab:layout_inline_combo(2, v.manual, v.manual_style, v.scope_length, scale, 125, pickers, true)
        end
         
        if type(self.tab.layout_inline_pickers) == 'function' and #world_pickers > 0 then
            self.tab:layout_inline_pickers(2, self.refs.world_label, v.scope_color, world_pickers, scale, true)
        end
        self.tab:layout_inline_combo(2, self.refs.world_label, self.refs.world_select, v.scope_length, scale, 85, world_pickers, true)
    end
    if self.page == 'Misc' and self.tab:is_active() and type(self.tab.layout_inline_combo) == 'function' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local scale, m = dpi / 100, self.misc_rage.refs
        if type(self.tab.layout_spacing_labels) == 'function' then
            self.tab:layout_spacing_labels(2, {m.event_group_gap, m.trash_group_gap}, scale)
        end
        self.tab:layout_inline_combo(2, m.trash, m.trash_mode, m.send_time, scale, 115, nil, true)
        self.tab:layout_inline_combo(3, m.anim, m.anim_sections, m.static_delta, scale, 145, nil, true)
        self.tab:layout_inline_combo(2, m.event, m.event_triggers, m.send_time, scale, 125, nil, true)
        local pickers = {m.event_hit_color, m.event_miss_color}
        if type(self.tab.layout_inline_pickers) == 'function' then
            self.tab:layout_inline_pickers(2, m.event, m.event_miss_color, pickers, scale, true)
        end
         
        self.tab:layout_inline_combo(2, m.trash, m.trash_mode, m.send_time, scale, 115, nil, true)
        self.tab:layout_inline_combo(2, m.event, m.event_triggers, m.send_time, scale, 125, pickers, true)
    end
     
    if self.page == 'Ragebot' and self.tab:is_active() and type(self.tab.layout_inline_combo) == 'function' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local scale, m = dpi / 100, self.misc_rage.refs
        self.tab:layout_inline_combo(2, m.fixes_label, m.fixes_category, m.record_gap, scale, 118, nil, true)
        self.tab:layout_inline_combo(3, m.tools_label, m.tools_category, m.reset_delay, scale, 118, nil, true)
    end
    if self.tab:is_active() and type(self.tab.anchor_footer) == 'function' then
        local dpi = 100
        if self.dpi_ref then
            local ok, value = pcall(ui.get, self.dpi_ref)
            if ok then dpi = tonumber(tostring(value):match('(%d+)')) or 100 end
        end
        local buttons = {
            self.refs.config_create, self.refs.config_load, self.refs.config_save,
            self.refs.config_delete, self.refs.config_import, self.refs.config_export
        }
        if self.page == 'Home' and type(self.tab.layout_config_grid) == 'function' then
            self.tab:layout_config_grid(2, self.refs.config_list, self.refs.config_include, buttons, dpi / 100)
            if type(self.tab.fit_config_list) == 'function' then
                self.tab:fit_config_list(2, self.refs.config_list, self.refs.footer1, self.refs.footer2, buttons, dpi / 100)
                self.tab:layout_config_grid(2, self.refs.config_list, self.refs.config_include, buttons, dpi / 100)
            end
        end
        local collisions = {}
        local function add(ref, combo)
            if ref then collisions[#collisions + 1] = combo and {ref = ref, combo = true} or ref end
        end
        local function add_all(refs, names, combo)
            for _, name in ipairs(names) do add(refs[name], combo) end
        end
        if self.page == 'Home' then
            add_all(self.refs, {'config_list','config_name','include_label','config_create','config_load','config_save','config_delete','config_import','config_export'})
        elseif self.page == 'Visuals' then
            local v = self.visuals.refs
            add_all(self.refs, {'windows_label','window_settings_label','window_style_label','window_damage_override_only','world_gap','world_label','windows_gap'})
            add_all(v, {'manual','manual_gap','left_symbol','right_symbol','forward_symbol','output','output_gap','scope','scope_length','scope_length_spacing','scope_gap','scope_gap_spacing','scope_speed'})
            add_all(self.refs, {'window_settings','window_settings_damage','window_settings_crosshair','window_crosshair_style','window_damage_font'}, true)
            add_all(v, {'manual_style','manual_font','output_style','scope_mode','scope_options_default','scope_options_rotated'}, true)
        elseif self.page == 'Misc' then
            local m = self.misc_rage.refs
            add_all(m, {'event','event_prefix','event_guide','event_group_gap','trash','spectating','send_time','message_interval','trash_group_gap','teammate','enemy_chat','allow_duck_fd','unlock_cvars','drop_nades','fast_ladder','avoid_flying','edge_quick_stop'})
            add_all(m, {'event_triggers','trash_mode','bait_events','author_events','drop_grenades'}, true)
        elseif self.page == 'Ragebot' then
            local m = self.misc_rage.refs
            add(m.fixes_category, true)
            add_all(m, {'air_strafe','strafe_smoothing','quick_stop','air_autostop','spread_autostop','dt_stability',
                'dt_return','backtrack','lag_records','extended_records','record_gap','extended_gap','adaptive',
                'prediction_stats','shot_delay','scan_accuracy','animation_flags'})
        elseif self.page == 'Anti-Aim' then
            local b = self.builder.refs
            local combos = {}
            for _, name in ipairs({'condition', 'yaw_base', 'pitch', 'delay_mode', 'delay_features', 'modifier', 'desync', 'desync_single', 'desync_direction'}) do
                combos[b[name]] = true
            end
            for _, ref in ipairs(self.builder.left_refs) do add(ref, combos[ref]) end
        else
            add(self.refs.placeholder)
        end
        self.tab:anchor_footer(2, self.refs.footer1, self.refs.footer2, dpi / 100, collisions)
    end
end
function menu:shutdown()
    if self.config and type(self.config.shutdown) == 'function' then
        local ok, err = pcall(self.config.shutdown, self.config)
        if not ok and client.error_log then client.error_log('[nyameeow.pink] Textbox save: ' .. tostring(err)) end
    end
    self.active = false
    for _, ref in ipairs(self.owned) do pcall(ui.set_visible, ref, false) end
    native.shutdown()
    if self.pui_bridge and type(self.pui_bridge.uninstall) == 'function' then
        pcall(self.pui_bridge.uninstall)
    end
    self.tab = nil
end
return menu


end,

 
