local function clone(value)
    if type(value) ~= 'table' then return value end
    local out = {}
    for key, item in pairs(value) do out[key] = clone(item) end
    return out
end
local function equal(a, b)
    if type(a) ~= type(b) then return false end
    if type(a) ~= 'table' then return a == b end
    for key, value in pairs(a) do if not equal(value, b[key]) then return false end end
    for key in pairs(b) do if a[key] == nil then return false end end
    return true
end
local function is_array(value)
    if type(value) ~= 'table' then return false end
    local count = 0
    for key in pairs(value) do
        if type(key) ~= 'number' or key < 1 or key ~= math.floor(key) then return false end
        count = count + 1
    end
    for i = 1, count do if value[i] == nil then return false end end
    return true
end
local function difference(base, current)
    if equal(base, current) then return nil end
    if type(base) ~= 'table' or type(current) ~= 'table' or is_array(base) or is_array(current) then
        return clone(current)
    end
    local out = {}
    for key, value in pairs(current) do
        local changed = difference(base[key], value)
        if changed ~= nil then out[key] = changed end
    end
    return out
end
local function merge(base, patch)
    if type(base) ~= 'table' or type(patch) ~= 'table' then return clone(patch) end
    if is_array(base) then return clone(patch) end
    if is_array(patch) then return next(patch) == nil and clone(base) or clone(patch) end
    local out = clone(base)
    for key, value in pairs(patch) do out[key] = merge(out[key], value) end
    return out
end
local function put_byte(out, value) out[#out + 1] = string.char(value % 256) end
local function put_u16(out, value)
    put_byte(out, value % 256); put_byte(out, math.floor(value / 256) % 256)
end
local function put_u32(out, value)
    put_byte(out, value % 256); put_byte(out, math.floor(value / 256) % 256)
    put_byte(out, math.floor(value / 65536) % 256); put_byte(out, math.floor(value / 16777216) % 256)
end
local function put_varint(out, value)
    value = math.floor(value)
    while value >= 128 do put_byte(out, value % 128 + 128); value = math.floor(value / 128) end
    put_byte(out, value)
end
local function checksum(value)
    local a, b = 0, 0
    for i = 1, #value do
        a = (a + value:byte(i)) % 65535
        b = (b + a) % 65535
    end
    return b * 65536 + a
end
local function encode_value(value, out, depth, counter)
    depth = depth or 0
    if depth > 12 then error('Preset nesting is too deep', 0) end
    counter[1] = counter[1] + 1
    if counter[1] > MAX_NODES then error('Preset has too many values', 0) end
    local kind = type(value)
    if kind == 'boolean' then
        put_byte(out, value and 2 or 1)
    elseif kind == 'number' then
        if value ~= value or value == math.huge or value == -math.huge then error('Preset numbers must be finite', 0) end
        if value == math.floor(value) then
            if math.abs(value) > 4503599627370496 then error('Preset integer is out of range', 0) end
            put_byte(out, 3)
            local encoded = value >= 0 and value * 2 or -value * 2 - 1
            put_varint(out, encoded)
        else
            local text = string.format('%.17g', value)
            put_byte(out, 7); put_varint(out, #text); out[#out + 1] = text
        end
    elseif kind == 'string' then
        if #value > MAX_PAYLOAD then error('Preset string is too long', 0) end
        put_byte(out, 4); put_varint(out, #value); out[#out + 1] = value
    elseif kind == 'table' then
        if is_array(value) then
            put_byte(out, 5); put_varint(out, #value)
            for _, item in ipairs(value) do encode_value(item, out, depth + 1, counter) end
        else
            local keys = {}
            for key in pairs(value) do
                if type(key) ~= 'string' then error('Preset map keys must be strings', 0) end
                keys[#keys + 1] = key
            end
            table.sort(keys)
            put_byte(out, 6); put_varint(out, #keys)
            for _, key in ipairs(keys) do
                put_byte(out, 4); put_varint(out, #key); out[#out + 1] = key
                encode_value(value[key], out, depth + 1, counter)
            end
        end
    else
        error('Unsupported preset value: ' .. kind, 0)
    end
end
local function encode_data(value)
    local out = {}
    encode_value(value, out, 0, {0})
    return table.concat(out)
end
local function reader(value)
    return {data = value, pos = 1, nodes = 0}
end
local function take(raw, count)
    if count < 0 or raw.pos + count - 1 > #raw.data then error('Truncated preset data', 0) end
    local value = raw.data:sub(raw.pos, raw.pos + count - 1)
    raw.pos = raw.pos + count
    return value
end
local function read_byte(raw) return take(raw, 1):byte() end
local function read_u16(raw) local a, b = take(raw, 2):byte(1, 2); return a + b * 256 end
local function read_u32(raw)
    local a, b, c, d = take(raw, 4):byte(1, 4)
    return a + b * 256 + c * 65536 + d * 16777216
end
local function read_varint(raw)
    local value, shift = 0, 1
    for i = 1, 10 do
        local byte = read_byte(raw)
        value = value + (byte % 128) * shift
        if byte < 128 then return value end
        shift = shift * 128
    end
    error('Invalid preset varint', 0)
end
local function read_string(raw)
    local length = read_varint(raw)
    if length > MAX_PAYLOAD then error('Preset string is too long', 0) end
    return take(raw, length)
end
local function decode_value(raw, depth)
    depth = depth or 0
    if depth > 12 then error('Preset nesting is too deep', 0) end
    raw.nodes = raw.nodes + 1
    if raw.nodes > MAX_NODES then error('Preset has too many values', 0) end
    local tag = read_byte(raw)
    if tag == 1 then return false
    elseif tag == 2 then return true
    elseif tag == 3 then
        local value = read_varint(raw)
        if value > 9007199254740991 then error('Preset number is out of range', 0) end
        return value % 2 == 0 and value / 2 or -math.floor(value / 2) - 1
    elseif tag == 4 then return read_string(raw)
    elseif tag == 7 then
        local value = tonumber(read_string(raw))
        if value == nil or value ~= value or value == math.huge or value == -math.huge then error('Invalid preset number', 0) end
        return value
    elseif tag == 5 or tag == 6 then
        local count = read_varint(raw)
        local out = {}
        if count > MAX_NODES or count > #raw.data - raw.pos + 1 then error('Invalid preset table size', 0) end
        if tag == 5 then
            for i = 1, count do out[i] = decode_value(raw, depth + 1) end
        else
            for _ = 1, count do
                if read_byte(raw) ~= 4 then error('Invalid preset map key', 0) end
                local key = read_string(raw)
                if out[key] ~= nil then error('Duplicate preset map key', 0) end
                out[key] = decode_value(raw, depth + 1)
            end
        end
        return out
    end
    error('Unknown preset value tag', 0)
end
local function decode_data(value, raw)
    raw = raw or reader(value)
    local out = decode_value(raw)
    if raw.pos ~= #value + 1 then error('Trailing preset data', 0) end
    return out
end
local function valid_name(name, allow_default)
    if type(name) ~= 'string' or #name == 0 or #name > MAX_NAME then return false end
    if name:match('^%s') or name:match('%s$') or name:find('[%c/\\:*?"<>|]') then return false end
    if not allow_default and name:lower() == 'default' then return false end
    return true
end
local function valid_sound_name(value)
    return value == 'Off' or (type(value) == 'string' and #value <= 240 and not value:find('[%c/\\:]')
        and not value:find('..', 1, true) and value:lower():sub(-4) == '.wav')
end
local function validate_data_shape(data, mask, name)
    if type(data) ~= 'table' then error('Invalid preset data: ' .. tostring(name), 0) end
    if data.format == 'pui-v1' then
        if type(data.pui) ~= 'table' then error('Missing unified PUI snapshot', 0) end
        for key in pairs(data) do
            if key ~= 'format' and key ~= 'pui' then error('Unknown unified preset field: ' .. tostring(key), 0) end
        end
        local group_bits = {rage = 1, aa = 2, visuals = 4, misc = 8}
        for key, bit in pairs(group_bits) do
            local included = mask % (bit * 2) >= bit
            if included then
                if type(data.pui[key]) ~= 'table' then error('Missing PUI section: ' .. key, 0) end
            elseif data.pui[key] ~= nil then
                error('PUI preset contains an excluded section: ' .. key, 0)
            end
        end
        for key, value in pairs(data.pui) do
            if not group_bits[key] or type(value) ~= 'table' then error('Invalid PUI section: ' .. tostring(key), 0) end
        end
        return
    end
    local allowed = {rage = true, aa = true, visuals = true, misc = true}
    for key in pairs(data) do if not allowed[key] then error('Unknown preset section: ' .. tostring(key), 0) end end
    for _, section in ipairs(SECTIONS) do
        local key = section.name == 'Ragebot' and 'rage' or section.name == 'Anti-Aim' and 'aa'
            or section.name == 'Visuals' and 'visuals' or 'misc'
        local present = mask % (section.bit * 2) >= section.bit
        if present then
            if type(data[key]) ~= 'table' then error('Missing preset section: ' .. key, 0) end
        elseif data[key] ~= nil then
            error('Preset contains an excluded section: ' .. key, 0)
        end
    end
    if data.aa then
        local fields = {values = true, states = true, defensive = true, selection = true, pui = true}
        for key, value in pairs(data.aa) do
            if not fields[key] then error('Invalid Anti-Aim preset field', 0) end
            if key == 'pui' then
                if type(value) ~= 'table' and type(value) ~= 'string' then error('Invalid PUI AA package', 0) end
            elseif type(value) ~= 'table' then
                error('Invalid Anti-Aim preset field', 0)
            end
        end
    end
    if data.visuals then
        local fields = {values = true, controls = true, textboxes = true}
        for key, value in pairs(data.visuals) do
            if not fields[key] then error('Invalid Visuals preset field', 0) end
            if key == 'textboxes' then
                if type(value) ~= 'table' and type(value) ~= 'string' then error('Invalid PUI textbox package', 0) end
            elseif type(value) ~= 'table' then
                error('Invalid Visuals preset field', 0)
            end
        end
    end
    if data.misc then
        local fields = {values = true, f12 = true, textboxes = true}
        for key, value in pairs(data.misc) do
            if not fields[key] then error('Invalid Misc preset field', 0) end
            if key == 'textboxes' then
                if type(value) ~= 'table' and type(value) ~= 'string' then error('Invalid PUI textbox package', 0) end
            elseif type(value) ~= 'table' then
                error('Invalid Misc preset field', 0)
            end
        end
        for key, value in pairs(data.misc.f12 or {}) do
            if key ~= 'f12_kill' and key ~= 'f12_miss' or not valid_sound_name(value) then error('Invalid F12 preset choice', 0) end
        end
    end
end
local function encode_preset(entry)
    if not valid_name(entry.name, true) or type(entry.mask) ~= 'number' or entry.mask < 1 or entry.mask > 15
        or entry.mask ~= math.floor(entry.mask) or type(entry.data) ~= 'table' then error('Invalid preset', 0) end
    validate_data_shape(entry.data, entry.mask, entry.name)
    local payload = encode_data(entry.data)
    if #payload > MAX_PAYLOAD then error('Preset payload is too large', 0) end
    local out = {}
    put_u16(out, #entry.name); out[#out + 1] = entry.name
    put_byte(out, entry.mask); put_byte(out, 0); put_u32(out, #payload); out[#out + 1] = payload
    put_u32(out, checksum(table.concat(out)))
    return table.concat(out)
end
local function read_preset(raw)
    local length = read_u16(raw)
    if length == 0 or length > MAX_NAME then error('Invalid preset name length', 0) end
    local name = take(raw, length)
    if not valid_name(name, true) then error('Invalid preset name', 0) end
    local mask, flags = read_byte(raw), read_byte(raw)
    if mask < 1 or mask > 15 or flags ~= 0 then error('Invalid preset header', 0) end
    local size = read_u32(raw)
    if size > MAX_PAYLOAD or size > #raw.data - raw.pos + 1 then error('Invalid preset payload size', 0) end
    local payload = take(raw, size)
    local expected = read_u32(raw)
    local record = string.char(length % 256, math.floor(length / 256)) .. name .. string.char(mask, flags)
        .. string.char(size % 256, math.floor(size / 256) % 256, math.floor(size / 65536) % 256, math.floor(size / 16777216)) .. payload
    if checksum(record) ~= expected then error('Preset checksum mismatch', 0) end
    local data = decode_data(payload)
    validate_data_shape(data, mask, name)
    return {name = name, mask = mask, data = data}, raw.pos
end
function config.encode_data(value) return encode_data(value) end
function config.decode_data(value) return decode_data(value) end
function config.encode_preset(entry) return encode_preset(entry) end
function config.decode_preset(value)
    if type(value) ~= 'string' or #value > MAX_PAYLOAD + 128 then error('Invalid preset blob', 0) end
    local raw = reader(value)
    local entry = read_preset(raw)
    if raw.pos ~= #value + 1 then error('Trailing preset data', 0) end
    return entry
end
function config.encode_file(presets)
    if type(presets) ~= 'table' or #presets > MAX_PRESETS then error('Invalid preset collection', 0) end
    local ordered = {}
    for _, entry in ipairs(presets) do
        if entry.default or entry.name:lower() == 'default' then error('Default presets are read-only', 0) end
        ordered[#ordered + 1] = entry
    end
    table.sort(ordered, function(a, b) return a.name:lower() < b.name:lower() end)
    local out = {MAGIC, string.char(VERSION)}
    put_u32(out, #ordered)
    for _, entry in ipairs(ordered) do out[#out + 1] = encode_preset(entry) end
    local value = table.concat(out)
    if #value > MAX_FILE then error('Preset file is too large', 0) end
    return value
end
function config.decode_file(value)
    if type(value) ~= 'string' or #value < 9 or #value > MAX_FILE or value:sub(1, 4) ~= MAGIC then error('Invalid preset file header', 0) end
    local version = value:byte(5)
    if version ~= 1 and version ~= 2 and version ~= VERSION then error('Unsupported preset file version', 0) end
    local raw = reader(value)
    raw.pos = 6
    local count = read_u32(raw)
    if count > MAX_PRESETS then error('Too many presets', 0) end
    local out, names = {}, {}
    for _ = 1, count do
        local entry = read_preset(raw)
        local key = entry.name:lower()
        if names[key] or key == 'default' then error('Duplicate or reserved preset name', 0) end
        names[key] = true
        out[#out + 1] = entry
    end
    if version == 2 then
        local size = read_u32(raw)
        if size > MAX_PAYLOAD or size > #value - raw.pos + 1 then error('Invalid legacy state payload size', 0) end
        local payload = take(raw, size)
        local expected = read_u32(raw)
        if checksum(payload) ~= expected then error('Legacy state checksum mismatch', 0) end
    end    if raw.pos ~= #value + 1 then error('Trailing preset file data', 0) end
    return out, version
end
function config.encode_aa(values) return encode_data(values) end
function config.decode_aa(value) return decode_data(value) end

 
local function safe_package_save(package)
    if package == nil then error('PUI package is not initialized', 0) end
    local method_ok, save = pcall(function() return package.save end)
    if not method_ok or type(save) ~= 'function' then error('PUI package has no save() method', 0) end
    local ok, value = pcall(save, package)
    if not ok then error('PUI package save() failed: ' .. tostring(value), 0) end
    if type(value) ~= 'table' then error('PUI package save() returned ' .. type(value) .. ', expected table', 0) end
    return value
end
local function safe_package_load(package, value)
    if package == nil or (type(value) ~= 'table' and type(value) ~= 'string') then return false end
    local method_ok, load = pcall(function() return package.load end)
    if not method_ok or type(load) ~= 'function' then return false end
    local ok, result = pcall(load, package, value)
    return ok and result ~= false
end

local function read_ui(ref, hotkey)
    local values = {pcall(ui.get, ref)}
    local ok = table.remove(values, 1)
    if not ok then error(values[1], 0) end
    if hotkey then return {values[2] or 'Always on', tonumber(values[3]) or 0} end
    if #values == 1 then return values[1] end
    return values
end
local function write_ui(ref, value, hotkey)
    if hotkey then
        ui.set(ref, type(value) == 'table' and value[1] or 'Always on', type(value) == 'table' and tonumber(value[2]) or 0)
    elseif type(value) == 'table' then
        ui.set(ref, unpack(value))
    else
        ui.set(ref, value)
    end
end
local function read_values(refs, keys)
    local out = {}
    for _, key in ipairs(keys) do
         
         
        if refs[key] ~= nil and not HOTKEYS[key] then
            out[key] = read_ui(refs[key], false)
        end
    end
    return out
end
local function write_values(refs, keys, values)
    for _, key in ipairs(keys) do
         
        if refs[key] ~= nil and values[key] ~= nil and not HOTKEYS[key] then
            write_ui(refs[key], values[key], false)
        end
    end
end
