local HOTKEY_MODES = {alwayson = true, onhotkey = true, toggle = true, offhotkey = true}
local function validate_ui_patch(refs, keys, allowed, patch, label)
    if type(patch) ~= 'table' then error('Invalid ' .. label .. ' values', 0) end
    for key, value in pairs(patch) do
        local ref = refs[key]
        if not allowed[key] or ref == nil then error('Unknown ' .. label .. ' control: ' .. tostring(key), 0) end
        local current = read_ui(ref, HOTKEYS[key])
        local rule = CONTROL_RULES[key]
        if HOTKEYS[key] then
             
             
             
             
        elseif rule then
            if rule.kind == 'slider' then
                if type(value) ~= 'number' or value < rule.min or value > rule.max then error('Invalid slider value: ' .. key, 0) end
            elseif rule.kind == 'multi' then
                if not is_array(value) then error('Invalid multiselect value: ' .. key, 0) end
                local options = key_lookup(rule.options)
                for _, item in ipairs(value) do
                    if type(item) ~= 'string' or not options[item] then error('Invalid multiselect value: ' .. key, 0) end
                end
            else
                local found = false
                for _, option in ipairs(rule.options) do
                    if rule.kind == 'contains' and type(value) == 'string' and value:find(option, 1, true)
                        or rule.kind ~= 'contains' and value == option then found = true; break end
                end
                if not found then error('Invalid option value: ' .. key, 0) end
            end
        elseif type(value) ~= type(current) then
            error('Invalid value type for ' .. label .. ':' .. key, 0) end
        if type(current) == 'table' and not HOTKEYS[key] and not rule then
            local color = #current == 4
            for i = 1, 4 do if type(current[i]) ~= 'number' then color = false end end
            if color then
                if #value ~= 4 then error('Invalid color value: ' .. key, 0) end
                for i = 1, 4 do
                    if type(value[i]) ~= 'number' or value[i] < 0 or value[i] > 255 or value[i] ~= math.floor(value[i]) then
                        error('Invalid color value: ' .. key, 0)
                    end
                end
            else
                if not is_array(value) then error('Invalid multiselect value: ' .. key, 0) end
                for _, item in ipairs(value) do if type(item) ~= 'string' then error('Invalid multiselect value: ' .. key, 0) end end
            end
        end
    end
end
local function validate_spec_patch(specs, patch, label)
    if type(patch) ~= 'table' then error('Invalid ' .. label .. ' state', 0) end
    for key, value in pairs(patch) do
        local spec = specs[key]
        if not spec then error('Unknown ' .. label .. ' value: ' .. tostring(key), 0) end
        if spec.kind == 'checkbox' then
            if type(value) ~= 'boolean' then error('Invalid checkbox value: ' .. key, 0) end
        elseif spec.kind == 'slider' then
            if type(value) ~= 'number' or value ~= value or value == math.huge or value == -math.huge or value < spec.min or value > spec.max then error('Invalid slider value: ' .. key, 0) end
        elseif spec.kind == 'combo' then
            local found = false
            for _, option in ipairs(spec.options) do if value == option then found = true; break end end
            if not found then error('Invalid combo value: ' .. key, 0) end
        elseif spec.kind == 'multi' then
            if not is_array(value) then error('Invalid multiselect value: ' .. key, 0) end
            local options = key_lookup(spec.options)
            for _, item in ipairs(value) do if type(item) ~= 'string' or not options[item] then error('Invalid multiselect value: ' .. key, 0) end end
        end
    end
end
local function default_builder_states(builder)
    local states, defensive = {}, {}
    for _, team in ipairs(BUILDER_TEAMS) do
        for _, condition in ipairs(BUILDER_CONDITIONS) do states[team .. ':' .. condition] = clone(builder.defaults) end
    end
    for _, condition in ipairs(BUILDER_CONDITIONS) do
        local values = {}
        for key, spec in pairs(builder.defensive_specs or {}) do values[key] = clone(spec.default) end
        defensive[condition] = values
    end
    return states, defensive
end
local function current_builder_states(builder, fallback)
    builder.states = builder.states or {}
    builder.defensive_states = builder.defensive_states or {}

    local active_key = builder:state_key()
    builder.current_key = active_key
    builder.states[active_key] = builder:snapshot()

    local active_condition = ui.get(builder.refs.condition)
    if active_condition ~= nil then
        builder.defensive_current = active_condition
        builder.defensive_states[active_condition] = builder:defensive_snapshot()
    end

    local states, defensive = clone(fallback[1]), clone(fallback[2])
    for key, value in pairs(builder.states) do states[key] = clone(value) end
    for key, value in pairs(builder.defensive_states) do defensive[key] = clone(value) end
    return states, defensive
end
local function trim(value) return (tostring(value or ''):gsub('^%s+', ''):gsub('%s+$', '')) end
local function append_list(list, entry)
    local out = {}
    for _, item in ipairs(list) do out[#out + 1] = item end
    out[#out + 1] = entry
    return out
end
local function remove_list(list, entry)
    local out = {}
    for _, item in ipairs(list) do if item ~= entry then out[#out + 1] = item end end
    return out
end
local function has(values, name)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == name then return true end end
    return false
end
local function intersect(a, b)
    local out = 0
    for _, section in ipairs(SECTIONS) do
        if a % (section.bit * 2) >= section.bit and b % (section.bit * 2) >= section.bit then out = out + section.bit end
    end
    return out
end

