            self.total = total
            self.remaining = math.max(0, total - self.elapsed)
        end
        if self.remaining > 0 then
             
            cmd.no_choke = false
            if fresh then self.elapsed = self.elapsed + 1; self.remaining = math.max(0, self.total - self.elapsed) end
        end
    end
end
