end,

 
['rage_fixes'] = function(...)
 
 
 
local modules = ...
local fixes = {}
local warned = {}

local function guard(name, fn, ...)
    local ok, err = pcall(fn, ...)
    if not ok and not warned[name] then
        warned[name] = true
        pcall(client.error_log, '[nyameeow.pink] ' .. name .. ': ' .. tostring(err))
    end
    return ok
end
 
 
local function read_control(ref)
    if not ref then return nil end
    if type(ref) == 'table' and ref.list ~= nil then
        local ok, values = pcall(ui.get, ref.list)
        if not ok or type(values) ~= 'table' then return nil end
        for _, value in ipairs(values) do if value == ref.option then return true end end
        return false
    end
    local ok, value = pcall(ui.get, ref)
    if ok then return value end
    return nil
end
local function write_control(ref, value)
    if not ref then return end
    if not (type(ref) == 'table' and ref.list ~= nil) then pcall(ui.set, ref, value); return end
    local ok, values = pcall(ui.get, ref.list)
    if not ok or type(values) ~= 'table' then return end
    local list, present = {}, false
    for _, item in ipairs(values) do
        if item == ref.option then present = true else list[#list + 1] = item end
    end
    if value and not present then list[#list + 1] = ref.option end
    if present ~= not not value then pcall(ui.set, ref.list, list) end
end
local function control_on(ref)
    local value = read_control(ref)
    return value == true
end

local ffi = require('ffi')
pcall(ffi.cdef, [[
typedef struct {
    void* base;
    void* allocation_base;
    uint32_t allocation_protect;
    uintptr_t region_size;
    uint32_t state;
    uint32_t protect;
    uint32_t kind;
