]])
 
 
local kernel
do
    local function bind_with(bind)
        local ok, api = pcall(function()
            return {
                VirtualQuery = bind('kernel32.dll', 'VirtualQuery', 'uintptr_t', {'uintptr_t', 'void*', 'uintptr_t'}),
                VirtualProtect = bind('kernel32.dll', 'VirtualProtect', 'int', {'uintptr_t', 'uintptr_t', 'uint32_t', 'uint32_t*'}),
                FlushInstructionCache = bind('kernel32.dll', 'FlushInstructionCache', 'int', {'uintptr_t', 'uintptr_t', 'uintptr_t'}),
                GetCurrentProcess = bind('kernel32.dll', 'GetCurrentProcess', 'uintptr_t', {}),
