    end
    local memory = type(modules) == 'table' and modules.lib_memory or nil
    if type(memory) == 'table' and type(memory.bind) == 'function' then
        kernel = bind_with(memory.bind)
    end
    if not kernel then
        local ok, library = pcall(require, 'lib/memory')
        if ok and type(library) == 'table' and type(library.bind) == 'function' then
            kernel = bind_with(library.bind)
