    end
    if not kernel then
        pcall(ffi.cdef, [[
int __stdcall VirtualProtect(void*, uintptr_t, unsigned long, unsigned long*);
int __stdcall VirtualQuery(void*, void*, uintptr_t);
int __stdcall FlushInstructionCache(void*, uintptr_t, uintptr_t);
void* __stdcall GetCurrentProcess(void);
]])
        local loaded, lib = pcall(ffi.load, 'kernel32')
        if not loaded or not lib then loaded, lib = pcall(ffi.load, 'kernel32.dll') end
        if loaded and lib and lib.VirtualQuery and lib.VirtualProtect
            and lib.FlushInstructionCache and lib.GetCurrentProcess then
            kernel = {
                VirtualQuery = lib.VirtualQuery,
                VirtualProtect = lib.VirtualProtect,
                FlushInstructionCache = lib.FlushInstructionCache,
                GetCurrentProcess = lib.GetCurrentProcess,
