    end
end
if not kernel then pcall(client.error_log, '[nyameeow.pink] memory API unavailable: byte patches disabled') end

local function valid_bytes(bytes)
    if type(bytes) ~= 'table' or #bytes == 0 or #bytes > 16 then return false end
    for i = 1, #bytes do
        local value = bytes[i]
        if type(value) ~= 'number' or value ~= value or value < 0 or value > 255
            or value ~= math.floor(value) then return false end
    end
    return true
end
local function match_bytes(a, b)
    if not a or not b or #a ~= #b then return false end
    for i = 1, #a do if a[i] ~= b[i] then return false end end
    return true
end
local function readable(address, length)
    if not kernel or not address or address < 0x10000 or length < 1 then return false end
    local info = ffi.new('afterglow_mbi_v1[1]')
    local cursor, finish = address, address + length
    while cursor < finish do
        local ok, size = pcall(kernel.VirtualQuery, cursor, info, ffi.sizeof(info))
        if not ok or tonumber(size) ~= ffi.sizeof(info) then return false end
        local region_end = tonumber(ffi.cast('uintptr_t', info[0].base)) + tonumber(info[0].region_size)
        local protection = tonumber(info[0].protect) or 0
        local access = bit.band(protection, 0xFF)
        if tonumber(info[0].state) ~= 0x1000 or bit.band(protection, 0x100) ~= 0 then return false end
        if access ~= 0x02 and access ~= 0x04 and access ~= 0x08 and access ~= 0x20
            and access ~= 0x40 and access ~= 0x80 then return false end
        if region_end <= cursor then return false end
        cursor = math.min(region_end, finish)
    end
    return true
end
local function read_bytes(address, length)
    if not address or not readable(address, length) then return nil end
    local pointer = ffi.cast('const uint8_t*', address)
    local out = {}
    for i = 1, length do out[i] = pointer[i - 1] end
    return out
end
local function write_bytes(address, bytes)
    if not kernel or not valid_bytes(bytes) or not readable(address, #bytes) then return false end
    local buffer = ffi.new('uint8_t[?]', #bytes, bytes)
    local old = ffi.new('uint32_t[1]')
    local protect_ok, protect_result = pcall(kernel.VirtualProtect, address, #bytes, 0x40, old)
    if not protect_ok or (tonumber(protect_result) or 0) == 0 then return false end
    local original = tonumber(old[0])
    local copied = pcall(ffi.copy, ffi.cast('void*', address), buffer, #bytes)
    local restored_ok, restored_result = pcall(kernel.VirtualProtect, address, #bytes, original, old)
    pcall(kernel.FlushInstructionCache, kernel.GetCurrentProcess(), address, #bytes)
    local restored = restored_ok and (tonumber(restored_result) or 0) ~= 0
    return copied and restored and match_bytes(read_bytes(address, #bytes), bytes)
end

local function new_engine()
    local engine = {_owned = {}, _pending_memory = {}}
    function engine:_cleanup_memory(address)
        local pending = self._pending_memory[address]
        if not pending then return true end
        if not readable(address, pending.length) then return false end
        if pending.protection ~= nil then
            local old = ffi.new('uint32_t[1]')
            local ok, result = pcall(kernel.VirtualProtect, address, pending.length, pending.protection, old)
            if ok and (tonumber(result) or 0) ~= 0 then pending.protection = nil end
        end
        if pending.flush then
            local ok, result = pcall(kernel.FlushInstructionCache, kernel.GetCurrentProcess(), address, pending.length)
            if ok and (tonumber(result) or 0) ~= 0 then pending.flush = nil end
        end
        if pending.protection == nil and not pending.flush then
            self._pending_memory[address] = nil
            return true
        end
        return false
    end
    function engine:_write(address, bytes)
        if not valid_bytes(bytes) or not self:_cleanup_memory(address)
            or not readable(address, #bytes) then return false end
        local old = ffi.new('uint32_t[1]')
        local protect_ok, protect_result = pcall(kernel.VirtualProtect, address, #bytes, 0x40, old)
        if not protect_ok or (tonumber(protect_result) or 0) == 0 then return false end
        local original = tonumber(old[0])
        local buffer = ffi.new('uint8_t[?]', #bytes, bytes)
        local copied = pcall(ffi.copy, ffi.cast('void*', address), buffer, #bytes)
        local restored_ok, restored_result = pcall(kernel.VirtualProtect, address, #bytes, original, old)
        local restored = restored_ok and (tonumber(restored_result) or 0) ~= 0
        local flushed_ok, flushed_result = pcall(kernel.FlushInstructionCache, kernel.GetCurrentProcess(), address, #bytes)
        local flushed = flushed_ok and (tonumber(flushed_result) or 0) ~= 0
        if not restored or not flushed then
            self._pending_memory[address] = {
                length = #bytes,
                protection = (not restored) and original or nil,
                flush = (not flushed) or nil,
            }
        end
        return copied and restored and flushed and match_bytes(read_bytes(address, #bytes), bytes)
    end
    function engine:_match(a, b) return match_bytes(a, b) end
    function engine:restore()
        for address, owned in pairs(self._owned) do
            local current = read_bytes(address, #owned.original)
            if match_bytes(current, owned.original) then
                if self:_cleanup_memory(address) then self._owned[address] = nil end
            elseif match_bytes(current, owned.patched) then
                if self:_write(address, owned.original) then self._owned[address] = nil end
            end
        end
        for address in pairs(self._pending_memory) do self:_cleanup_memory(address) end
        return next(self._owned) == nil and next(self._pending_memory) == nil
    end
    function engine:_validate_plan(plan)
        if type(plan) ~= 'table' then return false, 'invalid patch plan' end
        for key in pairs(plan) do
            if type(key) ~= 'number' or key ~= math.floor(key) or key < 1 or key > #plan then
                return false, 'invalid patch plan index'
            end
        end
        local ranges = {}
        for _, patch in ipairs(plan) do
            if type(patch) ~= 'table' or type(patch.address) ~= 'number'
                or patch.address ~= patch.address or patch.address < 0x10000
                or patch.address > 0xFFFFFFFF or patch.address ~= math.floor(patch.address)
                or not valid_bytes(patch.original) or not valid_bytes(patch.patched)
                or #patch.original ~= #patch.patched or patch.address + #patch.original > 0x100000000 then
                return false, 'invalid patch descriptor'
            end
            ranges[#ranges + 1] = {first = patch.address, last = patch.address + #patch.original}
        end
        table.sort(ranges, function(a, b) return a.first < b.first end)
        for i = 2, #ranges do
            if ranges[i].first < ranges[i - 1].last then return false, 'overlapping patch ranges' end
        end
        return true
    end
    function engine:_sync(plan)
        local valid, reason = self:_validate_plan(plan)
        if not valid then return false, reason end
        for address in pairs(self._pending_memory) do
            if not self:_cleanup_memory(address) then return false, 'page protection or instruction-cache cleanup pending' end
        end
        local wanted = {}
        for _, patch in ipairs(plan) do
            if wanted[patch.address] then return false, 'duplicate patch address' end
            wanted[patch.address] = patch
            local owned = self._owned[patch.address]
            local expected = owned and owned.patched or patch.original
            if not match_bytes(read_bytes(patch.address, #expected), expected) then
                return false, string.format('unsupported or externally modified site at 0x%X', patch.address)
            end
        end
        for address, owned in pairs(self._owned) do
            if not match_bytes(read_bytes(address, #owned.patched), owned.patched) then
                return false, string.format('owned site changed at 0x%X', address)
            end
        end
        for address, owned in pairs(self._owned) do
            if not wanted[address] then
                if not self:_write(address, owned.original) then self:restore(); return false, 'restore failed' end
                self._owned[address] = nil
            end
        end
        for _, patch in ipairs(plan) do
            local owned = self._owned[patch.address]
            local current = owned and owned.patched or patch.original
            if not match_bytes(current, patch.patched) then
                self._owned[patch.address] = {original = owned and owned.original or patch.original, patched = patch.patched}
                if not self:_write(patch.address, patch.patched) then
                    local observed = read_bytes(patch.address, #current)
                    if match_bytes(observed, current) then self._owned[patch.address] = owned end
                    self:restore()
                    return false, 'patch write/verification failed'
                end
            end
        end
        return true
    end
    return engine
end

local coordinator = {_claims = {}, _healthy = true, _last_check = -1, _warnings = {}}
local engine = new_engine()
function coordinator:_same(a, b)
    if not a or not b or a.priority ~= b.priority or #a.plan ~= #b.plan then return false end
    for i = 1, #a.plan do
        local x, y = a.plan[i], b.plan[i]
        if x.address ~= y.address or not match_bytes(x.original, y.original)
            or not match_bytes(x.patched, y.patched) then return false end
    end
    return true
end
function coordinator:_union(claims)
    local sites, plan = {}, {}
    for _, claim in pairs(claims) do
        for _, patch in ipairs(claim.plan) do
            local old = sites[patch.address]
            if old then
                if not match_bytes(old.patch.original, patch.original) then
                    return nil, 'different originals at a shared site'
                end
                if old.priority == claim.priority and not match_bytes(old.patch.patched, patch.patched) then
                    return nil, 'conflicting equal-priority patches'
                end
            end
            if not old or claim.priority > old.priority then sites[patch.address] = {patch = patch, priority = claim.priority} end
        end
    end
    for _, site in pairs(sites) do plan[#plan + 1] = site.patch end
    table.sort(plan, function(a, b) return a.address < b.address end)
    local valid, reason = engine:_validate_plan(plan)
    if not valid then return nil, reason end
    return plan
end
function coordinator:_warn(owner, reason)
    if self._warnings[owner] == reason then return end
    self._warnings[owner] = reason
    pcall(client.error_log, '[nyameeow.pink] ' .. owner .. ': ' .. tostring(reason))
end
function coordinator:_sync(claims)
    local plan, reason = self:_union(claims)
    if not plan then return false, reason end
    if #plan == 0 then return engine:restore() end
    return engine:_sync(plan)
end
function coordinator:claim(owner, plan, priority)
    local valid, reason = engine:_validate_plan(plan)
    if not valid then self:_warn(owner, reason or 'invalid patch plan'); return false end
    local claim = {plan = {}, priority = priority or 0}
    for i, patch in ipairs(plan) do
        local copy = {address = patch.address, original = {}, patched = {}}
        for j, value in ipairs(patch.original) do copy.original[j] = value end
        for j, value in ipairs(patch.patched) do copy.patched[j] = value end
        claim.plan[i] = copy
    end
    if self:_same(self._claims[owner], claim) then return self._healthy end
    local now = globals.realtime() or 0
    local refusal = self._refusal
    if refusal and refusal.owner == owner and now < refusal.until_time and self:_same(refusal.claim, claim) then return false end
    local proposed = {}
    for name, current in pairs(self._claims) do proposed[name] = current end
    proposed[owner] = claim
    local ok
    ok, reason = self:_sync(proposed)
    if ok then
        self._claims, self._healthy, self._refusal = proposed, true, nil
        self._warnings[owner] = nil
        return true
    end
    local clean = engine:restore()
    self._healthy = clean and self:_sync(self._claims) or false
    self._refusal = {owner = owner, claim = claim, until_time = now + 1}
    self:_warn(owner, reason or 'write/rollback pending')
    return false
end
function coordinator:release(owner)
    if self._refusal and self._refusal.owner == owner then self._refusal = nil end
    self._warnings[owner] = nil
    if not self._claims[owner] then return self._healthy end
    self._claims[owner] = nil
    local ok, reason = self:_sync(self._claims)
    if not ok then
        local clean = engine:restore()
        ok = clean and self:_sync(self._claims) or false
    end
    self._healthy = ok and true or false
    if not ok then self:_warn('Native patch cleanup', reason or 'retry pending') end
    return self._healthy
end
function coordinator:release_all()
    self._claims, self._refusal, self._warnings = {}, nil, {}
    self._healthy = engine:restore()
    return self._healthy
end
function coordinator:poll()
    local now = globals.realtime() or 0
    if now >= self._last_check and now - self._last_check < 0.5 then return end
    self._last_check = now
    local ok, reason = self:_sync(self._claims)
    if not ok then
        local clean = engine:restore()
        ok = clean and self:_sync(self._claims) or false
    end
    self._healthy = ok and true or false
    if not ok then self:_warn('Native patch cleanup', reason or 'retry pending')
    else self._warnings['Native patch cleanup'] = nil end
end

local function resolve_signature_address(pattern)
    local ok, match = pcall(client.find_signature, 'client.dll', pattern)
    if not ok or not match then return nil end
    local number_ok, address = pcall(tonumber, match)
    if not number_ok or not address or address == 0 then
        local cast_ok, casted = pcall(function() return tonumber(ffi.cast('uintptr_t', match)) end)
        if not cast_ok then return nil end
        address = casted
    end
    if not address or address == 0 then return nil end
    return address
end
local function make_native_literal_fix(name, pattern, offset, original, patched)
    return {
        _active = false,
        _site = nil,
        _original = original,
        _patched = patched,
        _last_attempt = -10,
        apply = function(self)
            if self._active then return true end
            local base = resolve_signature_address(pattern)
            if not base then return false end
            local address = base + offset
            local current = read_bytes(address, #self._original)
            if match_bytes(current, self._patched) then
                self._site = {address = address, changed = false}
                self._active = true
                return true
            end
            if not match_bytes(current, self._original) then return false end
            if not write_bytes(address, self._patched) then return false end
            if not match_bytes(read_bytes(address, #self._patched), self._patched) then
                local verify = read_bytes(address, #self._patched)
                if match_bytes(verify, self._original) then write_bytes(address, self._original) end
                return false
            end
            self._site = {address = address, changed = true}
            self._active = true
            return true
        end,
        restore = function(self)
            local site = self._site
            if not site then self._active = false; return true end
            if site.changed then
                local current = read_bytes(site.address, #self._patched)
                if match_bytes(current, self._patched) then
                    if not write_bytes(site.address, self._original) then return false end
                elseif not match_bytes(current, self._original) then
                    return false
                end
            end
            self._site = nil
            self._active = false
            return true
        end,
        handle = function(self, enabled)
            if not enabled or globals.mapname() == nil then
                self:restore()
                return
            end
            if self._active then return end
            local now = globals.realtime() or 0
            if now - self._last_attempt < 1 then return end
            self._last_attempt = now
            self:apply()
        end,
    }
end

 
fixes.air_strafe = {
    _numerator = 845.5,
    _flip = false,
    _ref = nil,
    _resolved = false,
    _saved_native = nil,
    _last_command = nil,
    _command_flip = nil,
    _last_player = nil,
    _last_output = nil,
    _last_input = nil,
    _normalize = function(_, angle)
        angle = math.fmod(angle, 360)
        if angle > 180 then return angle - 360 end
        if angle < -180 then return angle + 360 end
        return angle
    end,
    _finite = function(_, value)
        return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
    end,
    _reset = function(self)
        self._flip = false
        self._command_flip = nil
        self._last_command, self._last_player, self._last_output = nil, nil, nil
        self._last_input = nil
    end,
    _read_native = function(self)
        if not self._ref then return nil end
        local ok, value = pcall(ui.get, self._ref)
        if ok and type(value) == 'boolean' then return value end
        return nil
    end,
    _resolve = function(self)
        if self._resolved then return self._ref ~= nil end
        self._resolved = true
        local ok, reference = pcall(ui.reference, 'MISC', 'Movement', 'Air strafe')
        if ok and reference then
            self._ref = reference
            if self:_read_native() == nil then self._ref = nil end
        end
        return self._ref ~= nil
    end,
    restore = function(self)
        if self._saved_native ~= nil then
            if self:_read_native() == false and self._saved_native ~= false then
                pcall(ui.set, self._ref, self._saved_native)
            end
            self._saved_native = nil
        end
        self:_reset()
    end,
    sync = function(self)
        if not control_on(self._menu_ref) then
            if self._saved_native ~= nil then self:restore() end
            return false
        end
        if not self:_resolve() or self:_read_native() == nil then
            self:restore()
            pcall(client.error_log, '[nyameeow.pink] Neverlose Air Strafe: native Air strafe reference is unavailable')
            write_control(self._menu_ref, false)
            return false
        end
        if self._saved_native == nil then self._saved_native = self:_read_native() end
        if self:_read_native() ~= false then pcall(ui.set, self._ref, false) end
        if self:_read_native() ~= false then
            self:restore()
            pcall(client.error_log, '[nyameeow.pink] Neverlose Air Strafe: cannot disable native Air strafe')
            write_control(self._menu_ref, false)
            return false
        end
        return true
    end,
    _side_speed = function(self)
        local speed = 450
        if cvar and cvar.cl_sidespeed then
            local ok, value = pcall(function() return cvar.cl_sidespeed:get_float() end)
            if ok and self:_finite(value) and value ~= 0 then speed = math.abs(value) end
        end
        return math.min(speed, 450)
    end,
    _calculate = function(self, vx, vy, yaw, pitch, forward, side, smoothing, side_speed, flip)
        local has_input = forward ~= 0 or side ~= 0
        if has_input then
            local projected_forward = forward * math.cos(math.rad(pitch))
            yaw = yaw + math.deg(math.atan2(-side, projected_forward))
        end
        yaw = self:_normalize(yaw)
        local speed = math.sqrt(vx * vx + vy * vy)
        local ideal = speed > 0 and math.min(self._numerator / speed, 90) or 90
        local velocity_yaw = math.deg(math.atan2(vy, vx))
        local delta = self:_normalize(yaw - velocity_yaw)
        local correction = ideal * 0.03999999910593033 * (100 - smoothing)
        local out_yaw, out_side
        if speed > 80 and ((has_input and math.abs(delta) > 170) or delta > correction) then
            out_yaw, out_side = velocity_yaw + correction, -side_speed
        elseif speed > 80 and delta < -correction then
            out_yaw, out_side = velocity_yaw - correction, side_speed
        elseif flip then
            out_yaw, out_side = yaw - ideal, -side_speed
        else
            out_yaw, out_side = yaw + ideal, side_speed
        end
        return self:_normalize(out_yaw), out_side
    end,
    capture = function(self, cmd)
        if not control_on(self._menu_ref) or not cmd then return nil end
        local pitch, yaw = client.camera_angles()
        if self:_finite(cmd.pitch) then pitch = cmd.pitch end
        if self:_finite(cmd.yaw) then yaw = cmd.yaw end
        local forward, side = cmd.forwardmove or 0, cmd.sidemove or 0
        if not self:_finite(pitch) or not self:_finite(yaw)
            or not self:_finite(forward) or not self:_finite(side) then return nil end
        return {pitch = math.max(-89, math.min(89, pitch)), yaw = yaw, forward = forward, side = side}
    end,
    _apply = function(self, cmd, output, input)
        local basis = self:_finite(cmd.yaw) and cmd.yaw or input.yaw
        local delta = math.rad(self:_normalize(output.yaw - basis))
        local forward = output.side * math.sin(delta)
        local side = output.side * math.cos(delta)
        if math.abs(forward) < 0.001 then forward = 0 end
        if math.abs(side) < 0.001 then side = 0 end
        cmd.forwardmove, cmd.sidemove = forward, side
        cmd.move_yaw = basis
        cmd.in_forward = forward > 0 and 1 or 0
        cmd.in_back = forward < 0 and 1 or 0
        cmd.in_moveright = side > 0 and 1 or 0
        cmd.in_moveleft = side < 0 and 1 or 0
    end,
    handle = function(self, cmd, input)
        if not self:sync() or not cmd then return end
        input = input or self:capture(cmd)
        if not input then return end
        local player = entity.get_local_player()
        if not player or not entity.is_alive(player) or globals.mapname() == nil then
            self:_reset()
            return
        end
        if player ~= self._last_player then self:_reset(); self._last_player = player end
        local flags = entity.get_prop(player, 'm_fFlags')
        local move_type = entity.get_prop(player, 'm_MoveType')
        local water = entity.get_prop(player, 'm_nWaterLevel')
        local walk = cmd.in_speed == 1 or cmd.in_speed == true
        if type(flags) ~= 'number' or bit.band(flags, 1) ~= 0 or move_type ~= 2
            or (type(water) == 'number' and water >= 2) or walk then
            self._last_command, self._last_output = nil, nil
            self._last_input = nil
            self._command_flip = nil
            return
        end
        local vx, vy, vz = entity.get_prop(player, 'm_vecVelocity')
        if not self:_finite(vx) or not self:_finite(vy) or not self:_finite(vz) then return end
        if vx == 0 and vy == 0 and vz == 0 then return end
        local number = tonumber(cmd.command_number)
        if not self:_finite(number) or number <= 0 then number = nil end
        local repeated = number ~= nil and number == self._last_command
        if repeated and self._last_input then input = self._last_input end
        local flip = self._flip
        if repeated then flip = self._command_flip end
        local smoothing = tonumber(read_control(self._smoothing_ref)) or 50
        if not self:_finite(smoothing) then smoothing = 50 end
        smoothing = math.max(0, math.min(100, smoothing))
        local out_yaw, out_side = self:_calculate(vx, vy, input.yaw, input.pitch,
            input.forward, input.side, smoothing, self:_side_speed(), flip)
        if not self:_finite(out_yaw) or not self:_finite(out_side) then return end
        local output = {yaw = out_yaw, side = out_side}
        self:_apply(cmd, output, input)
        self._last_command, self._last_output = number, output
        self._last_input = input
        if not repeated then
            self._command_flip = flip
            self._flip = not flip
        end
    end,
}

