fixes.quick_stop = {
    _active = false,
    _sites = nil,
    _last_attempt = -10,
    _specs = {
        {
            name = 'first Early-result admission',
            pattern = '\xF7\x06\x00\x04\x00\x00\x0F\x85\xCC\xCC\xCC\xCC\x8B\x56\x0C\x85\xD2\x74\xCC',
            offset = 2,
            original = {0x00, 0x04, 0x00, 0x00},
            patched = {0x00, 0x04, 0x01, 0x00},
        },
        {
            name = 'second Early-result admission',
            pattern = '\xF7\x06\x00\x04\x00\x00\x0F\x85\xCC\xCC\xCC\xCC\x8B\x4E\x0C\x89\x8C\x24\xC8\x00\x00\x00',
            offset = 2,
            original = {0x00, 0x04, 0x00, 0x00},
            patched = {0x00, 0x04, 0x01, 0x00},
        },
        {
            name = 'Double Tap motion-policy fidelity',
            pattern = '\x83\xC8\x08\x83\x0D\xCC\xCC\xCC\xCC\x04\xA3\xCC\xCC\xCC\xCC\x8B\x8C\x24\x80\x00\x00\x00',
            offset = 9,
            original = {0x04},
            patched = {0x00},
        },
    },
    _resolve = function(self)
        local sites, occupied = {}, {}
        for i = 1, #self._specs do
            local spec = self._specs[i]
            local address = resolve_signature_address(spec.pattern)
            if not address then return nil end
            local patch_address = address + spec.offset
            if occupied[patch_address] then return nil end
            occupied[patch_address] = true
            local current = read_bytes(patch_address, #spec.original)
            local changed
            if match_bytes(current, spec.original) then
                changed = true
            elseif match_bytes(current, spec.patched) then
                changed = false
            else
                return nil
            end
            sites[#sites + 1] = {
                name = spec.name,
                address = patch_address,
                original = spec.original,
                patched = spec.patched,
                changed = changed,
            }
        end
        return sites
    end,
    apply = function(self)
        if self._active then return true end
        local sites = self:_resolve()
        if not sites then return false end
        local written = {}
        for i = 1, #sites do
            local site = sites[i]
            if site.changed then
                if not write_bytes(site.address, site.patched) then
                    for j = #written, 1, -1 do
                        local applied = written[j]
                        local current = read_bytes(applied.address, #applied.patched)
                        if match_bytes(current, applied.patched) then
                            write_bytes(applied.address, applied.original)
                        end
                    end
                    return false
                end
                written[#written + 1] = site
            end
        end
        self._sites = sites
        self._active = true
        return true
    end,
    restore = function(self)
        if not self._sites then
            self._active = false
            return
        end
        for i = #self._sites, 1, -1 do
            local site = self._sites[i]
            if site.changed then
                local current = read_bytes(site.address, #site.patched)
                if match_bytes(current, site.patched) then
                    write_bytes(site.address, site.original)
                end
            end
        end
        self._sites = nil
        self._active = false
    end,
    handle = function(self)
        if not control_on(self._menu_ref) or globals.mapname() == nil then
            self:restore()
            return
        end
        if self._active then return end
        local now = globals.realtime() or 0
        if now - self._last_attempt < 1 then return end
        self._last_attempt = now
        self:apply()
    end,
}

