local function u32_bytes(value)
    local n = bit.tobit(value)
    return string.char(
        bit.band(n, 0xFF),
        bit.band(bit.rshift(n, 8), 0xFF),
        bit.band(bit.rshift(n, 16), 0xFF),
        bit.band(bit.rshift(n, 24), 0xFF))
end
local function byte_list(value)
    local out = {}
    for i = 1, #value do out[i] = value:byte(i) end
    return out
end
fixes.dt_return = {
    _active = false,
    _caves = nil,
    _button_site = nil,
    _return_site = nil,
    _button_original = nil,
    _return_original = nil,
    _button_patch = nil,
    _return_patch = nil,
    _preserve_ptr = nil,
    _last_attempt = -10,
    _signature_button = '8B 86 A8 00 00 00 33 46 7C A9 1A 06 00 00 75 ? A1 ? ? ? ? 8B 54 24 24',
    _signature_return = '0F 2F E5 72 34 8B 44 24 34 8B 54 24 24 F3 0F 10 44 24 6C 81 60 30 FF FF FD FF',
    _button_bytes = {139, 134, 168, 0, 0, 0, 51, 70, 124, 169, 26, 6, 0, 0, 117, 71},
    _return_bytes = {15, 47, 229, 114, 52},
    _jmp = function(base, offset, target)
        return '\xE9' .. u32_bytes(target - (base + offset + 5))
    end,
    _jcc = function(opcode, base, offset, target)
        return '\x0F' .. string.char(opcode) .. u32_bytes(target - (base + offset + 6))
    end,
    _alloc_cave = function(self, size, fill)
        if not kernel then return nil end
        local storage = ffi.new('uint8_t[?]', size)
        for i = 0, size - 1 do storage[i] = fill or 0x90 end
        local address = tonumber(ffi.cast('uintptr_t', ffi.cast('void*', storage)))
        local old = ffi.new('uint32_t[1]')
        local ok, result = pcall(kernel.VirtualProtect, address, size, 0x40, old)
        if not ok or (tonumber(result) or 0) == 0 then return nil end
        self._caves = self._caves or {}
        self._caves[#self._caves + 1] = storage
        return {address = address, storage = storage}
    end,
    _build_caves = function(self, button_site, return_site, button_original)
        local button_cave = self:_alloc_cave(256, 0x90)
        local return_cave = self:_alloc_cave(128, 0x90)
        if not button_cave or not return_cave then return nil end
        local button_address = button_cave.address
        local return_address = return_cave.address
        local preserve_address = button_address + 224

        local button_target = button_site + 16 + 0x47
        local return_target = return_site + 5 + 0x34

        local button_code = '\x80\x7E\x78\x03'
        button_code = button_code .. self:_jcc(0x85, button_address, 4, button_address + 80)
        button_code = button_code .. '\x80\x3D' .. u32_bytes(preserve_address) .. '\x00'
        button_code = button_code .. self:_jcc(0x85, button_address, 17, button_address + 64)
        button_code = button_code .. self:_jmp(button_address, 23, button_address + 80)
        assert(#button_code == 28, 'button cave header size mismatch')
        button_code = button_code .. string.rep('\x90', 64 - #button_code)
        button_code = button_code .. self:_jmp(button_address, 64, button_site + 16)
        button_code = button_code .. string.rep('\x90', 80 - #button_code)
        button_code = button_code .. string.sub(string.char(unpack(button_original)), 1, 14)
        button_code = button_code .. self:_jcc(0x85, button_address, 94, button_target)
        button_code = button_code .. self:_jmp(button_address, 100, button_address + 64)
        button_code = button_code .. string.rep('\x90', 256 - #button_code)

        local return_code = '\x80\x7E\x78\x03'
        return_code = return_code .. self:_jcc(0x85, return_address, 4, return_address + 64)
        return_code = return_code .. '\x80\x3D' .. u32_bytes(preserve_address) .. '\x00'
        return_code = return_code .. self:_jcc(0x84, return_address, 17, return_target)
        return_code = return_code .. self:_jmp(return_address, 23, return_site + 5)
        assert(#return_code == 28, 'return cave header size mismatch')
        return_code = return_code .. string.rep('\x90', 64 - #return_code)
        return_code = return_code .. '\x0F\x2F\xE5'
        return_code = return_code .. self:_jcc(0x82, return_address, 67, return_target)
        return_code = return_code .. self:_jmp(return_address, 73, return_site + 5)
        return_code = return_code .. string.rep('\x90', 128 - #return_code)

        pcall(ffi.copy, ffi.cast('void*', button_address), button_code, #button_code)
        pcall(ffi.copy, ffi.cast('void*', return_address), return_code, #return_code)
        self._preserve_ptr = preserve_address
        pcall(function() ffi.cast('uint8_t*', preserve_address)[0] = 0 end)

        local button_patch = '\xE9' .. u32_bytes(button_address - (button_site + 5)) .. string.rep('\x90', 11)
        local return_patch = '\xE9' .. u32_bytes(return_address - (return_site + 5))
        return button_patch, return_patch
    end,
    apply = function(self)
        if self._active then return true end
        local button_site = resolve_signature_address(self._signature_button)
        local return_site = resolve_signature_address(self._signature_return)
        if not button_site or not return_site or button_site == return_site then return false end
        local button_original = read_bytes(button_site, 16)
        local return_original = read_bytes(return_site, 5)
        if not match_bytes(button_original, self._button_bytes) or not match_bytes(return_original, self._return_bytes) then
            return false
        end
        local button_disp = button_original[16]
        if button_disp >= 128 then button_disp = button_disp - 256 end
        if button_site + 16 + button_disp ~= button_site + 87 or return_original[5] ~= 0x34 then return false end

        local built, button_patch, return_patch = pcall(function()
            return self:_build_caves(button_site, return_site, button_original)
        end)
        if not built or not button_patch or not return_patch then
            self._preserve_ptr = nil
            return false
        end
        local button_patch_bytes = byte_list(button_patch)
        local return_patch_bytes = byte_list(return_patch)
        if not write_bytes(button_site, button_patch_bytes) then
            self._preserve_ptr = nil
            return false
        end
        if not write_bytes(return_site, return_patch_bytes) then
            local current = read_bytes(button_site, #button_patch_bytes)
            if match_bytes(current, button_patch_bytes) then write_bytes(button_site, button_original) end
            self._preserve_ptr = nil
            return false
        end
        if not match_bytes(read_bytes(button_site, #button_patch_bytes), button_patch_bytes)
            or not match_bytes(read_bytes(return_site, #return_patch_bytes), return_patch_bytes) then
            local current_return = read_bytes(return_site, #return_patch_bytes)
            local current_button = read_bytes(button_site, #button_patch_bytes)
            if match_bytes(current_return, return_patch_bytes) then write_bytes(return_site, return_original) end
            if match_bytes(current_button, button_patch_bytes) then write_bytes(button_site, button_original) end
            self._preserve_ptr = nil
            return false
        end
        self._button_site, self._return_site = button_site, return_site
        self._button_original, self._return_original = button_original, return_original
        self._button_patch, self._return_patch = button_patch_bytes, return_patch_bytes
        self._active = true
        return true
    end,
    set_preserve = function(self, enabled)
        if not self._preserve_ptr then return false end
        local ok = pcall(function()
            ffi.cast('uint8_t*', self._preserve_ptr)[0] = enabled and 1 or 0
        end)
        return ok
    end,
    restore = function(self)
        if not self._button_site then
            self._active = false
            self._preserve_ptr = nil
            return true
        end
        local safe = true
        local button_current = read_bytes(self._button_site, #self._button_patch)
        local return_current = read_bytes(self._return_site, #self._return_patch)
        if match_bytes(button_current, self._button_patch) then
            if not write_bytes(self._button_site, self._button_original) then safe = false end
        elseif not match_bytes(button_current, self._button_original) then
            safe = false
        end
        if match_bytes(return_current, self._return_patch) then
            if not write_bytes(self._return_site, self._return_original) then safe = false end
        elseif not match_bytes(return_current, self._return_original) then
            safe = false
        end
        if not safe then return false end
        self._button_site, self._return_site = nil, nil
        self._button_original, self._return_original = nil, nil
        self._button_patch, self._return_patch = nil, nil
        self._caves, self._preserve_ptr = nil, nil
        self._active = false
        return true
    end,
    handle = function(self)
        if not control_on(self._menu_ref) or globals.mapname() == nil then
            self:set_preserve(false)
            self:restore()
            return
        end
        if self._active then return end
        local now = globals.realtime() or 0
        if now - self._last_attempt < 1 then return end
        self._last_attempt = now
        self:apply()
    end,
}

fixes.defensive_dt = {
    _visible = {},
    _last_trigger_tick = -1000,
    _preserve_until_tick = -1,
    _last_command = -1,
    _can_hit_local = function(self, enemy, local_player)
        local ok, result = pcall(function()
            local enemy_x, enemy_y, enemy_z = entity.hitbox_position(enemy, 0)
            if enemy_x == nil or enemy_y == nil or enemy_z == nil then return false end
            local hitboxes = {0, 4, 5, 2}
            for i = 1, #hitboxes do
                local x, y, z = entity.hitbox_position(local_player, hitboxes[i])
                if x ~= nil and y ~= nil and z ~= nil then
                    local trace_ok, hit, damage = pcall(client.trace_bullet, enemy, enemy_x, enemy_y, enemy_z, x, y, z, enemy)
                    if trace_ok and hit == local_player and (tonumber(damage) or 0) > 0 then return true end
                end
            end
            return false
        end)
        return ok and result == true
    end,
    _double_tap_active = function(self)
        local dt = fixes._dt_ref
        if not dt or not dt[1] or not dt[2] then return false end
        local ok, value = pcall(function() return ui.get(dt[1]) and ui.get(dt[2]) end)
        return ok and value == true
    end,
    reset = function(self)
        self._visible = {}
        self._last_trigger_tick = -1000
        self._preserve_until_tick = -1
        self._last_command = -1
        fixes.dt_return:set_preserve(false)
    end,
    handle = function(self, cmd)
        local return_fix = fixes.dt_return
        if not control_on(self._menu_ref) or not return_fix._active or not cmd or globals.mapname() == nil then
            self:reset()
            return
        end
        local local_player = entity.get_local_player()
        if not local_player or not entity.is_alive(local_player) or not self:_double_tap_active() then
            self:reset()
            return
        end
        local tick = globals.tickcount() or 0
        local command_number = tonumber(cmd.command_number) or -1
        local enemies = entity.get_players(true) or {}
        if type(enemies) ~= 'table' then return end
        local visible_now = {}
        local trigger = false
        for i = 1, #enemies do
            local enemy = enemies[i]
            if enemy and entity.is_alive(enemy) then
                local dormant = false
                pcall(function() dormant = entity.is_dormant(enemy) end)
                if not dormant then
                    local vx, vy, vz = entity.get_prop(enemy, 'm_vecVelocity')
                    vx, vy, vz = tonumber(vx) or 0, tonumber(vy) or 0, tonumber(vz) or 0
                    local speed = math.sqrt(vx * vx + vy * vy + vz * vz)
                    if speed >= 55 and self:_can_hit_local(enemy, local_player) then
                        visible_now[enemy] = true
                        if not self._visible[enemy] and tick - self._last_trigger_tick >= 6 then trigger = true end
                    end
                end
            end
        end
        self._visible = visible_now
        if trigger and command_number ~= self._last_command then
            self._last_command = command_number
            self._last_trigger_tick = tick
            self._preserve_until_tick = tick + 3
            pcall(function() cmd.force_defensive = true end)
        end
        return_fix:set_preserve(tick <= self._preserve_until_tick)
    end,
}

