fixes.scan_accuracy = {
    _shut = false,
    _smoothed_fps = nil,
    _to_le32 = function(self, value)
        value = math.floor(value)
        if value < 0 then value = value + 0x100000000 end
        return {
            value % 0x100,
            math.floor(value / 0x100) % 0x100,
            math.floor(value / 0x10000) % 0x100,
            math.floor(value / 0x1000000) % 0x100,
        }
    end,
    _init_groups = function(self)
        if self._groups then return end
        local function join(a, b)
            local out = {}
            for index = 1, #a do out[#out + 1] = a[index] end
            for index = 1, #b do out[#out + 1] = b[index] end
            return out
        end
        local le = self._to_le32
        local to_le = function(value) return le(self, value) end
        self._groups = {
            sample = {
                {kind = 'cmp_imm32', address = 0x4333278D, original = join({0x81, 0xFF}, to_le(0x80)), build = function(v) return join({0x81, 0xFF}, to_le(v)) end},
                {kind = 'cmp_imm32', address = 0x4333285D, original = join({0x81, 0xF9}, to_le(0x80)), build = function(v) return join({0x81, 0xF9}, to_le(v)) end},
            },
            seed = {
                {kind = 'disp32', address = 0x433326CF, original = join({0x0F, 0xB6, 0x88}, to_le(0x4346FC50)), build = function(v) return join({0x0F, 0xB6, 0x88}, to_le(v)) end},
                {kind = 'disp32', address = 0x4333273E, original = join({0x0F, 0xB6, 0x87}, to_le(0x4346FC50)), build = function(v) return join({0x0F, 0xB6, 0x87}, to_le(v)) end},
                {kind = 'disp32', address = 0x433327B3, original = join({0x0F, 0xB6, 0x91}, to_le(0x4346FC50)), build = function(v) return join({0x0F, 0xB6, 0x91}, to_le(v)) end},
                {kind = 'disp32', address = 0x4333281F, original = join({0x0F, 0xB6, 0x80}, to_le(0x4346FC50)), build = function(v) return join({0x0F, 0xB6, 0x80}, to_le(v)) end},
            },
            percent_cap = {
                {kind = 'push_imm8', address = 0x43332890, original = {0x6A, 0x64}, build = function(v) return {0x6A, math.floor(v) % 0x100} end},
            },
            hitbox_cap = {
                {kind = 'push_imm8', address = 0x433337EA, original = {0x6A, 0x13}, build = function(v) return {0x6A, math.floor(v) % 0x100} end},
                {kind = 'push_imm8', address = 0x43333C88, original = {0x6A, 0x13}, build = function(v) return {0x6A, math.floor(v) % 0x100} end},
            },
            hitbox_mask = {
                {kind = 'mov_esi_imm32', address = 0x43333349, original = join({0xBE}, to_le(0xCA)), build = function(v) return join({0xBE}, to_le(v)) end},
            },
            distance_bypass = {
                {kind = 'bytes', address = 0x43333078, original = {0x76, 0x27}, patched = {0xEB, 0x27}},
                {kind = 'bytes', address = 0x433330A8, original = {0x76, 0x0D}, patched = {0xEB, 0x0D}},
            },
        }
        pcall(function()
            self._seed_table = ffi.new('unsigned char[512]')
            for index = 0, 511 do self._seed_table[index] = index % 256 end
            self._seed_addr = tonumber(ffi.cast('uintptr_t', ffi.cast('void*', self._seed_table)))
        end)
    end,
    _is_fakeduck = function(self)
        local duck = fixes._duck_ref
        if not duck or not duck[1] then return false end
        local ok, value = pcall(ui.get, duck[1])
        return ok and value and true or false
    end,
    _is_onground = function(self)
        local player = entity.get_local_player()
        if not player then return true end
        local flags = entity.get_prop(player, 'm_fFlags') or 0
        return bit.band(flags, 1) ~= 0
    end,
    _get_sample_count = function(self)
        if self:_is_fakeduck() then return 128 end
        if self._smoothed_fps and self._smoothed_fps < 128 then return 128 end
        return 256
    end,
    restore = function(self)
        coordinator:release('scan_accuracy_optimization')
    end,
    update = function(self)
        if self._shut then return end
        if not control_on(self._menu_ref) or globals.mapname() == nil then self:restore(); return end
        self:_init_groups()
        if not self._seed_addr then return end
        local values = {
            seed = self._seed_addr,
            sample = self:_get_sample_count(),
            percent_cap = self:_is_onground() and 76 or 65,
            hitbox_cap = 18,
            hitbox_mask = 255,
            distance_bypass = true,
        }
        local plan = {}
        for _, name in ipairs({'seed', 'sample', 'percent_cap', 'hitbox_cap', 'hitbox_mask', 'distance_bypass'}) do
            for _, patch in ipairs(self._groups[name]) do
                plan[#plan + 1] = {
                    address = patch.address,
                    original = patch.original,
                    patched = patch.kind == 'bytes' and patch.patched or patch.build(values[name]),
                }
            end
        end
        coordinator:claim('scan_accuracy_optimization', plan, 100)
    end,
    handle = function(self)
        if self._shut then return end
        local frame_time = globals.frametime()
        if frame_time and frame_time > 0 then
            local fps = math.min(1000, 1 / frame_time)
            self._smoothed_fps = self._smoothed_fps == nil and fps or self._smoothed_fps * 0.9 + fps * 0.1
        end
        self:update()
    end,
}

fixes.spread_autostop = {
    _active = false,
    _find = function(self)
        if self._specs then return self._specs end
        self._specs = {
            {addr = 0x4333278D, orig = {0x81, 0xFF, 0x80, 0x00, 0x00, 0x00}, write = {0x81, 0xFF, 0x00, 0x01, 0x00, 0x00}},
            {addr = 0x4333285D, orig = {0x81, 0xF9, 0x80, 0x00, 0x00, 0x00}, write = {0x81, 0xF9, 0x00, 0x01, 0x00, 0x00}},
            {addr = 0x43332890, orig = {0x6A, 0x64}, write = {0x6A, 0x46}},
        }
        return self._specs
    end,
    apply = function(self)
        local plan = {}
        for _, site in ipairs(self:_find()) do
            plan[#plan + 1] = {address = site.addr, original = site.orig, patched = site.write}
        end
        self._active = coordinator:claim('spread_autostop_fix', plan, 50)
        return self._active
    end,
    restore = function(self)
        coordinator:release('spread_autostop_fix')
        self._active = false
    end,
    handle = function(self)
        if not control_on(self._menu_ref) or globals.mapname() == nil then self:restore(); return end
        self:apply()
    end,
}

fixes.backtrack = (function()
    local record_engine = new_engine()
    local module = {
        MAX_MOVE = 512,
        _failed = nil,
        _patches = nil,
        _lr_dynamic = nil,
        _distance = nil,
        _distance_addr = nil,
    }
    function module:_init()
        if self._patches then return true end
        pcall(function()
            self._distance = ffi.new('float[1]', self.MAX_MOVE * self.MAX_MOVE)
            self._distance_addr = tonumber(ffi.cast('uintptr_t', self._distance))
        end)
        if not self._distance_addr then return false end
        local function le32(v)
            v = math.floor(v)
            if v < 0 then v = v + 0x100000000 end
            return {
                v % 0x100,
                math.floor(v / 0x100) % 0x100,
                math.floor(v / 0x10000) % 0x100,
                math.floor(v / 0x1000000) % 0x100,
            }
        end
        local function join(a, b)
            local out = {}
            for i = 1, #a do out[#out + 1] = a[i] end
            for i = 1, #b do out[#out + 1] = b[i] end
            return out
        end
        local dist_orig = join({0x0F, 0x2F, 0x15}, le32(0x43472B60))
        local dist_patch = join({0x0F, 0x2F, 0x15}, le32(self._distance_addr))
        self._patches = {
            core = {
                {id = 'distance', address = 0x433AED50, original = dist_orig, patched = dist_patch},
                {id = 'gap_default', address = 0x433AF012, original = {0x83, 0xF9, 0x08}, patched = {0x83, 0xF9, 0x14}},
            },
            lag_record = {
                {id = 'lr_lim_a', address = 0x433AEE6C, original = {0x3D, 0x80, 0x00, 0x00, 0x00}, patched = {0x3D, 0x80, 0x00, 0x00, 0x00}},
                {id = 'lr_lim_b', address = 0x433F94FD, original = {0x3D, 0x80, 0x00, 0x00, 0x00}, patched = {0x3D, 0x80, 0x00, 0x00, 0x00}},
                {id = 'lr_ja', address = 0x433259A4, original = {0x0F, 0x87, 0x2E, 0x04, 0x00, 0x00}, patched = {0x90, 0x90, 0x90, 0x90, 0x90, 0x90}},
            },
        }
        self._lr_dynamic = {
            {address = 0x433AF091, original = {0x83, 0xF8, 0x0A}},
            {address = 0x433AF167, original = {0x83, 0xF8, 0x0A}},
            {address = 0x433F9645, original = {0x83, 0xF8, 0x0A}},
            {address = 0x433F96F3, original = {0x83, 0xF8, 0x0A}},
        }
        return true
    end
    function module:restore()
        self._last_plan_key, self._next_plan_check = nil, nil
        return record_engine:restore()
    end
    function module:_plan(lag_records, gap)
        local plan = {}
        for _, patch in ipairs(self._patches.core) do plan[#plan + 1] = patch end
        if lag_records then
            for _, patch in ipairs(self._patches.lag_record) do plan[#plan + 1] = patch end
            for _, patch in ipairs(self._lr_dynamic) do
                plan[#plan + 1] = {address = patch.address, original = patch.original, patched = {0x83, 0xF8, gap}}
            end
        end
        return plan
    end
    function module:on_paint_ui()
        if control_on(self._menu_ref) and globals.mapname() ~= nil then return end
        self._failed = nil
        if next(record_engine._owned) or next(record_engine._pending_memory) then self:restore() end
    end
    function module:handle()
        if not control_on(self._menu_ref) or globals.mapname() == nil then
            if next(record_engine._owned) or next(record_engine._pending_memory) then self:restore() end
            self._failed = nil
            return
        end
        if self._failed then return end
        if not self:_init() then
            self._failed = 'initialization failed'
        else
            local refs = fixes.refs
            local extended = read_control(refs.extended_records) == true
            local source = extended and refs.extended_gap or refs.record_gap
            local gap = tonumber(read_control(source)) or 3
            if gap ~= gap or gap == math.huge or gap == -math.huge then gap = 3 end
            gap = math.max(1, math.min(extended and 20 or 10, math.floor(gap)))
            local lag_records = read_control(refs.lag_records) == true
            local plan_key = tostring(lag_records) .. ':' .. tostring(gap)
            local now = globals.realtime() or 0
            local due = self._next_plan_check == nil or now >= self._next_plan_check
                or now < self._next_plan_check - 0.5
            if plan_key ~= self._last_plan_key or due then
                local ok, reason = record_engine:_sync(self:_plan(lag_records, gap))
                if not ok then self._failed = reason or 'patch validation failed'
                else self._last_plan_key, self._next_plan_check = plan_key, now + 0.5 end
            end
        end
        if self._failed then
            self:restore()
            pcall(client.error_log, '[nyameeow.pink] Backtrack Record Fix disabled: ' .. self._failed)
            write_control(self._menu_ref, false)
        end
    end
    return module
end)()

fixes.adaptive = {
    _records = {},
    _stats = {samples = 0, hold = 0, linear = 0, adaptive = 0},
    _state = 'off',
    _read = function(self, name)
        local ok, value = pcall(function() return cvar[name]:get_float() end)
        if ok and type(value) == 'number' and value == value and value ~= math.huge and value ~= -math.huge then
            return value
        end
    end,
    _restore = function(self)
        if self._written == nil then return true end
        local current = self:_read('cl_interp_ratio')
        if current == nil then return false end
        if math.abs(current - self._written) > 0.00001 then
            self._written = nil
            return true
        end
        if math.abs(current - self._base) <= 0.00001 then self._written = nil; return true end
        pcall(function() cvar.cl_interp_ratio:set_float(self._base) end)
        local observed = self:_read('cl_interp_ratio')
        if observed and math.abs(observed - self._base) <= 0.00001 then self._written = nil; return true end
        return false
    end,
    stop = function(self)
        local clean = self:_restore()
        self._active, self._records, self._last_arrival, self._last_latency = false, {}, nil, nil
        self._samples, self._blocked, self._next_poll = 0, nil, nil
        if clean then self._base, self._map, self._state = nil, nil, 'off'
        else self._state = 'ratio restore pending' end
        return clean
    end,
    _set_ratio = function(self, value)
        local current = self:_read('cl_interp_ratio')
        if current == nil then return false end
        local expected = self._written or self._base
        if math.abs(current - expected) > 0.00001 then
            self._written, self._blocked, self._state = nil, true, 'external ratio change; suspended'
            return false
        end
        if math.abs(current - value) <= 0.00001 then return true end
        self._written = value
        pcall(function() cvar.cl_interp_ratio:set_float(value) end)
        local observed = self:_read('cl_interp_ratio')
        if observed and math.abs(observed - value) <= 0.00001 then
            if math.abs(value - self._base) <= 0.00001 then self._written = nil end
            return true
        end
        if observed and math.abs(observed - current) <= 0.00001 then
            self._written = math.abs(current - self._base) > 0.00001 and current or nil
        end
        self._blocked, self._state = true, 'ratio setter/readback failed; suspended'
        if not self._warned then
            self._warned = true
            pcall(client.error_log, '[nyameeow.pink] Adaptive interpolation: setter/readback failed; original ratio is being restored')
        end
        self:_restore()
        return false
    end,
    tick = function(self)
        local now = globals.realtime() or 0
        if self._next_poll and now >= self._next_poll - 0.25 and now < self._next_poll then return end
        self._next_poll = now + 0.25
        local map = globals.mapname()
        local player = entity.get_local_player()
        if not control_on(self._menu_ref) or map == nil or not player or not entity.is_alive(player) then
            self:stop()
            return
        end
        if self._active and self._map ~= map then if not self:stop() then return end end
        if not self._active then
            if not self:_restore() then return end
            local base_ratio = self:_read('cl_interp_ratio')
            if not base_ratio or base_ratio <= 0 then self._state = 'ratio unavailable'; return end
            self._base, self._map, self._active = base_ratio, map, true
            self._bad_until, self._samples, self._warned, self._blocked = now + 4, 0, nil, nil
            self._records, self._last_arrival, self._last_latency = {}, nil, nil
            self._stats = {samples = 0, hold = 0, linear = 0, adaptive = 0}
        end
        if self._blocked then self:_restore(); return end
        local h, rate_value = globals.tickinterval(), self:_read('cl_updaterate')
        local minimum, maximum = self:_read('sv_client_min_interp_ratio'), self:_read('sv_client_max_interp_ratio')
        local interp = self:_read('cl_interp')
        local function finite_number(value)
            return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
        end
        if not finite_number(h) or h <= 0 or not rate_value or rate_value <= 0
            or not minimum or not maximum or not interp then
            self._state = 'timing inputs unavailable'
            self:_set_ratio(self._base)
            return
        end
        if minimum == -1 then minimum, maximum = 0, math.huge end
        if minimum < 0 or maximum < minimum or maximum <= 0 then
            self._state = 'server ratio bounds unavailable'
            self:_set_ratio(self._base)
            return
        end
        local interval = math.max(h, 1 / rate_value)
        local stable = self._last_arrival and now >= (self._bad_until or math.huge)
            and now - self._last_arrival <= math.max(2 * interval, 0.05) and (self._samples or 0) >= 32
        local low = math.min(self._base, math.max(minimum, math.min(maximum, 1)))
        local target = stable and low or self._base
        if math.max(interp, target / rate_value) >= math.max(interp, self._base / rate_value) then target = self._base end
        if self:_set_ratio(target) then
            self._state = target < self._base and 'low latency' or 'original ratio / warmup'
        end
    end,
    _sample = function(self, index, h)
        if not entity.is_alive(index) or entity.is_dormant(index) then self._records[index] = nil; return end
        local t = entity.get_prop(index, 'm_flSimulationTime')
        local x, y, z = entity.get_prop(index, 'm_vecOrigin')
        local vx, vy, vz = entity.get_prop(index, 'm_vecVelocity')
        local flags, duck = entity.get_prop(index, 'm_fFlags'), entity.get_prop(index, 'm_flDuckAmount')
        local function finite_number(value)
            return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
        end
        for _, value in ipairs({t, x, y, z, vx, vy, vz, flags, duck}) do
            if not finite_number(value) then self._records[index] = nil; return end
        end
        local function distance(a, b)
            local dx, dy, dz = a[1] - b[1], a[2] - b[2], a[3] - b[3]
            return math.sqrt(dx * dx + dy * dy + dz * dz)
        end
        local current = {time = t, origin = {x, y, z}, velocity = {vx, vy, vz}, flags = flags, duck = duck}
        local previous = self._records[index]
        if previous and t == previous.time then return end
        if previous then
            local dt = t - previous.time
            local same_ground = bit.band(flags, 1) == 1 and bit.band(previous.flags, 1) == 1
            local coherent = dt >= h * 0.9 and dt <= h * 2.1 and same_ground
                and math.abs(duck - previous.duck) <= 0.1 and distance(current.origin, previous.origin) <= 64
            if coherent then
                if previous.forecast and math.abs(t - previous.forecast.time) <= h * 0.1 then
                    local stats = self._stats
                    stats.samples = stats.samples + 1
                    stats.hold = stats.hold + distance(current.origin, previous.origin)
                    stats.linear = stats.linear + distance(current.origin, previous.forecast.linear)
                    stats.adaptive = stats.adaptive + distance(current.origin, previous.forecast.adaptive)
                end
                local ax, ay = (vx - previous.velocity[1]) / dt, (vy - previous.velocity[2]) / dt
                local speed = math.sqrt(vx * vx + vy * vy)
                local old_speed = math.sqrt(previous.velocity[1]^2 + previous.velocity[2]^2)
                local cosine = speed > 5 and old_speed > 5
                    and (vx * previous.velocity[1] + vy * previous.velocity[2]) / (speed * old_speed) or 1
                if speed <= 500 and math.sqrt(ax * ax + ay * ay) <= 1000 and cosine >= 0.94 and math.abs(vz) <= 5 then
                    local linear = {x + vx * h, y + vy * h, z + vz * h}
                    current.forecast = {
                        time = t + h,
                        linear = linear,
                        adaptive = {linear[1] + 0.5 * ax * h * h, linear[2] + 0.5 * ay * h * h, linear[3]},
                    }
                end
            end
        end
        self._records[index] = current
    end,
    on_net_update_end = function(self)
        if not control_on(self._menu_ref) then return end
        if not self._active then self:tick() end
        if not self._active then return end
        local now, h = globals.realtime() or 0, globals.tickinterval()
        local rate_value = self:_read('cl_updaterate')
        local function finite_number(value)
            return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
        end
        if not finite_number(h) or h <= 0 or not rate_value or rate_value <= 0 then return end
        local interval = math.max(h, 1 / rate_value)
        if self._last_arrival then
            local dt = now - self._last_arrival
            if dt > interval * 1.8 or dt < 0 then
                self._bad_until, self._samples = now + 4, 0
                if not self._blocked then self:_set_ratio(self._base) end
            elseif dt >= interval * 0.25 then
                self._samples = math.min(256, (self._samples or 0) + 1)
            end
            if dt >= 0 and dt < interval * 0.25 then return end
        end
        self._last_arrival = now
        local ok, latency = pcall(client.latency)
        if ok and finite_number(latency) then
            if self._last_latency and math.abs(latency - self._last_latency) > h then
                self._bad_until, self._samples = now + 4, 0
                if not self._blocked then self:_set_ratio(self._base) end
            end
            self._last_latency = latency
        end
        local players = entity.get_players(true) or {}
        for i = 1, math.min(8, #players) do
            local index = players[i]
            local sampled = pcall(self._sample, self, index, h)
            if not sampled then self._records[index] = nil end
        end
        self:tick()
    end,
    print_stats = function(self)
        local stats = self._stats
        local ratio, rate_value, interp = self:_read('cl_interp_ratio'), self:_read('cl_updaterate'), self:_read('cl_interp')
        local lerp = ratio and rate_value and rate_value > 0 and interp and math.max(interp, ratio / rate_value) or nil
        client.log('[nyameeow.pink] Adaptive interpolation: ' .. self._state .. '; ratio=' .. tostring(ratio)
            .. '; reference lerp=' .. (lerp and string.format('%.3f ms', lerp * 1000) or 'unavailable'))
        if stats.samples > 0 then
            client.log(string.format('[nyameeow.pink] One-tick ground forecast: n=%d, held=%.3fu, linear=%.3fu, adaptive=%.3fu mean position error',
                stats.samples, stats.hold / stats.samples, stats.linear / stats.samples, stats.adaptive / stats.samples))
        else
            client.log('[nyameeow.pink] No comparable one-tick ground forecasts yet')
        end
        client.log('[nyameeow.pink] Forecast is observation only; it does not replace GameSense hitboxes or shot records')
    end,
}

local function reference(tab, group, name)
    local ok, a, b = pcall(ui.reference, tab, group, name)
    if ok and a then return {a, b} end
end

function fixes:init(refs)
    self.refs = refs
    self._dt_ref = reference('RAGE', 'Aimbot', 'Double tap')
    self._duck_ref = reference('RAGE', 'Other', 'Duck peek assist')
    self.air_strafe._menu_ref = refs.air_strafe
    self.air_strafe._smoothing_ref = refs.strafe_smoothing
    self.quick_stop._menu_ref = refs.quick_stop
    self.shot_delay._menu_ref = refs.shot_delay
    self.dt_stability._menu_ref = refs.dt_stability
    self.dt_return._menu_ref = refs.dt_return
    self.defensive_dt._menu_ref = refs.defensive_dt
    self.air_autostop._menu_ref = refs.air_autostop
    self.scan_accuracy._menu_ref = refs.scan_accuracy
    self.spread_autostop._menu_ref = refs.spread_autostop
    self.backtrack._menu_ref = refs.backtrack
    self.adaptive._menu_ref = refs.adaptive
    local backtrack_list = type(refs.backtrack) == 'table' and refs.backtrack.list or refs.backtrack
    if backtrack_list then ui.set_callback(backtrack_list, function()
        self.backtrack._failed = nil
        if not control_on(refs.backtrack) then self.backtrack:restore() end
    end) end
end

function fixes:capture_command(cmd)
    local ok, input = pcall(self.air_strafe.capture, self.air_strafe, cmd)
    if not ok then return nil end
    return input
end

function fixes:setup_command(cmd, input)
    guard('Accurate Quick Stop', self.quick_stop.handle, self.quick_stop)
    guard('Shot Delay Fix', self.shot_delay.handle, self.shot_delay)
    guard('Double Tap Stability Fix', self.dt_stability.handle, self.dt_stability)
    guard('Air Autostop', self.air_autostop.handle, self.air_autostop)
    guard('Scan Accuracy Optimization', self.scan_accuracy.handle, self.scan_accuracy)
    guard('Spread & Autostop Fix', self.spread_autostop.handle, self.spread_autostop)
    guard('Backtrack Record Fix', self.backtrack.handle, self.backtrack)
    guard('Double Tap Return Fix', self.dt_return.handle, self.dt_return)
    guard('Defensive Double Tap', self.defensive_dt.handle, self.defensive_dt, cmd)
    guard('Preserve Animation Flags', self.animation_flags.handle, self.animation_flags,
        control_on(self.refs.animation_flags))
    guard('Neverlose Air Strafe', self.air_strafe.handle, self.air_strafe, cmd, input)
end

function fixes:paint_ui()
    guard('Adaptive interpolation', self.adaptive.tick, self.adaptive)
    guard('Neverlose Air Strafe', self.air_strafe.sync, self.air_strafe)
    if globals.mapname() == nil then
        guard('Air Autostop', self.air_autostop.restore, self.air_autostop)
        guard('Scan Accuracy Optimization', self.scan_accuracy.restore, self.scan_accuracy)
        guard('Spread & Autostop Fix', self.spread_autostop.restore, self.spread_autostop)
        guard('Shot Delay Fix', self.shot_delay.restore, self.shot_delay)
        guard('Double Tap Stability Fix', self.dt_stability.restore, self.dt_stability)
    end
    coordinator:poll()
    guard('Backtrack Record Fix', self.backtrack.on_paint_ui, self.backtrack)
end

function fixes:net_update_end()
    guard('Adaptive interpolation', self.adaptive.on_net_update_end, self.adaptive)
end

function fixes:reset()
    guard('Adaptive interpolation', self.adaptive.stop, self.adaptive)
    self.air_strafe:_reset()
    guard('Air Autostop', self.air_autostop.restore, self.air_autostop)
    guard('Scan Accuracy Optimization', self.scan_accuracy.restore, self.scan_accuracy)
    guard('Spread & Autostop Fix', self.spread_autostop.restore, self.spread_autostop)
    guard('Shot Delay Fix', self.shot_delay.restore, self.shot_delay)
    guard('Double Tap Stability Fix', self.dt_stability.restore, self.dt_stability)
    coordinator:release_all()
    guard('Accurate Quick Stop', self.quick_stop.restore, self.quick_stop)
    guard('Defensive Double Tap', self.defensive_dt.reset, self.defensive_dt)
    guard('Double Tap Return Fix', self.dt_return.restore, self.dt_return)
    guard('Preserve Animation Flags', self.animation_flags.restore, self.animation_flags)
    guard('Backtrack Record Fix', self.backtrack.restore, self.backtrack)
end

function fixes:shutdown()
    self.scan_accuracy._shut = true
    self:reset()
end

return fixes


end,

 

 
['visuals_crosshair'] = function(...)
 
 
 
 
local modules = ...
local statistics = modules and modules.statistics
local indicator = {
    references = {},
    faces = {
        kill = {'(^▽^)', '(≧▽≦)', '＼(^o^)／', '(o^▽^o)'},
        miss = {'(>_<)', '(T_T)', '(ノ_<。)', '(；_；)'},
    },
}
local condition_names = {
    ['Air Crouching'] = 'AIRC',
    Crouching = 'CROUCH',
    Air = 'AIR',
    Sneaking = 'SNEAK',
    Slowing = 'SLOW',
    Running = 'RUN',
    Standing = 'STAND',
}
local function selected(ref, value)
    local choices = ui.get(ref)
    if type(choices) ~= 'table' then return false end
    for _, choice in ipairs(choices) do if choice == value then return true end end
    return false
end
local function native(tab, section, name)
    local ok, first, second = pcall(ui.reference, tab, section, name)
    if not ok or not first then return nil end
    return {first, second}
end
local function active(refs, checkbox_only)
    if not refs or not refs[1] then return false end
    local ok, enabled = pcall(ui.get, refs[1])
    if not ok or not enabled then return false end
    if refs[2] and not checkbox_only then
        local read, hotkey = pcall(ui.get, refs[2])
        if read and type(hotkey) == 'boolean' then return hotkey end
    end
    return true
end
local function condition_text(host)
    local runtime = host.menu and host.menu.builder_runtime
    local current = runtime and runtime.current
    if not current then return 'STAND' end
    if current.legit_aa then return 'LEGIT' end
    if current.effective == 'FREESTANDING' then return 'FS' end
    local detected = current.detected
    if type(detected) ~= 'string' then return 'Stand' end
    return condition_names[detected] or detected
end
local function force_shot_visible(host)
    local refs = host.menu and host.menu.misc_rage and host.menu.misc_rage.refs
    if not refs or not refs.force_shot then return false end
    local ok, enabled = pcall(ui.get, refs.force_shot)
    if not ok or enabled ~= true then return false end
    ok, enabled = pcall(ui.get, refs.force_indicator)
    if not ok or enabled ~= true then return false end
    if not refs.force_shot_key then return true end
    local binds = host.menu.binds
    if binds and type(binds.read) == 'function' then
        local read, value = pcall(binds.read, 'force_shot', refs.force_shot_key)
        if read then return value == true end
    end
    local read, value = pcall(ui.get, refs.force_shot_key)
    return read and value == true
end
function indicator:init(menu)
    self.menu = menu
    self.face_alpha = 0
    self.references = {
        dt = native('RAGE', 'Aimbot', 'Double tap'),
        hs = native('AA', 'Other', 'On shot anti-aim'),
        fd = native('RAGE', 'Other', 'Duck peek assist'),
        qp = native('RAGE', 'Other', 'Quick peek assist'),
        sw = native('AA', 'Other', 'Slow motion'),
        fs = native('AA', 'Anti-aimbot angles', 'Freestanding'),
    }
    local ok, funcs = pcall(require, 'gamesense/antiaim_funcs')
    if ok and type(funcs) == 'table' then self.functions = funcs end
end
function indicator:notify(kind)
    local pool = self.faces[kind]
    if not pool then return end
    self.face_text = pool[math.random(1, #pool)]
    self.face_until = (globals.realtime() or 0) + 2.2
end
function indicator:player_death(e)
    local me = entity.get_local_player()
    if not me or not e then return end
    local victim = client.userid_to_entindex(e.userid or 0)
    if not victim or victim == 0 or victim == me then return end
    if not entity.is_enemy(victim) then return end
    if client.userid_to_entindex(e.attacker or 0) ~= me then return end
    self:notify('kill')
end
function indicator:aim_miss()
    self:notify('miss')
end
function indicator:render(host)
    local r = self.menu.refs
    if not selected(r.windows_select, 'Crosshair Indicator') then
        self.scope_slide, self.jp, self.face_alpha, self.line_animations, self.state_offset = 0, nil, 0, nil, 0
        host:clear_preview('crosshair')
        return
    end
    local player, menu_open = entity.get_local_player(), ui.is_menu_open()
    local alive = player and entity.is_alive(player) or false
    local scoped = alive and entity.get_prop(player, 'm_bIsScoped')
    scoped = scoped == 1 or scoped == true
    local refs = self.references
    local dt, hs = active(refs.dt), active(refs.hs)
    local fd = active(refs.fd, true)
    local sw, sh = client.screen_size()
    if ui.get(r.window_crosshair_style) == 'Japanese' then
        local opacity = host:preview_opacity('crosshair', menu_open, alive)
        self.line_animations = nil
        self.state_offset = 0
        self:render_japanese(host, sw, sh, alive, scoped, dt, hs, opacity)
        return
    end
    self.jp = nil
    local opacity = host:preview_opacity('crosshair', menu_open, alive)
    if opacity <= 0 then return end
    local cr, cg, cb, alpha = ui.get(r.window_crosshair_color)
    if not alpha or alpha < 1 then return end
    alpha = math.floor(alpha * opacity + 0.5)
    if alpha < 1 then return end
    local position = host:position('ci_default', math.floor(sw * 0.5), math.floor(sh * 0.5))
    local percent = statistics and type(statistics.hitrate) == 'function' and statistics.hitrate() or 0
    local binds = {}
    if dt then binds[#binds+1]='DT' end
    if hs then binds[#binds+1]='HS' end
    if fd then binds[#binds+1]='FD' end
    if active(refs.qp) then binds[#binds+1]='QP' end
    if active(refs.sw) then binds[#binds+1]='SW' end
    if active(refs.fs) then binds[#binds+1]='FS' end
    if force_shot_visible(host) then binds[#binds+1]='FORCE' end
    local bind_text = table.concat(binds, '   ')
    local state_text = condition_text(host)
     
    local block_w = 70
    local function widen(width) if width and width > block_w then block_w = width end end
    if self.face_alpha > 0 and self.face_text then
        widen(select(1, renderer.measure_text('', self.face_text)))
    end
    widen(select(1, renderer.measure_text('b', 'nyameeow.pink')))
    widen(select(1, renderer.measure_text('-', 'HITRATE   ' .. tostring(percent) .. ' %')))
    if bind_text ~= '' then widen(select(1, renderer.measure_text('-', bind_text))) end
    widen(select(1, renderer.measure_text('-', state_text)))
    block_w = block_w + 12
    local ft = math.max(0, math.min(0.05, globals.frametime()))
     
    self.scope_slide = (self.scope_slide or 0) + ((scoped and 1 or 0) - (self.scope_slide or 0)) * (1 - math.exp(-18 * ft))
    if self.scope_slide < 0.001 then self.scope_slide = 0 elseif self.scope_slide > 0.999 then self.scope_slide = 1 end
    local x = position.x + 48 * self.scope_slide
    local y = position.y
    local function left_x(width)
        return x - (width or 0) * 0.5 * (1 - self.scope_slide)
    end
    local block_left = left_x(block_w)
    host:drag_item('ci_default', block_left, y - 16, block_w, 66, 0, position.x - block_left, 16)
    local now = globals.realtime() or 0
    local want = (self.face_text and now < (self.face_until or 0)) and 1 or 0
    local rate = want > (self.face_alpha or 0) and 26 or 12
    self.face_alpha = (self.face_alpha or 0) + (want - (self.face_alpha or 0)) * (1 - math.exp(-rate * ft))
    if want == 0 and self.face_alpha < 0.01 then self.face_alpha = 0 end
    if self.face_alpha > 0 and self.face_text then
        local fw, fh = renderer.measure_text('', self.face_text)
        fw, fh = fw or 0, fh or 10
        renderer.text(math.floor(left_x(fw) + 0.5), math.floor(y - fh - 3), 255, 255, 255,
            math.floor(alpha * self.face_alpha + 0.5), '', 0, self.face_text)
    end
    local title = 'nyameeow.pink'
    local width, height = renderer.measure_text('b', title)
    width, height = width or 0, height or 10
    local cursor = left_x(width)
    self.title_phase = ((self.title_phase or 0) + ft * 2.4) % (math.pi * 2)
    local travel = (1 - math.cos(self.title_phase)) * 0.5
    for i = 1, #title do
        local ch = title:sub(i,i)
        local unit = (i - 1) / math.max(#title - 1, 1)
        local mix = math.max(0, math.min(1, 1 - math.abs(unit - travel) / 0.42))
        mix = mix * mix * (3 - 2 * mix)
        renderer.text(math.floor(cursor + 0.5), y, math.floor(255 + (cr-255)*mix+0.5),
            math.floor(255 + (cg-255)*mix+0.5), math.floor(255 + (cb-255)*mix+0.5), alpha, 'b', 0, ch)
        cursor = cursor + (select(1, renderer.measure_text('b', ch)) or 0)
    end
    local line_y = y + height + 2
    local rate_label, rate_value = 'HITRATE ', tostring(percent) .. '%'
    local rate_width, rate_height = renderer.measure_text('-', rate_label .. rate_value)
    local label_width = renderer.measure_text('-', rate_label)
    rate_width, rate_height = rate_width or 0, rate_height or 10
    label_width = label_width or 0
    local rate_x = math.floor(left_x(rate_width) + 0.5)
    renderer.text(rate_x, line_y, 255, 255, 255, alpha, '-', 0, rate_label)
    renderer.text(math.floor(rate_x + label_width + 0.5), line_y, cr, cg, cb, alpha, '-', 0, rate_value)
    line_y = line_y + rate_height + 2
    self.line_animations = self.line_animations or {}
    local fade_in = 1 - math.exp(-16 * ft)
    local fade_out = 1 - math.exp(-20 * ft)
    local function fading_line(key, row_y, value)
        local anim = self.line_animations[key]
        if not anim then
            anim = {text = value, alpha = 0}
            self.line_animations[key] = anim
        end
        if value ~= anim.text then
            if anim.text ~= '' and anim.alpha > 0.01 then
                anim.outgoing, anim.outgoing_alpha = anim.text, anim.alpha
            end
            anim.text, anim.alpha = value, 0
        end
        anim.alpha = anim.alpha + (1 - anim.alpha) * fade_in
        if anim.outgoing then
            anim.outgoing_alpha = (anim.outgoing_alpha or 0) * (1 - fade_out)
            if anim.outgoing_alpha < 0.01 then anim.outgoing, anim.outgoing_alpha = nil, 0 end
        end
        local function draw(text, opacity)
            if text == '' or opacity <= 0.01 then return end
            local lw = renderer.measure_text('-', text)
            lw = lw or 0
            renderer.text(math.floor(left_x(lw) + 0.5), math.floor(row_y + 0.5), 255, 255, 255,
                math.floor(alpha * opacity + 0.5), '-', 0, text)
        end
        if anim.outgoing then draw(anim.outgoing, anim.outgoing_alpha) end
        draw(anim.text, anim.alpha)
    end
    local row_step = math.max(rate_height, 10) + 2
    local target_state_offset = bind_text ~= '' and row_step or 0
    self.state_offset = (self.state_offset or 0) + (target_state_offset - (self.state_offset or 0)) * (1 - math.exp(-14 * ft))
    fading_line('binds', line_y, bind_text)
    fading_line('state', line_y + self.state_offset, state_text)
end
function indicator:render_japanese(host, sw, sh, alive, scoped, dt, hs, preview_opacity)
    local state = self.jp or {alive=0, scoped=0, dt=0, hs=0, damage=0}
    self.jp = state
    local duck = active(self.references.fd)
    local override = false
    if host.override_enabled and host.override_hotkey and ui.get(host.override_enabled) then
        if host.menu and host.menu.binds then override = host.menu.binds.read('damage_override', host.override_hotkey)
        else override = ui.get(host.override_hotkey) == true end
    end
    local targets = {alive=(alive or preview_opacity > 0) and 1 or 0, scoped=scoped and 1 or 0,
        dt=dt and 1 or 0, hs=(not dt and hs) and 1 or 0, damage=override and 1 or 0}
    local ft = math.max(0, math.min(0.1, globals.frametime()))
    for k,v in pairs(targets) do state[k]=state[k]+(v-state[k])*(1-math.exp(-(k=='alive' and 14 or 18)*ft)) end
    if state.scoped < 0.001 then state.scoped = 0 elseif state.scoped > 0.999 then state.scoped = 1 end
    local pos = host:position('ci_japanese', sw * 0.5 + 22, sh * 0.5)
    if not self.jp_block_w then
        local widest = 90
        for _, item in ipairs({
            {'', 'てんしのような YAW'}, {'', 'どうてきな'},
            {'', 'リセット YAW'}, {'', 'デフォルト'},
            {'', '倍の (フェイクダック)'}, {'', 'アンチエイム (フェイクダック)'},
            {'-', 'ダメージ 000'},
        }) do
            local w = select(1, renderer.measure_text(item[1], item[2])) or 0
            if w > widest then widest = w end
        end
        self.jp_block_w = widest + 12
    end
    local x, y = pos.x + 48 * state.scoped, pos.y
    local block_left = x - self.jp_block_w * 0.5 * (1 - state.scoped)
    host:drag_item('ci_japanese', block_left, y, self.jp_block_w, 70, 0, pos.x - block_left, 0)
    if preview_opacity <= 0 or state.alive <= 0.01 then return end
    local function line(value, red, green, blue, opacity, flags)
        flags = flags or ''
        local width = renderer.measure_text(flags, value) or 0
        local text_x = x - width * 0.5 * (1 - state.scoped)
        renderer.text(math.floor(text_x + 0.5), math.floor(y), red, green, blue,
            math.floor(opacity * state.alive * preview_opacity + 0.5), flags, 0, value)
        local _,h=renderer.measure_text(flags,value); y=y+math.max(h or 8,8)
    end
    local aa = host.menu and host.menu.builder_runtime
    if aa and aa.manual_applied == true then
        line('リセット YAW', 177, 151, 255, 255)
        line('デフォルト', 255, 0, 0, 255)
    else
        line('てんしのような YAW', 218, 118, 0, 255)
        line('どうてきな', 209, 139, 230, 255)
    end
    if state.dt > 0.02 then
        local red, green = 255, 0
        if self.functions and self.functions.get_double_tap then
            local ok, charged = pcall(self.functions.get_double_tap)
            if ok and charged then red, green = 0, 255 end
        end
        line(duck and '倍の (フェイクダック)' or '倍の', red, green, 0, 255*state.dt)
    elseif state.hs > 0.02 then
        line(duck and 'アンチエイム (フェイクダック)' or 'アンチエイム', duck and 255 or 209, duck and 0 or 139, duck and 0 or 230, 255*state.hs)
    end
    if state.damage > 0.02 and host.override_value then
        local value = ui.get(host.override_value)
        if type(value)=='number' then
            line('ダメージ ' .. tostring(value), 255, 255, 255, 225*state.damage, '-')
        end
    end
end
return indicator


end,

 
['visuals_manual_arrows'] = function(...)
 
 
local modules = ...
local DEFAULT_OFFSET, MIN_OFFSET, MAX_OFFSET = 45, 24, 220
local Class = {util = {}, ui = {menu = {visuals_tab = {interface = {}}}}}
local arrows = {
 _ease = function(self, current, target, rate)
   local dt = math.max(0, math.min(0.1, globals.frametime()))
   return current + (target - current) * (1 - math.exp(-rate * dt))
 end,
 _reset_styles = function(self)
   self.dot, self.pointers, self.modern_state, self.custom_state = nil, nil, nil, nil
   self.skeet_fade = nil
   self.strip_alpha, self.snap_alpha = nil, nil
 end,
 _glow_dot = function(self, x, y, color, alpha, scale)
   local core = math.max(1, math.floor(2 * scale + 0.5))
   local extent = math.floor(22 * scale + 0.5)
   for i = 7, 1, -1 do
     local t = i / 10
     renderer.circle(x, y, math.floor(color[1]), math.floor(color[2]), math.floor(color[3]),
       math.floor(alpha * 0.44 * (1 - t)^1.15), core + math.floor(extent * t + 0.5), 0, 1)
   end
 end,
 _render_cs2 = function(self, menu_item, cx, cy, offset, dir, color)
   local _, height = renderer.measure_text("d", "a")
   local scale = math.max(1, (height or 12) / 12)
    
   local distance = math.floor(offset * (78 / 42) * scale + 0.5)
   cx, cy = cx + 1, cy + 1
   local x, y = cx, cy + distance
   local idle = {menu_item.cs2_idle_color:get()}
   local target = dir == 0 and idle or color
   if dir == 1 then x, y = cx - distance, cy
   elseif dir == 2 then x, y = cx + distance, cy
   elseif dir == 3 then x, y = cx, cy - distance end
   local now = globals.realtime()
   local state = self.dot
   if not state then
     state = {x = x, y = y, color = {target[1], target[2], target[3]}, alpha = 0, trails = {}}
      
     if dir == 0 then state.idle_since = now - 1 end
     self.dot = state
   end
   local px, py = state.x, state.y
   local previous = {state.color[1], state.color[2], state.color[3]}
   state.x = self:_ease(state.x, x, 19.71)
   state.y = self:_ease(state.y, y, 19.71)
   for i = 1, 3 do state.color[i] = self:_ease(state.color[i], target[i], 13.39) end
   if (state.x - px)^2 + (state.y - py)^2 > (scale * 5)^2 then
     state.trails[#state.trails + 1] = {x = px, y = py, color = previous, time = now}
     if #state.trails > 3 then table.remove(state.trails, 1) end
   end
   if dir ~= 0 then state.idle_since = nil
   elseif math.abs(state.x - x) <= scale and math.abs(state.y - y) <= scale then
     state.idle_since = state.idle_since or now
   else state.idle_since = nil end
   local alpha = target[4] or 255
   if state.idle_since and now - state.idle_since > 0.3 then alpha = 0 end
   state.alpha = self:_ease(state.alpha, alpha, 12.64)
   for i = #state.trails, 1, -1 do
     local trail = state.trails[i]
     local fade = 1 - (now - trail.time) / 0.22
     if fade <= 0 then table.remove(state.trails, i)
     elseif state.alpha > 1 then
       self:_glow_dot(trail.x, trail.y, trail.color, state.alpha * fade * 0.25, scale)
     end
   end
   if state.alpha > 1 then self:_glow_dot(state.x, state.y, state.color, state.alpha, scale) end
 end,
 _render_modern = function(self, cx, cy, dir, color)
    
    
    
   local state = self.modern_state
   if not state then
     state = {angle = 90, alpha = 0, active = false, center_time = 0}
     self.modern_state = state
   end
   if dir ~= 1 and dir ~= 2 and dir ~= 3 then dir = 0 end

   local dt = 1 / 60
   pcall(function() dt = math.max(0, math.min(0.05, globals.frametime())) end)
   local target_angle = dir == 1 and 150 or dir == 2 and 30 or 90
   if dir ~= 0 then
     state.active, state.center_time = true, 0
   elseif not state.active then
     return
   end

   local speed = (dir == 0) and 32 or 22
   state.angle = state.angle + (target_angle - state.angle) * (1 - math.exp(-speed * dt))
   if math.abs(target_angle - state.angle) < 0.15 then state.angle = target_angle end

   if dir ~= 0 then
     state.alpha = state.alpha + (1 - state.alpha) * (1 - math.exp(-30 * dt))
   else
     if math.abs(state.angle - 90) <= 1 then
       state.center_time = state.center_time + dt
       if state.center_time >= 0.06 then
         state.alpha = state.alpha * math.exp(-25 * dt)
       end
     else
       state.center_time = 0
     end
     if state.alpha <= 0.01 and state.center_time >= 0.06 then
       state.angle, state.alpha, state.active, state.center_time = 90, 0, false, 0
       return
     end
   end

   local visibility = math.max(0, math.min(1, state.alpha))
   if visibility < 0.001 then return end

   local cr = math.max(0, math.min(255, tonumber(color and color[1]) or 138))
   local cg = math.max(0, math.min(255, tonumber(color and color[2]) or 172))
   local cb = math.max(0, math.min(255, tonumber(color and color[3]) or 218))
   local ca = math.max(0, math.min(255, tonumber(color and color[4]) or 255))

    
    
   local tex = self.modern_textures
   if not tex then
     tex = {active = {}}
     self.modern_textures = tex
   end
   local sprites = self.modern_png_sprites
   if not sprites then
     sprites = {
    [-1] = nyameeow_decode64(''),
    [0] = nyameeow_decode64(''),
    [1] = nyameeow_decode64(''),
    [2] = nyameeow_decode64(''),
    [3] = nyameeow_decode64(''),
    [4] = nyameeow_decode64(''),
    [5] = nyameeow_decode64(''),
    [6] = nyameeow_decode64(''),
    [7] = nyameeow_decode64(''),
    [8] = nyameeow_decode64(''),
    [9] = nyameeow_decode64(''),
    [10] = nyameeow_decode64(''),
    [11] = nyameeow_decode64(''),
    [12] = nyameeow_decode64(''),
    [13] = nyameeow_decode64(''),
    [14] = nyameeow_decode64(''),
    [15] = nyameeow_decode64(''),
    [16] = nyameeow_decode64(''),
    [17] = nyameeow_decode64(''),
    [18] = nyameeow_decode64(''),
    [19] = nyameeow_decode64(''),
    [20] = nyameeow_decode64(''),
