    [120] = nyameeow_decode64(''),
     }
     self.modern_png_sprites = sprites
   end

   local function load_texture(data)
     if type(renderer.load_png) ~= 'function' then return nil end
     local ok, id = pcall(renderer.load_png, data, 84, 84)
     if ok and type(id) == 'number' and id >= 0 then return id end
     return nil
   end

    
    
   local now = 0
   pcall(function() now = globals.realtime() end)
   if tex.track == nil or (tex.track == false and now >= (tex.track_retry_at or 0)) then
     tex.track = load_texture(sprites[-1]) or false
     if tex.track == false then
       tex.track_retry_at = now + 1
       if not tex.warned then
         tex.warned = true
         pcall(client.error_log, '[nyameeow.pink] Modern: renderer.load_png failed; retrying')
       end
     else
       tex.warned = false
     end
   end
   if tex.track == false then return end

   local index = math.floor(math.max(0, math.min(120, state.angle - 30)) + 0.5)
   local active_tex = tex.active[index]
   tex.active_retry_at = tex.active_retry_at or {}
   if active_tex == nil or (active_tex == false and now >= (tex.active_retry_at[index] or 0)) then
     active_tex = load_texture(sprites[index]) or false
     tex.active[index] = active_tex
     if active_tex == false then
       tex.active_retry_at[index] = now + 1
     end
   end

   local x = math.floor(cx - 42 + 0.5)
   local y = math.floor(cy + 1 - 42 + 0.5)
   renderer.texture(tex.track, x, y, 84, 84, 132, 140, 154,
     math.floor(108 * visibility + 0.5))
   if active_tex ~= false then
     renderer.texture(active_tex, x, y, 84, 84, cr, cg, cb,
       math.floor(ca * visibility + 0.5))
   end
 end,

 _font_flags = function(self, name)
   if name == "Pixel" then return "-"
   elseif name == "Bold" then return "b"
   elseif name == "Large" then return "+"
   end
   return ""
 end,
 _clamp = function(_, v, lo, hi)
   if v < lo then return lo end
   if v > hi then return hi end
   return v
 end,
 _read_aa = function(self)
   local body, desync = 0, 0
   pcall(function()
     if antiaim_funcs.get_body_yaw then
       body = tonumber(antiaim_funcs.get_body_yaw()) or 0
     end
   end)
   pcall(function()
     if antiaim_funcs.get_desync then
       desync = tonumber(antiaim_funcs.get_desync()) or 0
     end
   end)
   return body, desync
 end,
 _arrow = function(self, side, cx, cy, size, r, g, b, a)
   size = math.floor(size + 0.5)
   if side < 0 then
     renderer.triangle(
       cx - size, cy,
       cx + size * 0.35, cy - size,
       cx + size * 0.35, cy + size,
       r, g, b, a
     )
   else
     renderer.triangle(
       cx + size, cy,
       cx - size * 0.35, cy - size,
       cx - size * 0.35, cy + size,
       r, g, b, a
     )
   end
 end,
 _bar = function(self, x, y, w, h, frac, r, g, b, a)
   frac = self:_clamp(frac or 0, 0, 1)
   renderer.rectangle(x, y, w, h, 20, 20, 20, math.floor(a * 0.55))
   local fill = math.floor(w * frac + 0.5)
   if fill > 0 then
     renderer.rectangle(x, y, fill, h, r, g, b, a)
   end
 end,
 _render_custom = function(self, menu_item, cx, cy, offset, r, g, b, a)
   local aa = Class.util.antiaim
   local dir = 0
   if aa and aa.manual_applied == true then
     dir = tonumber(aa.manual_direction) or 0
   end
   if dir ~= 1 and dir ~= 2 and dir ~= 3 then dir = 0 end
   local dt = 1 / 60
   pcall(function() dt = math.max(0, math.min(0.05, globals.frametime())) end)
   local state = self.custom_state
   if not state then
     state = {alpha = 0, dir = 0}
     self.custom_state = state
   end
   if dir ~= 0 then
     state.dir = dir
     state.alpha = state.alpha + (1 - state.alpha) * (1 - math.exp(-42 * dt))
   else
     state.alpha = state.alpha * math.exp(-30 * dt)
     if state.alpha <= 0.01 then
       state.alpha, state.dir = 0, 0
       return
     end
   end
   local fade = math.max(0, math.min(1, state.alpha))
   if fade <= 0.001 then return end
   a = math.floor((tonumber(a) or 255) * fade)
   local font = self:_font_flags(menu_item.font and menu_item.font:get() or "Default")
   local left_sym = menu_item.left and menu_item.left:get() or ""
   local right_sym = menu_item.right and menu_item.right:get() or ""
   local fwd_sym = menu_item.forward and menu_item.forward:get() or ""
   local flags = font .. "c"

    
   local draw_dir = dir ~= 0 and dir or state.dir
   if left_sym ~= "" and draw_dir == 1 then
     renderer.text(cx - offset, cy, r, g, b, a, flags, 0, left_sym)
   end
   if right_sym ~= "" and draw_dir == 2 then
     renderer.text(cx + offset, cy, r, g, b, a, flags, 0, right_sym)
   end
   if fwd_sym ~= "" and draw_dir == 3 then
     renderer.text(cx, cy - offset, r, g, b, a, flags, 0, fwd_sym)
   end
 end,
 _render_team_skeet = function(self, menu_item, cx, cy, offset, yaw_r, yaw_g, yaw_b, yaw_a)
    
   local body_r, body_g, body_b, body_a = 56, 158, 252, 255
   pcall(function()
     if menu_item.body_color then
       body_r, body_g, body_b, body_a = menu_item.body_color:get()
     end
   end)

   local off = math.max(MIN_OFFSET, math.min(MAX_OFFSET, tonumber(offset) or DEFAULT_OFFSET))
   local def_r, def_g, def_b, def_a = 35, 35, 35, 150

   local aa_state = Class.util.antiaim
   local dir = 0
   if aa_state and aa_state.manual_applied == true then
     dir = tonumber(aa_state.manual_direction) or 0
   end
   local body_side = 0
   local me = entity.get_local_player()

    
   pcall(function()
     local body = tonumber(antiaim_funcs.get_body_yaw()) or 0
     if body < -1 then body_side = -1
     elseif body > 1 then body_side = 1
     end
   end)
   if body_side == 0 and me and entity.is_alive(me) then
     pcall(function()
       local pose = entity.get_prop(me, "m_flPoseParameter", 11)
       if type(pose) == "number" then
         local deg = pose * 120 - 60
         if deg < -2 then body_side = -1
         elseif deg > 2 then body_side = 1
         end
       end
     end)
   end
    
    
   local dt = 1 / 60
   pcall(function() dt = math.max(0, math.min(0.05, globals.frametime())) end)
   local fade = self.skeet_fade
   if not fade then
     fade = {left = 0, right = 0, body_left = 0, body_right = 0}
     self.skeet_fade = fade
   end
    
    
   local preview = ui.is_menu_open() == true and 0.55 or nil
   local targets = {
     left = dir == 1 and 1 or preview or 0,
     right = dir == 2 and 1 or preview or 0,
     body_left = body_side < 0 and 1 or 0,
     body_right = body_side > 0 and 1 or 0,
   }
   for side, target in pairs(targets) do
     local value = fade[side] or 0
     local body = side == "body_left" or side == "body_right"
     local rate
     if target > value then
       rate = body and 42 or 26
     else
       rate = body and 30 or 14
     end
     value = value + (target - value) * (1 - math.exp(-rate * dt))
     if target == 0 and value < 0.004 then value = 0 end
     fade[side] = value
   end
   local function shade(idle, active, t) return math.floor(idle + (active - idle) * t + 0.5) end
   local function blend(t, r0, g0, b0, a0, r1, g1, b1, a1)
     if t <= 0.001 then return r0, g0, b0, a0 end
     return shade(r0, r1, t), shade(g0, g1, t), shade(b0, b1, t), shade(a0, a1, t)
   end

    
   do
     renderer.triangle(
       cx - off - 15, cy + 2,
       cx - off - 2, cy - 7,
       cx - off - 2, cy + 11,
       def_r, def_g, def_b, def_a
     )
     local t = fade.left
     if t > 0 then
       renderer.triangle(
         cx - off - 15, cy + 2,
         cx - off - 2, cy - 7,
         cx - off - 2, cy + 11,
         yaw_r, yaw_g, yaw_b, math.floor(yaw_a * t + 0.5)
       )
     end
   end
    
   do
     renderer.triangle(
       cx + off + 15, cy + 2,
       cx + off + 2, cy - 7,
       cx + off + 2, cy + 11,
       def_r, def_g, def_b, def_a
     )
     local t = fade.right
     if t > 0 then
       renderer.triangle(
         cx + off + 15, cy + 2,
         cx + off + 2, cy - 7,
         cx + off + 2, cy + 11,
         yaw_r, yaw_g, yaw_b, math.floor(yaw_a * t + 0.5)
       )
     end
   end
    
   do
     local r, g, b, a = blend(fade.body_left, def_r, def_g, def_b, def_a, body_r, body_g, body_b, body_a)
     renderer.rectangle(cx - off, cy - 7, 2, 18, r, g, b, a)
   end
   do
     local r, g, b, a = blend(fade.body_right, def_r, def_g, def_b, def_a, body_r, body_g, body_b, body_a)
     renderer.rectangle(cx + off - 2, cy - 7, 2, 18, r, g, b, a)
   end
 end,
 _draw_hint = function(self, x, y, text)
   local sw, sh = client.screen_size()
   local w, h = renderer.measure_text('bc', text)
   w, h = tonumber(w) or 110, tonumber(h) or 10
   x = math.floor(math.max(w * 0.5, math.min(x or 0, sw - w * 0.5)) + 0.5)
   y = math.floor(math.max(0, math.min(y or 0, sh - h)) + 0.5)
   local r, g, b = 140, 110, 115
   if modules and modules.text and type(modules.text.menu_color) == 'function' then
     local ok, cr, cg, cb = pcall(modules.text.menu_color)
     if ok then r, g, b = cr or r, cg or g, cb or b end
   end
   renderer.text(x + 1, y + 1, 0, 0, 0, 180, 'bc', 0, text)
   renderer.text(x, y, r, g, b, 255, 'bc', 0, text)
 end,
 _load_offset = function(self)
   if self.offset_value == nil then self.offset_value = DEFAULT_OFFSET end
   self.offset_value = math.max(MIN_OFFSET, math.min(MAX_OFFSET, math.floor((tonumber(self.offset_value) or DEFAULT_OFFSET) + 0.5)))
   return self.offset_value
 end,
  
 _save_offset = function(self)
   return self.offset_value
 end,
 _manual_offset = function(self, cx, cy, style, dir, item)
   local offset = self:_load_offset()
   if not ui.is_menu_open() then
     if self.offset_drag then self.offset_drag = nil; self:_save_offset() end
     self.offset_right = nil
     self.strip_alpha, self.snap_alpha = nil, nil
     return offset
   end
   local ok, mx, my = pcall(ui.mouse_position)
   if not ok then return offset end
   mx, my = tonumber(mx) or -1000, tonumber(my) or -1000
   local down = client.key_state(0x01) == true
   local right = client.key_state(0x02) == true
   local distance, factor, base_x, base_y = offset, 1, cx, cy
   local left_visible, right_visible, forward_visible = false, false, false
   local hit_w, hit_h = 38, 30
   local shift = 0
   if style == "Team Skeet" then
     left_visible, right_visible, shift = true, true, 8
   elseif style == "Custom" then
     left_visible, right_visible, forward_visible = dir == 1, dir == 2, dir == 3
     local symbol = item and (dir == 1 and item.left or dir == 2 and item.right or dir == 3 and item.forward)
     local ok_sym, value = false
     if symbol then ok_sym, value = pcall(function() return symbol:get() end) end
     if ok_sym and type(value) == "string" and value ~= "" then
       local font = "c"
       pcall(function()
         local selected = item.font and item.font:get() or "Default"
         if selected == "Pixel" then font = "-c"
         elseif selected == "Bold" then font = "bc"
         elseif selected == "Large" then font = "+c" end
       end)
       local w, h = renderer.measure_text(font, value)
       hit_w = math.max(hit_w, math.min(180, (tonumber(w) or 0) + 16))
       hit_h = math.max(hit_h, math.min(64, (tonumber(h) or 0) + 12))
     else
       left_visible, right_visible, forward_visible = false, false, false
     end
   elseif style == "CS2" then
     local _, h = renderer.measure_text("d", "a")
     factor = (78 / 42) * math.max(1, (tonumber(h) or 12) / 12)
     distance, base_x, base_y = math.floor(offset * factor + 0.5), cx + 1, cy + 1
     left_visible, right_visible, forward_visible = dir == 1, dir == 2, dir == 3
   end
   local function hit(x, y)
     return mx >= x - hit_w * 0.5 and mx <= x + hit_w * 0.5
       and my >= y - hit_h * 0.5 - 3 and my <= y + hit_h * 0.5 + 3
   end
   local left_x, right_x = base_x - distance - shift, base_x + distance + shift
   local forward_y = base_y - distance
   local dot = style == "CS2" and self.dot or nil
   local dot_hit = dot and (tonumber(dot.alpha) or 0) > 1 and hit(dot.x, dot.y)
   local over_left = left_visible and (style == "CS2" and dot_hit or hit(left_x, base_y)) or false
   local over_right = right_visible and (style == "CS2" and dot_hit or hit(right_x, base_y)) or false
   local over_forward = forward_visible and (style == "CS2" and dot_hit or hit(base_x, forward_y)) or false
   local hovered = over_left or over_right or over_forward

   local runtime = self.menu and self.menu.visuals_runtime
   local busy = runtime and runtime.drag ~= nil or false
   if runtime and not busy and (hovered or self.offset_drag) then
     runtime.drag_hovered = true
   end

   if right and not self.offset_right and hovered and not self.offset_drag and not busy then
     self.offset_value, offset = DEFAULT_OFFSET, DEFAULT_OFFSET
     self:_save_offset()
   end
   self.offset_right = right

   if self.offset_drag then
     if down then
       local cursor = self.offset_axis == "y" and my or mx
       local delta = (cursor - self.offset_start_cursor) * self.offset_side / self.offset_factor
       local next_offset = math.floor(math.max(MIN_OFFSET, math.min(MAX_OFFSET,
         self.offset_start_value + delta)) + 0.5)
       if math.abs(next_offset - DEFAULT_OFFSET) <= 6 then next_offset = DEFAULT_OFFSET end
       if next_offset ~= offset then
         self.offset_value, offset = next_offset, next_offset
         distance = math.floor(next_offset * factor + 0.5)
       end
       self:_draw_hint(base_x, base_y + hit_h * 0.5 + 10, tostring(offset) .. 'px')
     else
       self.offset_drag = nil
       self:_save_offset()
     end
   elseif down and hovered and not busy then
     self.offset_drag = true
     self.offset_axis = over_forward and "y" or "x"
     self.offset_start_cursor = over_forward and my or mx
     self.offset_start_value, self.offset_factor = offset, factor
     self.offset_side = (over_left or over_forward) and -1 or 1
   elseif hovered and not busy then
     self:_draw_hint(over_forward and base_x or over_left and left_x or right_x,
       base_y + hit_h * 0.5 + 10, 'press m2 to reset (45px)')
   end
   local dragging = self.offset_drag == true
   local ft = math.max(0, math.min(0.05, globals.frametime()))
   self.strip_alpha = (self.strip_alpha or 0)
     + ((dragging and 1 or 0) - (self.strip_alpha or 0)) * (1 - math.exp(-16 * ft))
   if self.strip_alpha < 0.01 then self.strip_alpha = 0 end
   local close = dragging and math.abs(offset - DEFAULT_OFFSET) <= 6 or false
   self.snap_alpha = (self.snap_alpha or 0)
     + ((close and 1 or 0) - (self.snap_alpha or 0)) * (1 - math.exp(-10 * ft))
   if self.snap_alpha < 0.01 then self.snap_alpha = 0 end
   if self.strip_alpha > 0 or self.snap_alpha > 0 then
     local r, g, b = 140, 110, 115
     if modules and modules.text and type(modules.text.menu_color) == 'function' then
       local ok, cr, cg, cb = pcall(modules.text.menu_color)
       if ok then r, g, b = cr or r, cg or g, cb or b end
     end
     if self.strip_alpha > 0 then
        
       local a = math.floor(120 * self.strip_alpha + 0.5)
       local edge = math.floor(a * 0.12 + 0.5)
       if self.offset_axis == 'y' then
         renderer.gradient(base_x - 1, base_y - distance, 2, distance, r, g, b, a, r, g, b, edge, false)
       else
         renderer.gradient(base_x - distance, base_y - 1, distance, 2, r, g, b, a, r, g, b, edge, true)
         renderer.gradient(base_x, base_y - 1, distance, 2, r, g, b, edge, r, g, b, a, true)
       end
     end
     if self.snap_alpha > 0 then
        
       local da = math.floor(255 * self.snap_alpha + 0.5)
       local ga = math.floor(90 * self.snap_alpha + 0.5)
       local snap_distance = math.floor(DEFAULT_OFFSET * factor + 0.5)
       if self.offset_axis == 'y' then
         renderer.circle(base_x, base_y - snap_distance, r, g, b, da, 3, 0, 1)
         renderer.circle_outline(base_x, base_y - snap_distance, r, g, b, ga, 6, 0, 1)
       else
         renderer.circle(base_x - snap_distance, base_y, r, g, b, da, 3, 0, 1)
         renderer.circle(base_x + snap_distance, base_y, r, g, b, da, 3, 0, 1)
         renderer.circle_outline(base_x - snap_distance, base_y, r, g, b, ga, 6, 0, 1)
         renderer.circle_outline(base_x + snap_distance, base_y, r, g, b, ga, 6, 0, 1)
       end
     end
   end
   return offset
 end,
 render = function(self)
   local item = Class.ui.menu.visuals_tab.interface.manual_arrows
   if not item or not item.enabled:get() then
     self:_reset_styles()
     self.offset_drag = nil
     self.last_style = nil
     return
   end
   local style = item.style and item.style:get() or "Team Skeet"
    
   if style == "Arc" then
     style = "Modern"
     pcall(function() item.style:set("Modern") end)
   end
   if self.last_style ~= style then self:_reset_styles(); self.last_style = style end
   local player = entity.get_local_player()
   local alive = player and entity.is_alive(player)
   if not alive and not ui.is_menu_open() then
     self:_reset_styles()
     return
   end
   local aa = Class.util.antiaim
   local dir = aa and aa.manual_applied == true and tonumber(aa.manual_direction) or 0
   if dir ~= 1 and dir ~= 2 and dir ~= 3 then dir = 0 end
   local width, height = client.screen_size()
   local cx, cy = math.floor(width * 0.5), math.floor(height * 0.5)
    
    
   local offset = DEFAULT_OFFSET
   if style == "Team Skeet" or style == "Custom" or style == "CS2" then
     offset = self:_manual_offset(cx, cy, style, dir, item)
   end

   local color_control = style == "Team Skeet" and item.yaw_color
     or style == "Modern" and item.arc_color
     or item.custom_color
   local color = { color_control:get() }
   if style == "Team Skeet" then
     self:_render_team_skeet(item, cx, cy, offset, unpack(color))
   elseif style == "CS2" then
     self:_render_cs2(item, cx, cy, offset, dir, color)
   elseif style == "Modern" then
     local modern_direction = aa and tonumber(aa.manual_direction) or 0
     if modern_direction ~= 1 and modern_direction ~= 2 and modern_direction ~= 3 then
       modern_direction = 0
     end
     self:_render_modern(cx, cy, modern_direction, color)
   else
     self:_render_custom(item, cx, cy, offset, unpack(color))
   end
 end,
}

local function control(ref)
    if not ref then return nil end
    return {
        get = function() return ui.get(ref) end,
        set = function(_, ...) return ui.set(ref, ...) end,
    }
end

function arrows:init(menu)
    self.menu = menu
end

function arrows:reset()
    self:_reset_styles()
    self.last_style = nil
end

function arrows:paint()
    local menu = self.menu
    local refs = menu and menu.visuals and menu.visuals.refs
    if not refs then self:_reset_styles(); return end

    local item = {
        enabled = control(refs.manual),
        style = control(refs.manual_style),
        yaw_color = control(refs.yaw_color),
        body_color = control(refs.body_color),
        custom_color = control(refs.custom_color),
        arc_color = control(refs.arc_color),
        cs2_idle_color = control(refs.idle_color),
        font = control(refs.manual_font),
        left = control(refs.left_symbol),
        right = control(refs.right_symbol),
        forward = control(refs.forward_symbol),
    }
    Class.ui.menu.visuals_tab.interface.manual_arrows = item
    Class.util.antiaim = menu.builder_runtime
    self:render()
    local runtime = menu.visuals_runtime
    if runtime then
        runtime.arrow_drag = ui.is_menu_open() == true and self.offset_drag == true or false
    end
end

return arrows


end,

 
