	fire = {1.0397, [[<svg version="1.1" id="Layer_1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" x="0px" y="0px" width="30.093px" height="28.944px" viewBox="0 0 30.093 28.944" enable-background="new 0 0 30.093 28.944" xml:space="preserve"><g id="guides"></g><path fill-rule="evenodd" clip-rule="evenodd" fill="#FFFFFF" d="M11.443,8.821c0.219,1.083,0.241,2.045,0.064,2.887 c-0.177,0.843-0.336,1.433-0.479,1.771c0.133-0.249,0.324-0.531,0.572-0.848c0.708-0.906,1.706-1.641,2.993-2.201 c0.661-0.29,1.171-0.501,1.527-0.635c1.144-0.434,1.763-0.995,1.859-1.687c0.082-0.563,0.043-1.144-0.118-1.74 c-0.155-0.586-0.193-1.108-0.117-1.567c0.099-0.591,0.483-1.083,1.153-1.478c0.258-0.152,0.51-0.269,0.757-0.35 c-0.037,0.022-0.114,0.263-0.229,0.722c-0.115,0.458-0.038,1.018,0.234,1.676c0.271,0.658,0.472,1.133,0.604,1.42 c0.132,0.29,0.241,0.853,0.324,1.689c0.084,0.838-0.127,1.822-0.629,2.952c-0.502,1.132-1.12,1.89-1.854,2.275 c-0.732,0.386-1.145,0.786-1.237,1.203c-0.092,0.419,0.087,0.755,0.535,1.013s0.927,0.282,1.436,0.074 c0.577-0.238,0.921-0.741,1.031-1.508c0.108-0.751,0.423-1.421,0.945-2.009c0.393-0.438,0.943-0.873,1.654-1.3 c0.24-0.143,0.532-0.285,0.879-0.43c0.192-0.078,0.47-0.191,0.835-0.338c0.622-0.276,1.075-0.65,1.358-1.123 c0.298-0.491,0.465-1.19,0.505-2.096c0.011-0.284,0.009-0.571-0.004-0.862c0.446,0.265,0.796,0.788,1.048,1.568 c0.251,0.782,0.32,1.457,0.206,2.025c-0.113,0.568-0.318,1.059-0.611,1.472c-0.295,0.412-0.695,0.901-1.201,1.469 c-0.519,0.578-0.864,0.985-1.04,1.222c-0.318,0.425-0.503,0.795-0.557,1.109c-0.044,0.269-0.05,0.763-0.016,1.481 c0.05,1.016,0.075,1.695,0.075,2.037c0,1.836-0.334,3.184-1.004,4.045c-0.874,1.123-1.731,1.902-2.568,2.336 c-0.955,0.49-2.228,0.736-3.813,0.736c-1.717,0-3.154-0.246-4.313-0.736c-1.237-0.525-2.083-1.303-2.541-2.336 c-0.394-0.885-0.668-1.938-0.827-3.158c-0.05-0.385-0.083-0.76-0.103-1.127c-0.49-0.092-0.916,0.209-1.278,0.904 c-0.36,0.693-0.522,1.348-0.484,1.957c0.039,0.611,0.246,1.471,0.625,2.578c0.131,0.449,0.185,0.801,0.161,1.051 c-0.031,0.311-0.184,0.521-0.456,0.631c-0.321,0.129-0.688,0.178-1.1,0.146c-0.463-0.037-0.902-0.174-1.319-0.41 c-1.062-0.604-1.706-1.781-1.937-3.531c-0.229-1.75-0.301-3.033-0.214-3.85c0.086-0.814,0.342-1.613,0.77-2.398 c0.428-0.783,0.832-1.344,1.213-1.681c0.382-0.338,0.893-0.712,1.532-1.122c0.64-0.408,1.108-0.745,1.405-1.008 c0.438-0.383,0.715-0.807,0.83-1.271C8.824,9.292,8.52,7.952,7.613,6.456C7.33,5.988,7.005,5.532,6.637,5.087 c0.837,0.111,1.791,0.49,2.865,1.138C10.576,6.872,11.223,7.737,11.443,8.821z"/></svg>]]},
}
local function proximity_warning()
	local NAME = "Grenade proximity warning"

	local FOOT            = 16          
	local RANGE           = 60 * FOOT
	local DANGER_RANGE    = 30 * FOOT
	local MAX_WARNINGS    = 4
	local OPACITY         = 0.9
	local DANGER_OPACITY  = 0.8         
	local RADIUS          = 30          
	local RADIUS_GROWTH   = 1.5         
	local PATH_TOLERANCE  = 20          
	local RESIMULATE_GAP  = 0.1         
	local TRACK_MEMORY    = 3           
	local DAMAGE_INTERVAL = 0.05        

	local HE_DAMAGE, HE_RADIUS, HE_MIN_RADIUS = effects.HE_DAMAGE, effects.HE_RADIUS, effects.HE_MIN_RADIUS
	local blast_damage = effects.blast_damage

	local EF_NODRAW   = 32              
	local PROJECTILES = {"CBaseCSGrenadeProjectile", "CMolotovProjectile"}
	local ALPHA       = floor(255 * OPACITY)

	 
	local function grenade_kind(entindex, radius)
		local model = model_name(entity_get_prop(entindex, "m_nModelIndex") or 0)
		if model:find("frag", 1, true) then return "he" end
		if model:find("flash", 1, true) then return "flash" end
		 
		if radius > 0 and radius <= HE_MIN_RADIUS then return "flash" end
		return "he"
	end

	 
	 
	local function is_threat(kind, thrower, player)
		if kind == "flash" then return true end
		return damage_scale(kind == "he" and "he" or "fire", thrower, player) > 0
	end

	local function distance_to_path(path, x, y, z)
		local nearest = huge
		for i = 1, #path, 3 do
			local dx, dy, dz = path[i] - x, path[i + 1] - y, path[i + 2] - z
			nearest = min(nearest, dx * dx + dy * dy + dz * dz)
		end
		return sqrt(nearest)
	end

	local tracked = {}    

	local function reset()
		tracked = {}
	end

	local smothered = effects.smothered

	local function add_projectiles(warnings, player)
		local now, dt = globals_realtime(), globals_tickinterval()
		 
		 
		 
		local game_now = globals.curtime()
		local game_rate = globals.frametime() / max(globals.absoluteframetime(), 1e-6)
		local half_latency = (client.latency() or 0) / 2 * game_rate
		 
		local lerp = max(cvar_float("cl_interp", 0.015625),
			cvar_float("cl_interp_ratio", 2) / max(cvar_float("cl_updaterate", 64), 1))
		local seen = {}

		for _, class in ipairs(PROJECTILES) do
			local molotov = class == "CMolotovProjectile"

			for _, entindex in ipairs(entity_get_all(class)) do
				local x, y, z = entity_get_prop(entindex, "m_vecOrigin")
				local exploded = band(entity_get_prop(entindex, "m_fEffects") or 0, EF_NODRAW) ~= 0
				local thrower = player_from_handle(entity_get_prop(entindex, "m_hThrower"))
				local radius = entity_get_prop(entindex, "m_DmgRadius") or 0
				local kind = molotov and "molotov" or grenade_kind(entindex, radius)

				 
				if exploded then tracked[entindex] = nil end

				if x and not exploded and is_threat(kind, thrower, player) then
					seen[entindex] = true

					 
					 
					 
					local ivx, ivy, ivz = entity_get_prop(entindex, "m_vInitialVelocity")
					local identity = string.format("%.1f %.1f %.1f", ivx or 0, ivy or 0, ivz or 0)
					local grenade = tracked[entindex]
					if not grenade or grenade.identity ~= identity then
						 
						grenade = {first_seen = game_now, initial_age = half_latency + dt, simulated = -1, identity = identity,
							class = class}
						tracked[entindex] = grenade
					end
					grenade.last_seen = game_now
					local age = grenade.initial_age + (game_now - grenade.first_seen)

					 
					local outdated = grenade.simulated < 0
					if not outdated and now - grenade.simulated >= RESIMULATE_GAP then
						outdated = not grenade.path or distance_to_path(grenade.path, x, y, z) > PATH_TOLERANCE
					end
					if outdated then
						local vx, vy, vz = entity_get_prop(entindex, "m_vecVelocity")
						local age_ticks = max(0, floor((age - lerp) / dt + 0.5))
						local path = {}
						local px, py, pz, time_left = simulate(x, y, z, vx or 0, vy or 0, vz or 0, kind, age_ticks, thrower, path)

						grenade.simulated, grenade.path = now, path
						grenade.x, grenade.y, grenade.z = px, py, pz
						grenade.fuse = px and age_ticks * dt + time_left    
						grenade.damage, grenade.damage_time = nil, nil
					end

					 
					if grenade.x and kind == "he" and now - (grenade.damage_time or -1) >= DAMAGE_INTERVAL then
						local damage = entity_get_prop(entindex, "m_flDamage") or 0
						grenade.damage_time = now
						grenade.damage, grenade.max_damage = blast_damage(player, grenade.x, grenade.y, grenade.z,
							damage >= 1 and damage or HE_DAMAGE,
							radius >= HE_MIN_RADIUS and radius or HE_RADIUS,
							damage_scale("he", thrower, player))
					end

					local put_out = kind == "molotov" and grenade.x
						and smothered(grenade.x, grenade.y, grenade.z, grenade.fuse - age)
					grenade.warning = nil
					if grenade.x and age <= grenade.fuse + 0.1 and not put_out then
						grenade.warning = {
							x = grenade.x, y = grenade.y, z = grenade.z,
							progress = min(1, age / max(grenade.fuse, 1e-3)), time_left = max(0, grenade.fuse - age),
							kind = kind, damage = grenade.damage, max_damage = grenade.max_damage, key = entindex,
							icon = molotov and entity_get_prop(entindex, "m_bIsIncGrenade") == 1 and "incgrenade" or nil,
						}
						warnings[#warnings + 1] = grenade.warning
					end
				end
			end
		end

		for entindex, grenade in pairs(tracked) do
			if not seen[entindex] then
				 
				local age = grenade.initial_age + (game_now - grenade.first_seen)
				local warning = grenade.warning
				 
				 
				if game_now - grenade.last_seen > TRACK_MEMORY or entity.get_classname(entindex) ~= grenade.class then
					tracked[entindex] = nil
				elseif warning and age <= grenade.fuse + 0.1 then
					warning.progress = min(1, age / max(grenade.fuse, 1e-3))
					warning.time_left = max(0, grenade.fuse - age)
					warnings[#warnings + 1] = warning
				end
			end
		end
	end

	 
	local function add_fires(warnings, player)
		local dt = globals_tickinterval()
		local lifetime = cvar_float("inferno_flame_lifetime", 7)

		for _, entindex in ipairs(entity_get_all("CInferno")) do
			local x, y, z = entity_get_prop(entindex, "m_vecOrigin")
			local ignited = entity_get_prop(entindex, "m_nFireEffectTickBegin")
			if x and ignited and ignited > 0 then
				local owner = player_from_handle(entity_get_prop(entindex, "m_hOwnerEntity"))
				local burning = max(0, (globals.tickcount() - ignited) * dt)
				if damage_scale("fire", owner, player) > 0 and burning < lifetime then
					warnings[#warnings + 1] = {x = x, y = y, z = z, progress = 1 - burning / lifetime, time_left = lifetime - burning,
						kind = "fire", key = -entindex}
				end
			end
		end
	end

	local function danger_of(warning, fire_reach)
		if warning.kind == "he" then
			return warning.damage and min(1, warning.damage / max(warning.max_damage or HE_DAMAGE, 1)) or 0
		elseif warning.kind == "fire" or warning.kind == "molotov" then
			return max(0, min(1, (DANGER_RANGE - warning.distance) / max(DANGER_RANGE - fire_reach, 1)))
		end
		return 0
	end

	 
	 
	local function screen_position(x, y, z, width, height, margin)
		local half_w, half_h = width / 2 - margin, height / 2 - margin

		local screen_x, screen_y = renderer.world_to_screen(x, y, z)
		if screen_x then
			local dx, dy = screen_x - width / 2, screen_y - height / 2
			local reach = sqrt((dx / half_w) ^ 2 + (dy / half_h) ^ 2)
			if reach > 1 then dx, dy = dx / reach, dy / reach end
			return width / 2 + dx, height / 2 + dy
		end

		local ex, ey, ez = client_eye_position()
		local pitch, yaw = client_camera_angles()
		if not ex or not pitch then return width / 2, height - margin end

		 
		local cp, sp, cy, sy = cos(rad(pitch)), sin(rad(pitch)), cos(rad(yaw)), sin(rad(yaw))
		local dx, dy, dz = x - ex, y - ey, z - ez
		local right = dx * sy - dy * cy
		local down = -(dx * (sp * cy) + dy * (sp * sy) + dz * cp)
		local length = sqrt(right * right + down * down)
		if length < 1e-4 then right, down, length = 0, 1, 1 end
		right, down = right / length, down / length

		local scale = 1 / sqrt((right / half_w) ^ 2 + (down / half_h) ^ 2)
		return width / 2 + right * scale, height / 2 + down * scale
	end

	 
	 
	local function time_left(warning)
		return max(0, min(1, warning.kind == "fire" and warning.progress or 1 - warning.progress))
	end

	local function in_range(warnings, ex, ey, ez)
		local nearby = {}
		for _, warning in ipairs(warnings) do
			local dx, dy, dz = warning.x - ex, warning.y - ey, warning.z - ez
			warning.distance = sqrt(dx * dx + dy * dy + dz * dz)
			if warning.distance <= RANGE then nearby[#nearby + 1] = warning end
		end
		table.sort(nearby, function(a, b) return a.distance < b.distance end)
		return nearby
	end

	local pin_states = {}    

	 
	local function shrink_of(state)
		local warning, label = state.warning, nil
		if warning.kind == "he" then
			if warning.damage and warning.damage > 0 then label = tostring(warning.damage) end
		elseif warning.kind ~= "fire" and warning.time_left ~= nil then
			label = string.format("%.1f", max(0, warning.time_left))
		elseif warning.kind == "fire" and warning.player_distance
			and warning.player_distance <= 6 * 39.3701 then
			label = string.format("%.1fm", warning.player_distance / 39.3701)
		end
		if label then state.label = label end
		local step = globals.frametime() / PIN.SHRINK_TIME
		state.shrink = label and min(1, state.shrink + step) or max(0, state.shrink - step)
		return state.shrink * state.shrink * (3 - 2 * state.shrink)
	end

	 
	 
	local glows = {}
	local function glow_texture(face, level)
		local key = face .. "x" .. level
		if glows[key] ~= nil then return glows[key] or nil end
		local strength = 0.06 + 0.30 * level / PIN.GLOW_LEVELS
		local size = 2 * ceil(face * 1.08) + 2
		local half, pixels = size / 2, {}
		for py = 0, size - 1 do
			for px = 0, size - 1 do
				local d = sqrt((px + 0.5 - half) ^ 2 + (py + 0.5 - half) ^ 2)
				local clear = 1
				for step = 1, PIN.GLOW_STEPS do
					local t = step / PIN.GLOW_STEPS
					clear = clear * (1 - strength * t * max(0, min(1, face * (1.08 - t) - d + 0.5)))
				end
				pixels[#pixels + 1] = string.char(255, 255, 255, floor(255 * (1 - clear) + 0.5))
			end
		end
		local ok, texture = pcall(renderer.load_rgba, table.concat(pixels), size, size)
		glows[key] = ok and texture and {texture, size} or false
		return glows[key] or nil
	end

	local function draw_pin(x, y, scale, state, anchored, rotation)
		local warning, danger, fade = state.warning, state.danger, state.fade
		local radius = floor(PIN.RADIUS * scale + 0.5)
		local border = max(2, floor(PIN.BORDER * scale + 0.5))
		local stalk = floor(PIN.STALK * scale + 0.5)
		local face = radius - border
		local bc, fc = PIN.BORDER_COLOR, PIN.FACE_COLOR

		 
		 
		local cx, cy = x, y
		if anchored then cy = y - stalk - radius end
		local body = pin_body(radius, stalk, anchored and 0 or rotation)
		if body then
			local half = radius + stalk
			renderer.texture(body, floor(cx - half + 0.5), floor(cy - half + 0.5), 2 * half, 2 * half,
				bc[1], bc[2], bc[3], floor(bc[4] * fade), "f")
		else
			renderer_circle(cx, cy, bc[1], bc[2], bc[3], floor(bc[4] * fade), radius, 0, 1)
		end
		renderer_circle(cx, cy, fc[1], fc[2], fc[3], floor(fc[4] * fade), face, 0, 1)

		 
		 
		local calm, hot = PIN.CALM_COLOR, PIN.DANGER_COLOR
		local level = floor(min(1, danger * 2.5) * PIN.GLOW_LEVELS + 0.5)
		local mix = level / PIN.GLOW_LEVELS
		local glow = glow_texture(face, level)
		if glow then
			renderer.texture(glow[1], floor(cx - glow[2] / 2 + 0.5), floor(cy - glow[2] / 2 + 0.5), glow[2], glow[2],
				calm[1] + (hot[1] - calm[1]) * mix, calm[2] + (hot[2] - calm[2]) * mix, calm[3] + (hot[3] - calm[3]) * mix,
				floor(255 * fade), "f")
		end

		 
		 
		local left = time_left(warning)
		if left > 0 then
			local r, g, b, a = timer_r, timer_g, timer_b, timer_a
			a = floor(a * fade)
			local width = max(2, floor(PIN.TIMER_WIDTH * scale + 0.5))
			local span = floor(PIN.TIMER_SPAN * left + 0.5)
			local shape = span >= 1 and timer_shape(face, width, PIN.TIMER_START, span)
			if shape then
				renderer.texture(shape, floor(cx - face + 0.5), floor(cy - face + 0.5), 2 * face, 2 * face, r, g, b, a, "f")
			elseif span >= 1 then
				local arc = face - width / 2    
				renderer_circle_outline(cx, cy, r, g, b, a, arc, PIN.TIMER_START, span / 360, width)
			end
		end

		 
		local t = shrink_of(state)
		local height = max(1, floor((PIN.ICON + (PIN.ICON_SMALL - PIN.ICON) * t) * scale + 0.5))
		local icon_y = cy - height / 2 + face * 0.28 * t
		if t > 0 and state.label then
			renderer_text(cx, cy - face * 0.38, 255, 255, 255, floor(255 * t * fade), "cb", 0, state.label)
		end
		local texture, width = icon(warning.icon or warning.kind, height)
		if texture then
			renderer.texture(texture, floor(cx - width / 2), floor(icon_y), width, height, 255, 255, 255, floor(255 * fade), "f")
		end
	end

	 
	 
	local function draw_pins(warnings, ex, ey, ez, marker, marker_margin)
		local nearby = in_range(warnings, ex, ey, ez)
		local width, height = client.screen_size()
		local scale = height / 1080
		local fire_reach = cvar_float("inferno_max_range", 150)
		local margin = marker_margin or (PIN.RADIUS + PIN.STALK) * scale + 6

		for _, state in pairs(pin_states) do state.seen = false end
		for i = 1, min(#nearby, MAX_WARNINGS) do
			local warning = nearby[i]
			local key = warning.key or 0
			local state = pin_states[key]
			if not state then
				state = {shrink = 0, fade = 0}
				pin_states[key] = state
			end
			state.seen, state.warning, state.danger = true, warning, danger_of(warning, fire_reach)
		end

		local step = globals.frametime() / PIN.FADE_TIME
		local order = {}
		for key, state in pairs(pin_states) do
			state.fade = state.seen and min(1, state.fade + step) or state.fade - step
			if state.fade <= 0 then
				pin_states[key] = nil
			else
				order[#order + 1] = state
			end
		end
		 
		table.sort(order, function(a, b) return a.warning.distance > b.warning.distance end)

		for _, state in ipairs(order) do
			local warning = state.warning
			local sx, sy = renderer.world_to_screen(warning.x, warning.y, warning.z)
			if marker then
				if not (sx and sx > margin and sx < width - margin and sy > margin and sy < height - margin) then
					sx, sy = screen_position(warning.x, warning.y, warning.z, width, height, margin)
				end
				marker(sx, sy, state)
			else
				local anchored = sx and sx > margin and sx < width - margin and sy > margin * 2 and sy < height - 6
				local rotation = 0
				if not anchored then
					sx, sy = screen_position(warning.x, warning.y, warning.z, width, height, margin)
					 
					local angle = math.deg(math.atan2(sy - height / 2, sx - width / 2)) - 90
					rotation = (floor(angle / PIN.TURN_STEP + 0.5) * PIN.TURN_STEP) % 360
				end
				draw_pin(sx, sy, scale, state, anchored, rotation)
			end
		end
	end


 local function paint(r, g, b, a)
  timer_r, timer_g, timer_b, timer_a = r, g, b, a
  local player = entity.get_local_player()
  local ex, ey, ez = client_eye_position()
  if not player or not entity.is_alive(player) or not ex then return end
  check_trace(player)
  trace_ignore = player
  local warnings = {}
  add_projectiles(warnings, player)
  add_fires(warnings, player)
   
  local px, py, pz = entity_get_prop(player, "m_vecOrigin")
  if px and py and pz then
   for _, warning in ipairs(warnings) do
    if warning.kind == "molotov" or warning.kind == "fire" then
     local dx, dy, dz = warning.x - px, warning.y - py, warning.z - pz
     warning.player_distance = sqrt(dx * dx + dy * dy + dz * dz)
    end
   end
  end
  draw_pins(warnings, ex, ey, ez)
 end
 local function clear()
  reset()
  for k in pairs(pin_states) do pin_states[k] = nil end
  forget_map()
 end
 return paint, clear
end

return proximity_warning()
end
 
function M:find_builtin()
 if self.builtin_searched then return self.builtin end
 self.builtin_searched = true
 for _, path in ipairs({
  {'VISUALS', 'Other ESP'}, {'VISUALS', 'Player ESP'}, {'VISUALS', 'Effects'},
  {'VISUALS', 'Colored models'}, {'MISC', 'Miscellaneous'}, {'MISC', 'Settings'},
 }) do
  local ok, ref = pcall(ui.reference, path[1], path[2], 'Grenade proximity warning')
  if ok and ref then self.builtin = ref; return ref end
 end
end
function M:restore_builtin()
 if not self.native_held then return end
 local ok, result = pcall(ui.set, self.builtin, self.native_saved)
 if not ok or result == false then error('Grenade proximity warning restore: ' .. tostring(result), 0) end
 self.native_held, self.native_saved = false, nil
end
function M:sync(enabled)
 if enabled and not self.native_held then
  local ref = assert(self:find_builtin(), 'Grenade proximity warning reference unavailable')
  local previous = ui.get(ref)
  assert(type(previous) == 'boolean', 'Cannot read Grenade proximity warning')
  self.native_saved, self.native_held = previous, true
  ui.set(ref, false)
 elseif not enabled then
  self:deactivate()
 end
end
function M:deactivate()
 self:restore_builtin()
 if self.active and self.clear then self.clear() end
 self.active = false
end
function M:paint(enabled, r, g, b, a)
 if not enabled then self:deactivate(); return end
 self:sync(true)
 if not self.paint_impl then
  assert(require('ffi').abi('32bit'), 'Grenade warning requires 32-bit CS:GO Legacy')
  self.paint_impl, self.clear = create_warning()
 end
 self.active = true
 self.paint_impl(r or 207, g or 182, b or 128, a or 230)
end
function M:reset() if self.clear then self.clear() end end
function M:shutdown() self:deactivate() end
return M


end,

 
['visuals_hitmarker'] = function(...)
 
local hitmarker = {expires = 0, points = {}, shots = {}, screen_duration = 0.5}
local function selected(ref, wanted)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == wanted then return true end end
    return false
end
local function duration(ref, fallback)
    local value = tonumber(ui.get(ref))
    if not value then return fallback end
    return math.max(0.1, math.min(5, value * 0.1))
end
function hitmarker:init(menu) self.menu = menu end
function hitmarker:enabled(name)
    local refs = self.menu.visuals.refs
    return selected(self.menu.refs.world_select, 'Hitmarkers')
        and ui.get(refs.hitmarkers_enabled) == true
        and selected(refs.hitmarker_types, name)
end
function hitmarker:reset() self.expires, self.points, self.shots = 0, {}, {} end
function hitmarker:player_hurt(event)
    if not self:enabled('2D') or not event or not event.userid or not event.attacker then return end
    local me = entity.get_local_player()
    if not me then return end
    local victim, attacker = client.userid_to_entindex(event.userid), client.userid_to_entindex(event.attacker)
    if victim and victim ~= me and attacker == me then
        self.screen_duration = duration(self.menu.visuals.refs.hitmarker_2d_duration, 0.5)
        self.expires = globals.realtime() + self.screen_duration
    end
end
function hitmarker:aim_fire(event)
    if not self:enabled('3D') or not event then return end
    local id = tonumber(event.id)
    local x, y, z = tonumber(event.x), tonumber(event.y), tonumber(event.z)
    if not id or not x or not y or not z then return end
    self.shots[id] = {x=x, y=y, z=z, created=globals.realtime()}
    local count, oldest_id, oldest_time = 0, nil, nil
    for shot_id, shot in pairs(self.shots) do
        count = count + 1
        if not oldest_time or shot.created < oldest_time then
            oldest_id, oldest_time = shot_id, shot.created
        end
    end
    if count > 64 then self.shots[oldest_id] = nil end
end
function hitmarker:aim_hit(event)
    if not self:enabled('3D') then return end
    local pos = nil
    if event then
        local id = tonumber(event.id)
        if id and self.shots[id] then
            pos = self.shots[id]
            self.shots[id] = nil
        end
    end
    if event and event.x ~= nil and event.y ~= nil and event.z ~= nil then
        local x, y, z = tonumber(event.x), tonumber(event.y), tonumber(event.z)
        if x and y and z then pos = {x=x, y=y, z=z} end
    end
    if not pos then return end
    local refs = self.menu.visuals.refs
    local life = duration(refs.hitmarker_3d_duration, 1)
    local fade_time = math.min(0.25, life)
    self.points[#self.points+1] = {x=pos.x, y=pos.y, z=pos.z, remaining=life, fade_time=fade_time}
end
function hitmarker:paint()
    local refs = self.menu.visuals.refs
    if self:enabled('2D') then
        local left = self.expires - globals.realtime()
        if left > 0 then
            local r, g, b, a = ui.get(refs.hitmarker_2d_color)
            local fade_time = math.min(0.25, self.screen_duration or 0.5)
            local alpha = math.floor((a or 255) * math.min(1, left / fade_time) + 0.5)
            if alpha > 0 then
                local sw, sh = client.screen_size()
                local x, y = sw * 0.5, sh * 0.5
                renderer.line(x - 10, y - 10, x - 5, y - 5, r, g, b, alpha)
                renderer.line(x + 10, y - 10, x + 5, y - 5, r, g, b, alpha)
                renderer.line(x + 10, y + 10, x + 5, y + 5, r, g, b, alpha)
                renderer.line(x - 10, y + 10, x - 5, y + 5, r, g, b, alpha)
            end
        end
    else
        self.expires = 0
    end

    if not self:enabled('3D') then
        self.points, self.shots = {}, {}
        return
    end
    local r, g, b, a = ui.get(refs.hitmarker_3d_color)
    local dt = math.max(0, globals.frametime())
    local index = 1
    while index <= #self.points do
        local point = self.points[index]
        point.remaining = point.remaining - dt
        if point.remaining <= 0 then
            table.remove(self.points, index)
        else
            local fade = point.remaining >= point.fade_time and 1 or point.remaining / point.fade_time
            local x, y = renderer.world_to_screen(point.x, point.y, point.z)
            if x and y then
                local alpha = math.floor((a or 255) * math.max(0, math.min(1, fade)))
                renderer.rectangle(x - 1, y - 5, 2, 10, r, g, b, alpha)
                renderer.rectangle(x - 5, y - 1, 10, 2, r, g, b, alpha)
            end
            index = index + 1
        end
    end
end
return hitmarker


end,

 
['visuals_output'] = function(...)
 
local output = {logs = {}, pending = nil, registered = false, preview_state = {}}
local MAX_LOGS, MAX_PARTS, MAX_TEXT, LIFETIME = 6, 64, 2048, 8
local surface_ok, surface = pcall(require, 'gamesense/surface')
if not surface_ok then surface = nil end
local icons_ok, icons_lib = pcall(require, 'gamesense/icons')
if not icons_ok then icons_lib = nil end
local console_font, new_font
local function now() return globals.realtime() or 0 end
local function clamp(v, a, b) return math.max(a, math.min(b, v)) end
local function ease(v) v = clamp(v,0,1); return v*v*(3-2*v) end
function output:init(menu)
    self.menu = menu
    local ok, ref = pcall(ui.reference, 'MISC', 'Miscellaneous', 'Draw console output')
    if ok then self.native_output = ref end
    self.callback = function(event)
        local ok, err = pcall(self.on_output, self, event)
        if not ok then self.callback_error = tostring(err) end
    end
end
  local HERO_ICONS = {
    hit = { name = "check", style = "solid", size = 13 },
    killed = { name = "check", style = "solid", size = 13 },
    miss = { name = "x-mark", style = "solid", size = 13 },
    purchase = { name = "shopping-cart", style = "outline", size = 13 },
    connection = { name = "x-mark", style = "solid", size = 13 },
    antibrute_reset = { name = "x-mark", style = "solid", size = 13 },
    antibrute_hit = { name = "check", style = "solid", size = 13 },
    antibrute = { name = "check", style = "solid", size = 13 },
    damage = { name = "check", style = "solid", size = 13 },
    config_success = { name = "check", style = "solid", size = 13 },
    config_error = { name = "x-mark", style = "solid", size = 13 },
    info = { name = "check", style = "solid", size = 13 },
  }

  local icon_textures = {}
  local icon_requested = {}
  local ICON_SIZE = 13

  local function hero_spec(category)
    local spec = HERO_ICONS[category]
    if not spec then return nil, "solid", ICON_SIZE end
    return spec.name, spec.style, spec.size or ICON_SIZE
  end

  local function request_hero_icon(category, r, g, b)
    local name, style, size = hero_spec(category)
    if not name then return nil, size, nil end
    local key = string.format("%s_%s_%d_%d_%d_%d", name, style, r or 240, g or 240, b or 240, size)
    if icon_textures[key] or icon_requested[key] then return key, size end
    icon_requested[key] = true
    if not icons_lib or not icons_lib.hero or type(icons_lib.hero.get_texture) ~= 'function' then return nil, size end
    pcall(icons_lib.hero.get_texture, name, style, {r or 240, g or 240, b or 240, 255}, size, function(tex)
      if tex then icon_textures[key] = tex end
    end)
    return key, size
  end

  local function get_hero_texture(category, r, g, b)
    local key, size = request_hero_icon(category, r, g, b)
    if not key then return nil, size or ICON_SIZE end
    return icon_textures[key], size or ICON_SIZE
  end

  local function get_console_font()
    if console_font then return console_font end
    console_font = surface.create_font("Lucida Console", 10, 400, {0x080})
    return console_font
  end

  local function get_new_font()
    if new_font then return new_font end
    new_font = surface.create_font("Segoe UI Semibold", 14, 600, {0x010, 0x080})
    return new_font
  end

  local function strip_output_text(text)
    text = tostring(text or "")
    text = text:gsub("%z", "")
    text = text:gsub("\n", "")
    return text
  end

  local function detect_category(text)
    local lower = strip_output_text(text):lower()

    if lower:find("anti%-bruteforce reset", 1)
      or lower:find("antibruteforce reset", 1, true) then
      return "antibrute_reset"
    end
    if lower:find("anti%-bruteforce updated", 1)
      or lower:find("antibruteforce updated", 1, true)
      or lower:find("anti%-bruteforce hit", 1)
      or lower:find("antibruteforce hit", 1, true) then
      return "antibrute_hit"
    end

    if lower:find("config ", 1, true) or lower:find("config:", 1, true) then
      if lower:find("write failed", 1, true)
        or lower:find("apply failed", 1, true)
        or lower:find("invalid data", 1, true)
        or lower:find("encode failed", 1, true)
        or lower:find("no data", 1, true)
        or lower:find("no preset", 1, true)
        or lower:find("empty name", 1, true)
        or lower:find("already exists", 1, true)
        or lower:find("read-only", 1, true)
        or lower:find("built-in", 1, true) then
        return "config_error"
      end
      return "config_success"
    end
    if lower:find("killed ", 1, true) then
      return "killed"
    end
    if lower:find("dormant hit ", 1, true) or lower:find("hit ", 1, true) then
      return "hit"
    end
    if lower:find("missed ", 1, true) then
      return "miss"
    end
    if lower:find(" bought ", 1, true) or lower:find("bought ", 1, true) then
      return "purchase"
    end
    if lower:find("packet loss", 1, true)
      or lower:find("ping spike", 1, true)
      or lower:find("high ping", 1, true)
      or lower:find("connection", 1, true) then
      return "connection"
    end
    if lower:find("burned ", 1, true)
      or lower:find("naded ", 1, true)
      or lower:find("knifed ", 1, true)
      or lower:find("got hurt ", 1, true) then
      return "damage"
    end
    return "info"
  end

  local function current_slot_position(log, now)
    local from = tonumber(log.slot_from) or tonumber(log.slot_to) or 0
    local to = tonumber(log.slot_to) or from
    local start_time = tonumber(log.slot_time) or now
    local duration = tonumber(log.slot_duration) or 0.34

    if duration <= 0 then
      return to
    end

    local progress = (now - start_time) / duration
    if progress <= 0 then
      return from
    end
    if progress >= 1 then
      return to
    end

    progress = progress * progress * progress * (progress * (progress * 6 - 15) + 10)
    return from + (to - from) * progress
  end

  local function begin_slot_tween(log, now, target_slot, duration)
    local current = current_slot_position(log, now)
    log.slot_from = current
    log.slot_to = target_slot
    log.slot_time = now
    log.slot_duration = duration or 0.34
  end

local function remove_prefix(parts, prefix)
    if type(prefix) ~= 'string' or prefix == '' then return parts end
    local all = {}
    for _, part in ipairs(parts) do all[#all + 1] = part.text end
    if table.concat(all):sub(1, #prefix) ~= prefix then return parts end
    local result, remaining = {}, #prefix
    for _, part in ipairs(parts) do
        local n = #part.text
        if remaining >= n then remaining = remaining - n
        else
            result[#result + 1] = {text=part.text:sub(remaining + 1), r=part.r,g=part.g,b=part.b,a=part.a}
            remaining = 0
        end
    end
    return result
end
function output:flush()
    local pending = self.pending
    self.pending = nil
    if not pending or pending.size == 0 then return end
    local events = self.menu.misc_events
    if events and type(events.output_prefix_text) == 'function' then
        local ok, prefix = pcall(events.output_prefix_text, events)
        if ok then pending.parts = remove_prefix(pending.parts, prefix) end
    end
    if #pending.parts == 0 then return end
    local t = now()
    pending.category = detect_category(pending.raw_text or '')
    pending.time, pending.first_log = t, #self.logs == 0
    for i, log in ipairs(self.logs) do
        begin_slot_tween(log, t, (tonumber(log.slot_to) or (i - 1)) + 1, 0.30)
    end
    pending.slot_from, pending.slot_to, pending.slot_time, pending.slot_duration = -0.85, 0, t, 0.34
    pending.entry_time, pending.animation = t, pending.first_log and 'first' or 'new'
    self.logs[#self.logs + 1] = pending
    while #self.logs > MAX_LOGS do table.remove(self.logs, 1) end
end
function output:on_output(event)
    if type(event) ~= 'table' then return end
    local text = tostring(event.text or '')
    local continued = text:sub(-1) == '\0'
    if continued then text = text:sub(1, -2) end
    if text:find('\n', 1, true) then continued = false end
    text = text:gsub('[\r\n%z]', '')
    local pending = self.pending or {parts = {}, size = 0, last = now(), raw_text = ''}
    self.pending = pending
    if text ~= '' and #pending.parts < MAX_PARTS and pending.size < MAX_TEXT then
        text = text:sub(1, MAX_TEXT - pending.size)
        pending.parts[#pending.parts + 1] = {text = text, r = tonumber(event.r) or 255,
            g = tonumber(event.g) or 255, b = tonumber(event.b) or 255, a = tonumber(event.a) or 255}
        pending.size = pending.size + #text
        pending.raw_text = pending.raw_text .. text
    end
    pending.last = now()
    if not continued or pending.size >= MAX_TEXT or #pending.parts >= MAX_PARTS then self:flush() end
end
function output:restore_native()
    if not self.native_held then return end
    local ok, result = pcall(ui.set, self.native_output, self.native_saved)
    if not ok or result == false then error('Draw console output restore: '..tostring(result), 0) end
    self.native_held, self.native_saved = false, nil
end
function output:sync()
    local enabled = ui.get(self.menu.visuals.refs.output) == true
    if enabled and not self.registered then
        assert(surface, 'gamesense/surface is required for Custom Output')
        assert(self.native_output, 'Draw console output reference unavailable')
        local previous = ui.get(self.native_output)
        assert(type(previous) == 'boolean', 'Cannot read Draw console output')
        client.set_event_callback('output', self.callback)
        self.registered = true
        self.native_saved, self.native_held = previous, true
        ui.set(self.native_output, false)
    elseif not enabled and (self.registered or self.native_held) then
        self:shutdown()
    end
    return enabled
end

  local function render_old(logs, origin_x, origin_y, preview_alpha)
    local font = get_console_font()
    if not font or #logs == 0 then return end
    local x, y = origin_x, origin_y
    local index = 1
    while index <= #logs do
      local log = logs[index]
      local age = globals.realtime() - log.time
      if age > 8 then
        table.remove(logs, index)
      else
        local life_left = 8 - age
        local fade = preview_alpha and log.preview_opacity or 1
        if life_left < 0.5 then
          fade = life_left / 0.5
          if fade < 0 then fade = 0 end
          if fade > 1 then fade = 1 end
          if index == 1 and fade < 0.2 then
            local _, text_height = surface.get_text_size(font, "A")
            y = y - (text_height or 12) * (1.0 - fade * 5)
          end
        end
        local draw_x = math.floor(x + (preview_alpha and log.preview_offset or 0) + 0.5)
        local _, preview_height = surface.get_text_size(font, "A")
        local preview_line_h = math.max(12, preview_height or 0)
        local line_y = preview_alpha and math.floor(origin_y + log.preview_slot * preview_line_h + 0.5) or y
        local line_h = 12
        local visible_parts = log.parts
        for p = 1, #visible_parts do
          local part = visible_parts[p]
          local part_text = part.text or ""
          local a = math.floor((part.a or 255) * fade)
          if a < 0 then a = 0 end
          if a > 255 then a = 255 end
          if part_text ~= "" then
            surface.draw_text(draw_x, line_y, part.r, part.g, part.b, a, font, part_text)
          end
          local text_width, text_height = surface.get_text_size(font, part_text)
          draw_x = draw_x + (text_width or 0)
          if text_height and text_height > line_h then line_h = text_height end
        end
        y = y + line_h
        index = index + 1
      end
    end
  end

  local function render_new(logs, origin_x, origin_y, preview_alpha)
    local font = get_new_font()
    if not font or #logs == 0 then return end

    local x, y = origin_x, origin_y
    local now = globals.realtime()
    local line_h = 22

    local function clamp01(value)
      if value < 0 then return 0 end
      if value > 1 then return 1 end
      return value
    end

    local function ease_smooth(value)
      value = clamp01(value)
      return value * value * value * (value * (value * 6 - 15) + 10)
    end

    for index = #logs, 1, -1 do
      if now - logs[index].time >= 8 then
        table.remove(logs, index)
      end
    end

    if #logs == 0 then return end

    local visible = {}
    for index = #logs, 1, -1 do
      visible[#visible + 1] = logs[index]
    end

    for index = 1, #visible do
      local log = visible[index]
      local desired_slot = index - 1
      local current_target = tonumber(log.slot_to)
      if preview_alpha then
         
      elseif current_target == nil then
        log.slot_from = desired_slot
        log.slot_to = desired_slot
        log.slot_time = now
        log.slot_duration = 0
      elseif math.abs(current_target - desired_slot) > 0.001 then
        begin_slot_tween(log, now, desired_slot, 0.30)
      end
    end

    for index = 1, #visible do
      local log = visible[index]
      local age = now - log.time
      local slot = current_slot_position(log, now)
      local visible_parts = log.parts
      local has_visible_text = type(visible_parts) == "table" and #visible_parts > 0

      local opacity = 1
      local entry_offset = 0

      local intro_duration = log.animation == "first" and 0.30 or 0.24
      local intro = preview_alpha and 1 or ease_smooth((now - (log.entry_time or log.time)) / intro_duration)
      opacity = preview_alpha and log.preview_opacity or intro
      entry_offset = -4 * (1 - intro)

      if age >= 7.45 then
        local fade = ease_smooth((age - 7.45) / 0.55)
        opacity = opacity * (1 - fade)
      end

      if opacity > 0.001 then
        local draw_y = math.floor(y + slot * line_h + entry_offset + 0.5)
        local draw_x = math.floor(x + (preview_alpha and log.preview_offset or 0) + 0.5)

         
        local icon_r, icon_g, icon_b = 240, 240, 240
         
        local hero_tex, hero_size = get_hero_texture(log.category, 255, 255, 255)
        hero_size = tonumber(hero_size) or ICON_SIZE
        local glyph_width, glyph_height = 0, 0
        if hero_tex ~= nil then
          glyph_width = hero_size
          glyph_height = hero_size
        end

        local text_height = 0
        local text_width = 0
        for part_index = 1, #visible_parts do
          local w, height = surface.get_text_size(font, visible_parts[part_index].text or "")
          if height and height > text_height then
            text_height = height
          end
          text_width = text_width + (tonumber(w) or 0)
        end
        if text_height <= 0 then text_height = 14 end

        local icon_gap = glyph_width > 0 and 6 or 0
        local content_w = glyph_width + icon_gap + text_width
        local row_h = math.max(text_height, glyph_height)
        if row_h <= 0 then row_h = 14 end

        local text_x = draw_x
        if glyph_width > 0 then
          text_x = draw_x + glyph_width + icon_gap
        end

         
        if content_w > 0 and opacity > 0.01 then
          local pad_y = 2
          local bg_h = row_h + pad_y * 2
          local bg_y = draw_y - pad_y
          if bg_y < 0 then
            bg_h = bg_h + bg_y
            bg_y = 0
          end
          local bg_x = math.max(0, math.floor(draw_x - 10))
          local solid_end = math.max(bg_x + 8, math.floor(text_x + text_width + 6))
          local fade_w = 30
          local bg_a = math.floor(30 * opacity + 0.5)
          if bg_a > 0 and bg_h > 0 then
            if solid_end > bg_x then
              renderer.rectangle(bg_x, bg_y, solid_end - bg_x, bg_h, 0, 0, 0, bg_a)
            end
            renderer.gradient(solid_end, bg_y, fade_w, bg_h, 0, 0, 0, bg_a, 0, 0, 0, 0, true)
          end
        end

        local icon_alpha = math.floor(255 * opacity + 0.5)
        if icon_alpha > 0 and glyph_width > 0 and hero_tex ~= nil then
          local icon_y = draw_y + math.floor((row_h - glyph_height) * 0.5 + 0.5)
          renderer.texture(hero_tex, draw_x, icon_y, hero_size, hero_size, icon_r, icon_g, icon_b, icon_alpha)
        end

        if has_visible_text then
          local text_draw_y = draw_y + math.floor((row_h - text_height) * 0.5 + 0.5)
          for part_index = 1, #visible_parts do
            local part = visible_parts[part_index]
            local part_text = part.text or ""
            local alpha = math.floor((part.a or 255) * opacity + 0.5)
            if alpha > 0 and part_text ~= "" then
              surface.draw_text(
                math.floor(text_x),
                text_draw_y,
                part.r or 245,
                part.g or 245,
                part.b or 245,
                alpha,
                font,
                part_text
              )
            end
            local width = select(1, surface.get_text_size(font, part_text)) or 0
            text_x = text_x + width
          end
        end
      end
    end
  end

local function preview_rows(t, menu)
    local refs = menu.misc_rage.refs
    if not ui.get(refs.event) then return {} end
    local triggers = ui.get(refs.event_triggers)
    if type(triggers) ~= 'table' then return {} end
    local selected = {}
    for _, name in ipairs(triggers) do selected[name] = true end
    local hr,hg,hb = ui.get(refs.event_hit_color)
    local mr,mg,mb = ui.get(refs.event_miss_color)
    local hit = {hr or 255,hg or 255,hb or 255}
    local miss = {mr or 225,mg or 80,mb or 80}
    local white = {240,240,240}
    local function part(text, c) return {text=text,r=c[1],g=c[2],b=c[3],a=255} end
    local function row(category, parts)
        return {time=t,entry_time=t,animation='first',category=category,parts=parts}
    end
    local result = {}
    if selected.Aimbot then
        result[#result+1] = row('hit',{part('Hit ',white),part('player',hit),part("'s ",white),part('head',hit),part(' for ',white),part('80',hit),part(' damage (',white),part('20',hit),part(' hp left) (bt: ',white),part('0t',hit),part(' · hc: ',white),part('75%',hit),part(') (delay=',white),part('0ms',hit),part(')',white)})
        result[#result+1] = row('miss',{part('Missed in ',white),part('player',miss),part("'s ",white),part('head',miss),part(' due to ',white),part('spread',miss),part(' (bt: ',white),part('0t',miss),part(' · hc: ',white),part('75%',miss),part(') (delay=',white),part('0ms',miss),part(')',white)})
    end
    if selected.Purchase then
        result[#result+1] = row('purchase',{part('player',hit),part(' Bought ',white),part('ak47',hit)})
    end
    if selected['Connection problems'] then
        result[#result+1] = row('connection',{part('High ping ',white),part('120 ms',miss)})
    end
    return result
end

 
 
local PREVIEW_ORDER = {'hit', 'miss', 'purchase', 'connection'}
local function update_preview(self, examples, show, t, dt)
    local selected, state = {}, self.preview_state
    if show then
        for _, row in ipairs(examples) do
            selected[row.category] = true
            local item = state[row.category]
            if not item then
                item = {progress = 0}
                state[row.category] = item
            end
            item.row = row  
        end
    end
    local rows, slot = {}, 0
    for _, category in ipairs(PREVIEW_ORDER) do
        local item = state[category]
        if item then
            local direction = selected[category] and 1 or -1
            item.progress = clamp(item.progress + direction * dt / 0.30, 0, 1)
            if item.progress <= 0 and not selected[category] then
                state[category] = nil
            elseif item.row then
                local row, opacity = item.row, ease(item.progress)
                row.time = t  
                row.preview_opacity = opacity
                row.preview_offset = -18 * (1 - opacity)
                row.preview_slot = slot
                row.slot_from, row.slot_to, row.slot_time, row.slot_duration = slot, slot, t, 0
                rows[#rows + 1] = row
                slot = slot + opacity
            end
        end
    end
    return rows
end

function output:paint_ui(host)
    if self.callback_error then
        local err = self.callback_error; self.callback_error = nil; self:shutdown(); error(err, 0)
    end
    if not self:sync() then return end
    local t = now()
    if self.pending and t - self.pending.last > 0.05 then self:flush() end
    for i = #self.logs, 1, -1 do if t - self.logs[i].time >= LIFETIME then table.remove(self.logs, i) end end
    local dt = clamp(tonumber(globals.frametime()) or 0, 0, 0.1)
    local examples = preview_rows(t, self.menu)
    local preview = update_preview(self, examples, ui.is_menu_open() and #self.logs == 0, t, dt)
    local preview_on = #self.logs == 0 and #preview > 0
    if #self.logs == 0 and not preview_on then return end
    local style = ui.get(self.menu.visuals.refs.output_style) or 'Old'
    local is_new = style == 'New'
    local font = is_new and get_new_font() or get_console_font()
    assert(font, 'Custom Output font unavailable')
    local rows = preview_on and preview or self.logs
     
     
    if preview_on and is_new then
        rows = {}
        for i = #preview, 1, -1 do rows[#rows + 1] = preview[i] end
    end
    local x, y = is_new and 10 or 8, is_new and 0 or 5
    if is_new then render_new(rows, x, y, preview_on) else render_old(rows, x, y, preview_on) end
end
function output:shutdown()
    local errors = {}
    if self.registered then
        local ok, err = pcall(client.unset_event_callback, 'output', self.callback)
        if ok then self.registered = false else errors[#errors+1] = tostring(err) end
    end
    local ok, err = pcall(self.restore_native, self)
    if not ok then errors[#errors+1] = tostring(err) end
    self.logs, self.pending, self.preview_state = {}, nil, {}
    if #errors > 0 then error(table.concat(errors, '; '), 0) end
end
return output


end,

 
['visuals_scope'] = function(...)
 
local scope = {alpha = 0, length = 0, gap = 0}
local function selected(ref, value)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, name in ipairs(values) do if name == value then return true end end
    return false
end
function scope:init(menu)
    self.menu = menu
    local ok, ref = pcall(ui.reference, 'VISUALS', 'Effects', 'Remove scope overlay')
    if ok then self.ref = ref end
end
function scope:restore()
    if self.previous ~= nil then
        ui.set(self.ref, self.previous)
        self.previous = nil
    end
    self.alpha = 0
    self.length, self.gap = 0, 0
end
function scope:report(err)
    if self.failed then return end
    self.failed = true
    local ok, restore_err = pcall(self.restore, self)
    local message = '[nyameeow.pink] Custom Scope: ' .. tostring(err)
    if not ok then message = message .. '; restore: ' .. tostring(restore_err) end
    if client.error_log then client.error_log(message) else client.log(message) end
end
function scope:run(fn)
    if self.failed then return end
    local ok, err = pcall(fn, self)
    if not ok then self:report(err) end
end
local function arm(cx, cy, x1, y1, x2, y2, r, g, b, alpha)
    local dx, dy = x2 - x1, y2 - y1
    if math.abs(dy) < 0.5 then
        local left = math.floor(cx + math.min(x1, x2) + 0.5)
        local right = math.floor(cx + math.max(x1, x2) + 0.5)
        if right <= left then return end
        local a1, a2 = x1 < x2 and 0 or alpha, x1 < x2 and alpha or 0
        renderer.gradient(left, math.floor(cy + y1 + 0.5), right - left, 1, r, g, b, a1, r, g, b, a2, true)
    elseif math.abs(dx) < 0.5 then
        local top = math.floor(cy + math.min(y1, y2) + 0.5)
        local bottom = math.floor(cy + math.max(y1, y2) + 0.5)
        if bottom <= top then return end
        local a1, a2 = y1 < y2 and 0 or alpha, y1 < y2 and alpha or 0
        renderer.gradient(math.floor(cx + x1 + 0.5), top, 1, bottom - top, r, g, b, a1, r, g, b, a2, false)
    else
        for index = 0, 7 do
            local t0, t1 = index / 8, (index + 1) / 8
            local xa, ya = cx + x1 + dx * t0, cy + y1 + dy * t0
            local xb, yb = cx + x1 + dx * t1, cy + y1 + dy * t1
            local a = math.floor(alpha * ((t0 + t1) * 0.5))
            renderer.line(xa, ya, xb, yb, r, g, b, a)
            renderer.line(xa + 0.5, ya, xb + 0.5, yb, r, g, b, a)
        end
    end
end
function scope:paint()
    self:run(function(self)
        local v = self.menu.visuals.refs
        if not ui.get(v.scope) then
            if self.previous ~= nil then self:restore() end
            return
        end
        assert(self.ref, 'Remove scope overlay reference unavailable')
        if self.previous == nil then
            self.previous = ui.get(self.ref)
            assert(self.previous ~= nil, 'Cannot read Remove scope overlay')
        end
         
        ui.set(self.ref, false)
        local player = entity.get_local_player()
        if not player then return end
        local sw, sh = client.screen_size()
        local t = math.min(1, globals.frametime() / 0.075)
        self.length = self.length + (ui.get(v.scope_length) - self.length) * t
        self.gap = self.gap + (ui.get(v.scope_gap) - self.gap) * t
        local scale = sh / 1080
        local gap = math.max(0, math.floor(self.gap * scale + 0.5))
        local length = math.max(gap + 4, math.floor(self.length * scale + 0.5))
        local weapon = entity.get_player_weapon(player)
        local level = weapon and entity.get_prop(weapon, 'm_zoomLevel')
        local active = entity.is_alive(player) and weapon and level and level > 0
            and entity.get_prop(player, 'm_bIsScoped') == 1 and entity.get_prop(player, 'm_bResumeZoom') ~= 1
        local frames = math.max(1, math.min(24, math.floor(ui.get(v.scope_speed))))
        self.alpha = math.max(0, math.min(1, self.alpha + (active and 1 / frames or -1 / frames)))
        if self.alpha < 0.01 then return end
        local r, g, b, a = ui.get(v.scope_color)
        local alpha = math.floor(self.alpha * a)
        local mode = ui.get(v.scope_mode)
        local options = mode == 'Rotated' and v.scope_options_rotated or v.scope_options_default
        local arms = {{0, -length, 0, -gap}, {0, length, 0, gap}, {-length, 0, -gap, 0}, {length, 0, gap, 0}}
        local reversed = selected(options, 'Reversed')
        local angle = 0
        if mode == 'Rotated' then
            angle = 45
            if selected(options, 'Animate') then
                local vx, vy = entity.get_prop(player, 'm_vecVelocity')
                if vx and vy and math.sqrt(vx * vx + vy * vy) >= 5 then angle = (globals.curtime() * 180) % 360 end
            end
        end
        local radians = math.rad(angle)
        local cs, sn = math.cos(radians), math.sin(radians)
        for _, p in ipairs(arms) do
            local x1, y1, x2, y2 = p[1], p[2], p[3], p[4]
            if reversed then x1, y1, x2, y2 = x2, y2, x1, y1 end
            arm(math.floor(sw * 0.5), math.floor(sh * 0.5), x1 * cs - y1 * sn, x1 * sn + y1 * cs,
                x2 * cs - y2 * sn, x2 * sn + y2 * cs, r, g, b, alpha)
        end
    end)
end
function scope:paint_ui()
    self:run(function(self)
        if self.previous == nil then return end
        if not ui.get(self.menu.visuals.refs.scope) then
            self:restore()
        else
            ui.set(self.ref, true)
        end
    end)
end
function scope:shutdown()
    local ok, err = pcall(self.restore, self)
    if not ok then
        local message = '[nyameeow.pink] Custom Scope shutdown: ' .. tostring(err)
        if client.error_log then client.error_log(message) else client.log(message) end
    end
end
return scope


end,

 
['visuals_watermark'] = function(...)
 
local render = {}
local function rgba_to_hex(r,g,b,a)
    local function channel(v) return math.max(0, math.min(255, math.floor((tonumber(v) or 255) + 0.5))) end
    return string.format('%02X%02X%02X%02X', channel(r), channel(g), channel(b), channel(a))
end
local function utf8_chars(str)
  local chars = {}
  local index = 1
  while index <= #str do
    local byte = str:byte(index)
    local char_len
    if byte < 128 then char_len = 1
    elseif byte < 224 then char_len = 2
    elseif byte < 240 then char_len = 3
    else char_len = 4 end
    table.insert(chars, str:sub(index, index + char_len - 1))
    index = index + char_len
  end
  return chars
end
render.gradient_text = function(str, speed, direction, r, g, b, a, r2, g2, b2, a2, progress_offset, total_length, time_value)
  speed = speed or 1
  direction = direction or "Right"
  r, g, b, a = r or 255, g or 255, b or 255, a or 255
  r2, g2, b2, a2 = r2 or 255, g2 or 255, b2 or 255, a2 or 255
  local r_add, g_add, b_add, a_add = r2 - r, g2 - g, b2 - b, a2 - a
  local chars = utf8_chars(str)
  local length = #chars
  local denominator = math.max((tonumber(total_length) or length) - 1, 1)
  local offset = tonumber(progress_offset) or 0
  local animation_time = tonumber(time_value) or globals.curtime()
  local t_out = {}
  for index = 1, length do
    local progress = (offset + index - 1) / denominator
    local iter = progress + animation_time * speed * (direction == "Right" and -1 or 1)
    local color_factor = math.abs(math.cos(iter))
    local cr = r + r_add * color_factor
    local cg = g + g_add * color_factor
    local cb = b + b_add * color_factor
    local ca = a + a_add * color_factor
    t_out[#t_out + 1] = "\a" .. rgba_to_hex(cr, cg, cb, ca)
    t_out[#t_out + 1] = chars[index]
  end
  return table.concat(t_out)
end
render.rainbow_text = function(text, speed, direction, a, saturation, progress_offset, total_length)
  if type(text) ~= "string" or text == "" then
    return ""
  end

  local chars = utf8_chars(text)
  local length = #chars
  local denominator = math.max((tonumber(total_length) or length) - 1, 1)
  local offset = tonumber(progress_offset) or 0
  local out = {}
  local sat = math.max(0, math.min(1, tonumber(saturation) or 1))
  local alpha = math.max(0, math.min(255, math.floor(tonumber(a) or 255)))
  local animation_speed = tonumber(speed) or 1
  local direction_sign = direction == "Left" and -1 or 1

  local time_phase = globals.realtime() * animation_speed * 0.22 * direction_sign

  for index = 1, length do
    local progress = (offset + index - 1) / denominator
    local hue = (progress + time_phase) % 1
    local h = hue * 6
    local c = sat
    local x = c * (1 - math.abs((h % 2) - 1))
    local m = 0.5 - c / 2
    local r, g, b

    if h < 1 then
      r, g, b = c, x, 0
    elseif h < 2 then
      r, g, b = x, c, 0
    elseif h < 3 then
      r, g, b = 0, c, x
    elseif h < 4 then
      r, g, b = 0, x, c
    elseif h < 5 then
      r, g, b = x, 0, c
    else
      r, g, b = c, 0, x
    end

    r = math.floor((r + m) * 255 + 0.5)
    g = math.floor((g + m) * 255 + 0.5)
    b = math.floor((b + m) * 255 + 0.5)

    out[#out + 1] = "\a" .. string.format("%02X%02X%02X%02X", r, g, b, alpha)
    out[#out + 1] = chars[index]
  end

  return table.concat(out)
end

