['visuals_world'] = function(...)
 
local world = {failed = {}, groups = {}, sleeves = {materials = {}, map = nil, retry = 0}}
local function selected(ref, name)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == name then return true end end
    return false
end
local function smooth(current, target, factor)
    return current + (target - current) * (1 - math.exp(-factor * globals.frametime() * 60))
end
function world:init(menu)
    self.menu = menu
    local ok, ref = pcall(ui.reference, 'MISC', 'Miscellaneous', 'Override zoom FOV')
    if ok then self.zoom_ref = ref end
end
function world:enabled(name, checkbox)
    return selected(self.menu.refs.world_select, name) and ui.get(checkbox)
end
function world:report(name, err)
    local message = '[nyameeow.pink] ' .. name .. ': ' .. tostring(err)
    if client.error_log then client.error_log(message) else client.log(message) end
end
function world:run(name, fn, restore)
    if self.failed[name] then return end
    local ok, err = pcall(fn, self)
    if not ok then
        if restore then
            local restored, restore_err = pcall(restore, self)
            if not restored then self:report(name .. ' restore', restore_err) end
        end
        self.failed[name] = true
        self:report(name, err)
    end
end
 
function world:restore_group(name)
    local group = self.groups[name]
    if not group then return end
    local errors = {}
    for _, item in ipairs(group) do
        if item.saved ~= nil then
            local ok, err = pcall(function() item.cvar[item.setter](item.cvar, item.saved) end)
            if ok then item.saved = nil else errors[#errors + 1] = tostring(err) end
        end
    end
    if #errors > 0 then error(table.concat(errors, '; ')) end
    self.groups[name] = nil
end
function world:cvar_group(name, descriptors)
    if self.groups[name] then return self.groups[name] end
    local group = {}
    for _, spec in ipairs(descriptors) do
        local cv = assert(cvar[spec[1]], 'Missing cvar: ' .. spec[1])
        local value = cv:get_float()
        assert(type(value) == 'number', 'Cannot read cvar: ' .. spec[1])
        group[#group + 1] = {cvar = cv, saved = value, value = value, setter = spec[2]}
    end
    self.groups[name] = group
    return group
end
local viewmodel_cvars = {
    {'viewmodel_offset_x', 'set_raw_float'}, {'viewmodel_offset_y', 'set_raw_float'},
    {'viewmodel_offset_z', 'set_raw_float'}, {'viewmodel_fov', 'set_raw_float'},
}
local bob_cvars = {
    {'cl_bob_lower_amt', 'set_float'}, {'cl_bobamt_lat', 'set_float'}, {'cl_bobamt_vert', 'set_float'},
}
function world:viewmodel()
    local v = self.menu.visuals.refs
    if not self:enabled('Viewmodel Changer', v.viewmodel) then return self:restore_group('viewmodel') end
    local group = self:cvar_group('viewmodel', viewmodel_cvars)
    local targets = {ui.get(v.viewmodel_x) / 10, ui.get(v.viewmodel_y) / 10,
        ui.get(v.viewmodel_z) / 10, ui.get(v.viewmodel_fov) / 10}
    for i, item in ipairs(group) do
        item.value = smooth(item.value, targets[i], 0.30)
        if item.last == nil or math.abs(item.value - item.last) > 0.001 then
            item.cvar:set_raw_float(item.value)
            item.last = item.value
        end
    end
end
function world:lock_bob()
    local v = self.menu.visuals.refs
    if not self:enabled('Viewmodel Changer', v.viewmodel) or not selected(v.viewmodel_features, 'Lock Bob') then
        return self:restore_group('bob')
    end
    local group = self:cvar_group('bob', bob_cvars)
    for _, item in ipairs(group) do item.cvar:set_float(0) end
end
function world:restore_knife()
    if self.knife_baseline ~= nil then
        cvar.cl_righthand:set_int(self.knife_baseline)
        self.knife_baseline = nil
    end
    self.was_knife = false
end
function world:knife_hand()
    local v = self.menu.visuals.refs
    if not self:enabled('Viewmodel Changer', v.viewmodel) or not selected(v.viewmodel_features, 'Opposite Knife Hand') then
        return self:restore_knife()
    end
    local player = entity.get_local_player()
    if not player or not entity.is_alive(player) then
        if self.was_knife then self:restore_knife() end
        return
    end
    local weapon = entity.get_player_weapon(player)
    local class = weapon and entity.get_classname(weapon) or ''
    local knife = type(class) == 'string' and (class == 'CKnife' or class:lower():find('knife', 1, true) ~= nil)
    local current = cvar.cl_righthand:get_int()
    assert(current == 0 or current == 1, 'Invalid cl_righthand value')
    if not knife then
        if self.was_knife and self.knife_baseline ~= nil then
            cvar.cl_righthand:set_int(self.knife_baseline)
            current = self.knife_baseline
        end
        self.knife_baseline, self.was_knife = current, false
        return
    end
    if self.knife_baseline == nil then self.knife_baseline = current end
    local target = self.knife_baseline == 1 and 0 or 1
    if current ~= target then cvar.cl_righthand:set_int(target) end
    self.was_knife = true
end
function world:restore_sleeves()
    local state, remaining = self.sleeves, {}
    for _, material in ipairs(state.materials) do
        local ok = pcall(function() material:set_material_var_flag(2, false) end)
        if not ok then remaining[#remaining + 1] = material end
    end
    state.materials, state.map, state.retry = remaining, nil, 0
    if #remaining > 0 then error('Could not restore ' .. #remaining .. ' sleeve materials') end
end
function world:remove_sleeves()
    local v = self.menu.visuals.refs
    local enabled = self:enabled('Viewmodel Changer', v.viewmodel) and selected(v.viewmodel_features, 'Remove Sleeves')
    local state = self.sleeves
    if not enabled then
        if state.map ~= nil or #state.materials > 0 then self:restore_sleeves() end
        return
    end
    local map = globals.mapname() or ''
    if state.map == map then return end
    if state.map ~= nil or #state.materials > 0 then self:restore_sleeves() end
    local now = globals.realtime()
    if now < state.retry then return end
    state.retry = now + 1
    local materials = materialsystem.find_materials('sleeve', true)
    if type(materials) ~= 'table' then return end
    for _, material in pairs(materials) do
        local ok, hidden = pcall(function() return material:get_material_var_flag(2) end)
        if ok and not hidden then
            local success = pcall(function() material:set_material_var_flag(2, true) end)
            if success then state.materials[#state.materials + 1] = material end
        end
    end
    state.map = map
end
function world:restore_second_zoom()
    if self.zoom_previous ~= nil then
        ui.set(self.zoom_ref, self.zoom_previous)
        self.zoom_previous = nil
    end
end
function world:second_zoom()
    local v = self.menu.visuals.refs
    local enabled = self:enabled('Force Second Zoom', v.second_scope)
    local player = entity.get_local_player()
    local weapon = player and entity.get_player_weapon(player)
    local active = enabled and player and entity.is_alive(player) and weapon and entity.get_prop(weapon, 'm_zoomLevel') == 2
    if not active then return self:restore_second_zoom() end
    assert(self.zoom_ref, 'Override zoom FOV reference unavailable')
    if self.zoom_previous == nil then self.zoom_previous = ui.get(self.zoom_ref) end
    assert(self.zoom_previous ~= nil, 'Cannot read Override zoom FOV')
    local animated = self:enabled('Zoom Animation', v.zoom)
    ui.set(self.zoom_ref, animated and 0 or ui.get(v.second_amount))
end
function world:override_view(event)
    if self.failed['Zoom Animation'] then return end
    self:run('Zoom Animation', function(self)
        local v = self.menu.visuals.refs
        if not self:enabled('Zoom Animation', v.zoom) or not event or type(event.fov) ~= 'number' then
            self.smooth_fov = nil
            return
        end
        local player = entity.get_local_player()
        local weapon = player and entity.get_player_weapon(player)
        local zoom = weapon and entity.get_prop(weapon, 'm_zoomLevel') or 0
        local target = event.fov
        if player and entity.is_alive(player) and zoom == 2 and self:enabled('Force Second Zoom', v.second_scope) then
            target = ui.get(v.second_amount)
        end
        self.smooth_fov = smooth(self.smooth_fov or event.fov, target, math.max(0.05, math.min(1, ui.get(v.zoom_speed) / 100)))
        event.fov = math.max(1, self.smooth_fov)
    end)
end
function world:paint()
    self:run('Viewmodel Changer', self.viewmodel, function(s) s:restore_group('viewmodel') end)
    self:run('Lock Bob', self.lock_bob, function(s) s:restore_group('bob') end)
    self:run('Opposite Knife Hand', self.knife_hand, self.restore_knife)
    self:run('Remove Sleeves', self.remove_sleeves, self.restore_sleeves)
    self:run('Force Second Zoom', self.second_zoom, self.restore_second_zoom)
end
function world:shutdown()
    local actions = {
        {'viewmodel', function() self:restore_group('viewmodel') end},
        {'bob', function() self:restore_group('bob') end},
        {'knife', function() self:restore_knife() end},
        {'sleeves', function() self:restore_sleeves() end},
        {'second zoom', function() self:restore_second_zoom() end},
    }
    for _, action in ipairs(actions) do
        local ok, err = pcall(action[2]); if not ok then self:report(action[1] .. ' shutdown', err) end
    end
    self.smooth_fov = nil
end
return world


end,

 
['visuals_runtime'] = function(...)
local modules = ...
local runtime = {
    positions = {},
    drag = nil,
    mouse_down = false,
    velocity = 1,
    aspect = nil,
    failed = {},
}
local DRAG_LIMIT_KEYS = {damage = true, ci_default = true, ci_japanese = true}

local function selected(ref, value)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, name in ipairs(values) do if name == value then return true end end
    return false
end

local function hotkey_active(host, name, ref)
    if not ref then return false end
    if host and host.menu and host.menu.binds then return host.menu.binds.read(name, ref) end
    return ui.get(ref) == true
end

local function clamp(value, low, high)
    return math.max(low, math.min(high, value))
end

local function smooth(current, target, rate)
    local factor = 1 - math.exp(-rate * globals.frametime() * 60)
    return current + (target - current) * factor
end

local POS_DB_KEY = 'afterglow.drag.positions.v1'

function runtime:load_positions()
    if not database or type(database.read) ~= 'function' then return end
    local ok, data = pcall(database.read, POS_DB_KEY)
    if not ok or type(data) ~= 'table' then return end
    for key, value in pairs(data) do
        if type(key) == 'string' and type(value) == 'table'
            and type(value.x) == 'number' and type(value.y) == 'number' then
            self.positions[key] = {x = value.x, y = value.y}
        end
    end
end

function runtime:save_positions()
    if not database or type(database.write) ~= 'function' then return end
    local out = {}
    for key, value in pairs(self.positions) do
        if type(key) == 'string' and type(value) == 'table'
            and type(value.x) == 'number' and type(value.y) == 'number' then
            out[key] = {x = value.x, y = value.y}
        end
    end
    pcall(database.write, POS_DB_KEY, out)
end

function runtime:reset_positions()
    self.positions = {}
    self.drag = nil
    self.drag_dirty = false
    if database and type(database.write) == 'function' then
        pcall(database.write, POS_DB_KEY, {})
    end
end

function runtime:init(menu, world, scope, watermark, crosshair)
    self.menu = menu
    self.world, self.scope, self.watermark, self.crosshair = world, scope, watermark, crosshair
    if world then world:init(menu) end
    if scope then scope:init(menu) end
    local damage_ok, damage_ref = pcall(ui.reference, 'RAGE', 'Aimbot', 'Minimum damage')
    if damage_ok then self.damage_ref = damage_ref end
    local override_ok, a, b, c = pcall(ui.reference, 'RAGE', 'Aimbot', 'Minimum damage override')
    if override_ok then self.override_enabled, self.override_hotkey, self.override_value = a, b, c end
    self:load_positions()
end

function runtime:report(feature, err)
    if self.failed[feature] then return end
    local message = '[nyameeow.pink] ' .. feature .. ': ' .. tostring(err)
    self.failed[feature] = message
    if client.error_log then client.error_log(message) else client.log(message) end
end

function runtime:run(feature, fn)
    if self.failed[feature] then return end
    local ok, err = pcall(fn, self)
    if not ok then
        if feature == 'Custom Output' and self.output then pcall(self.output.shutdown, self.output) end
        if feature == 'Grenade Warning' and self.grenade_warning then pcall(self.grenade_warning.shutdown, self.grenade_warning) end
        if feature == 'Aspect Ratio' and self.aspect ~= nil then
            local restored, restore_error = pcall(function() cvar.r_aspectratio:set_float(self.aspect.original) end)
            if restored then self.aspect = nil else self:report('Aspect Ratio restore', restore_error) end
        end
        self:report(feature, err)
    end
end

function runtime:position(key, default_x, default_y)
    local pos = self.positions[key]
    if type(pos) ~= 'table' or type(pos.x) ~= 'number' or type(pos.y) ~= 'number' then
        pos = {x = default_x, y = default_y}
        self.positions[key] = pos
    end
    return pos
end

local function mouse_over_menu(mx, my)
    if type(ui.menu_position) ~= 'function' or type(ui.menu_size) ~= 'function' then return false end
    local ok_pos, x, y = pcall(ui.menu_position)
    local ok_size, w, h = pcall(ui.menu_size)
    return ok_pos and ok_size and type(x) == 'number' and type(y) == 'number'
        and type(w) == 'number' and type(h) == 'number'
        and mx >= x and mx <= x + w and my >= y and my <= y + h
end
function runtime:drag_item(key, x, y, width, height, padding, anchor_x, anchor_y)
    local pos = self.positions[key]
    if not pos or not ui.is_menu_open() then return end
    local mx, my = ui.mouse_position()
    if type(mx) ~= 'number' or type(my) ~= 'number' then return end
    local down, right = client.key_state(0x01) == true, client.key_state(0x02) == true
    padding, anchor_x, anchor_y = padding or 0, anchor_x or 0, anchor_y or 0
    local inside = mx >= x - padding and mx <= x + width + padding
        and my >= y - padding and my <= y + height + padding
    local active = self.drag and self.drag.key == key
    local hover = inside and not mouse_over_menu(mx, my) and (not self.drag or active) and not self.drag_hovered
    if hover then self.drag_hovered = true end
    if down and not self.mouse_down and not self.drag and hover then
        self.drag = {key=key, x=mx-pos.x, y=my-pos.y}
        active = true
    end
    if active then self.drag_seen = true end
    if active and down then
        local sw, sh = client.screen_size()
        local min_x, max_x = anchor_x, math.max(anchor_x, sw-width+anchor_x)
        local min_y, max_y = anchor_y, math.max(anchor_y, sh-height+anchor_y)
        if DRAG_LIMIT_KEYS[key] then
             
            local size = key == 'damage' and 80 or 220
            local half = size * 0.5
            local cx, cy = sw * 0.5, sh * 0.5
            min_x = cx - half + anchor_x
            max_x = cx + half - (width - anchor_x)
            min_y = cy - half + anchor_y
            max_y = cy + half - (height - anchor_y)
            if max_x < min_x then min_x = (min_x + max_x) * 0.5; max_x = min_x end
            if max_y < min_y then min_y = (min_y + max_y) * 0.5; max_y = min_y end
            self.drag_limits = {x=cx-half, y=cy-half, width=size, height=size}
        end
        pos.x = clamp(mx-self.drag.x, min_x, max_x)
        pos.y = clamp(my-self.drag.y, min_y, max_y)
        self.drag_dirty = true
    elseif hover and right and not self.right_down then
        local sw = client.screen_size()
        pos.x = clamp(sw*0.5-width*0.5+anchor_x, anchor_x, math.max(anchor_x,sw-width+anchor_x))
        self.drag_dirty = true
        self:save_positions()
        self.drag_dirty = false
    end
    if (hover or active) then
        local sw, sh = client.screen_size()
        local top = pos.y - anchor_y
        local bottom = top + height
        local hint_h = 12
        local below_gap, above_gap = 6, 3
         
        local place_above = (bottom + below_gap + hint_h) > (sh - 2)
        if self.drag_limits then
            local lim = self.drag_limits
            local lim_bottom = lim.y + lim.height
            if (bottom + below_gap + hint_h) > (lim_bottom - 2) then
                place_above = true
            end
        end
         
        local target_y = place_above and top or bottom
        local cx = pos.x - anchor_x + width * 0.5
        local prev = self.drag_hint or self._drag_hint_keep
        if not prev then
            self.drag_hint = {
                x = cx,
                target_y = target_y,
                above = place_above,
                above_gap = above_gap,
                below_gap = below_gap,
                alpha = 1,
                phase = 'shown',
            }
        else
            prev.x = cx
            prev.above_gap = above_gap
            prev.below_gap = below_gap
            if prev.above ~= place_above and prev.phase == 'shown' then
                prev.phase = 'out'
                prev.pending_above = place_above
                prev.pending_y = target_y
            elseif prev.phase == 'shown' or prev.phase == 'in' then
                prev.target_y = target_y
                prev.above = place_above
            elseif prev.phase == 'out' then
                prev.pending_above = place_above
                prev.pending_y = target_y
            end
            self.drag_hint = prev
        end
    end
end
local function dashed_line(x1, y1, x2, y2, r, g, b, a, dash, gap)
    dash = dash or 6
    gap = gap or 4
    local dx, dy = x2 - x1, y2 - y1
    local len = math.sqrt(dx * dx + dy * dy)
    if len < 1 then return end
    local ux, uy = dx / len, dy / len
    local pos = 0
    while pos < len do
        local start = pos
        local stop = math.min(len, pos + dash)
        renderer.line(
            math.floor(x1 + ux * start + 0.5), math.floor(y1 + uy * start + 0.5),
            math.floor(x1 + ux * stop + 0.5), math.floor(y1 + uy * stop + 0.5),
            r, g, b, a
        )
        pos = pos + dash + gap
    end
end

local function dashed_arc(cx, cy, radius, start_deg, sweep_frac, r, g, b, a, dash, gap)
     
    local sweep = 360 * (sweep_frac or 0.25)
    local arc_len = math.abs(2 * math.pi * radius * (sweep / 360))
    if arc_len < 1 then return end
    dash, gap = dash or 5, gap or 4
    local pos = 0
    while pos < arc_len do
        local a0 = start_deg + (pos / arc_len) * sweep
        local a1 = start_deg + (math.min(arc_len, pos + dash) / arc_len) * sweep
        local rad0, rad1 = math.rad(a0), math.rad(a1)
        renderer.line(
            math.floor(cx + math.cos(rad0) * radius + 0.5),
            math.floor(cy + math.sin(rad0) * radius + 0.5),
            math.floor(cx + math.cos(rad1) * radius + 0.5),
            math.floor(cy + math.sin(rad1) * radius + 0.5),
            r, g, b, a
        )
        pos = pos + dash + gap
    end
end

function runtime:draw_drag_hint()
    local hint = self.drag_hint
    if not hint or not ui.is_menu_open() then return end
    local sw, sh = client.screen_size()
    local label = 'press m2 to centrize'
    local width, height = renderer.measure_text('bc', label)
    width, height = tonumber(width) or 110, tonumber(height) or 10
    local ft = clamp(tonumber(globals.frametime()) or 0.016, 0, 0.05)
    local phase = hint.phase or 'shown'
    local alpha = hint.alpha
    if type(alpha) ~= 'number' then alpha = 1 end
    if phase == 'out' then
        alpha = alpha - ft * 7
        if alpha <= 0 then
            alpha = 0
            if hint.pending_y ~= nil then
                hint.target_y = hint.pending_y
                hint.above = hint.pending_above
                hint.pending_y, hint.pending_above = nil, nil
            end
            hint.phase = 'in'
        end
    elseif phase == 'in' then
        alpha = alpha + ft * 7
        if alpha >= 1 then
            alpha = 1
            hint.phase = 'shown'
        end
    else
        alpha = 1
        hint.phase = 'shown'
    end
    hint.alpha = alpha
    local above_gap = hint.above_gap or 3
    local below_gap = hint.below_gap or 6
    local edge = hint.target_y or 0
    local y
    if hint.above then
         
        y = edge - above_gap - height
    else
        y = edge + below_gap
    end
    y = clamp(y, 2, math.max(2, sh - height - 2))
    hint.y = y
    local x = clamp(hint.x or (sw * 0.5), width * 0.5 + 2, math.max(width * 0.5 + 2, sw - width * 0.5 - 2))
    local r, g, b = 255, 255, 255
    if modules and modules.text and type(modules.text.menu_color) == 'function' then
        local ok, cr, cg, cb = pcall(modules.text.menu_color)
        if ok then r, g, b = cr or r, cg or g, cb or b end
    end
    local a = math.floor(255 * alpha + 0.5)
    if a < 1 then return end
    local ix, iy = math.floor(x + 0.5), math.floor(y + 0.5)
    local glow = {
        {dx = 1, dy = 0, a = 55}, {dx = -1, dy = 0, a = 55},
        {dx = 0, dy = 1, a = 55}, {dx = 0, dy = -1, a = 55},
        {dx = 2, dy = 0, a = 28}, {dx = -2, dy = 0, a = 28},
        {dx = 0, dy = 2, a = 28}, {dx = 0, dy = -2, a = 28},
        {dx = 1, dy = 1, a = 32}, {dx = -1, dy = 1, a = 32},
        {dx = 1, dy = -1, a = 32}, {dx = -1, dy = -1, a = 32},
        {dx = 3, dy = 0, a = 14}, {dx = -3, dy = 0, a = 14},
        {dx = 0, dy = 3, a = 14}, {dx = 0, dy = -3, a = 14},
    }
    for i = 1, #glow do
        local g0 = glow[i]
        local ga = math.floor(g0.a * alpha + 0.5)
        if ga > 0 then
            renderer.text(ix + g0.dx, iy + g0.dy, r, g, b, ga, 'bc', 0, label)
        end
    end
    renderer.text(ix, iy, r, g, b, a, 'bc', 0, label)
end

function runtime:draw_drag_limits()
    local limits = self.drag_limits
    if not limits or not ui.is_menu_open() then return end
    local r, g, b = 140, 110, 115
    if modules and modules.text and type(modules.text.menu_color) == 'function' then
        local ok, cr, cg, cb = pcall(modules.text.menu_color)
        if ok then r, g, b = cr or r, cg or g, cb or b end
    end
    local fade = self.drag_fade or 1
    local alpha = math.floor(235 * fade + 0.5)
    if alpha < 1 then return end
    local x, y = math.floor(limits.x), math.floor(limits.y)
    local w, h = math.floor(limits.width), math.floor(limits.height)
    if w < 1 or h < 1 then return end
    local radius = math.max(8, math.min(16, math.floor(math.min(w, h) * 0.07 + 0.5)))
    local dash, gap = 7, 5
     
    dashed_line(x + radius, y, x + w - radius, y, r, g, b, alpha, dash, gap)
    dashed_line(x + w, y + radius, x + w, y + h - radius, r, g, b, alpha, dash, gap)
    dashed_line(x + w - radius, y + h, x + radius, y + h, r, g, b, alpha, dash, gap)
    dashed_line(x, y + h - radius, x, y + radius, r, g, b, alpha, dash, gap)
     
    dashed_arc(x + radius, y + radius, radius, 180, 0.25, r, g, b, alpha, 5, 4)
    dashed_arc(x + w - radius, y + radius, radius, 270, 0.25, r, g, b, alpha, 5, 4)
    dashed_arc(x + w - radius, y + h - radius, radius, 0, 0.25, r, g, b, alpha, 5, 4)
    dashed_arc(x + radius, y + h - radius, radius, 90, 0.25, r, g, b, alpha, 5, 4)
end
 
 
function runtime:draw_failure_notes()
    local notes, count = {}, 0
    for _, message in pairs(self.failed) do
        if type(message) == 'string' then
            count = count + 1
            notes[count] = message
        end
    end
    if count == 0 then return end
    table.sort(notes)
    local r, g, b = 255, 255, 255
    if modules and modules.text and type(modules.text.menu_color) == 'function' then
        local ok, cr, cg, cb = pcall(modules.text.menu_color)
        if ok then r, g, b = cr or r, cg or g, cb or b end
    end
    local y = 10
    for i = 1, count do
        renderer.text(11, y + 1, 0, 0, 0, 200, '-', 0, notes[i])
        renderer.text(10, y, r, g, b, 255, '-', 0, notes[i])
        y = y + 12
    end
end

function runtime:paint_ui()
    if self.grenade_warning then
        self:run('Grenade Warning', function(host)
            host.grenade_warning:sync(selected(host.menu.refs.world_select, 'Grenade Warning'))
        end)
    end
    local menu_open = ui.is_menu_open()
    self.drag_hovered, self.drag_seen, self.drag_limits = false, false, nil
     
    self._drag_hint_keep = self.drag_hint
    self.drag_hint = nil
    local dt = clamp(tonumber(globals.frametime()) or 0, 0, 0.05)
    local target = menu_open and (self.drag or self.arrow_drag) and 1 or 0
    self.drag_fade = (self.drag_fade or 0) + (target-(self.drag_fade or 0))*(1-math.exp(-15*dt))
    if not menu_open or self.drag_fade < 0.001 then self.drag_fade=0 end
    if self.drag_fade > 0 then
        local sw,sh = client.screen_size()
        if sw and sh and sw>0 and sh>0 then renderer.rectangle(0,0,sw,sh,0,0,0,math.floor(135*self.drag_fade+0.5)) end
    end
    self:run('Damage Indicator', self.damage_indicator)
    self:run('Velocity Indicator', self.velocity_indicator)
    if self.crosshair then self:run('Crosshair Indicator', function(host) host.crosshair:render(host) end) end
    if self.watermark then self:run('Watermark', function(host) host.watermark:render(host) end) end
    if self.output then self:run('Custom Output', function(host) host.output:paint_ui(host) end) end
    local down = menu_open and client.key_state(0x01) or false
    if self.drag and (not down or not self.drag_seen) then
        if self.drag_dirty then
            self:save_positions()
            self.drag_dirty = false
        end
        self.drag = nil
    end
    self.mouse_down = down
    self.right_down = menu_open and client.key_state(0x02) or false
    if self.scope then self.scope:paint_ui() end
    if not self.drag_hint and self._drag_hint_keep and (self.drag_seen or self.drag) then
        self.drag_hint = self._drag_hint_keep
    end
    self._drag_hint_keep = nil
    self:draw_drag_limits()
    self:draw_drag_hint()
    self:draw_failure_notes()
end

 
 
function runtime:preview_opacity(key, menu_open, real_visible)
    self.preview_progress = self.preview_progress or {}
    local progress = self.preview_progress[key] or 0
    if menu_open then
        progress = 1
    else
        local dt = clamp(tonumber(globals.frametime()) or 0, 0, 0.1)
        progress = clamp(progress - dt / 0.30, 0, 1)
    end
    self.preview_progress[key] = progress
    if real_visible then return 1 end
    return progress * progress * (3 - 2 * progress)
end

function runtime:clear_preview(key)
    if self.preview_progress then self.preview_progress[key] = nil end
end

function runtime:damage_indicator()
    local refs = self.menu.refs
    if not selected(refs.windows_select, 'Damage Indicator') then self:clear_preview('damage'); return end
    if not self.damage_ref then error('Minimum damage reference unavailable') end
    local player, menu_open = entity.get_local_player(), ui.is_menu_open()
    local alive = player and entity.is_alive(player) or false
    local override = self.override_enabled and self.override_hotkey ~= nil
        and ui.get(self.override_enabled)
        and hotkey_active(self, 'damage_override', self.override_hotkey) or false
    local real_visible = alive and (not ui.get(refs.window_damage_override_only) or override)
    local opacity = self:preview_opacity('damage', menu_open, real_visible)
    if opacity <= 0 then return end
    if override and not self.override_value then error('Minimum damage override reference unavailable') end
    local ref = override and self.override_value or self.damage_ref
    local value = ui.get(ref)
    local label = value == 0 and 'AUTO' or value > 100 and ('+' .. tostring(value - 100)) or tostring(value)
    local fonts = {Default = '', Small = '-', Bold = 'b'}
    local flags = fonts[ui.get(refs.window_damage_font)] or ''
    local width, height = renderer.measure_text(flags, label)
    width, height = width or 24, height or 12
    local sw, sh = client.screen_size()
    local pos = self:position('damage', math.floor(sw * 0.5 + 20), math.floor(sh * 0.5 - 30))
    self:drag_item('damage', pos.x, pos.y, width, height, 8)
    local r, g, b, a = ui.get(refs.window_damage_color)
    renderer.text(math.floor(pos.x), math.floor(pos.y), r, g, b, math.floor(a * opacity + 0.5), flags, nil, label)
end

local function round_rect(x, y, w, h, radius, r, g, b, a)
    if a < 1 or w < 1 or h < 1 then return end
    x, y, w, h = math.floor(x), math.floor(y), math.floor(w), math.floor(h)
    radius = math.floor(math.min(radius, w / 2, h / 2))
    if radius < 1 then renderer.rectangle(x, y, w, h, r, g, b, a); return end
    renderer.rectangle(x + radius, y, w - radius * 2, h, r, g, b, a)
    renderer.rectangle(x, y + radius, radius, h - radius * 2, r, g, b, a)
    renderer.rectangle(x + w - radius, y + radius, radius, h - radius * 2, r, g, b, a)
    renderer.circle(x + radius, y + radius, r, g, b, a, radius, 180, 0.25)
    renderer.circle(x + w - radius, y + radius, r, g, b, a, radius, 90, 0.25)
    renderer.circle(x + radius, y + h - radius, r, g, b, a, radius, 270, 0.25)
    renderer.circle(x + w - radius, y + h - radius, r, g, b, a, radius, 0, 0.25)
end

function runtime:velocity_indicator()
    local refs = self.menu.refs
    if not selected(refs.windows_select, 'Velocity Indicator') then
        self:clear_preview('velocity'); self.preview_velocity_modifier = nil; return
    end
    local menu_open = ui.is_menu_open()
    local player = entity.get_local_player()
    local real_modifier
    if player and entity.is_alive(player) then
        real_modifier = entity.get_prop(player, 'm_flVelocityModifier') or 1
    end
    local real_visible = real_modifier ~= nil and real_modifier < 0.999
    local opacity = self:preview_opacity('velocity', menu_open, real_visible)
    if opacity <= 0 then self.preview_velocity_modifier = nil; return end
    local modifier
    if menu_open then
        modifier = (math.sin(globals.realtime() * 0.7) + 1) * 0.5
        self.preview_velocity_modifier = modifier
    elseif real_visible then
        modifier = real_modifier
    else
        modifier = self.preview_velocity_modifier or self.velocity
    end
    local sw, sh = client.screen_size()
    local pos = self:position('velocity', sw * 0.5 - 90, sh * 0.35)
    self:drag_item('velocity', pos.x, pos.y, 180, 8, 10)
    self.velocity = smooth(self.velocity, modifier, 0.18)
    local fade = real_visible and not menu_open and self.velocity > 0.9 and (1 - self.velocity) / 0.1 or 1
    fade = fade * opacity
    if fade < 0.02 then return end
    local r, g, b, a = ui.get(refs.window_velocity_color)
    local alpha, bg = math.floor(a * fade), math.floor(105 * fade)
    if alpha < 1 then return end
    local x, y, fill = pos.x, pos.y, math.max(0, 174 * self.velocity)
    round_rect(x + 2, y + 3, 180, 8, 4, 0, 0, 0, math.floor(bg * 0.28))
    round_rect(x + 4, y + 6, 180, 8, 5, 0, 0, 0, math.floor(bg * 0.12))
    round_rect(x, y, 180, 8, 4, 8, 8, 11, bg)
    if fill > 1 then
        round_rect(x + 1, y, fill + 4, 8, 3, r, g, b, math.floor(alpha * 0.20))
        renderer.gradient(x + 3, y + 2, fill, 4, 0, 0, 0, alpha, r, g, b, alpha, true)
        if fill >= 4 then
            renderer.circle(x + 5, y + 4, 0, 0, 0, alpha, 2, 180, 0.25)
            renderer.circle(x + 3 + fill - 2, y + 4, r, g, b, alpha, 2, 0, 0.25)
        end
    end
    renderer.text(math.floor(x + 90), math.floor(y - 12), 255, 255, 255, alpha, 'c', 0,
        string.format('Max velocity reduced by %.0f%%', (1 - self.velocity) * 100))
end

function runtime:paint()
    if self.hitmarker then self:run('Hitmarkers', function(host) host.hitmarker:paint() end) end
    if self.manual_arrows then self:run('Manual Arrows', function(host) host.manual_arrows:paint() end) end
    self:run('Aspect Ratio', self.aspect_ratio)
    if self.world then self.world:paint() end
    if self.scope then self.scope:paint() end
    if self.grenade_warning then
        self:run('Grenade Warning', function(host)
            local r, g, b, a = ui.get(host.menu.visuals.refs.grenade_warning_color)
            host.grenade_warning:paint(selected(host.menu.refs.world_select, 'Grenade Warning'), r, g, b, a)
        end)
    end
     
    if self.drag_fade and self.drag_fade > 0 and ui.is_menu_open()
        and type(renderer.blur) == 'function' and not self.drag_blur_failed then
        local sw, sh = client.screen_size()
        if sw and sh and sw > 0 and sh > 0 then
            local ok = pcall(renderer.blur, 0, 0, sw, sh, self.drag_fade * 0.9, 0.55)
            if not ok then self.drag_blur_failed = true end
        end
    end
end

function runtime:level_init()
    if self.hitmarker then self.hitmarker:reset() end
    if self.manual_arrows then self.manual_arrows:reset() end
    if self.grenade_warning then self.grenade_warning:reset() end
end

function runtime:override_view(event)
    if self.world then self.world:override_view(event) end
end

function runtime:aspect_ratio()
    local refs, visual = self.menu.refs, self.menu.visuals.refs
    local enabled = selected(refs.world_select, 'Aspect Ratio') and ui.get(visual.aspect)
    if not enabled then
        if self.aspect ~= nil then
            cvar.r_aspectratio:set_float(self.aspect.original)
            self.aspect = nil
        end
        return
    end
    if self.aspect == nil then
        local original = cvar.r_aspectratio:get_float()
        self.aspect = {original = original, smooth = original, last = original}
    end
    local presets = {['5:4'] = 1.25, ['4:3'] = 1.33, ['16:10'] = 1.6, ['16:9'] = 16 / 9}
    local value = presets[ui.get(visual.aspect_preset)] or ui.get(visual.aspect_amount) / 100
    local current = self.aspect
    current.smooth = smooth(current.smooth, value, 0.24)
    if math.abs(current.smooth - current.last) > 0.0001 then
        cvar.r_aspectratio:set_float(current.smooth)
        current.last = current.smooth
    end
end

function runtime:shutdown()
    local errors = {}
    local function attempt(name, fn)
        local ok, err = pcall(fn)
        if not ok then errors[#errors+1] = name .. ': ' .. tostring(err) end
        return ok
    end
    if self.grenade_warning then attempt('Grenade Warning', function() self.grenade_warning:shutdown() end) end
    if self.output then attempt('Custom Output', function() self.output:shutdown() end) end
    if self.world then attempt('World', function() self.world:shutdown() end) end
    if self.scope then attempt('Scope', function() self.scope:shutdown() end) end
    if self.aspect ~= nil then
        if attempt('Aspect Ratio', function() cvar.r_aspectratio:set_float(self.aspect.original) end) then self.aspect = nil end
    end
    if self.drag then self.drag = nil end
    if #errors > 0 then error(table.concat(errors, '; '), 0) end
end
return runtime


end,

 

 
['misc_animation'] = function(...)
 
local ffi, bit, c_entity
local Class = {ui={menu={misc_tab={}}},util={reference={}}}
local breaker = {
 _ffi_helper = function(self, cmd_number)
   if not ffi or not cmd_number or cmd_number == 0 then return nil end
   local success, result = pcall(function()
     if not pcall(ffi.typeof, "bt_cusercmd_t") then
       ffi.cdef[[
       typedef struct {
        struct bt_cusercmd_t (*cusercmd)();
        int     command_number;
        int     tick_count;
        float   view[3];
        float   aim[3];
        float   move[3];
        int     buttons;
       } bt_cusercmd_t;
      ]]
    end
    if not pcall(ffi.typeof, "bt_get_usercmd") then
      ffi.cdef[[
      typedef bt_cusercmd_t*(__thiscall* bt_get_usercmd)(void* input, int, int command_number);
      ]]
    end
    local sig = client.find_signature("client.dll", "\xB9\xCC\xCC\xCC\xCC\x8B\x40\x38\xFF\xD0\x84\xC0\x0F\x85")
    if not sig then return nil end
    local vtbl = ffi.cast("void***", ffi.cast("void**", ffi.cast("uintptr_t", sig) + 1)[0])
    local location = ffi.cast("bt_get_usercmd", vtbl[0][8])
    return location(vtbl, 0, cmd_number)
  end)
  if success then return result end
  return nil
end,
_get_airwalk_animstate = function(self, local_player)
  if not local_player or not ffi then return nil end
  local ok, result = pcall(function()
    if not pcall(ffi.typeof, "afterglow_airwalk_animstate_t") then
      ffi.cdef[[
        typedef struct {
          char pad[0x124];
          float flAffectedFraction;
        } afterglow_airwalk_animstate_t;
      ]]
    end

    if not self._airwalk_entity_list or not self._airwalk_get_client_entity then
      local interface = client.create_interface("client.dll", "VClientEntityList003")
      if interface == nil or tonumber(ffi.cast("uintptr_t", interface)) == 0 then
        return nil
      end
      local entity_list = ffi.cast("void***", interface)
      if entity_list == nil or tonumber(ffi.cast("uintptr_t", entity_list)) == 0 then
        return nil
      end
      local get_client_entity = entity_list[0][3]
      if get_client_entity == nil then return nil end
      self._airwalk_entity_list = entity_list
      self._airwalk_get_client_entity = ffi.cast(
        "void*(__thiscall*)(void*, int)", get_client_entity
      )
    end

    local entity_pointer = self._airwalk_get_client_entity(self._airwalk_entity_list, local_player)
    if entity_pointer == nil or tonumber(ffi.cast("uintptr_t", entity_pointer)) == 0 then
      return nil
    end

    local entity_address = tonumber(ffi.cast("uintptr_t", entity_pointer))
    local animstate = ffi.cast(
      "afterglow_airwalk_animstate_t**", entity_address + 0x9960
    )[0]
    if animstate == nil or tonumber(ffi.cast("uintptr_t", animstate)) == 0 then
      return nil
    end
    return animstate
  end)
  if ok then return result end
  return nil
end,
_set_air_walking = function(self, local_player, active)
  if not active or not local_player then return false end
  local animstate = self:_get_airwalk_animstate(local_player)
  if not animstate then return false end
  self:_set_pose_parameter(local_player, 0, 7)
  animstate.flAffectedFraction = 1
  return true
end,
_prepare_anim_player = function(self, local_player)
  if not local_player or self._anim_player == local_player then return end
  self._anim_player = local_player
  self:_reset_animation_state()
end,
_set_pose_parameter = function(self, local_player, value, index)
  if not local_player then return end
  entity.set_prop(local_player, "m_flPoseParameter", value, index)
end,
_update_anim_overlay = function(self, overlay_index, weight)
  local local_player = entity.get_local_player()
  if not local_player or not c_entity then return false end
  local ent = c_entity.new(local_player)
  if not ent then return false end
  local overlay = ent:get_anim_overlay(overlay_index)
  if not overlay then return false end
  overlay.weight = weight
  return true
end,
_reset_ground_state = function(self)
  self._ground_jitter_phase = nil
  self._ground_jitter_delay = nil
  self._ground_jitter_value = nil
  self._ground_moonwalk_active = false
end,
_reset_air_state = function(self)
  self._air_pose_target = nil
end,
_reset_animation_state = function(self)
  self:_reset_ground_state()
  self:_reset_air_state()
  self._earthshake_tick = nil
  self._earthshake_weight = nil
end,
_custom_legs_movement_active = function(self)
  local animation_breaker = Class.ui.menu.misc_tab and Class.ui.menu.misc_tab.animation_breaker
  if not animation_breaker or not animation_breaker.other then return false end
  local active = false
  pcall(function()
    active = animation_breaker.enabled:get() == true
      and self:_multi_has(animation_breaker.triggers, "Other")
      and self:_multi_has(animation_breaker.other.mode, "Leg movement")
  end)
  return active
end,
_apply_legs_movement = function(self)
  local animation_breaker = Class.ui.menu.misc_tab.animation_breaker
  local legs_ref = Class.util.reference.aa_legs_movement
  local player = entity.get_local_player()
  if not legs_ref or not legs_ref[1] or not player or not entity.is_alive(player)
    or not animation_breaker.enabled:get() then return end
  local flags = entity.get_prop(player, "m_fFlags") or 0
  local on_ground = bit.band(flags, 1) == 1
  local mode = animation_breaker.ground.mode:get()
  local ground = on_ground and self:_multi_has(animation_breaker.triggers, "Legs")
  if self:_custom_legs_movement_active() then
    ui.set(legs_ref[1], animation_breaker.other.leg_movement:get())
  elseif ground then
    ui.set(legs_ref[1], mode == "Moonwalk" and "Never slide" or "Always slide")
  end
end,
_ground_animations = function(self, cmd, velocity)
  local animation_breaker = Class.ui.menu.misc_tab.animation_breaker
  local local_player = entity.get_local_player()
  if not local_player then return end
  local breaker_mode = animation_breaker.ground.mode:get()
  local target = 0

  if breaker_mode == "Moonwalk" then
    self._ground_jitter_phase = nil
    self._ground_jitter_delay = nil
    self._ground_jitter_value = nil
    self:_set_pose_parameter(local_player, 0, 1)
    self:_set_pose_parameter(local_player, 1, 7)
    self._ground_moonwalk_active = true
    return
  else
    self._ground_moonwalk_active = false
  end

  if breaker_mode == "Static" then
    local delta = tonumber(animation_breaker.ground.static_delta:get()) or 0
    target = math.max(0, math.min(100, delta)) / 100
    self._ground_jitter_phase = nil
    self._ground_jitter_delay = nil
    self._ground_jitter_value = nil
  elseif breaker_mode == "Jitter" then
    local delta_from = tonumber(animation_breaker.ground.delta_from:get()) or 0
    local delta_to = tonumber(animation_breaker.ground.delta_to:get()) or 100
    delta_from = math.max(0, math.min(100, delta_from))
    delta_to = math.max(0, math.min(100, delta_to))
    if delta_from > delta_to then delta_from, delta_to = delta_to, delta_from end

    local delay = math.floor(tonumber(animation_breaker.ground.jitter_delay:get()) or 2)
    delay = math.max(1, math.min(32, delay))
    if self._ground_jitter_delay ~= delay then
      self._ground_jitter_delay = delay
      self._ground_jitter_phase = nil
      self._ground_jitter_value = nil
    end

    local tick = tonumber(globals.tickcount()) or 0
    local phase = math.floor(tick / delay) % 2
    if self._ground_jitter_phase ~= phase or self._ground_jitter_value == nil then
      self._ground_jitter_phase = phase
       
      self._ground_jitter_value = phase == 0
        and 0
        or client.random_float(delta_from / 100, delta_to / 100)
    end
    target = self._ground_jitter_value
  end

  self:_set_pose_parameter(local_player, target, 0)
end,
_air_animations = function(self)
  local animation_breaker = Class.ui.menu.misc_tab.animation_breaker
  local local_player = entity.get_local_player()
  if not local_player then return end
  local breaker_mode = animation_breaker.air.mode:get()
  local target = 0

  if breaker_mode == "Static" then
    target = 0.25
    self:_set_air_walking(local_player, false)
  elseif breaker_mode == "Allah" then
    target = 0
    self:_set_air_walking(local_player, true)
  elseif breaker_mode == "Kangaroo" then
     
    self._air_pose_target = nil
    return
  else
    self:_set_air_walking(local_player, false)
  end

  if self._air_pose_target == nil then
    self._air_pose_target = target
  else
    local smoothing = 0.75
    self._air_pose_target = self._air_pose_target + ((target - self._air_pose_target) * smoothing)
  end
  if math.abs(self._air_pose_target) < 0.001 then self._air_pose_target = 0 end
  self:_set_pose_parameter(local_player, self._air_pose_target, 6)
end,
_multi_has = function(self, el, name)
  if not el then return false end
  local success, value = pcall(function() return el:get(name) end)
  if success and value == true then return true end
  local ok, values = pcall(function() return el:get() end)
  if ok then
    if type(values) == "table" then
      for index = 1, #values do
        if values[index] == name then return true end
      end
      if values[name] then return true end
    elseif values == name then
      return true
    end
  end
  return false
end,
_extra_animations = function(self, cmd, velocity)
  local animation_breaker = Class.ui.menu.misc_tab.animation_breaker
  local local_player = entity.get_local_player()
  if not animation_breaker or not local_player or not animation_breaker.triggers
    or not self:_multi_has(animation_breaker.triggers, "Other") then
    return
  end

  local options = animation_breaker.other
  if not options or not options.mode then
    return
  end

  local overlay_weight = 0
  local has_overlay_effect = false
  local selected_body_lean = self:_multi_has(options.mode, "Body Lean")
  local selected_earthshake = self:_multi_has(options.mode, "Earthshake")

  if selected_body_lean then
    local allow_standing = false
    pcall(function()
      allow_standing = options.allow_standing_leaning and options.allow_standing_leaning:get() == true
    end)
    local lean = 0
    pcall(function() lean = tonumber(options.body_lean:get()) or 0 end)
    lean = math.max(0, math.min(100, lean)) / 100
    if lean > 0 and (allow_standing or (tonumber(velocity) or 0) > 5) then
      overlay_weight = lean
      has_overlay_effect = true
    end
  end

  if selected_earthshake then
    local strength = 100
    pcall(function() strength = tonumber(options.earthshake_strength:get()) or 100 end)
    strength = math.max(1, math.min(100, strength))
    local in_air = false
    local flags = entity.get_prop(local_player, "m_fFlags") or 0
    in_air = bit.band(flags, 1) == 0
    if strength >= 100 or not in_air then
      local tick = tonumber(globals.tickcount()) or 0
      if self._earthshake_tick ~= tick then
        local min_weight = 0.05 + (strength / 100) * 0.15
        local max_weight = 0.15 + (strength / 100) * 0.85
        self._earthshake_weight = client.random_float(min_weight, max_weight)
        self._earthshake_tick = tick
      end
      local earth_weight = tonumber(self._earthshake_weight) or 0
      if has_overlay_effect then
         
        overlay_weight = overlay_weight * earth_weight
      else
        overlay_weight = earth_weight
      end
      has_overlay_effect = true
    end
  end

  if has_overlay_effect then
    self:_update_anim_overlay(12, overlay_weight)
  end

  if options.walking_legs and options.walking_legs:get() and cmd then
    local peek = Class.util.reference.rage_peek_assist
    local peek_on = false
    if peek and peek[2] then pcall(function() peek_on = ui.get(peek[2]) == true end) end
    if peek_on and entity.get_prop(local_player, "m_MoveType") == 2 then
      local command_number = cmd.command_number
      local command = self:_ffi_helper(command_number)
      if command then
        pcall(function()
          command.buttons = bit.band(command.buttons, bit.bnot(8))
          command.buttons = bit.band(command.buttons, bit.bnot(16))
          command.buttons = bit.band(command.buttons, bit.bnot(512))
          command.buttons = bit.band(command.buttons, bit.bnot(1024))
        end)
      end
    end
  end
end,
update = function(self, cmd)
  local animation_breaker = Class.ui.menu.misc_tab and Class.ui.menu.misc_tab.animation_breaker
  local local_player = entity.get_local_player()
  local alive = local_player ~= nil and entity.is_alive(local_player)
  local enabled = animation_breaker and animation_breaker.enabled and animation_breaker.enabled:get() == true

  self:_prepare_anim_player(local_player)
  self:_apply_legs_movement()
  if not enabled or not alive then
    self:_reset_animation_state()
    return
  end

  local flags = entity.get_prop(local_player, "m_fFlags") or 0
  local in_air = bit.band(flags, 1) == 0
  local vx = tonumber(entity.get_prop(local_player, "m_vecVelocity[0]")) or 0
  local vy = tonumber(entity.get_prop(local_player, "m_vecVelocity[1]")) or 0
  local velocity = math.sqrt((vx * vx) + (vy * vy))
  local has_legs = self:_multi_has(animation_breaker.triggers, "Legs")
  local has_air = self:_multi_has(animation_breaker.triggers, "Air")
  local has_other = self:_multi_has(animation_breaker.triggers, "Other")

  if not in_air then
    self:_reset_air_state(local_player)
  end

  if has_legs and not in_air then
    self:_ground_animations(cmd, velocity)
  else
    self:_reset_ground_state(local_player)
  end

  if has_air and in_air then
    self:_air_animations()
  elseif in_air then
    self:_reset_air_state(local_player)
  end

  if has_other then
    self:_extra_animations(cmd, velocity)
  end
end,

on_post_update_clientside_animation = function(self)
  local animation_breaker = Class.ui.menu.misc_tab and Class.ui.menu.misc_tab.animation_breaker
  local local_player = entity.get_local_player()
  local alive = animation_breaker and animation_breaker.enabled
    and animation_breaker.enabled:get() == true
    and local_player ~= nil and entity.is_alive(local_player)

  local air_walking = false
  if alive and animation_breaker.air and animation_breaker.air.mode then
    local flags = entity.get_prop(local_player, "m_fFlags") or 0
    local in_air = bit.band(flags, 1) == 0
    air_walking = in_air
      and self:_multi_has(animation_breaker.triggers, "Air")
      and animation_breaker.air.mode:get() == "Allah"
  end
  self:_set_air_walking(local_player, air_walking)

  if alive then
    local flags = entity.get_prop(local_player, "m_fFlags") or 0
    local on_ground = bit.band(flags, 1) == 1
    local ground_mode = animation_breaker.ground and animation_breaker.ground.mode
      and animation_breaker.ground.mode:get() or "Default"
    if on_ground and self:_multi_has(animation_breaker.triggers, "Legs")
      and ground_mode == "Moonwalk" then
      self:_set_pose_parameter(local_player, 0, 1)
      self:_set_pose_parameter(local_player, 1, 7)
    end
  end

  if not alive or not self:_multi_has(animation_breaker.triggers, "Other") then
    return
  end
  local vx = tonumber(entity.get_prop(local_player, "m_vecVelocity[0]")) or 0
  local vy = tonumber(entity.get_prop(local_player, "m_vecVelocity[1]")) or 0
  self:_extra_animations(nil, math.sqrt((vx * vx) + (vy * vy)))
end,

}
local function control(ref)
 return {get=function(_, name)
  local value=ui.get(ref)
  if name == nil then return value end
  if type(value)~='table' then return false end
  for _,v in ipairs(value) do if v==name then return true end end
  return false
 end}
end
local function native(...)
 local ok,a,b=pcall(ui.reference,...)
 if not ok or not a then return nil end
 return {a,b}
end
function breaker:init(menu,report)
 local r=menu.misc_rage.refs
 self.menu,self.report=menu,report
 Class.ui.menu.misc_tab.animation_breaker={enabled=control(r.anim),triggers=control(r.anim_sections),
  air={mode=control(r.air_mode)},
  ground={mode=control(r.legs_mode),static_delta=control(r.static_delta),delta_from=control(r.delta_from),delta_to=control(r.delta_to),jitter_delay=control(r.legs_delay)},
  other={mode=control(r.other_modes),leg_movement=control(r.leg_movement),body_lean=control(r.body_lean),
   allow_standing_leaning=control(r.standing_lean),earthshake_strength=control(r.earthshake),walking_legs=control(r.walking_legs)}}
 Class.util.reference.aa_legs_movement=native('AA','Other','Leg movement')
 Class.util.reference.rage_peek_assist=native('RAGE','Other','Quick peek assist')
end
function breaker:ensure()
 if bit then return true end
 local ok,v=pcall(require,'bit')
 if not ok then if not self.missing_bit then self.report('Animation Breaker','LuaJIT bit unavailable');self.missing_bit=true end;return false end
 bit=v
 ok,v=pcall(require,'ffi');if ok then ffi=v end
 ok,v=pcall(require,'gamesense/entity');if ok then c_entity=v end
 return true
end
 
 
 
local function smooth_enabled(self)
 local r = self.menu.misc_rage.refs
 if not ui.get(r.anim) then return false end
 local sections, modes = ui.get(r.anim_sections), ui.get(r.other_modes)
 if type(sections) ~= 'table' or type(modes) ~= 'table' then return false end
 local other, smooth = false, false
 for _, v in ipairs(sections) do if v == 'Other' then other = true end end
 for _, v in ipairs(modes) do if v == 'Smooth Animfix' then smooth = true end end
 return other and smooth
end
local function smooth_entity(player)
 if not c_entity or type(c_entity.new) ~= 'function' or not player or not entity.is_alive(player) then return nil end
 local ent = c_entity.new(player)
 if not ent or type(ent.get_anim_overlay) ~= 'function' then return nil end
 return ent
end
local function finite(value)
 value = tonumber(value)
 if value and value == value and value ~= math.huge and value ~= -math.huge then return value end
end
function breaker:smooth_reset()
 self._smooth_samples, self._smooth_player = nil, nil
end
function breaker:smooth_capture()
 if not smooth_enabled(self) or not c_entity then self:smooth_reset(); return end
 local player = entity.get_local_player()
 if self._smooth_player and self._smooth_player ~= player then self:smooth_reset() end
 local ent = smooth_entity(player)
 if not ent then self._smooth_samples, self._smooth_player = nil, nil; return end
 local t = finite(globals.realtime())
 if not t then self._smooth_samples, self._smooth_player = nil, nil; return end
 local sample = {time=t, weapon=entity.get_player_weapon(player), layers={}}
  
  
 for index = 0, 12 do
  local layer = ent:get_anim_overlay(index)
  if layer then
   local cycle, weight = finite(layer.cycle), finite(layer.weight)
   if cycle and weight then sample.layers[index] = {cycle=cycle, weight=weight, sequence=tonumber(layer.sequence)} end
  end
 end
 local samples = self._smooth_samples or {}
 local last = samples[#samples]
 if last and (t < last.time or t - last.time > 0.25) then samples = {}; last = nil end
 if last and t == last.time then samples[#samples] = sample else samples[#samples+1] = sample end
 while #samples > 2 do table.remove(samples, 1) end
 self._smooth_samples, self._smooth_player = samples, player
end
function breaker:smooth_render()
 if not smooth_enabled(self) or not c_entity then self:smooth_reset(); return end
 local player = entity.get_local_player()
 if player ~= self._smooth_player then self:smooth_reset(); return end
 local ent, samples = smooth_entity(player), self._smooth_samples
 if not ent or not samples or #samples < 2 then return end
 local a, b = samples[1], samples[2]
 local duration, current = b.time - a.time, finite(globals.realtime())
 if not current or duration <= 0 or current < b.time or current - b.time > 0.25 then return end
  
  
 local fraction = math.max(0, math.min(1, (current - b.time) / duration))
 local modes = ui.get(self.menu.misc_rage.refs.other_modes) or {}
 local lean_active = false
 for _, mode in ipairs(modes) do
  if mode == 'Body Lean' or mode == 'Earthshake' then lean_active = true end
 end
 for index = 0, 12 do
  local first, last = a.layers[index], b.layers[index]
  if first and last and not (index == 12 and lean_active) then
   local layer = ent:get_anim_overlay(index)
   if layer then
    local cycle, weight = finite(layer.cycle), finite(layer.weight)
    if cycle and weight then
     local snap = ((index == 1 or index == 2) and a.weapon ~= b.weapon)
       or (first.sequence and last.sequence and first.sequence ~= last.sequence)
     local f = snap and 1 or fraction
     local out_cycle = first.cycle + (last.cycle - first.cycle) * f
     local out_weight = first.weight + (last.weight - first.weight) * f
     layer.cycle, layer.weight = out_cycle, out_weight
    end
   end
  end
 end
end
function breaker:finish(cmd)
 if not ui.get(self.menu.misc_rage.refs.anim) and not bit then return end
 if not self:ensure() then return end
 local r=self.menu.misc_rage.refs
 local enabled=ui.get(r.anim) == true
 local sections=ui.get(r.anim_sections) or {}
 local selected=false
 for _,v in ipairs(sections) do if v=='Other' then selected=true end end
 local other=(enabled and selected) and (ui.get(r.other_modes) or {}) or {}
 local need_entity=false
 for _,v in ipairs(other) do
  if v=='Body Lean' or v=='Earthshake' or v=='Pitch Zero on Land' or v=='Smooth Animfix' then need_entity=true end
 end
 if need_entity and not c_entity and not self.warned_entity then self.report('Animation Breaker','install gamesense/entity for Body Lean, Earthshake, Pitch Zero on Land and Smooth Animfix');self.warned_entity=true end
 local air=false
 for _,v in ipairs(sections) do if v=='Air' then air=true end end
 if enabled and not ffi and not self.warned_ffi and ((air and ui.get(r.air_mode)=='Allah') or (selected and ui.get(r.walking_legs))) then self.report('Animation Breaker','LuaJIT ffi unavailable for Allah / Walking Legs');self.warned_ffi=true end
 self:update(cmd)
 self:smooth_capture()
end
 
 
function breaker:apply_air_preview()
 if not bit then return end
 local r = self.menu.misc_rage.refs
 if not ui.get(r.anim) then return end
 local mode = ui.get(r.air_mode)
 if mode ~= 'Allah' and mode ~= 'Kangaroo' then return end
 local sections = ui.get(r.anim_sections)
 if type(sections) ~= 'table' then return end
 local selected = false
 for _, name in ipairs(sections) do if name == 'Air' then selected = true; break end end
 if not selected then return end
 local player = entity.get_local_player()
 if not player or not entity.is_alive(player) then return end
 local flags = entity.get_prop(player, 'm_fFlags') or 0
 if bit.band(flags, 1) ~= 0 then return end
 if mode == 'Allah' then
  if self:_set_air_walking(player, true) then
   self:_set_pose_parameter(player, self._air_pose_target or 0, 6)
  end
 else
   
  self:_set_pose_parameter(player, math.random(0, 10) / 10, 3)
  self:_set_pose_parameter(player, math.random(0, 10) / 10, 7)
  self:_set_pose_parameter(player, math.random(0, 10) / 10, 6)
 end
end
 
function breaker:setup_command(cmd)
 self._jump_released = cmd ~= nil and cmd.in_jump == 0
end
 
function breaker:apply_extra_animations()
 if not bit then return end
 local animation_breaker = Class.ui.menu.misc_tab.animation_breaker
 if not animation_breaker or not animation_breaker.enabled:get()
   or not self:_multi_has(animation_breaker.triggers, 'Other') then return end
 local player = entity.get_local_player()
 if not player or not entity.is_alive(player) then return end
 local vx = tonumber(entity.get_prop(player, 'm_vecVelocity[0]')) or 0
 local vy = tonumber(entity.get_prop(player, 'm_vecVelocity[1]')) or 0
 self:_extra_animations(nil, math.sqrt(vx * vx + vy * vy))
end
 
function breaker:apply_pitch_on_land()
 if not bit or not c_entity then return end
 local r = self.menu.misc_rage.refs
 if not ui.get(r.anim) then return end
 local sections, modes = ui.get(r.anim_sections), ui.get(r.other_modes)
 if type(sections) ~= 'table' or type(modes) ~= 'table' then return end
 local other, pitch = false, false
 for _, v in ipairs(sections) do if v == 'Other' then other = true end end
 for _, v in ipairs(modes) do if v == 'Pitch Zero on Land' then pitch = true end end
 if not other or not pitch or self._jump_released ~= true then return end
 local player = entity.get_local_player()
 if not player or not entity.is_alive(player) then return end
 local ent = c_entity.new(player)
 if not ent then return end
 local state = ent:get_anim_state()
 if state == nil then return end
 local landing = state.hit_in_ground_animation
 if landing == true or landing == 1 then
  self:_set_pose_parameter(player, 0.5, 12)
 end
end
function breaker:post_animation()
 if not bit then return end
 self:on_post_update_clientside_animation()
end
function breaker:reset()
 self:smooth_reset()
 self._jump_released = nil
 if not bit then return end
 self:_reset_animation_state()
 self._anim_player=nil
end
function breaker:shutdown() self:reset() end
return breaker


end,

 
['misc_chat_filter'] = function(...)
 
 
local filter = {active = false}
local blocked = {[1] = true, [5] = true, [7] = true, [22] = true}

function filter:install()
    if self.installed then self.active = true; return end
    local ffi = require('ffi')
    assert(ffi.abi('32bit'), 'VClient018 filter requires the 32-bit client')
    local raw = client.create_interface('client.dll', 'VClient018')
    assert(raw ~= nil and tonumber(ffi.cast('uintptr_t', raw)) ~= 0, 'VClient018 unavailable')
    local interface = ffi.cast('uintptr_t**', raw)
    local original = interface[0]
    assert(original ~= nil and tonumber(ffi.cast('uintptr_t', original)) ~= 0, 'client vtable unavailable')

     
     
    local count = 0
    while count < 256 and original[count] ~= 0 do count = count + 1 end
    assert(count > 38 and count < 256, 'VClient018 vtable length unsupported')
    local replacement = ffi.new('uintptr_t[?]', count)
    for i = 0, count - 1 do replacement[i] = original[i] end
    local signature = 'bool(__thiscall*)(void*, int, int, int, const void*)'
    local dispatch = ffi.cast(signature, original[38])
    local callback = ffi.cast(signature, function(this, message_type, flags, size, data)
        if self.active and blocked[message_type] then return true end
        return dispatch(this, message_type, flags, size, data)
    end)
    replacement[38] = ffi.cast('uintptr_t', callback)
    self.ffi, self.interface, self.original, self.replacement, self.callback = ffi, interface, original, replacement, callback
    self.active = true
    interface[0] = replacement
    self.installed = true
end

function filter:uninstall()
    self.active = false
    if not self.installed then return end
    local ffi = self.ffi
    if ffi.cast('uintptr_t', self.interface[0]) ~= ffi.cast('uintptr_t', self.replacement) then
         
        error('VClient018 was hooked by another script; disable the other hook and reload', 0)
    end
    self.interface[0] = self.original
    self.installed = false
    self.callback:free()
    self.ffi, self.interface, self.original, self.replacement, self.callback = nil, nil, nil, nil, nil
end

function filter:sync(enabled)
    if enabled then self:install() else self:uninstall() end
end
function filter:shutdown() self:uninstall() end
return filter


end,

 
['misc_cvars'] = function(...)
 
local ffi, bit
local unlock = {
 _interface = nil,
 _iterator = nil,
 _saved = {},
 _active = false,
 _last_attempt = -2,
 _last_count = 0,
 _last_error = nil,
 _init = function(self)
  if self._iterator ~= nil then return true end
  local now = globals.realtime() or 0
  if now - self._last_attempt < 2 then return false end
  self._last_attempt = now
  local ok, result = pcall(function()
   if not pcall(ffi.typeof, "GOTH_CVAR_FACTORY_ITERATOR") then
    ffi.cdef[[
     typedef void* (__thiscall* GOTH_CVAR_FACTORY_ITERATOR)(void*);
     typedef void (__thiscall* GOTH_CVAR_ITER_SET_FIRST)(void*);
     typedef unsigned char (__thiscall* GOTH_CVAR_ITER_IS_VALID)(void*);
     typedef void (__thiscall* GOTH_CVAR_ITER_NEXT)(void*);
     typedef void* (__thiscall* GOTH_CVAR_ITER_GET)(void*);
    ]]
   end
   local interface = client.create_interface("vstdlib.dll", "VEngineCvar007")
   if interface == nil then error("ICvar interface unavailable") end
   local vtable = ffi.cast("void***", interface)[0]
   if vtable == nil or vtable[42] == nil then error("ICvar iterator entry unavailable") end
   local factory = ffi.cast("GOTH_CVAR_FACTORY_ITERATOR", vtable[42])
   local iterator = factory(interface)
   if iterator == nil then error("ICvar iterator creation failed") end
   self._interface = interface
   self._iterator = iterator
   return true
  end)
  if not ok then
   self._last_error = tostring(result)
   return false
  end
  self._last_error = nil
  return result == true
 end,
 _walk = function(self, callback)
  if not self._iterator then return false end
  local vtable = ffi.cast("void***", self._iterator)[0]
  if vtable == nil then return false end
  local set_first = ffi.cast("GOTH_CVAR_ITER_SET_FIRST", vtable[0])
  local is_valid = ffi.cast("GOTH_CVAR_ITER_IS_VALID", vtable[2])
  local next_item = ffi.cast("GOTH_CVAR_ITER_NEXT", vtable[1])
  local get_item = ffi.cast("GOTH_CVAR_ITER_GET", vtable[3])
  if set_first == nil or is_valid == nil or next_item == nil or get_item == nil then return false end
  set_first(self._iterator)
  local walked = 0
  while is_valid(self._iterator) ~= 0 and walked < 20000 do
   local item = get_item(self._iterator)
   if item ~= nil then callback(item) end
   next_item(self._iterator)
   walked = walked + 1
  end
  return true
 end,
 apply = function(self)
  if self._active then return end
  if not ffi or not bit then
   local ok1, lib1 = pcall(require, 'ffi')
   local ok2, lib2 = pcall(require, 'bit')
   if not ok1 or not ok2 then self._last_error='LuaJIT ffi/bit unavailable'; return end
   ffi, bit = lib1, lib2
  end
  if not self:_init() then return end
  local saved = {}
  local changed = 0
  local ok = pcall(function()
   local walked = self:_walk(function(item)
    local flags_ptr = ffi.cast("int32_t*", ffi.cast("uint8_t*", item) + 0x14)
    local flags = tonumber(flags_ptr[0])
    if flags ~= nil and bit.band(flags, 0x12) ~= 0 then
     saved[#saved + 1] = { ptr = flags_ptr, value = bit.band(flags, 0x12) }
     flags_ptr[0] = bit.band(flags, bit.bnot(0x12))
     changed = changed + 1
    end
   end)
   if not walked then error("ICvar enumeration failed") end
  end)
  if not ok then
   for index = #saved, 1, -1 do
    pcall(function()
     local current = tonumber(saved[index].ptr[0]) or 0
     saved[index].ptr[0] = bit.bor(bit.band(current, bit.bnot(0x12)), saved[index].value)
    end)
   end
   self._saved = {}
   self._active = false
   self._last_error = "Cvar flags could not be updated"
   return
  end
  self._saved = saved
  self._last_count = changed
  self._active = true
  self._last_error = nil
 end,
 restore = function(self)
  for index = #self._saved, 1, -1 do
   local item = self._saved[index]
   pcall(function()
    local current = tonumber(item.ptr[0]) or 0
    item.ptr[0] = bit.bor(bit.band(current, bit.bnot(0x12)), item.value)
   end)
  end
  self._saved = {}
  self._active = false
 end,
 sync = function(self)
  if ui.get(self.menu.misc_rage.refs.unlock_cvars) then
   self:apply()
   if self._last_error and self._last_error ~= self._reported_error then
    self.report('Unlock Hidden Cvars', self._last_error); self._reported_error=self._last_error
   elseif not self._last_error then self._reported_error=nil end
  elseif self._active or #self._saved > 0 then
   self:restore()
  end
 end,
 shutdown = function(self)
  self:restore()
 end
}
function unlock:init(menu, report) self.menu, self.report=menu,report end
return unlock


end,

 
['misc_discord'] = function(...)
 
local discord
do
  local named_pipes_ok, named_pipes = pcall(require, "gamesense/named_pipes")
  local OPCODE_HANDSHAKE, OPCODE_FRAME, OPCODE_CLOSE, OPCODE_PING, OPCODE_PONG = 0, 1, 2, 3, 4
  local DISCORD_CLIENT_ID = "1563196456163221640"

  local function pack_int32le(int)
    int = math.floor(int)
    return string.char(int % 256, math.floor(int / 256) % 256, math.floor(int / 65536) % 256, math.floor(int / 16777216) % 256)
  end
  local function unpack_int32le(str)
    local a,b,c,d = str:byte(1,4)
    if not d then return nil end
    return a + b*256 + c*65536 + d*16777216
  end
  local function encode_str(opcode, str)
    return pack_int32le(opcode) .. pack_int32le(#str) .. str
  end

  local function clean_mapname(name)
    name = tostring(name or ""):lower()
    name = name:gsub("^workshop/%d+/", "")
    name = name:gsub("%.bsp$", "")
    name = name:match("([^/\\]+)$") or name
    return name
  end

  local rpc = {
    pipe = nil,
    open = false,
    ready = false,
    last_activity = nil,
    last_update = 0,
    last_connect_try = 0,
    session_start = nil,
    last_signature = nil,
  }

  local function rpc_close()
    if rpc.pipe and rpc.pipe.close then
      pcall(function() rpc.pipe:close() end)
    end
    rpc.pipe, rpc.open, rpc.ready = nil, false, false
  end

  local function rpc_write(opcode, str)
    if not rpc.pipe then return false end
    local ok = pcall(function()
      rpc.pipe:write(encode_str(opcode, str))
    end)
    if not ok then
      rpc_close()
      return false
    end
    return true
  end

  local function rpc_read()
    if not rpc.pipe then return end
    local ok = pcall(function()
      for frame = 1, 32 do
        local header = rpc.pipe:read(8)
        if header == nil then break end
        if type(header) ~= "string" or #header ~= 8 then error("Invalid Discord RPC header", 0) end
        local opcode = unpack_int32le(header:sub(1, 4))
        local len = unpack_int32le(header:sub(5, 8))
        if len < 0 or len > 65536 then error("Invalid Discord RPC frame length", 0) end
        local raw = rpc.pipe:read(len)
        if type(raw) ~= "string" or #raw ~= len then error("Invalid Discord RPC payload", 0) end
        local parsed
        local data
        parsed, data = pcall(json.parse, raw)
        if not parsed then error(data, 0) end
        if type(data) ~= "table" then error("Invalid Discord RPC JSON", 0) end
        if opcode == OPCODE_CLOSE then
          rpc_close()
          break
        elseif opcode == OPCODE_PING then
          rpc_write(OPCODE_PONG, raw or "{}")
        elseif data.evt == "READY" then
          rpc.ready = true
        elseif data.cmd == "DISPATCH" and data.evt == "READY" then
          rpc.ready = true
        end
      end
    end)
    if not ok then rpc_close() end
  end

  local function rpc_connect()
    if not named_pipes_ok or not named_pipes then return false end
    if rpc.pipe and rpc.open then return true end
    rpc_close()
    local now = globals.realtime() or 0
    if now - (rpc.last_connect_try or 0) < 3 then return false end
    rpc.last_connect_try = now
    for i = 0, 9 do
      local ok, pipe = pcall(named_pipes.open_pipe, "\\\\?\\pipe\\discord-ipc-" .. i)
      if ok and pipe then
        rpc.pipe = pipe
        rpc.open = true
        rpc.ready = false
        rpc.last_signature = nil
        local payload = string.format('{"v":1,"client_id":"%s"}', DISCORD_CLIENT_ID)
        rpc_write(OPCODE_HANDSHAKE, payload)
        return true
      end
    end
    return false
  end

  local function rpc_set_activity(activity)
    if not rpc.ready then return end
    local payload = {
      cmd = "SET_ACTIVITY",
      args = {
        pid = 0,
        activity = activity,
      },
      nonce = string.format("%d-%d", globals.tickcount() or 0, math.floor((globals.realtime() or 0) * 1000) % 100000),
    }
    local encoded = nil
    pcall(function() encoded = json.stringify(payload) end)
    if encoded then
      local written = rpc_write(OPCODE_FRAME, encoded)
      if written then
        rpc.last_activity = activity
        return true
      end
    end
    return false
  end

  local function rpc_clear()
    if not rpc.ready then return end
    local payload = {
      cmd = "SET_ACTIVITY",
      args = { pid = 0, activity = json.null },
      nonce = string.format("clear-%d", globals.tickcount() or 0),
    }
    local encoded = nil
    pcall(function() encoded = json.stringify(payload) end)
    if not encoded then
      pcall(function()
        encoded = '{"cmd":"SET_ACTIVITY","args":{"pid":0,"activity":null},"nonce":"clear"}'
      end)
    end
    if encoded then rpc_write(OPCODE_FRAME, encoded) end
    rpc.last_activity = nil
    rpc.last_signature = nil
  end

  local function ensure_session_start()
     
     
    if type(rpc.session_start) == "number" and rpc.session_start > 1000000000 then
      return rpc.session_start
    end

    local start_time = nil
    if client and type(client.unix_time) == "function" then
      local ok, value = pcall(client.unix_time)
      if ok and type(value) == "number" and value > 1000000000 then
        start_time = value
      end
    end
    if not start_time and os and type(os.time) == "function" then
      local ok, value = pcall(os.time)
      if ok and type(value) == "number" and value > 1000000000 then
        start_time = value
      end
    end

    if start_time then
      rpc.session_start = math.floor(start_time)

    end
    return rpc.session_start
  end

  local function build_activity()
     
    ensure_session_start()

    local mapname = globals.mapname and globals.mapname() or nil
    local activity = {
      type = 0,
      name = "nyameeow.pink",
      details = "In main menu",
      assets = {
         
        large_image = "a_painterly_textured_anime_style_illustration_in",
        large_text = "nyameeow.pink",
      },
      instance = true,
    }
    if rpc.session_start ~= nil then
      activity.timestamps = { start = rpc.session_start }
    end

    if mapname and mapname ~= "" then
       
      activity.details = clean_mapname(mapname)

      local kills, deaths = 0, 0
      local lp = entity.get_local_player()
      local pr = entity.get_player_resource and entity.get_player_resource() or nil
      if lp and pr then
        kills = tonumber(entity.get_prop(pr, "m_iKills", lp)) or 0
        deaths = tonumber(entity.get_prop(pr, "m_iDeaths", lp)) or 0
      end
      local ratio
      if deaths <= 0 then
        ratio = kills > 0 and string.format("%.2f", kills) or "0.00"
      else
        ratio = string.format("%.2f", kills / deaths)
      end
      activity.state = string.format("K/D %d/%d (%s)", kills, deaths, ratio)
    end
    return activity
  end

  discord = {
    update = function(self)
      local enabled = false
      pcall(function()
        local options = ui.get(discord.menu.misc_rage.refs.utility_features) or {}
        for _, value in ipairs(options) do if value == "Discord RPC" then enabled = true; break end end
      end)
      if not enabled then
        if rpc.pipe then self:shutdown() end
        return
      end
      if not named_pipes_ok or not named_pipes then
        if not self.warned then self.warned=true; self.report("Discord RPC", "install gamesense/named_pipes") end
        return
      end
      if not rpc.open then
        rpc_connect()
      end
      rpc_read()
      if not rpc.ready then
        rpc_connect()
        rpc_read()
        return
      end
      local now = globals.realtime() or 0
      if now - (rpc.last_update or 0) < 1 then return end
      rpc.last_update = now
      local activity = build_activity()
      local signature = tostring(activity.name or "") .. "|" .. tostring(activity.details or "") .. "|" .. tostring(activity.state or "")
       
       
      if signature ~= rpc.last_signature then
        if rpc_set_activity(activity) then
          rpc.last_signature = signature
        end
      end
    end,
    shutdown = function(self)
      pcall(rpc_clear)
      rpc_close()
      rpc.last_activity = nil
    end,
  }
end
function discord:init(menu, report) self.menu, self.report = menu, report end
return discord


end,

 
['misc_events'] = function(...)
 
 
local events = {}
local Class = {ui = {menu = {}}, util = {}, misc = {}, render = {}}
local icons_ok, icons_lib = pcall(require, 'gamesense/icons')
if not icons_ok then icons_lib = nil end
local function control(ref)
    return {get=function(_, option)
        if option == nil then return ui.get(ref) end
        local values = ui.get(ref)
        if type(values) ~= 'table' then return false end
        for _, value in ipairs(values) do if value == option then return true end end
        return false
    end}
end
function Class.util.output_message(parts)
    for _, part in ipairs(parts) do
        if part.text and part.color then client.color_log(part.color[1], part.color[2], part.color[3], part.text .. "\0") end
    end
end

Class.util.format_log_prefix = function(self, raw, accent, white, first_color)
  raw = tostring(raw or "")
  local options = {
   custom_prefix = nil,
   use_prefix = true,
   use_brackets = true,
   use_color = true,
   bracket_type = "[]",
  }
  local first = first_color or accent
  local plain = {}
  for token in raw:gmatch("%S+") do
    if token == "nh" then
      options.use_color = false
    elseif token == "nb" then
      options.use_brackets = false
    elseif token == "np" then
      options.use_prefix = false
    elseif token:sub(1, 2) == "p=" then
      options.custom_prefix = token:sub(3)
    elseif token:sub(1, 2) == "b=" then
      local brackets = token:sub(3)
      if brackets ~= "" then
        options.bracket_type = brackets
      end
    else
      plain[#plain + 1] = token
    end
  end

  if options.custom_prefix == nil and #plain > 0 then
    options.custom_prefix = table.concat(plain, " ")
  end
  if options.custom_prefix == nil then
    options.custom_prefix = "nyameeow.pink"
  end
  if not options.use_prefix or options.custom_prefix == "" then
    return {}
  end

  local prefix = tostring(options.custom_prefix)
  local result = {}

  if options.use_brackets and options.bracket_type:sub(1, 1) ~= "" then
    result[#result + 1] = { text = options.bracket_type:sub(1, 1), color = white }
  end

  result[#result + 1] = {
    text = prefix,
    color = options.use_color and first or white
  }

  if options.use_brackets and options.bracket_type:sub(2, 2) ~= "" then
    result[#result + 1] = { text = options.bracket_type:sub(2, 2), color = white }
  end
  result[#result + 1] = { text = " ", color = white }
  return result
end

  Class.render.notifications = {
  config = {
    max_items = 5,
    lifetime = 3.0,
    corner_radius = 5,
    background_alpha = 175,
    text_flags = "",
    stack_gap = 4,
  },

  items = {},
  pos = {x = nil, y = nil},
  target_pos = {x = nil, y = nil},
  _clamp = function(self, value, min_value, max_value)
    value = tonumber(value) or min_value
    if value < min_value then return min_value end
    if value > max_value then return max_value end
    return value
  end,

  _smooth = function(self, current, target, speed)
    local dt = tonumber(globals.frametime()) or 0
    if dt <= 0 then dt = 1 / 60 end
    dt = math.min(dt, 0.05)
    local factor = 1 - math.exp(-(speed or 14) * dt)
    return current + (target - current) * factor
  end,

  _body_parts = function(self, item)
    local base_text = {240, 240, 240, 255}
    local accent = item.color or base_text
    local text = item.raw_text or ""
    local parts = {}
    local current_color = base_text
    local pos = 1

    while true do
      local marker_start, marker_end = text:find("/[vr]", pos)
      if not marker_start then
        local tail = text:sub(pos)
        if tail ~= "" then
          parts[#parts + 1] = {text = tail, color = current_color}
        end
        break
      end

      local chunk = text:sub(pos, marker_start - 1)
      if chunk ~= "" then
        parts[#parts + 1] = {text = chunk, color = current_color}
      end

      local marker = text:sub(marker_start, marker_end)
      current_color = marker == "/v" and accent or base_text
      pos = marker_end + 1
    end

    if #parts == 0 and text ~= "" then
      parts[1] = {text = text, color = base_text}
    end
    return parts
  end,

  _measure_parts = function(self, parts)
    local width, height = 0, 0
    local flags = self.config.text_flags
    for index = 1, #parts do
      local part = parts[index]
      if part.text and part.text ~= "" then
        local w, h = renderer.measure_text(flags, part.text)
        width = width + (w or 0)
        height = math.max(height, h or 0)
      end
    end
    return width, math.max(height, 11)
  end,

  _rounded = function(self, x, y, w, h, radius, r, g, b, a)
     
    if a <= 0 then return end
    x, y, w, h = math.floor(x + 0.5), math.floor(y + 0.5), math.floor(w + 0.5), math.floor(h + 0.5)
    radius = math.floor(self:_clamp(radius, 0, math.min(w, h) * 0.5) + 0.5)

    if radius <= 1 then
      renderer.rectangle(x, y, w, h, r, g, b, a)
      return
    end

    renderer.rectangle(x + radius, y + radius, w - radius * 2, h - radius * 2, r, g, b, a)
    renderer.rectangle(x + radius, y, w - radius * 2, radius, r, g, b, a)
    renderer.rectangle(x + radius, y + h - radius, w - radius * 2, radius, r, g, b, a)
    renderer.rectangle(x, y + radius, radius, h - radius * 2, r, g, b, a)
    renderer.rectangle(x + w - radius, y + radius, radius, h - radius * 2, r, g, b, a)
    renderer.circle(x + radius, y + radius, r, g, b, a, radius, 180, 0.25)
    renderer.circle(x + w - radius, y + radius, r, g, b, a, radius, 90, 0.25)
    renderer.circle(x + w - radius, y + h - radius, r, g, b, a, radius, 0, 0.25)
    renderer.circle(x + radius, y + h - radius, r, g, b, a, radius, 270, 0.25)
  end,

  _icon = function(self, x, y, r, g, b, a, notification_type)
    if (tonumber(a) or 0) <= 0 then return end
    local rr = math.max(0, math.min(255, math.floor(tonumber(r) or 255)))
    local gg = math.max(0, math.min(255, math.floor(tonumber(g) or 255)))
    local bb = math.max(0, math.min(255, math.floor(tonumber(b) or 255)))
    local alpha = math.max(0, math.min(255, math.floor(tonumber(a) or 255)))
    local icon_size = 12

    local kind = tostring(notification_type or "info"):lower():gsub("[%s%-]+", "_")
    local icon_specs = self._notification_icon_specs
    if not icon_specs then
       
      icon_specs = {
        hit = {"bolt", "outline"},
        miss = {"x-circle", "outline"},
        connection = {"sparkles", "outline"},
        antibrute = {"sparkles", "outline"},
        antibrute_reset = {"sparkles", "outline"},
        config_success = {"check", "outline"},
        config_error = {"x-mark", "outline"},
        info = {"sparkles", "outline"},
      }
      self._notification_icon_specs = icon_specs
    end

    local spec = icon_specs[kind]
    if not spec then return end
    local name, style = spec[1], spec[2]
    local textures = self._notification_icon_textures
    local requested = self._notification_icon_requested
    if not textures then textures = {}; self._notification_icon_textures = textures end
    if not requested then requested = {}; self._notification_icon_requested = requested end
    local key = name .. ":" .. style .. ":" .. tostring(icon_size)

    if not textures[key] and not requested[key] then
      requested[key] = true
      if icons_lib and icons_lib.hero and icons_lib.hero.get_texture then icons_lib.hero.get_texture(name, style, {255, 255, 255, 255}, icon_size, function(texture)
        if texture then textures[key] = texture end
      end) end
    end

    local icon = textures[key]
    local draw_x = math.floor(x - icon_size * 0.5 + 0.5)
    local draw_y = math.floor(y - icon_size * 0.5 + 0.5)
    if icon then
      renderer.texture(icon, draw_x, draw_y, icon_size, icon_size, rr, gg, bb, alpha)
      return
    end

     
  end,

  is_active = function(self)
    local active = false
    pcall(function()
      local logger = Class.ui.menu.misc_tab.event_logger
      active = logger and logger.enabled:get()
        and logger.triggers
        and logger.triggers.event_triggers:get("On Screen") == true or false
    end)
    if not active then
      pcall(function()
        local ab = Class.ui.menu.antiaim_tab.additional.fakelag.anti_bruteforce
        active = ab and ab.enabled:get()
          and ab.notify
          and ab.notify:get("On Screen") == true or false
      end)
    end
    return active
  end,

  push = function(self, text, notif_type, force)
    local notification_kind = tostring(notif_type or "info")
    if not force and not self:is_active() then return end

    local menu_bg = {0, 0, 0, 255}
     
    local menu_accent = Class.util.accent_color and Class.util.accent_color.first or {222, 206, 168, 255}
    local accent_col = {
      menu_accent[1] or 222,
      menu_accent[2] or 206,
      menu_accent[3] or 168,
      menu_accent[4] or 255,
    }
     
    local pure_red = {255, 0, 0, 255}
    if notification_kind == "antibrute_reset"
      or notification_kind == "miss"
      or notification_kind == "connection" or notification_kind == "config_error" then
      accent_col = pure_red
    end

    table.insert(self.items, 1, {
      time = globals.realtime(),
      raw_text = type(text) == "string" and text or tostring(text or ""),
      color = accent_col,
      bg_color = menu_bg,
      type = notif_type or "info",
      opacity = 0,
      y_offset = 4,
    })

    while #self.items > self.config.max_items do
      table.remove(self.items)
    end
  end,

  clear = function(self)
    self.items = {}
  end,

  render = function(self)
    local now = globals.realtime()
    local cfg = self.config
    local menu = Class.ui.menu.visuals_tab.other.notifications

    if menu then
      pcall(function()
        local life_raw = tonumber(menu.lifetime:get()) or 30
         
        cfg.lifetime = math.max(0.5, life_raw * 0.1)
        cfg.max_items = math.max(1, math.floor(tonumber(menu.max_items:get()) or cfg.max_items))
      end)
    end

    for index = #self.items, 1, -1 do
      local item = self.items[index]
      local age = now - item.time
      local target = age < cfg.lifetime and 1 or 0
      item.opacity = self:_smooth(item.opacity, target, target > item.opacity and 22 or 10)
      local entering = age < 0.45 and target > 0
      if entering then
        item.y_offset = self:_smooth(item.y_offset or 4, 0, 20)
      else
        item.y_offset = self:_smooth(item.y_offset or 0, 0, 20)
      end
      if age > cfg.lifetime + 0.9 and item.opacity < 0.01 then
        table.remove(self.items, index)
      end
    end

    if #self.items == 0 then return end

    local sw, sh = client.screen_size()
    sw, sh = tonumber(sw) or 0, tonumber(sh) or 0
    if sw < 64 or sh < 64 then return end
    local y_off = 80
    if menu then
      pcall(function() y_off = tonumber(menu.y_offset:get()) or 80 end)
    end
    y_off = self:_clamp(y_off, 0, sh)
    self.target_pos.x = math.floor(sw * 0.5)
    self.target_pos.y = math.floor(sh - y_off)
    local res_changed = self._last_sw ~= sw or self._last_sh ~= sh
    if not self.pos.x or not self.pos.y or res_changed then
      self.pos.x = self.target_pos.x
      self.pos.y = self.target_pos.y
      self._last_sw, self._last_sh = sw, sh
    else
      self.pos.x = self:_smooth(self.pos.x, self.target_pos.x, 18)
      self.pos.y = self:_smooth(self.pos.y, self.target_pos.y, 18)
    end

    local pad_left = 11
    local pad_right = 11
    local bottom = self.pos.y

    for index = 1, #self.items do
      local item = self.items[index]
      local body_parts = self:_body_parts(item)
      local body_w, body_h = self:_measure_parts(body_parts)
      local card_h = math.max(26, math.max(14, body_h) + 11)
      local card_w = math.max(pad_left + 24 + body_w + pad_right, 90)
      local target_y = bottom - card_h
      item.y = self:_smooth(item.y or target_y, target_y, 20)
      bottom = target_y - cfg.stack_gap

      local x = math.floor(self.pos.x - card_w * 0.5 + 0.5)
      local y = math.floor(item.y + (item.y_offset or 0) + 0.5)
      local radius = math.min(cfg.corner_radius, card_h * 0.5, card_w * 0.5)
      local opacity = self:_clamp(item.opacity, 0, 1)
      local bg = item.bg_color or {0, 0, 0, 255}
      local accent = item.color or {255, 255, 255, 255}
       
      local bg_a = math.floor(175 * opacity + 0.5)
      local fg_a = math.floor(255 * opacity + 0.5)

      if bg_a > 0 then
         
        local ol_a = math.floor(200 * opacity + 0.5)
        self:_rounded(x - 1, y - 1, card_w + 2, card_h + 2, radius + 1, 70, 70, 70, ol_a)
        self:_rounded(x, y, card_w, card_h, radius,
          bg[1] or 0, bg[2] or 0, bg[3] or 0, bg_a)
      end

      if fg_a > 0 then
        local center_y = math.floor(y + card_h * 0.5 + 0.5)
        local prefix_x = math.floor(x + pad_left + 0.5)
        local icon_size, icon_gap = 12, 5
        local separator_width, separator_height = 2, 14
        local icon_cx = prefix_x + icon_size * 0.5
        local icon_alpha = math.floor((accent[4] or 255) * opacity + 0.5)
        self:_icon(icon_cx, center_y, accent[1] or 255, accent[2] or 255,
          accent[3] or 255, icon_alpha, item.type)
        local separator_x = math.floor(prefix_x + icon_size + icon_gap + 0.5)
        local separator_y = math.floor(center_y - separator_height * 0.5 + 0.5)
        renderer.rectangle(separator_x, separator_y, separator_width, separator_height,
          240, 240, 240, icon_alpha)

        local text_x = prefix_x + icon_size + icon_gap * 2 + separator_width
        local text_y = math.floor(center_y - body_h * 0.5 + 0.5)
        for part_index = 1, #body_parts do
          local part = body_parts[part_index]
          local part_text = part.text or ""
          if part_text ~= "" then
            local c = part.color or {240, 240, 240, 255}
            local a = math.floor((c[4] or 255) * opacity + 0.5)
            renderer.text(math.floor(text_x + 0.5), text_y,
              c[1] or 240, c[2] or 240, c[3] or 240, a,
              cfg.text_flags, 0, part_text)
            text_x = text_x + (select(1, renderer.measure_text(cfg.text_flags, part_text)) or 0)
          end
        end
      end
    end
  end,
}

Class.misc.event_logger = {
 shots = {},
 hitgroups = {"generic", "head", "chest", "stomach", "left arm", "right arm", "left leg", "right leg", "neck", "?", "gear"},
 _get_color = function(self, field, fallback)
   fallback = fallback or {240, 240, 240}
   local element = nil
   pcall(function()
     element = Class.ui.menu.misc_tab.event_logger.color[field]
   end)
   if not element then return {fallback[1], fallback[2], fallback[3]} end
   local ok, r, g, b = pcall(element.get, element)
   if not ok then return {fallback[1], fallback[2], fallback[3]} end
   if type(r) == "table" then
     g, b = r[2] or r.g, r[3] or r.b
     r = r[1] or r.r
   end
   r, g, b = tonumber(r), tonumber(g), tonumber(b)
   if not r or not g or not b then return {fallback[1], fallback[2], fallback[3]} end
   return {
     math.max(0, math.min(255, math.floor(r + 0.5))),
     math.max(0, math.min(255, math.floor(g + 0.5))),
     math.max(0, math.min(255, math.floor(b + 0.5)))
   }
 end,
 _log_prefix = function(self, accent, white)
   local logger = Class.ui.menu.misc_tab.event_logger
   local raw = ""
   pcall(function() raw = logger.prefix:get() or "" end)

   return Class.util:format_log_prefix(raw, accent or white, white, accent or white)
 end,
 _emit = function(self, accent, white, parts)
   local message = self:_log_prefix(accent, white)
   for index = 1, #parts do
     message[#message + 1] = parts[index]
   end
   if #message > 0 then
     local last = message[#message]
     if last.text and type(last.text) == "string" and last.text:sub(-1) ~= string.char(10) then
       last.text = last.text .. string.char(10)
     end
   end
   Class.util.output_message(message)
 end,
 _reason = function(self, shot, e)
   local raw = e and e.reason or nil
   if shot and shot.handle_time and (globals.realtime() - shot.handle_time) >= 0.5 then
     return "event timeout"
   end

   local local_player = entity.get_local_player()
   local fired_hits = shot and tonumber(shot.total_hits)
   local current_hits = local_player and tonumber(entity.get_prop(local_player, "m_totalHitsOnServer"))
   if fired_hits ~= nil and current_hits ~= nil and current_hits > fired_hits then
     return "damage rejection"
   end

   if raw == "prediction error" then
     return "prediction error"
   end
   if raw == "unregistered shot" then
     return "unregistered shot"
   end
   if raw == "spread" then
     return "spread"
   end
   if raw == "death" then
     return "death"
   end
   if raw == "occlusion" then
     return "occlusion"
   end
   if raw == "?" or raw == nil or raw == "" then
     return "correction"
   end
   return tostring(raw)
 end,
 _get_shot = function(self, e)
   if not e or e.id == nil then return nil, nil end
   return self.shots[e.id], e.id
 end,
 _prune = function(self)
   local now = globals.realtime() or 0
   for id, shot in pairs(self.shots) do
     if not shot.handle_time or now - shot.handle_time > 2.0 then
       self.shots[id] = nil
     end
   end

 end,
 on_net_update_start = function(self)
   self:_prune()
 end,
 on_aim_fire = function(self, e)
   if not e or e.id == nil then return end
   local tick = globals.tickcount()
   self.shots[e.id] = {
     id = e.id,
     target = e.target,
     original = e,
     damage = tonumber(e.damage) or 0,
     hitchance = tonumber(e.hit_chance) or 0,
     hitbox = e.hitgroup,
     history = tick - (e.tick or tick),
     fire_tick = tick,
     total_hits = (entity.get_local_player() and tonumber(entity.get_prop(entity.get_local_player(), "m_totalHitsOnServer"))) or 0,
     handle_time = globals.realtime(),
   }
   self:_prune()
 end,
 on_aim_hit = function(self, e)
   local logger = Class.ui.menu.misc_tab.event_logger
   if not logger.enabled:get() or not logger.triggers.event_triggers:get("Aimbot") then return end
   local shot, id = self:_get_shot(e)
   if not shot then
     shot = {
       id = e and e.id,
       target = e and e.target,
       damage = tonumber(e and e.damage) or 0,
       hitchance = tonumber(e and e.hit_chance) or 0,
       hitbox = e and e.hitgroup,
       history = 0,
       total_hits = entity.get_local_player() and tonumber(entity.get_prop(entity.get_local_player(), "m_totalHitsOnServer")),
     }
   end
   local accent = self:_get_color("hit_purchase_color", {255, 255, 255})
   local white = {240, 240, 240}
   local target = e and e.target or shot.target
   local target_name = target and entity.get_player_name(target) or "?"
   local hitbox = self.hitgroups[(tonumber(e and e.hitgroup) or 0) + 1] or "?"
   local aimed_hitbox = self.hitgroups[(tonumber(shot.hitbox) or 0) + 1] or "?"
   local damage = tonumber(e and e.damage) or shot.damage or 0
   local hitchance = math.floor((shot.hitchance or e.hit_chance or 0) + 0.5)
   local bt = tonumber(shot.history) or 0
   local expected = tonumber(shot.damage) or 0
   local delay_ticks = 0
   pcall(function()
     local fire_tick = tonumber(shot.fire_tick)
     local current_tick = tonumber(globals.tickcount())
     if fire_tick and current_tick then
       delay_ticks = math.max(current_tick - fire_tick - 1, -2)
     end
   end)
   local delay = 0
   pcall(function()
     local tickinterval = tonumber(globals.tickinterval()) or 0
     delay = math.floor(delay_ticks * tickinterval * 1000 + (delay_ticks >= 0 and 0.5 or -0.5))
   end)
   local target_health = tonumber(e and e.health)
   if target_health == nil and target then
     target_health = tonumber(entity.get_prop(target, "m_iHealth"))
   end
   local killed = target_health ~= nil and target_health <= 0
   local hitbox_mismatch = aimed_hitbox ~= "?" and hitbox ~= aimed_hitbox
   local damage_mismatch = expected > 0 and expected ~= damage
   local parts
   if killed then
     parts = {
       { text = "Killed ", color = white },
       { text = target_name, color = accent },
       { text = " in ", color = white },
       { text = hitbox, color = accent },
     }
   else
     parts = {
       { text = "Hit ", color = white },
       { text = target_name, color = accent },
       { text = "'s ", color = white },
       { text = hitbox, color = accent },
     }
   end
   if hitbox_mismatch then
     parts[#parts + 1] = { text = " (expected hitbox: ", color = white }
     parts[#parts + 1] = { text = aimed_hitbox, color = accent }
     parts[#parts + 1] = { text = ")", color = white }
   end
   parts[#parts + 1] = { text = " for ", color = white }
   parts[#parts + 1] = { text = tostring(math.floor(damage + 0.5)), color = accent }
   if damage_mismatch then
     parts[#parts + 1] = { text = " (missmatched for: ", color = white }
     parts[#parts + 1] = { text = tostring(math.floor(expected + 0.5)), color = accent }
     parts[#parts + 1] = { text = ")", color = white }
   end
   parts[#parts + 1] = { text = " damage (", color = white }
   parts[#parts + 1] = { text = target_health ~= nil and tostring(math.max(0, math.floor(target_health + 0.5))) or "?", color = accent }
   parts[#parts + 1] = { text = " hp left) (bt: ", color = white }
   parts[#parts + 1] = { text = tostring(bt) .. "t", color = accent }
   parts[#parts + 1] = { text = " · hc: ", color = white }
   parts[#parts + 1] = { text = tostring(hitchance) .. "%", color = accent }
   parts[#parts + 1] = { text = ") (delay=", color = white }
   parts[#parts + 1] = { text = tostring(delay) .. "ms", color = accent }
   parts[#parts + 1] = { text = ")", color = white }
   self:_emit(accent, white, parts)

   if Class.misc.notifications_ui and Class.misc.notifications_ui:should_show("Hit") then
     local notif
     if killed then
       notif = string.format("/rKilled /v%s/r in /v%s/r for /v%d/r damage", target_name, hitbox, damage)
     else
       notif = string.format("/rHit /v%s/r's /v%s/r for /v%d/r damage", target_name, hitbox, damage)
     end
     Class.render.notifications:push(notif, "hit")
   end
   if id ~= nil then self.shots[id] = nil end
 end,
 on_aim_miss = function(self, e)
   local logger = Class.ui.menu.misc_tab.event_logger
   if not logger.enabled:get() or not logger.triggers.event_triggers:get("Aimbot") then return end
   local shot, id = self:_get_shot(e)
   if not shot then
     shot = {
       id = e and e.id,
       target = e and e.target,
       damage = 0,
       hitchance = tonumber(e and e.hit_chance) or 0,
       hitbox = e and e.hitgroup,
       history = 0,
     }
   end
   local accent = self:_get_color("miss_connection_color", {225, 80, 80})
   local white = {240, 240, 240}
   local target = e and e.target or shot.target
   local target_name = target and entity.get_player_name(target) or "?"
   local hitbox = self.hitgroups[(tonumber(e and e.hitgroup) or 0) + 1] or "?"
   local aimed_hitbox = self.hitgroups[(tonumber(shot.hitbox) or 0) + 1] or "?"
   local reason = self:_reason(shot, e)
   local backtrack = tonumber(shot.history) or 0
   local hitchance = math.floor((shot.hitchance or e.hit_chance or 0) + 0.5)
   local pred = tonumber(shot.damage) or 0
   local delay_ticks = 0
   pcall(function()
     local fire_tick = tonumber(shot.fire_tick)
     local current_tick = tonumber(globals.tickcount())
     if fire_tick and current_tick then
       delay_ticks = math.max(current_tick - fire_tick - 1, -2)
     end
   end)
   local delay = 0
   pcall(function()
     local tickinterval = tonumber(globals.tickinterval()) or 0
     delay = math.floor(delay_ticks * tickinterval * 1000 + (delay_ticks >= 0 and 0.5 or -0.5))
   end)
   local parts = {
     { text = "Missed in ", color = white },
     { text = target_name, color = accent },
     { text = "'s ", color = white },
     { text = hitbox, color = accent },
     { text = " due to ", color = white },
     { text = reason, color = accent },
   }
   if pred > 0 then
     parts[#parts + 1] = { text = " (dmg: ", color = white }
     parts[#parts + 1] = { text = tostring(math.floor(pred + 0.5)), color = accent }
     parts[#parts + 1] = { text = " · hitbox: ", color = white }
     parts[#parts + 1] = { text = aimed_hitbox, color = accent }
     parts[#parts + 1] = { text = ") (bt: ", color = white }
   else
     parts[#parts + 1] = { text = " (bt: ", color = white }
   end
   parts[#parts + 1] = { text = tostring(backtrack) .. "t", color = accent }
   parts[#parts + 1] = { text = " · hc: ", color = white }
   parts[#parts + 1] = { text = tostring(hitchance) .. "%", color = accent }
   parts[#parts + 1] = { text = ") (delay=", color = white }
   parts[#parts + 1] = { text = tostring(delay) .. "ms", color = accent }
   parts[#parts + 1] = { text = ")", color = white }
   self:_emit(accent, white, parts)

   if Class.misc.notifications_ui and Class.misc.notifications_ui:should_show("Miss") then
     Class.render.notifications:push(
       string.format("/rMissed in /v%s/r's /v%s/r due to /v%s/r", target_name, hitbox, reason),
       "miss"
     )
   end
   if id ~= nil then self.shots[id] = nil end
 end,
 on_player_hurt = function(self, e)
   local logger = Class.ui.menu.misc_tab.event_logger
   if not logger.enabled:get() or not logger.triggers.event_triggers:get("Aimbot") then return end
   local local_player = entity.get_local_player()
   if not local_player then return end
   local attacker = client.userid_to_entindex(e.attacker)
   local victim = client.userid_to_entindex(e.userid)
   if attacker ~= local_player or victim == local_player then return end
   local weapon = tostring(e.weapon or ""):lower():gsub("^weapon_", "")
   local verb
   if weapon == "inferno" or weapon == "molotov" or weapon == "incgrenade" then
     verb = "Burned"
   elseif weapon == "hegrenade" then
     verb = "Naded"
   elseif weapon:find("knife", 1, true) or weapon == "bayonet" then
     verb = "Knifed"
   end
   if not verb then return end
   local accent = self:_get_color("hit_purchase_color", {255, 255, 255})
   local white = {240, 240, 240}
   local target_name = entity.get_player_name(victim) or "?"
   local damage = math.floor(tonumber(e.dmg_health) or 0)
   local remaining = math.max(0, math.floor(tonumber(e.health) or 0))
   self:_emit(accent, white, {
     { text = verb .. " ", color = white },
     { text = target_name, color = accent },
     { text = " for ", color = white },
     { text = tostring(damage), color = accent },
     { text = " damage (", color = white },
     { text = tostring(remaining), color = accent },
     { text = " health remaining)", color = white },
   })
 end,
 on_item_purchase = function(self, e)
   local logger = Class.ui.menu.misc_tab.event_logger
   if not logger.enabled:get() or not logger.triggers.event_triggers:get("Purchase") then return end
   local purchaser = client.userid_to_entindex(e.userid)
   if not purchaser or purchaser == 0 or purchaser == entity.get_local_player() then return end
   local target_name = entity.get_player_name(purchaser)
   if not target_name then return end
   local accent = self:_get_color("hit_purchase_color", {255, 255, 255})
   local white = {240, 240, 240}
   local weapon_name = e.weapon and e.weapon:gsub("^%l", string.lower) or "unknown"
   self:_emit(accent, white, {
     { text = target_name, color = accent },
     { text = " Bought ", color = white },
     { text = weapon_name, color = accent },
   })
 end,
}

function events:init(menu, text)
    self.menu = menu
    self.menu, self.text = menu, text
    local r, n = menu.misc_rage.refs, menu.visuals.refs
    Class.ui.menu.misc_tab = {event_logger={enabled=control(r.event), prefix=control(r.event_prefix),
        triggers={event_triggers=control(r.event_triggers)}, color={hit_purchase_color=control(r.event_hit_color),miss_connection_color=control(r.event_miss_color)}}}
    Class.ui.menu.visuals_tab = {other={notifications={lifetime=control(n.lifetime),max_items=control(n.max_items),y_offset=control(n.y_offset)}}}
    Class.misc.notifications_ui = {should_show=function()
        return ui.get(r.event) and control(r.event_triggers):get('On Screen')
    end}
end
function events:output_prefix_text()
    local r = self.menu.misc_rage.refs
    local prefix = ui.get(r.event) and (ui.get(r.event_prefix) or '') or 'nb'
    local parts = Class.util:format_log_prefix(prefix, {255,255,255}, {255,255,255}, {255,255,255})
    local values = {}
    for _, part in ipairs(parts) do values[#values + 1] = tostring(part.text or '') end
    return table.concat(values)
end
function events:run(name, ...)
    local logger = Class.misc.event_logger
    local fn = logger['on_' .. name]
    if fn then fn(logger, ...) end
end
 
 
function events:notify(text, kind)
    Class.render.notifications:push(text, kind, true)
end
function events:emit_parts(accent, white, parts)
    Class.misc.event_logger:_emit(accent, white, parts)
end
function events:paint_ui()
    local r,g,b,a = self.text.menu_color()
    Class.util.accent_color = {first={r,g,b,a}}
    Class.render.notifications:render()
end
function events:connection(title, detail)
    local r = self.menu.misc_rage.refs
    if not ui.get(r.event) or not control(r.event_triggers):get('Connection problems') then return end
    local red,green,blue = ui.get(r.event_miss_color)
    local accent = {red or 255,green or 0,blue or 0}
    Class.misc.event_logger:_emit(accent, {240,240,240}, {
        {text=title .. ' ',color={240,240,240}}, {text=detail,color=accent}})
    if control(r.event_triggers):get('On Screen') then
        Class.render.notifications:push('/r' .. title .. ' /v' .. detail .. '/r', 'connection')
    end
end
function events:test_notification()
    Class.render.notifications:push('/rTest /vnotification/r', 'info')
end
function events:print_guide()
    local chat = require('gamesense/chat')
    local me = entity.get_local_player()
    assert(me and chat and type(chat.print_player)=='function', 'open a game and install gamesense/chat')
    for _, line in ipairs({'[nyameeow.pink] EVENT LOGGER GUIDE', 'p=TEXT - custom prefix', 'nh - disable prefix color',
        'b=[] - custom brackets', 'nb - remove brackets', 'np - disable prefix',
        'Plain text can also be used as a prefix.', 'Commands are separated by spaces; b=XY sets brackets.'}) do
        chat.print_player(me, line)
    end
end
function events:reset()
    Class.misc.event_logger.shots = {}
    Class.render.notifications:clear()
end
return events


end,

 
['misc_f12'] = function(...)
 
local voice = {generation = 0}
local MAX_FILE, MAX_DURATION = 8 * 1024 * 1024, 20
local function has(ref, name)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, value in ipairs(values) do if value == name then return true end end
    return false
end
local function le(s, i, count)
    if i + count - 1 > #s then return nil end
    local n = 0
    for j = count - 1, 0, -1 do n = n * 256 + s:byte(i+j) end
    return n
end
local function prepare_wav(wav)
    if type(wav) ~= 'string' or #wav < 44 or #wav > MAX_FILE or wav:sub(1,4) ~= 'RIFF' or wav:sub(9,12) ~= 'WAVE' then return nil end
    local riff_size = le(wav, 5, 4)
    if not riff_size or riff_size + 8 > #wav then return nil end
    local limit, at, fmt, length, data_at = riff_size + 8, 13, nil, nil, nil
    while at + 7 <= limit do
        local tag, size = wav:sub(at, at+3), le(wav, at+4, 4)
        local start = at + 8
        if not size or start + size - 1 > limit then return nil end
        if tag == 'fmt ' then
            if size < 16 then return nil end
            fmt = {format=le(wav,start,2),channels=le(wav,start+2,2),rate=le(wav,start+4,4),
                byte_rate=le(wav,start+8,4),align=le(wav,start+12,2),bits=le(wav,start+14,2)}
        elseif tag == 'data' then
            if length then return nil end
            length, data_at = size, start
        end
        at = start + size + size % 2
    end
    if not fmt or not length or fmt.format ~= 1 or (fmt.channels ~= 1 and fmt.channels ~= 2) or fmt.bits ~= 16
        or not fmt.rate or fmt.rate < 8000 or fmt.rate > 96000
        or fmt.align ~= fmt.channels * 2 or fmt.byte_rate ~= fmt.rate * fmt.align
        or length % fmt.align ~= 0 then return nil end
    local frames = length / fmt.align
    local seconds = frames / fmt.rate
    if seconds < 0.05 or seconds > MAX_DURATION then return nil end
    local target_rate = 22050
    local function put(n, count)
        local bytes = {}
        for i = 1, count do bytes[i] = string.char(n % 256); n = math.floor(n / 256) end
        return table.concat(bytes)
    end
    local data
    if fmt.channels == 1 and fmt.rate == target_rate then
        data = wav:sub(data_at, data_at + length - 1)
    else
         
        local function sample(frame)
            local pos = data_at + frame * fmt.align
            local a, b = wav:byte(pos, pos + 1)
            local left = a + b * 256
            if left >= 32768 then left = left - 65536 end
            if fmt.channels == 1 then return left end
            a, b = wav:byte(pos + 2, pos + 3)
            local right = a + b * 256
            if right >= 32768 then right = right - 65536 end
            return (left + right) / 2
        end
        local output, n = {}, math.floor(frames * target_rate / fmt.rate + 0.5)
        for i = 0, n - 1 do
            local position = i * fmt.rate / target_rate
            local index = math.floor(position)
            if index >= frames then index = frames - 1 end
            local next_index = math.min(index + 1, frames - 1)
            local first = sample(index)
            local v = first + (sample(next_index) - first) * (position - index)
            v = math.max(-32768, math.min(32767, math.floor(v + 0.5)))
            if v < 0 then v = v + 65536 end
            output[i+1] = string.char(v % 256, math.floor(v / 256))
        end
        data = table.concat(output)
    end
    local output_length = #data
    local header = 'RIFF' .. put(36 + output_length, 4) .. 'WAVEfmt ' .. put(16, 4)
        .. put(1, 2) .. put(1, 2) .. put(target_rate, 4) .. put(target_rate * 2, 4)
        .. put(2, 2) .. put(16, 2) .. 'data' .. put(output_length, 4)
    return output_length / (target_rate * 2), header .. data
end
local event_keys = {Kill='f12_kill', Miss='f12_miss'}
local function option_index(options, name)
    for i, value in ipairs(options) do if value == name then return i - 1 end end
    return 0
end
function voice:sync_selection()
    local r = self.menu.misc_rage.refs
    local event = ui.get(r.f12_event_edit)
    local desired = self.saved_choices[event_keys[event]] or 'Off'
    local previous = self.updating_choices
    self.updating_choices = true
    local ok, err = pcall(ui.set, r.f12_file, option_index(self.options, desired))
    self.updating_choices = previous
    if not ok then self.report('F12 Sound selection', err) end
end
function voice:apply_choices(choices)
    local clean = {}
    for _, key in ipairs({'f12_kill', 'f12_miss'}) do
        local value = choices[key]
        if value == 'Off' or (type(value) == 'string' and #value <= 240 and not value:find('[%c/\\:]')
            and not value:find('..', 1, true) and value:lower():sub(-4) == '.wav') then clean[key] = value end
    end
    self.saved_choices = clean
    self:sync_selection()
end
function voice:init(menu, report, scanner, enemy_misses)
    self.menu, self.report, self.scanner, self.enemy_misses = menu, report, scanner, enemy_misses
    self.enemy_miss_count = self.enemy_misses and tonumber(self.enemy_misses.count) or 0
    self.stopping, self.playing, self.next_scan, self.file_signature = false, nil, 0, nil
    self.options, self.available, self.saved_choices = {'Off'}, {Off=true}, {}
    local r = menu.misc_rage.refs
    ui.set_callback(r.f12_event_edit, function() self:sync_selection() end)
    ui.set_callback(r.f12_file, function()
        if self.updating_choices then return end
        local key = event_keys[ui.get(r.f12_event_edit)]
        local selected = self.options[(tonumber(ui.get(r.f12_file)) or 0) + 1]
        if key and selected then
            self.saved_choices[key] = selected
        end
    end)
     
     
    self.enabled_last, self.log_scan = self:enabled(), false
end
function voice:refresh_files()
    local now = globals.realtime()
    if now < self.next_scan then return end
    self.next_scan = now + 2
    local ok, names = pcall(self.scanner.list, self.scanner)
    if not ok then
        if self.scan_error ~= tostring(names) then self.report('F12 Sound file list', names) end
        self.scan_error = tostring(names)
        return
    end
    self.scan_error = nil
    local options, exists = {'Off'}, {Off=true}
    for _, name in ipairs(names) do if not exists[name] then options[#options+1]=name; exists[name]=true end end
    local signature = table.concat(options, '\0')
    if signature ~= self.file_signature then
        local previous = self.updating_choices
        self.updating_choices = true
        local r = self.menu.misc_rage.refs
        local updated, err = pcall(function()
            local function update() ui.update(r.f12_file, options) end
            if self.menu.tab and type(self.menu.tab.with_listbox_width_preserved)=='function' then
                self.menu.tab:with_listbox_width_preserved(r.f12_file, update)
            else update() end
            local desired = self.saved_choices[event_keys[ui.get(r.f12_event_edit)]] or 'Off'
            ui.set(r.f12_file, option_index(options, desired))
        end)
        self.updating_choices = previous
        if not updated then
            if self.update_error ~= tostring(err) then self.report('F12 Sound list update', err) end
            self.update_error = tostring(err)
            return
        end
        self.update_error = nil
        self.options, self.available, self.file_signature = options, exists, signature
    end
    if self.log_scan then
        self.log_scan = false
        self:log_files(#names)
    end
end
function voice:stop()
    local state = self.playing
    self.generation = self.generation + 1
    if not state then return true end
    local errors = {}
    local function attempt(label, fn)
        local ok, err = pcall(fn)
        if not ok then errors[#errors+1] = label..': '..tostring(err); return false end
        return true
    end
    if state.started and attempt('voice stop', function() client.exec('-voicerecord') end) then
        state.started = false
    end
    attempt('voice_inputfromfile restore', function() cvar.voice_inputfromfile:set_int(state.input) end)
    attempt('voice_loopback restore', function() cvar.voice_loopback:set_int(state.loopback) end)
    if not state.file_restored then
        local restored = attempt('voice_input.wav restore', function()
            if state.previous == nil then return true end
            local current = readfile('voice_input.wav')
            if current == state.previous then return true end
            assert(not state.write_complete or current == state.sample, 'file changed externally; not overwritten')
            writefile('voice_input.wav', state.previous)
            assert(readfile('voice_input.wav') == state.previous, 'write verification failed')
            return true
        end)
        if restored then state.file_restored = true end
    end
     
    if #errors > 0 then self.report('F12 Sound', table.concat(errors, '; ')); return false end
    self.playing = nil
    return true
end
function voice:enabled()
    return not self.stopping and has(self.menu.misc_rage.refs.utility_features, 'F12 Sound')
end
function voice:log_files(count)
    local accent, white = {140, 110, 115, 255}, {240, 240, 240, 255}
    local events = self.menu and self.menu.misc_events
    if events and events.text and type(events.text.menu_color) == 'function' then
        local r, g, b = events.text.menu_color()
        accent = {tonumber(r) or 140, tonumber(g) or 110, tonumber(b) or 115, 255}
    end
    local folder = self.scanner.api and self.scanner.api.folder or 'afterglow/sounds'
    if type(client.color_log) == 'function' then
        client.color_log(white[1], white[2], white[3], '[nyameeow.pink] F12 Sound search: \0')
        client.color_log(accent[1], accent[2], accent[3], folder .. '\0')
        client.color_log(white[1], white[2], white[3], '\n[nyameeow.pink] F12 Sound: ' .. tostring(count) .. ' WAV files\n\0')
    elseif type(client.log) == 'function' then
        client.log('[nyameeow.pink] F12 Sound search: ' .. folder .. '\n[nyameeow.pink] F12 Sound: ' .. tostring(count) .. ' WAV files')
    end
end
function voice:tick()
    local enabled = self:enabled()
    if enabled and not self.enabled_last then
        self.log_scan, self.next_scan = true, 0
    end
    self.enabled_last = enabled
    if self.playing then self:stop() end
    if enabled then self:refresh_files() end
    if self.enemy_misses then
        local count = tonumber(self.enemy_misses.count) or 0
        if enabled and count > self.enemy_miss_count then self:play('Miss') end
        self.enemy_miss_count = count
    end
end
function voice:play(event_name)
    local r = self.menu.misc_rage.refs
    if not self:enabled() or not has(r.f12_events, event_name) or self.playing then return end
    local key = event_keys[event_name]
    local filename = tostring(key and self.saved_choices[key] or ''):gsub('^%s+', ''):gsub('%s+$', '')
    if filename == '' or filename == 'Off' or not self.available[filename] then return end
    if #filename > 240 or filename:find('[%c/\\:]') or filename:find('..',1,true) or filename:lower():sub(-4) ~= '.wav' then error('Invalid WAV filename') end
    local wav = self.scanner:read(filename)
    local cache = self.wav_cache
    local seconds, canonical_wav
    if cache and cache.name == filename and cache.original == wav then
        seconds, canonical_wav = cache.seconds, cache.converted
    else
        seconds, canonical_wav = prepare_wav(wav)
        assert(seconds, 'Unsupported WAV: use 16-bit PCM mono/stereo, 8–96 kHz, 0.05–20 s in afterglow/sounds/' .. filename)
        self.wav_cache = {name=filename, original=wav, seconds=seconds, converted=canonical_wav}
    end
    wav = canonical_wav
    assert(cvar.voice_inputfromfile and cvar.voice_loopback, 'voice input cvars unavailable')
    local input, loopback = cvar.voice_inputfromfile:get_int(), cvar.voice_loopback:get_int()
    assert(input ~= 1, 'voice input from file is already in use; sound was not started')
    local previous = readfile('voice_input.wav')
    assert(previous == nil or (type(previous)=='string' and #previous <= MAX_FILE), 'cannot back up voice_input.wav (file too large)')
    local state = {input=input, loopback=loopback, previous=previous, sample=wav, started=false, write_complete=false}
    self.playing = state
    local ok, err = pcall(function()
        writefile('voice_input.wav', wav)
        assert(readfile('voice_input.wav') == wav, 'could not write voice_input.wav')
        state.write_complete = true
        cvar.voice_loopback:set_int(ui.get(r.f12_loopback) and 1 or 0)
        cvar.voice_inputfromfile:set_int(1)
        state.started = true
        client.exec('+voicerecord')
        self.generation = self.generation + 1
        local generation = self.generation
        client.delay_call(seconds, function() if not self.stopping and self.generation == generation then self:stop() end end)
    end)
    if not ok then self:stop(); error(err, 0) end
end
function voice:event(name, e)
    if name ~= 'player_death' or not e then return end
    local me = entity.get_local_player()
    if not me then return end
    local victim = e.userid and client.userid_to_entindex(e.userid)
    local attacker = e.attacker and client.userid_to_entindex(e.attacker)
    if attacker == me and victim and victim ~= me and entity.is_enemy(victim) then self:play('Kill') end
end
function voice:shutdown() self.stopping = true; self:stop() end
return voice


end,

 
['misc_file_list'] = function(...)
 
 
 
local files = {}
local PATH_ID = 'AFTERGLOW_F12_SOUNDS_ROOT'
local MAX_FILE = 8 * 1024 * 1024
local function allowed(name)
    return type(name)=='string' and #name > 4 and #name <= 240 and not name:find('[%c/\\:]')
        and not name:find('..',1,true) and name:lower():sub(-4)=='.wav'
end
local function iface(ffi, module, name, slots)
    local raw = client.create_interface(module, name)
    assert(raw ~= nil, name..' unavailable')
    local ptr = ffi.cast('void***', raw)
    assert(ptr ~= nil and ptr[0] ~= nil, name..' vtable unavailable')
    for _, index in ipairs(slots) do assert(ptr[0][index] ~= nil, name..' method '..index..' unavailable') end
    return ptr, ptr[0]
end
function files:setup()
    if self.api then return end
    local ok, ffi = pcall(require, 'ffi')
    assert(ok and ffi, 'LuaJIT ffi unavailable')
    local fs, f = iface(ffi, 'filesystem_stdio.dll', 'VFileSystem017', {11,12,22,33,34,35,36})
    local base, b = iface(ffi, 'filesystem_stdio.dll', 'VBaseFileSystem011', {0,2,3,7,21})
    local engine, e = iface(ffi, 'engine.dll', 'VEngineClient014', {36})
    local game_dir_ptr = ffi.cast('const char*(__thiscall*)(void*)',e[36])(engine)
    assert(game_dir_ptr ~= nil, 'game directory unavailable')
    local game_dir = ffi.string(game_dir_ptr):gsub('/', '\\'):gsub('\\+$','')
    local last = game_dir:match('([^\\]+)$') or ''
    local root = last:lower() == 'csgo' and game_dir:match('^(.*)\\[^\\]+$') or game_dir
    assert(root and (root:match('^%a:\\') or root:match('^\\\\')), 'game directory is not an absolute path: '..game_dir)
    self.api = {
        fs=fs, base=base, root=root, game_dir=game_dir, folder=root..'\\afterglow\\sounds',
        add=ffi.cast('void(__thiscall*)(void*, const char*, const char*, int)',f[11]),
        remove=ffi.cast('bool(__thiscall*)(void*, const char*, const char*)',f[12]),
        mkdir=ffi.cast('void(__thiscall*)(void*, const char*, const char*)',f[22]),
        next=ffi.cast('const char*(__thiscall*)(void*, int)',f[33]),
        is_directory=ffi.cast('bool(__thiscall*)(void*, int)',f[34]),
        close_find=ffi.cast('void(__thiscall*)(void*, int)',f[35]),
        first=ffi.cast('const char*(__thiscall*)(void*, const char*, const char*, int*)',f[36]),
        read=ffi.cast('int(__thiscall*)(void*, void*, int, void*)',b[0]),
        open=ffi.cast('void*(__thiscall*)(void*, const char*, const char*, const char*)',b[2]),
        close_file=ffi.cast('void(__thiscall*)(void*, void*)',b[3]),
        size=ffi.cast('unsigned int(__thiscall*)(void*, void*)',b[7]),
        is_path_directory=ffi.cast('bool(__thiscall*)(void*, const char*, const char*)',b[21]),
    }
    self.ffi = ffi
end
function files:ensure_folders()
    self:setup()
    if self.folders_prepared then return end
    local api = self.api
    self:with_path(api.root, function(a)
        a.mkdir(a.fs, 'afterglow', PATH_ID)
        a.mkdir(a.fs, 'afterglow\\sounds', PATH_ID)
        assert(a.is_path_directory(a.base, 'afterglow', PATH_ID), 'Could not create afterglow folder')
        assert(a.is_path_directory(a.base, 'afterglow\\sounds', PATH_ID), 'Could not create afterglow/sounds folder')
    end)
    self.folders_prepared = true
end
function files:with_path(path,fn)
    self:setup()
    local a=self.api
    a.add(a.fs,path,PATH_ID,0)
    local ok, result = pcall(fn,a,self.ffi)
    local remove_ok, removed = pcall(a.remove,a.fs,path,PATH_ID)
    if not ok then error(result,0) end
    if not remove_ok then error(removed,0) end
    if removed ~= true then error('Could not remove search path '..path,0) end
    return result
end
function files:list()
    self:setup()
    local api=self.api
    self:ensure_folders()
    local results=self:with_path(api.folder,function(a,ffi)
        local handle=ffi.new('int[1]',-1)
        local current=a.first(a.fs,'*',PATH_ID,handle)
        if current==nil then return {} end
        local results, inspected={},0
        local ok, err=pcall(function()
            while current~=nil and inspected<2000 do
                inspected=inspected+1
                local name=ffi.string(current)
                if not a.is_directory(a.fs,handle[0]) and allowed(name) then results[#results+1]=name end
                if inspected<2000 then current=a.next(a.fs,handle[0]) end
            end
        end)
        a.close_find(a.fs,handle[0])
        if not ok then error(err,0) end
        table.sort(results,function(x,y)return x:lower()<y:lower() end)
        return results
    end)
    return results
end
function files:read(name)
    assert(allowed(name),'Invalid WAV filename')
    self:setup()
    self:ensure_folders()
    return self:with_path(self.api.folder,function(a,ffi)
        local handle=a.open(a.base,name,'rb',PATH_ID)
        assert(handle~=nil,'Could not open afterglow/sounds/'..name)
        local ok, result=pcall(function()
            local size=tonumber(a.size(a.base,handle))
            assert(size and size>0 and size<=MAX_FILE,'WAV is empty or larger than 8 MB')
            local buf=ffi.new('char[?]',size)
            assert(tonumber(a.read(a.base,buf,size,handle))==size,'Could not read the complete WAV')
            return ffi.string(buf,size)
        end)
        a.close_file(a.base,handle)
        if not ok then error(result,0) end
        return result
    end)
end
return files


end,

 
['misc_network'] = function(...)
 
local network = {last_ping=nil, high_ping=false, high_loss=false, spike_time=0, next_check=0}
local function has(ref, value)
    local values = ui.get(ref)
    if type(values) ~= 'table' then return false end
    for _, v in ipairs(values) do if v == value then return true end end
    return false
end
function network:init(menu, events, report) self.menu,self.events,self.report=menu,events,report end
function network:read()
    if not self.channel then
        local ok, ffi = pcall(require, 'ffi')
        assert(ok and ffi, 'LuaJIT ffi unavailable')
        local raw = client.create_interface('engine.dll','VEngineClient014')
        assert(raw ~= nil and tonumber(ffi.cast('uintptr_t',raw)) ~= 0, 'VEngineClient014 unavailable')
        local ptr = ffi.cast('void***',raw)
        assert(ptr[0] ~= nil and ptr[0][78] ~= nil, 'GetNetChannelInfo unavailable')
        self.channel = {ffi=ffi, engine=ptr, get=ffi.cast('void*(__thiscall*)(void*)',ptr[0][78])}
    end
    local c, ffi = self.channel, self.channel.ffi
    local raw = c.get(c.engine)
    if raw == nil then return nil end
    local ptr = ffi.cast('void***',raw)
    if ptr[0] == nil or ptr[0][6] == nil or ptr[0][10] == nil or ptr[0][11] == nil then return nil end
    local loop = ffi.cast('bool(__thiscall*)(void*)',ptr[0][6])(ptr)
    local ping = ffi.cast('float(__thiscall*)(void*, int)',ptr[0][10])(ptr,1) * 1000
    local loss = ffi.cast('float(__thiscall*)(void*, int)',ptr[0][11])(ptr,1) * 100
    local resource, me = entity.get_player_resource(), entity.get_local_player()
    local score = resource and me and entity.get_prop(resource,'m_iPing',me)
    if tonumber(score) and tonumber(score)>0 then ping=tonumber(score) end
    return {loopback=loop,ping=ping,loss=loss}
end
function network:reset() self.high_ping=false;self.high_loss=false;self.last_ping=nil;self.spike_time=0 end
function network:update()
    local r=self.menu.misc_rage.refs
    if not ui.get(r.event) or not has(r.event_triggers,'Connection problems') then self:reset();return end
    local now=globals.realtime()
    if now < self.next_check then return end
    self.next_check=now+0.5
    if not entity.get_local_player() then self:reset();return end
    local ok,data=pcall(self.read,self)
    if not ok then
        if self.last_error~=tostring(data) then self.report('Connection problems',data) end
        self.last_error=tostring(data);return
    end
    self.last_error=nil
    if not data or data.loopback then return end
    local ping,loss=math.max(0,tonumber(data.ping) or 0),math.max(0,tonumber(data.loss) or 0)
    if ping<=0 then local ok_latency,value=pcall(client.latency); if ok_latency and type(value)=='number' then ping=math.max(0,value*1000) end end
    if ping<=0 then self.last_ping=nil;return end
    if ping>=120 and not self.high_ping then self.events:connection('High ping',string.format('%d ms',math.floor(ping+0.5)));self.high_ping=true
    elseif ping<100 then self.high_ping=false end
    if loss>=5 and not self.high_loss then self.events:connection('Packet loss',string.format('%.1f%%',loss));self.high_loss=true
    elseif loss<3 then self.high_loss=false end
    if self.last_ping and math.abs(ping-self.last_ping)>=35 and now>=self.spike_time then
        local change=ping-self.last_ping
        self.events:connection('Ping spike',string.format('%d → %d ms (%+d ms)',math.floor(self.last_ping+0.5),math.floor(ping+0.5),math.floor(change+0.5)))
        self.spike_time=now+2
    end
    self.last_ping=ping
end
return network


end,

 
['misc_nickname'] = function(...)
 
 
local nickname = {}
local function has(ref, name)
 local values=ui.get(ref);if type(values)~='table' then return false end
 for _,value in ipairs(values) do if value==name then return true end end
 return false
end
local function clean(value)
 local text=tostring(value or ''):gsub('[%c]',''):gsub('^%s+',''):gsub('%s+$','')
 local i,last=1,0
 while i<=#text and i<=127 do
  local b=text:byte(i)
  local n=b<128 and 1 or b<224 and 2 or b<240 and 3 or 4
  if i+n-1>#text or i+n-1>127 then break end
  last=i+n-1;i=i+n
 end
 return text:sub(1,last)
end
function nickname:init(menu,report) self.menu,self.report=menu,report end
function nickname:lookup(player)
 if not self.ffi then
  local ok,ffi=pcall(require,'ffi');assert(ok and ffi,'LuaJIT ffi unavailable')
  local signature=client.find_signature('engine.dll','\xA1\xCC\xCC\xCC\xCC\x0F\x28\xC1\xF3\x0F\x5C\x80\xCC\xCC\xCC\xCC\xF3\x0F\x11\x45\xCC\xA1\xCC\xCC\xCC\xCC\x56\x85\xC0\x75\x04\x33\xF6\xEB\x26\x80\x78\x14\x00\x74\xF6\x8B\x4D\x08\x33\xD2\xE8\xCC\xCC\xCC\xCC\x8B\xF0\x85\xF6')
  assert(signature~=nil and tonumber(ffi.cast('uintptr_t',signature))~=0,'playerinfo signature unavailable')
  local playerinfo=ffi.typeof([[struct {
    int64_t unknown; int64_t steamID64; char szName[128]; int userId; char szSteamID[20];
    char pad[0x10]; unsigned long iSteamID; char szFriendsName[128]; bool fakeplayer;
    bool ishltv; unsigned int customfiles[4]; unsigned char filesdownloaded;
  }]])
  self.entry_type=ffi.typeof('$*(__thiscall*)(void*, int, int*)',playerinfo)
  self.root=ffi.cast('uintptr_t**',ffi.cast('uintptr_t',signature)+1)
  self.ffi=ffi
 end
 local ffi=self.ffi
 if self.root==nil or self.root[0]==nil then return nil end
 local client_state=tonumber(self.root[0][0]);if not client_state or client_state==0 then return nil end
 local table_ptr=ffi.cast('void***',client_state+21184)[0]
 if table_ptr==nil then return nil end
 local vtable=ffi.cast('void***',table_ptr)[0]
 if vtable==nil or vtable[11]==nil then return nil end
 local getter=ffi.cast(self.entry_type,vtable[11])
 return getter(table_ptr,player-1,nil)
end
function nickname:read(info) return self.ffi.string(info[0].szName) end
function nickname:write(info,value)
 local dest=info[0].szName
 self.ffi.fill(dest,128,0)
 self.ffi.copy(dest,value,#value)
end
function nickname:restore()
 local state=self.state
 if not state then return true end
 local me=entity.get_local_player()
 local restored=true
 if me==state.player then
  local ok,result,err=pcall(function()
   local info=self:lookup(me)
   if info==nil then return false end
   if self:read(info)==state.applied then self:write(info,state.original) end
   return true
  end)
  if not ok then
   restored=false
   self.report('Client-side Nickname restore',err)
  elseif result==false then
   restored=false
  end
 end
 if restored or me~=state.player then self.state=nil end
 return restored
end
function nickname:update()
 local r=self.menu.misc_rage.refs
 local me=entity.get_local_player()
 local desired=clean(ui.get(r.client_nickname_text))
 if not has(r.utility_features,'Client-side Nickname') or desired=='' or not me then self:restore();return end
 if self.state and self.state.player~=me then self.state=nil end
 local ok,err=pcall(function()
  local info=self:lookup(me)
  if info==nil then return end
  local current=self:read(info)
  if not self.state then self.state={player=me,original=current,applied=desired}
  elseif current~=self.state.applied then self.state.original=current end
  if current~=desired then self:write(info,desired) end
  self.state.applied=desired
 end)
 if not ok then
  if self.last_error~=tostring(err) then self.report('Client-side Nickname',err) end
  self.last_error=tostring(err)
 else self.last_error=nil end
end
function nickname:shutdown() self:restore() end
return nickname


end,

 
