local function has(ref, value)
    local options = ui.get(ref)
    if type(options) ~= 'table' then return false end
    for _, v in ipairs(options) do if v == value then return true end end
    return false
end
local function cvar_write(cv, value)
    local integer = math.floor(value)
    local raw = integer == value and 'set_raw_int' or 'set_raw_float'
    local fallback = integer == value and 'set_int' or 'set_float'
    local ok = pcall(function() cv[raw](cv, value) end)
    if not ok then cv[fallback](cv, value) end
end
local function cvar_read(cv)
    local ok, value = pcall(function() return cv:get_float() end)
    if not ok or type(value) ~= 'number' then value = cv:get_int() end
    assert(type(value) == 'number', 'cvar has no numeric value')
    return value
end
function misc:init(menu)
    self.menu = menu
    local ok, ref = pcall(ui.reference, 'RAGE', 'Aimbot', 'Target teammates')
    if ok then self.target_teammates = ref end
    local duck_ok, a, b = pcall(ui.reference, 'RAGE', 'Other', 'Duck peek assist')
    if duck_ok then self.duck_checkbox, self.duck_hotkey = a, b or a end
    local ok_vector, vector = pcall(require, 'vector')
    local ok_trace, trace = pcall(require, 'gamesense/trace')
    local ok_bit, bit = pcall(require, 'bit')
    if ok_vector and ok_trace and ok_bit then self.vector, self.trace, self.bit = vector, trace, bit end
end
function misc:report(name, err)
    local message = '[nyameeow.pink] ' .. name .. ': ' .. tostring(err)
    if client.error_log then client.error_log(message) else client.log(message) end
end
function misc:run(name, fn, restore, ...)
    if self.failed[name] then return end
    local ok, err = pcall(fn, self, ...)
    if not ok then
        if restore then
            local restored, restore_err = pcall(restore, self)
            if not restored then self:report(name .. ' restore', restore_err) end
        end
        self.failed[name] = true
        self:report(name, err)
    end
end
function misc:warmup_setup()
     
    for _, command in ipairs(warmup_commands) do client.exec(command) end
end
function misc:restore_teammate()
    local s = self.teammate_state
    if not s then return end
    local errors = {}
    if s.cvar ~= nil then
        local ok, err = pcall(function() cvar.mp_teammates_are_enemies:set_int(s.cvar) end)
        if ok then s.cvar = nil else errors[#errors+1] = tostring(err) end
    end
    if s.target ~= nil then
        local ok, err = pcall(ui.set, self.target_teammates, s.target)
        if ok then s.target = nil else errors[#errors+1] = tostring(err) end
    end
    if #errors > 0 then error(table.concat(errors, '; ')) end
    self.teammate_state = nil
end
function misc:teammate()
    if not ui.get(self.menu.misc_rage.refs.teammate) then return self:restore_teammate() end
    local cv = assert(cvar.mp_teammates_are_enemies, 'mp_teammates_are_enemies unavailable')
    if not self.teammate_state then
        local old = cv:get_int(); assert(type(old) == 'number', 'cannot read mp_teammates_are_enemies')
        local target = self.target_teammates and ui.get(self.target_teammates) or nil
         
        if self.target_teammates then target = ui.get(self.target_teammates) end
        self.teammate_state = {cvar = old, target = target}
    end
    if cv:get_int() ~= 1 then cv:set_int(1) end
    if self.target_teammates and not ui.get(self.target_teammates) then ui.set(self.target_teammates, true) end
end
function misc:restore_console()
    local s = self.console_state
    if not s then return end
    local errors = {}
    if s.enabled ~= nil then
        local ok, err = pcall(function() cvar.con_filter_enable:set_int(s.enabled) end)
