    end
    if s.text ~= nil then
        local ok, err = pcall(function() cvar.con_filter_text:set_string(s.text) end)
        if ok then s.text = nil else errors[#errors+1] = tostring(err) end
    end
    if #errors > 0 then error(table.concat(errors, '; ')) end
    self.console_state = nil
end
function misc:console_filter()
