    if not self.console_state then
        local enabled, text = cvar.con_filter_enable:get_int(), cvar.con_filter_text:get_string()
        assert(type(enabled)=='number' and type(text)=='string', 'cannot read console filter state')
        self.console_state = {enabled=enabled, text=text}
    end
    local filter = 'IrWL5106TZZKNFPz4P4Gl3pSN?J370f5hi373ZjPg%VOVh6lN'
    if cvar.con_filter_enable:get_int() ~= 1 then cvar.con_filter_enable:set_int(1) end
    if cvar.con_filter_text:get_string() ~= filter then cvar.con_filter_text:set_string(filter) end
end
function misc:restore_optimizer()
    local errors = {}
    for name, state in pairs(self.optimized) do
        local ok, err = pcall(cvar_write, state.cv, state.saved)
        if ok then self.optimized[name] = nil else errors[#errors+1] = name .. ': ' .. tostring(err) end
    end
    if #errors > 0 then error(table.concat(errors, '; ')) end
end
function misc:is_peeking()
    local player = entity.get_local_player()
    if not player or not entity.is_alive(player) then return false end
    local x, y = entity.get_prop(player, 'm_vecVelocity')
    return type(x)=='number' and type(y)=='number' and x*x+y*y >= 65*65
end
function misc:optimizer_tick()
    local r = self.menu.misc_rage.refs
    local enabled = has(r.utility_features, 'Performance Optimizer')
    local profile, flag = ui.get(r.optimizer_profile), ui.get(r.optimizer_flags)
    local selected = {}
    local values = ui.get(r.optimizer_cvars)
    if type(values)=='table' then for _, v in ipairs(values) do selected[#selected+1] = v end end
    table.sort(selected)
    local ui_signature = table.concat({tostring(enabled), tostring(profile), tostring(flag), table.concat(selected, '|')}, ':')
    local peeking = enabled and flag == 'Peeking' and self:is_peeking() or false
    if ui_signature == self.optimizer_ui_signature and peeking == self.optimizer_peeking then return end
    local now = globals.realtime()
    if ui_signature == self.optimizer_ui_signature and now < (self.next_peek_update or 0) then return end
    self:optimizer()
    self.optimizer_ui_signature, self.optimizer_peeking = ui_signature, peeking
    self.next_peek_update = now + 0.25
end
function misc:optimizer()
    local r = self.menu.misc_rage.refs
    local desired = {}
    local enabled = has(r.utility_features, 'Performance Optimizer')
    if enabled and ui.get(r.optimizer_flags) == 'Peeking' then
        enabled = self:is_peeking()
    end
    if enabled then
        local profile = ui.get(r.optimizer_profile)
        local names = profile == 'Custom' and ui.get(r.optimizer_cvars) or profiles[profile]
        if type(names) == 'table' then
            for _, name in ipairs(names) do if optimizer_values[name] ~= nil then desired[name] = optimizer_values[name] end end
        end
    end
    for name, state in pairs(self.optimized) do
        if desired[name] == nil then cvar_write(state.cv, state.saved); self.optimized[name] = nil end
    end
    for name, target in pairs(desired) do
        if not self.missing[name] then
            local state = self.optimized[name]
            if not state then
                local ok, cv = pcall(function() return cvar[name] end)
                if not ok or cv == nil then self.missing[name] = true
                else
                    local read_ok, value = pcall(cvar_read, cv)
                    if not read_ok then self.missing[name] = true
                    else state = {cv=cv, saved=value}; self.optimized[name] = state end
                end
            end
            if state and math.abs(cvar_read(state.cv) - target) > 0.001 then cvar_write(state.cv, target) end
        end
    end
end
local function clan_frames()
    local text, frames, replacements = 'nyameeow.pink', {}, {a='4',e='3',t='7',l='1',g='9',o='0',s='$'}
    local function add(s) frames[#frames+1]=s end
    add(''); add('|'); add(''); add('|')
    for i=1,#text do
        local part=text:sub(1,i); add(part..'|')
        local last=text:sub(i,i); local g=replacements[last] or last
        if g~=last then add(text:sub(1,i-1)..g..'|'); add(part..'|') end
        add(part)
    end
    add(text..'|'); add(text); add(text..'|'); add(text)
    for _, s in ipairs({'nyameeow.pink','ny4meeow.pink','nyam3eow.pink','nyamee0w.pink','nyam3e0w.pink','ny4m3e0w.pink','nyameeow.pink','nyam3eow.pink','ny4mee0w.pink','nyameeow.pink'}) do add(s); add(s..'|') end
    for _=1,3 do add(text); add(text..'|') end; add(text)
    for i=#text-1,0,-1 do local part=text:sub(1,i);add(part..'|');add(part) end
    add('|');add('');add('|');add('')
    return frames
end
function misc:clan_tag()
    if not has(self.menu.misc_rage.refs.utility_features, 'Clan Tag Spammer') then
        if self.clan_active then client.set_clan_tag(''); self.clan_active=false; self.clan_previous=nil end
        return
    end
    if not self.clan_frames then self.clan_frames = clan_frames() end
    local interval = globals.tickinterval() or 0.015625
    local latency = client.latency() or 0
    local tick = globals.tickcount() + math.floor(latency / interval + 0.5)
    local speed = math.max(1, math.floor(0.16 / interval + 0.5))
    local frame = self.clan_frames[math.floor(tick / speed) % #self.clan_frames + 1]
    if not self.clan_active or frame ~= self.clan_previous then client.set_clan_tag(frame); self.clan_previous=frame end
    self.clan_active = true
end
function misc:fast_ladder(cmd)
    local r = self.menu.misc_rage.refs
    if not ui.get(r.fast_ladder) then return end
    local player = entity.get_local_player()
    if not player or not entity.is_alive(player) or entity.get_prop(player,'m_MoveType') ~= 9 then return end
    local weapon = entity.get_player_weapon(player)
    if not weapon then return end
    local throwing = entity.get_prop(weapon, 'm_fThrowTime')
    if throwing ~= nil and throwing ~= 0 then return end
    if cmd.forwardmove > 0 and cmd.pitch < 45 then
        cmd.pitch, cmd.in_moveright, cmd.in_moveleft, cmd.in_forward, cmd.in_back = 89,1,0,0,1
        cmd.yaw = cmd.yaw + (cmd.sidemove == 0 and 90 or cmd.sidemove < 0 and 150 or 30)
    elseif cmd.forwardmove < 0 then
        cmd.pitch, cmd.in_moveleft, cmd.in_moveright, cmd.in_forward, cmd.in_back = 89,1,0,1,0
        cmd.yaw = cmd.yaw + (cmd.sidemove == 0 and 90 or cmd.sidemove > 0 and 150 or 30)
    end
end
function misc:avoid_flying(cmd)
    local r = self.menu.misc_rage.refs
    if not ui.get(r.fast_ladder) or not ui.get(r.avoid_flying) then self.duck_ticks=0; return end
    assert(self.vector and self.trace and self.bit, 'requires vector, gamesense/trace and bit')
    local player = entity.get_local_player()
    if not player or not entity.is_alive(player) then self.duck_ticks=0; return end
    if entity.get_prop(player, 'm_MoveType') == 9 then
        local nx,ny,nz=entity.get_prop(player,'m_vecLadderNormal')
        local ox,oy,oz=entity.get_origin(player)
        local vx,vy,vz=entity.get_prop(player,'m_vecVelocity')
        local minx,miny,minz=entity.get_prop(player,'m_vecMins')
        local maxx,maxy,maxz=entity.get_prop(player,'m_vecMaxs')
        if nx and ny and nz and ox and oy and oz and vx and vy and vz and minx and miny and minz and maxx and maxy and maxz then
            local vec, bit = self.vector, self.bit
            local normal = -vec(nx,ny,nz)
            if normal:lengthsqr() > 0 then
                local dt=globals.tickinterval(); local gravity=cvar.sv_gravity:get_float()*0.4
                local predicted=vec(ox,oy,oz)+vec(vx*dt,vy*dt,(vz-gravity*dt*0.5)*dt)
                local result=self.trace.hull(predicted,predicted+normal:normalized()*12,vec(minx,miny,minz),vec(maxx,maxy,maxz),
                    {skip=player,mask=bit.band(33636363,bit.bnot(65536))})
                if vz-gravity*dt>0 and result and result.fraction~=0 and bit.band(result.contents or 0,536870912)==0 then self.duck_ticks=3 end
            end
        end
    end
    if (self.duck_ticks or 0)>0 then cmd.in_duck=1;self.duck_ticks=self.duck_ticks-1 end
end
 
function misc:edge_quick_stop(cmd)
    local r=self.menu.misc_rage.refs
    local bound
    if self.menu.binds then bound = self.menu.binds.read('edge_quick_stop', r.edge_quick_stop_key)
    else bound = ui.get(r.edge_quick_stop_key) == true end
    if not ui.get(r.edge_quick_stop) or not bound then return end
    local p=entity.get_local_player()
    if not p or not entity.is_alive(p) then return end
    local flags=entity.get_prop(p,'m_fFlags') or 0
    if flags % 2 == 0 then return end
    local _,yaw=client.camera_angles(); if not yaw then return end
    local ox,oy,oz=entity.get_prop(p,'m_vecOrigin'); if not ox or not oy or not oz then return end
    local directions = {}
    if cmd.forwardmove ~= 0 then directions[cmd.forwardmove > 0 and 'forward' or 'back'] = cmd.forwardmove > 0 and 0 or 180 end
    if cmd.sidemove ~= 0 then directions[cmd.sidemove > 0 and 'right' or 'left'] = cmd.sidemove > 0 and -90 or 90 end
    local blocked={}
    for name,offset in pairs(directions) do
        local rad=math.rad(yaw+offset);local dx,dy=math.cos(rad),math.sin(rad)
        local safe=0
        for distance=2,70,2 do
            local x,y=ox+dx*distance,oy+dy*distance
            local fraction=client.trace_line(p,x,y,oz+5,x,y,oz-35)
            if fraction==1 or fraction*40>40 then break end
            safe=distance
        end
        if safe<70 then
            local x,y=ox+dx*80,oy+dy*80
            local fraction=client.trace_line(p,x,y,oz+5,x,y,oz-35)
            if fraction~=1 and fraction*40<=40 then safe=safe+20 end
            blocked[name]=safe
        end
    end
    local f=blocked[cmd.forwardmove>0 and 'forward' or 'back']
    if cmd.forwardmove~=0 and f and f<70 then cmd.forwardmove=cmd.forwardmove*f/70 end
    local s=blocked[cmd.sidemove>0 and 'right' or 'left']
    if cmd.sidemove~=0 and s and s<70 then cmd.sidemove=cmd.sidemove*s/70 end
end
function misc:restore_duck()
    if self.duck_saved ~= nil then
        ui.set(self.duck_hotkey, self.duck_saved)
        self.duck_saved = nil
    end
end
function misc:allow_duck(cmd)
    local r = self.menu.misc_rage.refs
    if not ui.get(r.allow_duck_fd) then return self:restore_duck() end
    local player = entity.get_local_player()
    if not player or not entity.is_alive(player) then return self:restore_duck() end
    assert(self.duck_hotkey, 'Duck peek assist reference unavailable')
    local active, mode = ui.get(self.duck_hotkey)
    if self.duck_checkbox ~= self.duck_hotkey then active = ui.get(self.duck_checkbox) or active end
    local ducking = cmd.in_duck == 1 and (entity.get_prop(player, 'm_flDuckAmount') or 0) > 0.8
    if ducking and active and self.duck_saved == nil then
        local modes = {[0]='Always on',[1]='On hotkey',[2]='Toggle',[3]='Off hotkey'}
        if type(mode) == 'number' then mode = modes[mode] end
        assert(mode == 'Always on' or mode == 'On hotkey' or mode == 'Toggle' or mode == 'Off hotkey',
            'Cannot read duck peek assist hotkey mode; refusing to modify it')
        self.duck_saved = mode
        ui.set(self.duck_hotkey, (mode == 'Toggle' or mode == 'Off hotkey') and 'On hotkey' or 'Off hotkey')
    elseif not ducking then self:restore_duck() end
end
function misc:cancel_nades()
    self.nade_generation = (self.nade_generation or 0) + 1
    self.nade_throw_until = nil
    self.nade_key_down = false
end
function misc:drop_nades(cmd)
    local r = self.menu.misc_rage.refs
    if not ui.get(r.drop_nades) then
        if self.nade_throw_until or self.nade_key_down then self:cancel_nades() end
        return
    end
    local player = entity.get_local_player()
    if not player or not entity.is_alive(player) then self:cancel_nades(); return end
    local weapon = entity.get_player_weapon(player)
    if not weapon then return end
    local down
    if self.menu.binds then down = self.menu.binds.read('drop_nades', r.drop_nades_key)
    else down = ui.get(r.drop_nades_key) == true end
    local now = globals.realtime()
    if down and not self.nade_key_down and not self.nade_throw_until then
        if not self.weapon_info then self.weapon_info = require('gamesense/csgo_weapons') end
        local allowed = {weapon_hegrenade='HE Grenade', weapon_smokegrenade='Smoke',
            weapon_incgrenade='Molotov', weapon_molotov='Molotov'}
        local queue = {}
        for i=0,63 do
            local item = entity.get_prop(player, 'm_hMyWeapons', i)
            if item then
                local info = self.weapon_info(item)
                local key = info and allowed[info.item_class]
                if info and info.weapon_type_int == 9 and key and has(r.drop_grenades, key) then
                    queue[#queue+1] = info.item_class
                end
            end
        end
        if #queue > 0 then
            local generation = (self.nade_generation or 0) + 1
            self.nade_generation = generation
            local interval = math.max(0, client.latency()) + globals.tickinterval() * 4
            self.nade_throw_until = now + interval * #queue + 0.1
            for i, item_class in ipairs(queue) do
                local command = 'use ' .. item_class .. '; drop'
                client.delay_call(interval * i, function()
                    if self.stopping or self.nade_generation ~= generation or not ui.get(r.drop_nades) then return end
                    local me = entity.get_local_player()
                    if me ~= player or not entity.is_alive(me) then return end
                    local ok, err = pcall(client.exec, command)
                    if not ok then self:report('Drop Nades', err); self:cancel_nades() end
                end)
            end
        end
    end
    self.nade_key_down = down
    if self.nade_throw_until then
        if now >= self.nade_throw_until then self.nade_throw_until = nil; return end
        local pitch, yaw = client.camera_angles()
        if pitch and yaw then
            cmd.yaw, cmd.pitch = yaw, pitch + (pitch > 0 and -0.0001 or 0.0001)
            cmd.no_choke, cmd.allow_send_packet = true, true
        end
    end
end
function misc:player_chat(event)
    if event and event.entity then
        self.last_chat = self.last_chat or {}
        self.last_chat[event.entity] = globals.realtime()
    end
end
function misc:player_say(event)
    self:run('Enemy Chat Viewer', function(self)
        if not ui.get(self.menu.misc_rage.refs.enemy_chat) or not event or not event.userid then return end
        local player = client.userid_to_entindex(event.userid)
        if not player or player == 0 or not entity.is_enemy(player) then return end
        if not self.chat_api then
            local chat = require('gamesense/chat')
            local localize = require('gamesense/localize')
            local api = panorama.open().GameStateAPI
            assert(chat and type(chat.print_player)=='function' and localize and api,
                'gamesense/chat, gamesense/localize or GameStateAPI unavailable')
            self.chat_api = {chat=chat, localize=localize, game=api}
        end
        local api = self.chat_api
        local xuid = api.game.GetPlayerXuidStringFromEntIndex(player)
        if api.game.IsSelectedPlayerMuted(xuid) then return end
        if cvar.cl_mute_enemy_team and cvar.cl_mute_enemy_team:get_int() == 1 then return end
        if cvar.cl_mute_all_but_friends_and_party and cvar.cl_mute_all_but_friends_and_party:get_int() == 1 then return end
        local message = tostring(event.text or '')
        client.delay_call(0.2, function()
            if self.stopping or not ui.get(self.menu.misc_rage.refs.enemy_chat) then return end
            self:run('Enemy Chat Viewer', function(self)
                local last = self.last_chat and self.last_chat[player]
                if last and math.abs(globals.realtime()-last)<0.4 then return end
                local resource=entity.get_player_resource()
                local team=resource and entity.get_prop(resource, 'm_iTeam', player)
                local side=team==2 and 'T' or 'CT'
                local location=entity.get_prop(player,'m_szLastPlaceName') or ''
                local name=entity.get_player_name(player) or '?'
                local key='Cstrike_Chat_'..side..'_'..(entity.is_alive(player) and 'Loc' or 'Dead')
                local loc = api.localize(location~='' and location or 'UI_Unknown')
                api.chat.print_player(player, api.localize(key, {s1=name,s2=message,s3=loc}))
            end)
        end)
    end)
end
function misc:event(name, event)
    if self.nickname and name == 'net_update_end' then self.nickname:update() end
    if name == 'cs_win_panel_match' and not self.match_disconnected and has(self.menu.misc_rage.refs.utility_features, 'Auto Disconnect') and entity.get_local_player() then
        self.match_disconnected = true
        local ok, err = pcall(client.exec, 'disconnect')
        if not ok then self:report('Auto Disconnect', err) end
    end
    if self.trash and name == 'player_death' then self:run('Trash Talk', function(self) self.trash:on_player_death(event) end) end
    if self.voice then
        local ok, err = pcall(self.voice.event, self.voice, name, event)
        if not ok then
            if self.voice.last_error ~= tostring(err) then self:report('F12 Sound', err) end
            self.voice.last_error = tostring(err)
        else self.voice.last_error = nil end
    end
    if not self.events then return end
    self:run('Event Logger ' .. name, function(self) self.events:run(name, event) end)
end
function misc:paint_ui()
    if self.voice then self:run('F12 Sound tick', function(self) self.voice:tick() end) end
    if self.discord then self:run('Discord RPC', function(self) self.discord:update() end) end
    if self.network then self:run('Connection problems', function(self) self.network:update() end) end
    if self.nickname and not has(self.menu.misc_rage.refs.utility_features, 'Client-side Nickname') then self.nickname:restore() end
    if self.unlock then self:run('Unlock Hidden Cvars', function(self) self.unlock:sync() end, function(self) self.unlock:restore() end) end
    if self.events then self:run('Notifications', function(self) self.events:paint_ui() end) end
    self:run('Force Teammate Aimbot', self.teammate, self.restore_teammate)
    self:run('Console Filter', self.console_filter, self.restore_console)
    if self.chat_filter then self:run('Chat Filter', function(self)
        self.chat_filter:sync(has(self.menu.misc_rage.refs.utility_features, 'Chat Filter'))
    end) end
    self:run('Performance Optimizer', self.optimizer_tick, self.restore_optimizer)
    self:run('Clan Tag Spammer', self.clan_tag)
end
function misc:finish_command(cmd)
    if self.breaker then self:run('Animation Breaker', function(self) self.breaker:finish(cmd) end, function(self) self.breaker:reset() end) end
end
function misc:pre_render()
    if self.breaker then
        self:run('Smooth Animfix', function(self) self.breaker:smooth_render() end, function(self) self.breaker:smooth_reset() end)
        self:run('Animation Breaker other', function(self) self.breaker:apply_extra_animations() end)
        self:run('Animation Breaker air', function(self) self.breaker:apply_air_preview() end)
        self:run('Pitch Zero on Land', function(self) self.breaker:apply_pitch_on_land() end)
    end
end
function misc:post_animation()
    if self.breaker then self:run('Animation Breaker post', function(self) self.breaker:post_animation() end, function(self) self.breaker:reset() end) end
end
function misc:setup_command(cmd)
    if self.breaker then self.breaker:setup_command(cmd) end
    self:run('Allow Duck on FD', self.allow_duck, self.restore_duck, cmd)
    self:run('Fast Ladder', self.fast_ladder, nil, cmd)
    self:run('Avoid Flying', self.avoid_flying, nil, cmd)
    self:run('Edge Quick Stop', self.edge_quick_stop, nil, cmd)
    self:run('Drop Nades', self.drop_nades, self.cancel_nades, cmd)
end
function misc:level_init()
    self.match_disconnected = false
    if self.network then self.network:reset() end
    if self.breaker then self.breaker:reset() end
    if self.nickname then self.nickname:restore() end
    if self.voice then self.voice:stop() end
    if self.trash then self.trash:reset_match() end
    self:cancel_nades()
    self.missing={}; self.last_chat={}; self.optimizer_ui_signature=nil
    if self.events then self.events:reset() end
end
function misc:shutdown()
    self.stopping = true
    local function attempt(label, fn)
        local ok, err = pcall(fn)
        if not ok then self:report(label .. ' shutdown', err) end
    end
    if self.chat_filter then attempt('Chat Filter', function() self.chat_filter:shutdown() end) end
    if self.voice then attempt('F12 Sound', function() self.voice:shutdown() end) end
    if self.discord then attempt('Discord RPC', function() self.discord:shutdown() end) end
    if self.trash then attempt('Trash Talk', function() self.trash:shutdown() end) end
    if self.unlock then attempt('Unlock Hidden Cvars', function() self.unlock:shutdown() end) end
    if self.breaker then attempt('Animation Breaker', function() self.breaker:shutdown() end) end
    if self.nickname then attempt('Client-side Nickname', function() self.nickname:shutdown() end) end
    attempt('Grenades', function() self:cancel_nades() end)
    if self.events then attempt('Notifications', function() self.events:reset() end) end
    for _, action in ipairs({{'teammate',self.restore_teammate},{'console filter',self.restore_console},{'optimizer',self.restore_optimizer},{'duck hotkey',self.restore_duck}}) do
        attempt(action[1], function() action[2](self) end)
    end
    if self.clan_active then
        local ok, err = pcall(client.set_clan_tag, '')
        if ok then self.clan_active = false else self:report('clan tag shutdown', err) end
    end
end
return misc


end,

 

 
['core'] = function(...)
 
local modules = ...
local core = {callbacks = {}, stopping = false, shutdown_running = false}
local function report(where, err)
    local message = '[nyameeow.pink] ' .. where .. ': ' .. tostring(err)
    if client.error_log then client.error_log(message) else client.log(message) end
end
function core:start()
    self.callbacks = {}
    self.stopping, self.shutdown_running = false, false
    local ok, err = pcall(function()
        modules.statistics.start()
        modules.menu:init()
    end)
    if not ok then
        report('startup', err)
        self:shutdown()
        return false
    end
    local reported = {}
    local function step(label, fn, ...)
        local success, first, second, third = pcall(fn, ...)
        if not success then
            if not reported[label] then
                reported[label] = true
                report(label, first)
            end
            return
        end
        return first, second, third
    end
     
    local anti_failed = {}
    local function anti(name, ...)
        if anti_failed[name] then return end
        local fn = modules.menu.anti_bruteforce[name]
        local success, error_message = pcall(fn, modules.menu.anti_bruteforce, ...)
        if not success then anti_failed[name] = true; report('Anti-Bruteforce ' .. name, error_message) end
    end

    local builder_retry_at, builder_last_error = 0, nil
    local function update_builder(cmd)
        local cfg = modules.menu.config
        if (cfg and cfg.config_load_guard) or modules.menu.builder.changing then return end
        local now = globals.realtime()
        if now < builder_retry_at then return end
        local success, error_message = pcall(modules.menu.builder_runtime.setup_command, modules.menu.builder_runtime, cmd)
        if not success then
            builder_retry_at = now + 0.25
            pcall(modules.menu.builder_runtime.reset, modules.menu.builder_runtime)
            if error_message ~= builder_last_error then report('Builder state', error_message) end
            builder_last_error = error_message
        else
            builder_retry_at, builder_last_error = 0, nil
        end
    end
    local crosshair_failed = false
    local function crosshair_event(name, ...)
        if crosshair_failed then return end
        local crosshair = modules.menu.visuals_runtime and modules.menu.visuals_runtime.crosshair
        local fn = crosshair and crosshair[name]
        if type(fn) ~= 'function' then return end
        local success, error_message = pcall(fn, crosshair, ...)
        if not success then crosshair_failed = true; report('Crosshair ' .. name, error_message) end
    end
    local events = {
        pre_config_load = function()
            local cfg = modules.menu.config
            if cfg and type(cfg.before_config_load) == 'function' then
                step('Builder CFG pre-load', cfg.before_config_load, cfg)
            end
        end,
        pre_config_save = function()
            local cfg = modules.menu.config
            if cfg and type(cfg.before_config_save) == 'function' then
                step('Builder CFG save', cfg.before_config_save, cfg)
            end
        end,
        post_config_load = function()
            local cfg = modules.menu.config
            if cfg and type(cfg.after_config_load) == 'function' then
                step('Builder CFG load', cfg.after_config_load, cfg)
            end
        end,
        paint_ui = function()
            step('Enemy misses update', modules.enemy_misses.update)
            step('Menu paint', modules.menu.paint, modules.menu)
            step('Visuals paint_ui', modules.menu.visuals_runtime.paint_ui, modules.menu.visuals_runtime)
            step('Misc paint_ui', modules.menu.misc_runtime.paint_ui, modules.menu.misc_runtime)
            step('Rage quick switch', modules.menu.rage_runtime.sync_quick_switch, modules.menu.rage_runtime)
            step('Rage paint_ui', modules.menu.rage_runtime.paint_ui, modules.menu.rage_runtime)
            step('Rage fixes paint_ui', modules.menu.rage_fixes.paint_ui, modules.menu.rage_fixes)
        end,
        paint = function()
            step('Visuals paint', modules.menu.visuals_runtime.paint, modules.menu.visuals_runtime)
        end,
        pre_render = function()
            step('Misc pre_render', modules.menu.misc_runtime.pre_render, modules.menu.misc_runtime)
        end,
        setup_command = function(cmd)
            local strafe_input = step('Strafe input', modules.menu.rage_fixes.capture_command, modules.menu.rage_fixes, cmd)
            anti('setup_command', cmd)
            update_builder(cmd)
            step('Misc setup_command', modules.menu.misc_runtime.setup_command, modules.menu.misc_runtime, cmd)
            step('Rage setup_command', modules.menu.rage_runtime.setup_command, modules.menu.rage_runtime, cmd)
            step('Rage fixes setup_command', modules.menu.rage_fixes.setup_command, modules.menu.rage_fixes, cmd, strafe_input)
        end,
        run_command = function(cmd)
            return step('Builder run_command', modules.menu.builder_runtime.run_command, modules.menu.builder_runtime, cmd)
        end,
        predict_command = function(cmd)
            return step('Builder predict_command', modules.menu.builder_runtime.predict_command, modules.menu.builder_runtime, cmd)
        end,
        console_input = function(text)
            return step('Builder console_input', modules.menu.builder_runtime.console_input, modules.menu.builder_runtime, text)
        end,
        finish_command = function(cmd)
            step('Misc finish_command', modules.menu.misc_runtime.finish_command, modules.menu.misc_runtime, cmd)
        end,
        post_update_clientside_animation = function()
            step('Misc post_animation', modules.menu.misc_runtime.post_animation, modules.menu.misc_runtime)
        end,
        level_init = function()
            step('Rage level reset', modules.menu.rage_runtime.reset, modules.menu.rage_runtime)
            step('Rage fixes level reset', modules.menu.rage_fixes.reset, modules.menu.rage_fixes)
            step('Builder level reset', modules.menu.builder_runtime.reset, modules.menu.builder_runtime)
            anti('reset')
            step('Misc level_init', modules.menu.misc_runtime.level_init, modules.menu.misc_runtime)
            step('Visuals level_init', modules.menu.visuals_runtime.level_init, modules.menu.visuals_runtime)
        end,
        player_say = function(e)
            step('Misc player_say', modules.menu.misc_runtime.player_say, modules.menu.misc_runtime, e)
        end,
        player_chat = function(e)
            step('Misc player_chat', modules.menu.misc_runtime.player_chat, modules.menu.misc_runtime, e)
        end,
        override_view = function(e)
            step('Visuals override_view', modules.menu.visuals_runtime.override_view, modules.menu.visuals_runtime, e)
        end,
        weapon_fire = function(e)
            step('Enemy misses fire', modules.enemy_misses.fire, modules.enemy_misses, e)
            step('Rage weapon_fire', modules.menu.rage_runtime.weapon_fire, modules.menu.rage_runtime, e)
            if type(modules.menu.builder_runtime.defensive_shot) == 'function' then
                step('Builder defensive_shot', modules.menu.builder_runtime.defensive_shot, modules.menu.builder_runtime, e, false)
            end
        end,
        grenade_thrown = function(e)
            step('Rage grenade_thrown', modules.menu.rage_runtime.grenade_thrown, modules.menu.rage_runtime, e)
        end,
        bullet_impact = function(e)
            step('Enemy misses impact', modules.enemy_misses.impact, modules.enemy_misses, e)
            anti('bullet_impact', e)
        end,
        player_hurt = function(e)
            step('Enemy misses hurt', modules.enemy_misses.hurt, modules.enemy_misses, e)
            anti('player_hurt', e)
            step('Misc player_hurt', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'player_hurt', e)
            if modules.menu.visuals_runtime.hitmarker then
                step('Hitmarkers player_hurt', modules.menu.visuals_runtime.run, modules.menu.visuals_runtime, 'Hitmarkers', function(host) host.hitmarker:player_hurt(e) end)
            end
            if type(modules.menu.builder_runtime.defensive_damage) == 'function' then
                step('Builder defensive_damage', modules.menu.builder_runtime.defensive_damage, modules.menu.builder_runtime, e)
            end
        end,
        round_start = function()
            step('Enemy misses round reset', modules.enemy_misses.reset_pending)
            step('Builder round_start', modules.menu.builder_runtime.round_start, modules.menu.builder_runtime)
            anti('reset')
        end,
        cs_game_disconnected = function()
            step('Rage disconnect reset', modules.menu.rage_runtime.reset, modules.menu.rage_runtime)
            step('Rage fixes disconnect reset', modules.menu.rage_fixes.reset, modules.menu.rage_fixes)
            step('Builder disconnect reset', modules.menu.builder_runtime.reset, modules.menu.builder_runtime)
            anti('reset')
            step('Enemy misses disconnect reset', modules.enemy_misses.reset_pending)
            step('Misc disconnect reset', modules.menu.misc_runtime.level_init, modules.menu.misc_runtime)
            step('Visuals disconnect reset', modules.menu.visuals_runtime.level_init, modules.menu.visuals_runtime)
        end,
        aim_fire = function(e)
            step('Statistics fire', modules.statistics.fire)
            if modules.menu.visuals_runtime.hitmarker then
                step('Hitmarkers aim_fire', modules.menu.visuals_runtime.run, modules.menu.visuals_runtime, 'Hitmarkers', function(host) host.hitmarker:aim_fire(e) end)
            end
            step('Rage arm', modules.menu.rage_runtime.arm, modules.menu.rage_runtime)
            step('Misc aim_fire', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'aim_fire', e)
            if type(modules.menu.builder_runtime.defensive_shot) == 'function' then
                step('Builder defensive_shot', modules.menu.builder_runtime.defensive_shot, modules.menu.builder_runtime, e, true)
            end
        end,
        aim_hit = function(e)
            step('Statistics hit', modules.statistics.hit)
            step('Misc aim_hit', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'aim_hit', e)
            if modules.menu.visuals_runtime.hitmarker then
                step('Hitmarkers aim_hit', modules.menu.visuals_runtime.run, modules.menu.visuals_runtime, 'Hitmarkers', function(host) host.hitmarker:aim_hit(e) end)
            end
        end,
        aim_miss = function(e)
            step('Misc aim_miss', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'aim_miss', e)
            crosshair_event('aim_miss')
        end,
        item_purchase = function(e)
            step('Misc item_purchase', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'item_purchase', e)
        end,
        cs_win_panel_match = function(e)
            step('Misc match result', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'cs_win_panel_match', e)
        end,
        net_update_start = function()
            step('Misc net_update_start', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'net_update_start')
        end,
        net_update_end = function()
            step('Misc net_update_end', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'net_update_end')
            step('Rage fixes net_update_end', modules.menu.rage_fixes.net_update_end, modules.menu.rage_fixes)
        end,
        player_death = function(e)
            step('Statistics death', modules.statistics.death, modules.statistics, e)
            step('Misc player_death', modules.menu.misc_runtime.event, modules.menu.misc_runtime, 'player_death', e)
            anti('player_death', e)
            crosshair_event('player_death', e)
        end,
    }
    local registered, registration_error = pcall(function()
        for name, handler in pairs(events) do
            local event_name = name
            local wrapped = function(...)
                if core.stopping then return end
                return handler(...)
            end
            local success, err = pcall(client.set_event_callback, event_name, wrapped)
            if success then
                self.callbacks[event_name] = wrapped
            elseif event_name == 'post_update_clientside_animation' or event_name == 'pre_render' then
                report(event_name .. ' unavailable', err)
            else
                error(err, 0)
            end
        end
        local shutdown_callback = function() self:shutdown() end
        local success, err = pcall(client.set_event_callback, 'shutdown', shutdown_callback)
        if not success then error(err, 0) end
        self.callbacks.shutdown = shutdown_callback
    end)
    if not registered then
        report('event registration', registration_error)
        self:shutdown()
        return false
    end
    return true
end
function core:shutdown()
    if self.shutdown_running then return false end
    self.shutdown_running = true
    self.stopping = true
    local success = true
    local function cleanup(label, fn, ...)
        local ok, err = pcall(fn, ...)
        if not ok then success = false; report(label, err) end
    end
    for name, callback in pairs(self.callbacks) do
        cleanup('unregister ' .. name, client.unset_event_callback, name, callback)
    end
    self.callbacks = {}
    cleanup('CFG shutdown snapshot', function()
        local cfg = modules.menu and modules.menu.config
        if cfg and not cfg.config_load_guard and type(cfg.before_config_save) == 'function' then
            cfg._builder_save_pending = false
            cfg:before_config_save()
        end
    end)
    cleanup('rage runtime reset', function()
        if modules.menu.rage_runtime then modules.menu.rage_runtime:reset() end
    end)
    cleanup('rage fixes shutdown', function()
        if modules.menu.rage_fixes and type(modules.menu.rage_fixes.shutdown) == 'function' then
            modules.menu.rage_fixes:shutdown()
        end
    end)
    cleanup('builder shutdown', function()
        if modules.menu.builder_runtime and type(modules.menu.builder_runtime.shutdown) == 'function' then
            modules.menu.builder_runtime:shutdown()
        end
    end)
    cleanup('misc shutdown', function()
        if modules.menu.misc_runtime then modules.menu.misc_runtime:shutdown() end
    end)
    cleanup('visuals shutdown', function()
        if modules.menu.visuals_runtime then modules.menu.visuals_runtime:shutdown() end
    end)
    cleanup('menu shutdown', modules.menu.shutdown, modules.menu)
    self.shutdown_running = false
    return success
end
return core


end,
}

local modules = {}
local module_environment = nil

local function load_module(name)
    local chunk = sources[name]
    if type(chunk) ~= 'function' then
        error('[nyameeow.pink] embedded module is missing: ' .. tostring(name), 0)
    end
    if module_environment ~= nil then
        if type(setfenv) ~= 'function' then
            error('[nyameeow.pink] Lua environment isolation is unavailable', 0)
        end
        setfenv(chunk, module_environment)
    end
    local ok, result = pcall(chunk, modules)
    if not ok then
        error('[nyameeow.pink] ' .. name .. ' load failed: ' .. tostring(result), 0)
    end
    if type(result) ~= 'table' then
        error('[nyameeow.pink] ' .. name .. ' must return a module table', 0)
    end
    modules[name] = result
    sources[name] = nil
    return result
end


 
local pui_bridge = load_module('pui_bridge')
pui_bridge.install()
module_environment = pui_bridge.environment()

local load_order = {
    'lib_memory',
    'icon',
    'lib_custom_tab',
    'profile',
    'statistics',
    'text',
    'symbols',
    'enemy_misses',
    'builder_menu',
    'visuals_crosshair',
    'visuals_manual_arrows',
    'misc_rage_menu',
    'visuals_menu',
    'tab',
    'anti_bruteforce',
    'binds',
    'builder_runtime',
    'config',
    'home',
    'inline_nav',
    'misc_animation',
    'misc_chat_filter',
    'misc_cvars',
    'misc_discord',
    'misc_events',
    'misc_f12',
    'misc_file_list',
    'misc_network',
    'misc_nickname',
    'misc_runtime',
    'misc_trash',
    'rage_fixes',
    'rage_runtime',
    'visuals_grenade_warning',
    'visuals_hitmarker',
    'visuals_output',
    'visuals_runtime',
    'visuals_scope',
    'visuals_watermark',
    'visuals_world',
    'watermark_icons',
    'menu',
    'nav_layout',
    'core',
}

for _, name in ipairs(load_order) do
    load_module(name)
end

local started = modules.core:start()
if started ~= true then
    error('[nyameeow.pink] startup failed; see the first nyameeow.pink error above', 0)
end

return modules
